INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '83451598-c685-7ebe-8b99-5ad338f1b09d', '2f92596c-7a0c-7c08-a174-a4e9ce4ef417', 1, 'PUBLISHED', 'String', '[{"id":"261b6555-a1b6-762e-9e55-922dc6244d8e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"String problems are about "},{"type":"text","text":"finding a pattern inside a text","marks":[{"type":"bold"}]},{"type":"text","text":" without re-comparing characters you have already looked at. Naive matching restarts from scratch after every mismatch; Rabin–Karp compares hashes first; KMP precomputes exactly how far the pattern can safely slide. Around them sit the classic sliding-window and counting problems: anagram search, longest distinct substring and the lexicographic rank of a string."}]}]}},"revision":1},{"id":"5d86daa2-36e5-78f4-baea-85d2f6127691","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern searching","marks":[{"type":"bold"}]},{"type":"text","text":" — given a text "},{"type":"text","text":"txt","marks":[{"type":"code"}]},{"type":"text","text":" of length "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" and a pattern "},{"type":"text","text":"pat","marks":[{"type":"code"}]},{"type":"text","text":" of length "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"1 ≤ m ≤ n","marks":[{"type":"code"}]},{"type":"text","text":"), report every index "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" such that "},{"type":"text","text":"txt[i..i+m−1] == pat","marks":[{"type":"code"}]},{"type":"text","text":". There are "},{"type":"text","text":"n − m + 1","marks":[{"type":"code"}]},{"type":"text","text":" candidate positions."}]}]}},"revision":1},{"id":"c05d2765-5fc8-7cba-9cc8-2f2df1bfc65e","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"The landscape of pattern-searching algorithms"}]},"revision":1},{"id":"de2acc4e-1873-75f7-a268-14e913aeead2","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Preprocessing"}],[{"type":"text","text":"Algorithm"}],[{"type":"text","text":"Time"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"none"}],[{"type":"text","text":"naive"}],[{"type":"text","text":"O((n − m + 1) · m)","marks":[{"type":"code"}]}],[{"type":"text","text":"simple; the bound is tight for "},{"type":"text","text":"txt = aaaa…","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"pat = aaab","marks":[{"type":"code"}]}]],[[{"type":"text","text":"none"}],[{"type":"text","text":"naive, pattern characters distinct"}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"after a mismatch at "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":", slide by "},{"type":"text","text":"j","marks":[{"type":"code"}]}]],[[{"type":"text","text":"pattern"}],[{"type":"text","text":"Rabin–Karp"}],[{"type":"text","text":"O((n − m + 1) · m)","marks":[{"type":"code"}]},{"type":"text","text":" worst, "},{"type":"text","text":"O(n + m)","marks":[{"type":"code"}]},{"type":"text","text":" expected"}],[{"type":"text","text":"compares a rolling hash first; great for many patterns of the same length"}]],[[{"type":"text","text":"pattern"}],[{"type":"text","text":"KMP (Knuth–Morris–Pratt)"}],[{"type":"text","text":"O(n + m)","marks":[{"type":"code"}]},{"type":"text","text":" guaranteed"}],[{"type":"text","text":"LPS array tells how far to fall back; never re-reads a text character"}]],[[{"type":"text","text":"text"}],[{"type":"text","text":"suffix tree / suffix array"}],[{"type":"text","text":"O(m)","marks":[{"type":"code"}]},{"type":"text","text":" per query after "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" build"}],[{"type":"text","text":"when the same text is searched for many patterns"}]]]},"revision":1},{"id":"00a58bfa-03cb-763c-9902-86140031fec8","type":"callout","position":"a4","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Preprocess whichever side is reused. One text, many patterns → preprocess the "},{"type":"text","text":"text","marks":[{"type":"bold"}]},{"type":"text","text":" (suffix structures). One pattern, many texts (or a streaming text) → preprocess the "},{"type":"text","text":"pattern","marks":[{"type":"bold"}]},{"type":"text","text":" (KMP, Rabin–Karp)."}]}]}},"revision":1},{"id":"21e07f72-5ced-7df9-97cb-8db0ba060a9c","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Naive pattern searching"}]},"revision":1},{"id":"9e3c9de0-ab70-789a-962f-81cee73d6093","type":"callout","position":"a6","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"GEEKSFORGEEKS\", pat = \"EKS\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"2 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"AAAA\", pat = \"AAA\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"0 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"geeks for geeks\", pat = \"geeks\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"0 10","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"2f9bed57-3925-7fe1-9bfa-254a6eb764f7","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Library search already does this: Python''s "},{"type":"text","text":"str.find(pat, start)","marks":[{"type":"code"}]},{"type":"text","text":" repeated from "},{"type":"text","text":"pos + 1","marks":[{"type":"code"}]},{"type":"text","text":" finds every (possibly overlapping) occurrence."}]}]}},"revision":1},{"id":"f6579711-7c75-73a4-83f8-628c4bac5452","type":"code","position":"a8","content":{"language":"python","code":"def find_all(txt, pat):\n    pos = txt.find(pat)\n    while pos >= 0:\n        print(pos, end=\" \")\n        pos = txt.find(pat, pos + 1)      # start just after the last hit → overlaps are found too\n    print()\n\nfind_all(\"GEEKSFORGEEKS\", \"EKS\")\nfind_all(\"AAAA\", \"AAA\")","filename":"Python — using str.find"},"revision":1},{"id":"9e0e5bf8-0160-760d-bf65-eaaf41d59794","type":"code","position":"a9","content":{"language":"text","code":"2 10\n0 1","filename":"Output"},"revision":1},{"id":"1c8d6d0b-09cf-7c67-b7e6-6a3db0e52cd5","type":"callout","position":"aA","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Try every start "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"n − m","marks":[{"type":"code"}]},{"type":"text","text":". Compare "},{"type":"text","text":"pat[0..m−1]","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"txt[i..i+m−1]","marks":[{"type":"code"}]},{"type":"text","text":" character by character and stop at the first mismatch. Report "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" when all "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" characters matched. (The original notes printed inside the inner loop, which reports a hit only when the last compared character happens to be the final one — the report belongs "},{"type":"text","text":"after","marks":[{"type":"italic"}]},{"type":"text","text":" the inner loop.)"}]}]}},"revision":1},{"id":"97e19ff3-a3ec-71ea-89b9-731c2500168f","type":"code","position":"aB","content":{"language":"python","code":"def naive_search(txt, pat):\n    n, m = len(txt), len(pat)\n    res = []\n    for i in range(n - m + 1):              # every candidate start\n        j = 0\n        while j < m and txt[i + j] == pat[j]:\n            j += 1\n        if j == m:                          # all m characters matched\n            res.append(i)\n    return res\n\nfor txt, pat in [(\"GEEKSFORGEEKS\", \"EKS\"), (\"AAAA\", \"AAA\"), (\"geeks for geeks\", \"geeks\")]:\n    print(pat, \"in\", txt, \"→\", \" \".join(map(str, naive_search(txt, pat))))","filename":"Python"},"revision":1},{"id":"ab8491ab-c81a-7c8e-80c4-6a3e0dc28d31","type":"code","position":"aC","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvector<int> naiveSearch(const string& txt, const string& pat) {\n    int n = txt.size(), m = pat.size();\n    vector<int> res;\n    for (int i = 0; i + m <= n; i++) {           // every candidate start\n        int j = 0;\n        while (j < m && txt[i + j] == pat[j]) j++;\n        if (j == m) res.push_back(i);            // all m characters matched\n    }\n    return res;\n}\n\nstring join(const vector<int>& v) {\n    string s;\n    for (size_t i = 0; i < v.size(); i++) s += (i ? \" \" : \"\") + to_string(v[i]);\n    return s;\n}\n\nint main() {\n    vector<pair<string, string>> tests = {{\"GEEKSFORGEEKS\", \"EKS\"}, {\"AAAA\", \"AAA\"}, {\"geeks for geeks\", \"geeks\"}};\n    for (auto& [txt, pat] : tests)\n        cout << pat << \" in \" << txt << \" → \" << join(naiveSearch(txt, pat)) << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"5e7d0052-904c-7e8c-9fe0-0a94263c538e","type":"code","position":"aD","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static List<Integer> naiveSearch(String txt, String pat) {\n        int n = txt.length(), m = pat.length();\n        List<Integer> res = new ArrayList<>();\n        for (int i = 0; i + m <= n; i++) {                // every candidate start\n            int j = 0;\n            while (j < m && txt.charAt(i + j) == pat.charAt(j)) j++;\n            if (j == m) res.add(i);                       // all m characters matched\n        }\n        return res;\n    }\n\n    static String join(List<Integer> v) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : v) sb.append(sb.length() == 0 ? \"\" : \" \").append(x);\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        String[][] tests = {{\"GEEKSFORGEEKS\", \"EKS\"}, {\"AAAA\", \"AAA\"}, {\"geeks for geeks\", \"geeks\"}};\n        for (String[] t : tests)\n            System.out.println(t[1] + \" in \" + t[0] + \" → \" + join(naiveSearch(t[0], t[1])));\n    }\n}","filename":"Java"},"revision":1},{"id":"62edac12-1446-73d8-b1e8-fa49e3ae3738","type":"code","position":"aE","content":{"language":"javascript","code":"function naiveSearch(txt, pat) {\n    const n = txt.length, m = pat.length;\n    const res = [];\n    for (let i = 0; i + m <= n; i++) {               // every candidate start\n        let j = 0;\n        while (j < m && txt[i + j] === pat[j]) j++;\n        if (j === m) res.push(i);                    // all m characters matched\n    }\n    return res;\n}\n\nfor (const [txt, pat] of [[\"GEEKSFORGEEKS\", \"EKS\"], [\"AAAA\", \"AAA\"], [\"geeks for geeks\", \"geeks\"]])\n    console.log(pat, \"in\", txt, \"→\", naiveSearch(txt, pat).join(\" \"));","filename":"JavaScript"},"revision":1},{"id":"d2588517-7f71-783a-b8e9-27ca3b9d4b4f","type":"code","position":"aF","content":{"language":"text","code":"EKS in GEEKSFORGEEKS → 2 10\nAAA in AAAA → 0 1\ngeeks in geeks for geeks → 0 10","filename":"Output"},"revision":1},{"id":"578cd939-ee87-7a07-8c13-fe1fa1c6d6a3","type":"text","position":"aG","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O((n − m + 1) · m) · Space O(1)"}]}]}},"revision":1},{"id":"f4a1e7a9-91d2-7cab-9937-51231f8b70b8","type":"callout","position":"aH","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The worst case needs a text and pattern that agree for a long time before each mismatch — "},{"type":"text","text":"txt = \"AAAAAAAAAB\"","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"pat = \"AAAB\"","marks":[{"type":"code"}]},{"type":"text","text":" compares "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" characters at almost every start. On typical text the first character already mismatches and the naive search runs close to "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"facc1017-49c2-7d95-8255-729b3515a802","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Improved naive when the pattern''s characters are distinct"}]},"revision":1},{"id":"0a5c1158-50b7-7dc7-b6c9-337c168ba877","type":"callout","position":"aJ","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"ABCABCDABCD\", pat = \"ABCD\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"3 7","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"AAAB\", pat = \"AB\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"2","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"99031f8a-e3f1-7b6c-8cc2-a4ccb828d5dc","type":"callout","position":"aK","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Suppose the comparison at start "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" fails at position "},{"type":"text","text":"j > 0","marks":[{"type":"code"}]},{"type":"text","text":", so "},{"type":"text","text":"txt[i..i+j−1] == pat[0..j−1]","marks":[{"type":"code"}]},{"type":"text","text":". Could a match begin at "},{"type":"text","text":"i + s","marks":[{"type":"code"}]},{"type":"text","text":" for some "},{"type":"text","text":"1 ≤ s < j","marks":[{"type":"code"}]},{"type":"text","text":"? It would need "},{"type":"text","text":"txt[i+s] == pat[0]","marks":[{"type":"code"}]},{"type":"text","text":", but "},{"type":"text","text":"txt[i+s] = pat[s]","marks":[{"type":"code"}]},{"type":"text","text":", and all pattern characters are "},{"type":"text","text":"distinct","marks":[{"type":"bold"}]},{"type":"text","text":", so "},{"type":"text","text":"pat[s] ≠ pat[0]","marks":[{"type":"code"}]},{"type":"text","text":". Therefore the next possible start is "},{"type":"text","text":"i + j","marks":[{"type":"code"}]},{"type":"text","text":": slide by "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":". Every text character is now compared at most twice, giving "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"a22fb42f-0fc4-79dd-b28e-cab4ebba3aa2","type":"code","position":"aL","content":{"language":"text","code":"txt :  A B C A B C D A B C D\npat :  A B C D                 mismatch at j = 3 (A ≠ D)\n             A B C D           slide by 3 → match at i = 3\n                     A B C D   slide by m = 4 → match at i = 7","filename":"Text characters are never re-scanned from the middle of a partial match"},"revision":1},{"id":"2d677f35-2606-7977-a3cf-dd0be3d8191c","type":"code","position":"aM","content":{"language":"python","code":"def distinct_search(txt, pat):\n    n, m = len(txt), len(pat)\n    res = []\n    i = 0\n    while i <= n - m:\n        j = 0\n        while j < m and txt[i + j] == pat[j]:\n            j += 1\n        if j == m:\n            res.append(i)\n        i += max(1, j)            # slide by j (by 1 when the very first character failed)\n    return res\n\nprint(\" \".join(map(str, distinct_search(\"ABCABCDABCD\", \"ABCD\"))))\nprint(\" \".join(map(str, distinct_search(\"AAAB\", \"AB\"))))","filename":"Python"},"revision":1},{"id":"e929310f-5dcc-73f6-afc1-a660c577f997","type":"code","position":"aN","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvector<int> distinctSearch(const string& txt, const string& pat) {\n    int n = txt.size(), m = pat.size();\n    vector<int> res;\n    int i = 0;\n    while (i <= n - m) {\n        int j = 0;\n        while (j < m && txt[i + j] == pat[j]) j++;\n        if (j == m) res.push_back(i);\n        i += max(1, j);                // slide by j (by 1 when the very first character failed)\n    }\n    return res;\n}\n\nstring join(const vector<int>& v) {\n    string s;\n    for (size_t i = 0; i < v.size(); i++) s += (i ? \" \" : \"\") + to_string(v[i]);\n    return s;\n}\n\nint main() {\n    cout << join(distinctSearch(\"ABCABCDABCD\", \"ABCD\")) << \"\\n\";\n    cout << join(distinctSearch(\"AAAB\", \"AB\")) << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"0fa21f28-4e70-7535-a582-2578ec8713e4","type":"code","position":"aO","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static List<Integer> distinctSearch(String txt, String pat) {\n        int n = txt.length(), m = pat.length();\n        List<Integer> res = new ArrayList<>();\n        int i = 0;\n        while (i <= n - m) {\n            int j = 0;\n            while (j < m && txt.charAt(i + j) == pat.charAt(j)) j++;\n            if (j == m) res.add(i);\n            i += Math.max(1, j);       // slide by j (by 1 when the very first character failed)\n        }\n        return res;\n    }\n\n    static String join(List<Integer> v) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : v) sb.append(sb.length() == 0 ? \"\" : \" \").append(x);\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        System.out.println(join(distinctSearch(\"ABCABCDABCD\", \"ABCD\")));\n        System.out.println(join(distinctSearch(\"AAAB\", \"AB\")));\n    }\n}","filename":"Java"},"revision":1},{"id":"f4d5d7b5-79a7-7120-a4ea-8155fb6ec8aa","type":"code","position":"aP","content":{"language":"javascript","code":"function distinctSearch(txt, pat) {\n    const n = txt.length, m = pat.length;\n    const res = [];\n    let i = 0;\n    while (i <= n - m) {\n        let j = 0;\n        while (j < m && txt[i + j] === pat[j]) j++;\n        if (j === m) res.push(i);\n        i += Math.max(1, j);           // slide by j (by 1 when the very first character failed)\n    }\n    return res;\n}\n\nconsole.log(distinctSearch(\"ABCABCDABCD\", \"ABCD\").join(\" \"));\nconsole.log(distinctSearch(\"AAAB\", \"AB\").join(\" \"));","filename":"JavaScript"},"revision":1},{"id":"2a709cc2-f1b2-7438-8853-4e057fb48663","type":"code","position":"aQ","content":{"language":"text","code":"3 7\n2","filename":"Output"},"revision":1},{"id":"df07a1f4-425d-7401-8f14-a6ebf4d72db4","type":"text","position":"aR","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}},"revision":1},{"id":"4adecf55-e173-7357-bd3f-36820758f147","type":"callout","position":"aS","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The original notes ran this with "},{"type":"text","text":"pat = \"geeks\"","marks":[{"type":"code"}]},{"type":"text","text":" — whose "},{"type":"text","text":"e","marks":[{"type":"code"}]},{"type":"text","text":" repeats — so the precondition was violated (and the Python "},{"type":"text","text":"for j in range(m)","marks":[{"type":"code"}]},{"type":"text","text":" loop could never reach "},{"type":"text","text":"j == m","marks":[{"type":"code"}]},{"type":"text","text":"). With a repeated character, sliding by "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" can skip a real match: "},{"type":"text","text":"txt = \"aab\"","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"pat = \"ab\"","marks":[{"type":"code"}]},{"type":"text","text":" fails at "},{"type":"text","text":"j = 1","marks":[{"type":"code"}]},{"type":"text","text":" on start 0 and would jump to start 1 — fine here, but "},{"type":"text","text":"txt = \"aaab\"","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"pat = \"aab\"","marks":[{"type":"code"}]},{"type":"text","text":" fails at "},{"type":"text","text":"j = 2","marks":[{"type":"code"}]},{"type":"text","text":" and skips the match at 1. That is exactly the gap KMP closes."}]}]}},"revision":1},{"id":"91dfafe3-ead8-7439-a67d-fc21473e5047","type":"heading","position":"aT","content":{"level":1,"content":[{"type":"text","text":"Rabin–Karp with a rolling hash"}]},"revision":1},{"id":"f502ae39-6835-74d6-a2b8-451c8426df99","type":"callout","position":"aU","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"geeks for geeks\", pat = \"geeks\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"0 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"GEEKSFORGEEKS\", pat = \"EKS\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"2 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"aaaaab\", pat = \"aaaa\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"0 1","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"72cfba0f-c4a8-7199-9d60-3146e5b086ee","type":"text","position":"aV","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Like the naive algorithm, slide the pattern over every start — but compare a "},{"type":"text","text":"hash","marks":[{"type":"bold"}]},{"type":"text","text":" of the pattern with a hash of the current window first, and only compare characters when the hashes agree. The trick is computing the next window''s hash from the previous one in "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" — a "},{"type":"text","text":"rolling hash","marks":[{"type":"italic"}]},{"type":"text","text":"."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A first attempt: the sum of character codes","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"t(i+1) = t(i) + txt[i+m] − txt[i]","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" per shift, but every anagram of the pattern ("},{"type":"text","text":"abc","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"bca","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"cab","marks":[{"type":"code"}]},{"type":"text","text":") has the same hash, so spurious hits are common."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A better hash: treat the window as a base-","marks":[{"type":"bold"}]},{"type":"text","text":"d","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" number","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"h(s) = s[0]·d^(m−1) + s[1]·d^(m−2) + … + s[m−1]·d^0","marks":[{"type":"code"}]},{"type":"text","text":". With "},{"type":"text","text":"d = 5","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"a = 1, b = 2, c = 3, d = 4","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"h(\"abc\") = 1·25 + 2·5 + 3 = 38","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"h(\"dab\") = 4·25 + 1·5 + 2 = 107","marks":[{"type":"code"}]},{"type":"text","text":". Position now matters."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Roll it","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Remove the leading digit, shift left, append the new digit: "},{"type":"text","text":"t(i+1) = d · (t(i) − txt[i] · d^(m−1)) + txt[i+m]","marks":[{"type":"code"}]},{"type":"text","text":". Three multiplications and two additions — "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" whatever "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" is."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep numbers small","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Take everything modulo a prime "},{"type":"text","text":"q","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"d = 256","marks":[{"type":"code"}]},{"type":"text","text":" for bytes, "},{"type":"text","text":"q = 101","marks":[{"type":"code"}]},{"type":"text","text":" in the examples). Equal hashes are then only "},{"type":"text","text":"probably","marks":[{"type":"italic"}]},{"type":"text","text":" equal strings — the character check settles it."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"t(i+1) = ( d · ( t(i) − txt[i] · d^(m−1) ) + txt[i+m] ) mod q","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"bd07ffaa-227a-76a2-8127-6ee5f45bb46a","type":"callout","position":"aW","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hashing shifts the cost from "},{"type":"text","text":"O(m)","marks":[{"type":"code"}]},{"type":"text","text":" per window to "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" per window plus "},{"type":"text","text":"O(m)","marks":[{"type":"code"}]},{"type":"text","text":" only when the hashes collide. A good hash collides rarely, so the expected time is "},{"type":"text","text":"O(n + m)","marks":[{"type":"code"}]},{"type":"text","text":"; with a bad hash (or an adversarial input) every window collides and it degrades to the naive "},{"type":"text","text":"O(n · m)","marks":[{"type":"code"}]},{"type":"text","text":". The program below also reports "},{"type":"text","text":"spurious hits","marks":[{"type":"bold"}]},{"type":"text","text":" — windows whose hash matched but whose text did not."}]}]}},"revision":1},{"id":"c30071c2-f539-7a79-ab61-1d2e2567f96f","type":"code","position":"aX","content":{"language":"python","code":"d, q = 256, 101                              # alphabet size, prime modulus\n\ndef rabin_karp(txt, pat):\n    n, m = len(txt), len(pat)\n    h = 1                                    # h = d^(m-1) mod q\n    for _ in range(m - 1):\n        h = (h * d) % q\n    p = t = 0\n    for i in range(m):                       # hash of the pattern and of the first window\n        p = (p * d + ord(pat[i])) % q\n        t = (t * d + ord(txt[i])) % q\n    hits, spurious = [], []\n    for i in range(n - m + 1):\n        if p == t:                           # hashes agree → verify character by character\n            if txt[i:i + m] == pat:\n                hits.append(i)\n            else:\n                spurious.append(i)\n        if i < n - m:                        # roll: drop txt[i], append txt[i+m]\n            t = (d * (t - ord(txt[i]) * h) + ord(txt[i + m])) % q\n            if t < 0:\n                t += q                       # (Python''s % is never negative; kept for symmetry)\n    return hits, spurious\n\nfor txt, pat in [(\"geeks for geeks\", \"geeks\"), (\"GEEKSFORGEEKS\", \"EKS\"), (\"aaaaab\", \"aaaa\")]:\n    hits, spurious = rabin_karp(txt, pat)\n    line = pat + \" in \" + txt + \" → \" + \" \".join(map(str, hits))\n    if spurious:\n        line += \" (spurious hits at \" + \" \".join(map(str, spurious)) + \")\"\n    print(line)","filename":"Python"},"revision":1},{"id":"d3e85b51-3322-76de-9501-593d0a08bee1","type":"code","position":"aY","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nconst int d = 256, q = 101;                  // alphabet size, prime modulus\n\nstring join(const vector<int>& v) {\n    string s;\n    for (size_t i = 0; i < v.size(); i++) s += (i ? \" \" : \"\") + to_string(v[i]);\n    return s;\n}\n\nvoid rabinKarp(const string& txt, const string& pat) {\n    int n = txt.size(), m = pat.size();\n    int h = 1;                                // h = d^(m-1) mod q\n    for (int i = 0; i < m - 1; i++) h = (h * d) % q;\n    int p = 0, t = 0;\n    for (int i = 0; i < m; i++) {             // hash of the pattern and of the first window\n        p = (p * d + pat[i]) % q;\n        t = (t * d + txt[i]) % q;\n    }\n    vector<int> hits, spurious;\n    for (int i = 0; i <= n - m; i++) {\n        if (p == t) {                         // hashes agree → verify character by character\n            if (txt.compare(i, m, pat) == 0) hits.push_back(i);\n            else spurious.push_back(i);\n        }\n        if (i < n - m) {                      // roll: drop txt[i], append txt[i+m]\n            t = (d * (t - txt[i] * h) + txt[i + m]) % q;\n            if (t < 0) t += q;                // C++ % can be negative\n        }\n    }\n    cout << pat << \" in \" << txt << \" → \" << join(hits);\n    if (!spurious.empty()) cout << \" (spurious hits at \" << join(spurious) << \")\";\n    cout << \"\\n\";\n}\n\nint main() {\n    rabinKarp(\"geeks for geeks\", \"geeks\");\n    rabinKarp(\"GEEKSFORGEEKS\", \"EKS\");\n    rabinKarp(\"aaaaab\", \"aaaa\");\n}","filename":"C++"},"revision":1},{"id":"c94f54a8-cb2a-7c05-88f9-3fa5f597f48a","type":"code","position":"aZ","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static final int d = 256, q = 101;        // alphabet size, prime modulus\n\n    static String join(List<Integer> v) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : v) sb.append(sb.length() == 0 ? \"\" : \" \").append(x);\n        return sb.toString();\n    }\n\n    static void rabinKarp(String txt, String pat) {\n        int n = txt.length(), m = pat.length();\n        int h = 1;                            // h = d^(m-1) mod q\n        for (int i = 0; i < m - 1; i++) h = (h * d) % q;\n        int p = 0, t = 0;\n        for (int i = 0; i < m; i++) {         // hash of the pattern and of the first window\n            p = (p * d + pat.charAt(i)) % q;\n            t = (t * d + txt.charAt(i)) % q;\n        }\n        List<Integer> hits = new ArrayList<>(), spurious = new ArrayList<>();\n        for (int i = 0; i <= n - m; i++) {\n            if (p == t) {                     // hashes agree → verify character by character\n                if (txt.startsWith(pat, i)) hits.add(i);\n                else spurious.add(i);\n            }\n            if (i < n - m) {                  // roll: drop txt[i], append txt[i+m]\n                t = (d * (t - txt.charAt(i) * h) + txt.charAt(i + m)) % q;\n                if (t < 0) t += q;            // Java % can be negative\n            }\n        }\n        String line = pat + \" in \" + txt + \" → \" + join(hits);\n        if (!spurious.isEmpty()) line += \" (spurious hits at \" + join(spurious) + \")\";\n        System.out.println(line);\n    }\n\n    public static void main(String[] args) {\n        rabinKarp(\"geeks for geeks\", \"geeks\");\n        rabinKarp(\"GEEKSFORGEEKS\", \"EKS\");\n        rabinKarp(\"aaaaab\", \"aaaa\");\n    }\n}","filename":"Java"},"revision":1},{"id":"456c7641-d59e-7a50-8b85-5d5a6dd899fe","type":"code","position":"aa","content":{"language":"javascript","code":"const d = 256, q = 101;                        // alphabet size, prime modulus\n\nfunction rabinKarp(txt, pat) {\n    const n = txt.length, m = pat.length;\n    let h = 1;                                 // h = d^(m-1) mod q\n    for (let i = 0; i < m - 1; i++) h = (h * d) % q;\n    let p = 0, t = 0;\n    for (let i = 0; i < m; i++) {              // hash of the pattern and of the first window\n        p = (p * d + pat.charCodeAt(i)) % q;\n        t = (t * d + txt.charCodeAt(i)) % q;\n    }\n    const hits = [], spurious = [];\n    for (let i = 0; i <= n - m; i++) {\n        if (p === t) {                         // hashes agree → verify character by character\n            if (txt.startsWith(pat, i)) hits.push(i);\n            else spurious.push(i);\n        }\n        if (i < n - m) {                       // roll: drop txt[i], append txt[i+m]\n            t = (d * (t - txt.charCodeAt(i) * h) + txt.charCodeAt(i + m)) % q;\n            if (t < 0) t += q;                 // JavaScript % can be negative\n        }\n    }\n    let line = pat + \" in \" + txt + \" → \" + hits.join(\" \");\n    if (spurious.length) line += \" (spurious hits at \" + spurious.join(\" \") + \")\";\n    console.log(line);\n}\n\nrabinKarp(\"geeks for geeks\", \"geeks\");\nrabinKarp(\"GEEKSFORGEEKS\", \"EKS\");\nrabinKarp(\"aaaaab\", \"aaaa\");","filename":"JavaScript"},"revision":1},{"id":"4acd7ff8-33ff-716f-b763-9f99e8a5a58d","type":"code","position":"ab","content":{"language":"text","code":"geeks in geeks for geeks → 0 10\nEKS in GEEKSFORGEEKS → 2 10 (spurious hits at 5)\naaaa in aaaaab → 0 1","filename":"Output"},"revision":1},{"id":"565b2cd2-2ddd-7ce6-b817-de710d1702c7","type":"text","position":"ac","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n + m) expected, O(n · m) worst · Space O(1)"}]}]}},"revision":1},{"id":"a3fdb848-7346-783c-b0f9-76b7c487397a","type":"callout","position":"ad","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Window 5 of "},{"type":"text","text":"GEEKSFORGEEKS","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"SFO","marks":[{"type":"code"}]},{"type":"text","text":", which happens to hash to the same value as "},{"type":"text","text":"EKS","marks":[{"type":"code"}]},{"type":"text","text":" modulo 101 — a "},{"type":"text","text":"spurious hit","marks":[{"type":"bold"}]},{"type":"text","text":" caught by the character comparison. A larger prime ("},{"type":"text","text":"10^9 + 7","marks":[{"type":"code"}]},{"type":"text","text":" with 64-bit arithmetic) makes such collisions rare in practice; in C++/Java use "},{"type":"text","text":"long","marks":[{"type":"code"}]},{"type":"text","text":" so "},{"type":"text","text":"d · t","marks":[{"type":"code"}]},{"type":"text","text":" cannot overflow."}]}]}},"revision":1},{"id":"0aa38391-ef02-7824-b7e8-dc0c6968b552","type":"callout","position":"ae","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The subtraction in the rolling step makes the remainder "},{"type":"text","text":"negative","marks":[{"type":"bold"}]},{"type":"text","text":" in C++, Java and JavaScript ("},{"type":"text","text":"-7 % 101 == -7","marks":[{"type":"code"}]},{"type":"text","text":"). Always add "},{"type":"text","text":"q","marks":[{"type":"code"}]},{"type":"text","text":" back (or write "},{"type":"text","text":"((x % q) + q) % q","marks":[{"type":"code"}]},{"type":"text","text":"). Python''s "},{"type":"text","text":"%","marks":[{"type":"code"}]},{"type":"text","text":" already returns a non-negative result, which is why the bug does not show in Python prototypes."}]}]}},"revision":1},{"id":"a2eca954-dc7c-7879-99c5-e028623ac71e","type":"heading","position":"af","content":{"level":1,"content":[{"type":"text","text":"KMP: the LPS array (longest proper prefix which is also a suffix)"}]},"revision":1},{"id":"ab045c70-a013-728e-b7d0-f5cae051dd1e","type":"callout","position":"ag","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"pat = \"ababc\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"lps = [0, 0, 1, 2, 0]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"pat = \"aaaa\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"lps = [0, 1, 2, 3]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"pat = \"abacabad\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"lps = [0, 0, 1, 0, 1, 2, 3, 0]","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"f9eabade-dd14-73fb-b134-d733c85fa564","type":"text","position":"ah","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"proper prefix","marks":[{"type":"bold"}]},{"type":"text","text":" of a string is a prefix that is not the whole string; likewise for suffixes. For "},{"type":"text","text":"\"abc\"","marks":[{"type":"code"}]},{"type":"text","text":": proper prefixes "},{"type":"text","text":"\"\"","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"\"a\"","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"\"ab\"","marks":[{"type":"code"}]},{"type":"text","text":"; proper suffixes "},{"type":"text","text":"\"\"","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"\"c\"","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"\"bc\"","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"lps[i]","marks":[{"type":"code"}]},{"type":"text","text":" is the length of the longest proper prefix of "},{"type":"text","text":"pat[0..i]","marks":[{"type":"code"}]},{"type":"text","text":" that is also a suffix of "},{"type":"text","text":"pat[0..i]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"4ca48f54-1224-7c46-a97b-969a549e941e","type":"code","position":"ai","content":{"language":"text","code":"pat[0..i]    longest proper prefix that is also a suffix    lps[i]\na            \"\"                                                0\nab           \"\"                                                0\naba          \"a\"                                               1\nabab         \"ab\"                                              2\nababc        \"\"                                                0","filename":"lps for \"ababc\" = [0, 0, 1, 2, 0]"},"revision":1},{"id":"3f50ef66-6a8f-7b0b-8aea-e501c45e8694","type":"text","position":"aj","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Computing each entry by brute force — try every length from "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" down to "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":" and compare — is simple but cubic:"}]}]}},"revision":1},{"id":"b7b89c82-3ee7-7dcd-8b05-86307f0929ae","type":"code","position":"ak","content":{"language":"python","code":"def longest_proper_prefix_suffix(s):\n    n = len(s)\n    for length in range(n - 1, 0, -1):             # longest first\n        if s[:length] == s[n - length:]:\n            return length\n    return 0\n\ndef lps_naive(pat):\n    return [longest_proper_prefix_suffix(pat[:i + 1]) for i in range(len(pat))]\n\nprint(lps_naive(\"ababc\"))\nprint(lps_naive(\"abacabad\"))","filename":"Python — naive"},"revision":1},{"id":"5e6e4c0e-6f7f-7675-8001-313232759093","type":"code","position":"al","content":{"language":"text","code":"[0, 0, 1, 2, 0]\n[0, 0, 1, 0, 1, 2, 3, 0]","filename":"Output"},"revision":1},{"id":"c33ab455-1f35-77fa-bfee-54f0ed5828a6","type":"text","position":"am","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n³) · Space O(n)"}]}]}},"revision":1},{"id":"51726a9c-de0c-7663-95da-d10973fcd55e","type":"callout","position":"an","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Build "},{"type":"text","text":"lps","marks":[{"type":"code"}]},{"type":"text","text":" left to right, reusing the previous answer. Let "},{"type":"text","text":"len = lps[i−1]","marks":[{"type":"code"}]},{"type":"text","text":" — the prefix "},{"type":"text","text":"pat[0..len−1]","marks":[{"type":"code"}]},{"type":"text","text":" matches the suffix ending at "},{"type":"text","text":"i−1","marks":[{"type":"code"}]},{"type":"text","text":". If "},{"type":"text","text":"pat[len] == pat[i]","marks":[{"type":"code"}]},{"type":"text","text":", that match extends by one: "},{"type":"text","text":"lps[i] = len + 1","marks":[{"type":"code"}]},{"type":"text","text":". Otherwise fall back to the "},{"type":"text","text":"next shorter","marks":[{"type":"bold"}]},{"type":"text","text":" candidate: the longest proper prefix-suffix of "},{"type":"text","text":"pat[0..len−1]","marks":[{"type":"code"}]},{"type":"text","text":", which is "},{"type":"text","text":"lps[len−1]","marks":[{"type":"code"}]},{"type":"text","text":", and compare again. Fall back until a match or "},{"type":"text","text":"len == 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"c955d256-9534-74c3-b608-dca5d27d3130","type":"code","position":"ao","content":{"language":"text","code":"pat = a b a c a b a d        lps so far = 0 0 1 0 1 2 3 ?       (i = 7, len = lps[6] = 3)\n\npat[3] = ''c'' ≠ pat[7] = ''d''   →  len = lps[2] = 1\npat[1] = ''b'' ≠ ''d''            →  len = lps[0] = 0\npat[0] = ''a'' ≠ ''d'', len == 0  →  lps[7] = 0","filename":"Falling back through shorter prefix-suffix candidates instead of rescanning"},"revision":1},{"id":"b104aa0a-6650-7976-a533-511b99fa1887","type":"code","position":"ap","content":{"language":"python","code":"def compute_lps(pat):\n    m = len(pat)\n    lps = [0] * m\n    length = 0                         # length of the previous longest prefix-suffix\n    i = 1\n    while i < m:\n        if pat[i] == pat[length]:\n            length += 1\n            lps[i] = length            # the match extends by one\n            i += 1\n        elif length != 0:\n            length = lps[length - 1]   # fall back to the next shorter candidate; i stays\n        else:\n            lps[i] = 0\n            i += 1\n    return lps\n\nfor pat in [\"ababc\", \"aaaa\", \"abacabad\"]:\n    print(pat, \"→\", \" \".join(map(str, compute_lps(pat))))","filename":"Python"},"revision":1},{"id":"37c58d37-7733-7c3e-af5c-2bb1a743edcc","type":"code","position":"aq","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvector<int> computeLps(const string& pat) {\n    int m = pat.size();\n    vector<int> lps(m, 0);\n    int len = 0;                           // length of the previous longest prefix-suffix\n    int i = 1;\n    while (i < m) {\n        if (pat[i] == pat[len]) {\n            lps[i++] = ++len;              // the match extends by one\n        } else if (len != 0) {\n            len = lps[len - 1];            // fall back to the next shorter candidate; i stays\n        } else {\n            lps[i++] = 0;\n        }\n    }\n    return lps;\n}\n\nint main() {\n    for (string pat : {\"ababc\", \"aaaa\", \"abacabad\"}) {\n        cout << pat << \" →\";\n        for (int x : computeLps(pat)) cout << \" \" << x;\n        cout << \"\\n\";\n    }\n}","filename":"C++"},"revision":1},{"id":"a6e3336c-3c82-7ed9-94d3-b605bfcd48ee","type":"code","position":"ar","content":{"language":"java","code":"public class Main {\n    static int[] computeLps(String pat) {\n        int m = pat.length();\n        int[] lps = new int[m];\n        int len = 0;                           // length of the previous longest prefix-suffix\n        int i = 1;\n        while (i < m) {\n            if (pat.charAt(i) == pat.charAt(len)) {\n                lps[i++] = ++len;              // the match extends by one\n            } else if (len != 0) {\n                len = lps[len - 1];            // fall back to the next shorter candidate; i stays\n            } else {\n                lps[i++] = 0;\n            }\n        }\n        return lps;\n    }\n\n    public static void main(String[] args) {\n        for (String pat : new String[]{\"ababc\", \"aaaa\", \"abacabad\"}) {\n            StringBuilder sb = new StringBuilder(pat + \" →\");\n            for (int x : computeLps(pat)) sb.append(\" \").append(x);\n            System.out.println(sb);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"98d20b2d-27db-77c1-befb-292424efc81a","type":"code","position":"as","content":{"language":"javascript","code":"function computeLps(pat) {\n    const m = pat.length;\n    const lps = new Array(m).fill(0);\n    let len = 0;                               // length of the previous longest prefix-suffix\n    let i = 1;\n    while (i < m) {\n        if (pat[i] === pat[len]) {\n            lps[i++] = ++len;                  // the match extends by one\n        } else if (len !== 0) {\n            len = lps[len - 1];                // fall back to the next shorter candidate; i stays\n        } else {\n            lps[i++] = 0;\n        }\n    }\n    return lps;\n}\n\nfor (const pat of [\"ababc\", \"aaaa\", \"abacabad\"])\n    console.log(pat, \"→\", computeLps(pat).join(\" \"));","filename":"JavaScript"},"revision":1},{"id":"06145794-d415-7b3d-8720-de9e1f6dd952","type":"code","position":"at","content":{"language":"text","code":"ababc → 0 0 1 2 0\naaaa → 0 1 2 3\nabacabad → 0 0 1 0 1 2 3 0","filename":"Output"},"revision":1},{"id":"92912eb4-a487-7a21-9218-ef2c5994c26f","type":"text","position":"au","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(m) · Space O(m)"}]}]}},"revision":1},{"id":"630675eb-5e9b-7af8-bcaf-8e56a812e681","type":"callout","position":"av","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why "},{"type":"text","text":"O(m)","marks":[{"type":"code"}]},{"type":"text","text":" despite the inner fall-back loop: "},{"type":"text","text":"len","marks":[{"type":"code"}]},{"type":"text","text":" increases at most once per character (by 1) and every fall-back strictly decreases it, so the total number of fall-backs over the whole run is at most "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":". The same argument gives the linear bound for the matching phase below."}]}]}},"revision":1},{"id":"d68cbbb6-91c4-7c58-9b65-2b1c99303749","type":"heading","position":"aw","content":{"level":1,"content":[{"type":"text","text":"KMP string matching"}]},"revision":1},{"id":"0a2aa4ee-a772-7941-a1fe-ced2102cac9d","type":"callout","position":"ax","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"abcdefg\", pat = \"bcd\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"aaaaab\", pat = \"aaaa\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"0 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"aaaaabaaaaac\", pat = \"aaaa\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"0 1 6 7","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"6283cc41-99fa-7a42-8b7f-77948c6d2571","type":"callout","position":"ay","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Run two indices, "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" over the text and "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" over the pattern. On a match advance both. On a mismatch with "},{"type":"text","text":"j > 0","marks":[{"type":"code"}]},{"type":"text","text":", the characters "},{"type":"text","text":"txt[i−j..i−1]","marks":[{"type":"code"}]},{"type":"text","text":" equal "},{"type":"text","text":"pat[0..j−1]","marks":[{"type":"code"}]},{"type":"text","text":" — and "},{"type":"text","text":"lps[j−1]","marks":[{"type":"code"}]},{"type":"text","text":" says how long a prefix of the pattern is "},{"type":"text","text":"still","marks":[{"type":"italic"}]},{"type":"text","text":" aligned with the end of that stretch. So set "},{"type":"text","text":"j = lps[j−1]","marks":[{"type":"code"}]},{"type":"text","text":" and compare again "},{"type":"text","text":"without moving ","marks":[{"type":"bold"}]},{"type":"text","text":"i","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":". When "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" reaches "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" report "},{"type":"text","text":"i − m","marks":[{"type":"code"}]},{"type":"text","text":" and continue the same way ("},{"type":"text","text":"j = lps[m−1]","marks":[{"type":"code"}]},{"type":"text","text":") to find overlapping occurrences. "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" never moves backwards, so the text is read once."}]}]}},"revision":1},{"id":"9b1d5cbd-21fc-7c72-a2b3-1f0e29c3ed2a","type":"code","position":"az","content":{"language":"text","code":"txt :  a a a a a b a a a a a c\npat :  a a a a                  j = 4 = m → report 0, j = lps[3] = 3\npat :    a a a a                txt[4] = a = pat[3] → j = 4 → report 1, j = 3\npat :      a a a a              txt[5] = b ≠ pat[3] → j = lps[2] = 2 … → j = 0, then i++\npat :              a a a a      matches resume at i = 6 → report 6, then 7","filename":"The text index i never goes back; only the pattern index j falls back"},"revision":1},{"id":"db54b6b8-c735-76a9-8dbd-a369c2bae985","type":"code","position":"b00","content":{"language":"python","code":"def compute_lps(pat):\n    lps = [0] * len(pat)\n    length, i = 0, 1\n    while i < len(pat):\n        if pat[i] == pat[length]:\n            length += 1\n            lps[i] = length\n            i += 1\n        elif length != 0:\n            length = lps[length - 1]\n        else:\n            lps[i] = 0\n            i += 1\n    return lps\n\ndef kmp_search(txt, pat):\n    n, m = len(txt), len(pat)\n    lps = compute_lps(pat)\n    res = []\n    i = j = 0                          # i → text, j → pattern\n    while i < n:\n        if txt[i] == pat[j]:\n            i += 1\n            j += 1\n            if j == m:                 # full match ends at i-1\n                res.append(i - j)\n                j = lps[j - 1]         # keep going: overlapping matches\n        elif j != 0:\n            j = lps[j - 1]             # fall back in the pattern; i does not move\n        else:\n            i += 1                     # no partial match to reuse\n    return res\n\nfor txt, pat in [(\"abcdefg\", \"bcd\"), (\"aaaaab\", \"aaaa\"), (\"aaaaabaaaaac\", \"aaaa\")]:\n    print(pat, \"in\", txt, \"→\", \" \".join(map(str, kmp_search(txt, pat))))","filename":"Python"},"revision":1},{"id":"3e04eeca-65af-76f7-b620-633cc8e59be8","type":"code","position":"b01","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvector<int> computeLps(const string& pat) {\n    int m = pat.size();\n    vector<int> lps(m, 0);\n    int len = 0, i = 1;\n    while (i < m) {\n        if (pat[i] == pat[len]) lps[i++] = ++len;\n        else if (len != 0) len = lps[len - 1];\n        else lps[i++] = 0;\n    }\n    return lps;\n}\n\nvector<int> kmpSearch(const string& txt, const string& pat) {\n    int n = txt.size(), m = pat.size();\n    vector<int> lps = computeLps(pat), res;\n    int i = 0, j = 0;                          // i → text, j → pattern\n    while (i < n) {\n        if (txt[i] == pat[j]) {\n            i++; j++;\n            if (j == m) {                      // full match ends at i-1\n                res.push_back(i - j);\n                j = lps[j - 1];                // keep going: overlapping matches\n            }\n        } else if (j != 0) {\n            j = lps[j - 1];                    // fall back in the pattern; i does not move\n        } else {\n            i++;                               // no partial match to reuse\n        }\n    }\n    return res;\n}\n\nstring join(const vector<int>& v) {\n    string s;\n    for (size_t i = 0; i < v.size(); i++) s += (i ? \" \" : \"\") + to_string(v[i]);\n    return s;\n}\n\nint main() {\n    vector<pair<string, string>> tests = {{\"abcdefg\", \"bcd\"}, {\"aaaaab\", \"aaaa\"}, {\"aaaaabaaaaac\", \"aaaa\"}};\n    for (auto& [txt, pat] : tests)\n        cout << pat << \" in \" << txt << \" → \" << join(kmpSearch(txt, pat)) << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"f8383cb7-be94-7f10-9413-a30ea09bad54","type":"code","position":"b02","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static int[] computeLps(String pat) {\n        int m = pat.length();\n        int[] lps = new int[m];\n        int len = 0, i = 1;\n        while (i < m) {\n            if (pat.charAt(i) == pat.charAt(len)) lps[i++] = ++len;\n            else if (len != 0) len = lps[len - 1];\n            else lps[i++] = 0;\n        }\n        return lps;\n    }\n\n    static List<Integer> kmpSearch(String txt, String pat) {\n        int n = txt.length(), m = pat.length();\n        int[] lps = computeLps(pat);\n        List<Integer> res = new ArrayList<>();\n        int i = 0, j = 0;                          // i → text, j → pattern\n        while (i < n) {\n            if (txt.charAt(i) == pat.charAt(j)) {\n                i++; j++;\n                if (j == m) {                      // full match ends at i-1\n                    res.add(i - j);\n                    j = lps[j - 1];                // keep going: overlapping matches\n                }\n            } else if (j != 0) {\n                j = lps[j - 1];                    // fall back in the pattern; i does not move\n            } else {\n                i++;                               // no partial match to reuse\n            }\n        }\n        return res;\n    }\n\n    static String join(List<Integer> v) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : v) sb.append(sb.length() == 0 ? \"\" : \" \").append(x);\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        String[][] tests = {{\"abcdefg\", \"bcd\"}, {\"aaaaab\", \"aaaa\"}, {\"aaaaabaaaaac\", \"aaaa\"}};\n        for (String[] t : tests)\n            System.out.println(t[1] + \" in \" + t[0] + \" → \" + join(kmpSearch(t[0], t[1])));\n    }\n}","filename":"Java"},"revision":1},{"id":"ea255a6f-49d7-720f-9255-a2af7bc1b1b2","type":"code","position":"b03","content":{"language":"javascript","code":"function computeLps(pat) {\n    const m = pat.length, lps = new Array(m).fill(0);\n    let len = 0, i = 1;\n    while (i < m) {\n        if (pat[i] === pat[len]) lps[i++] = ++len;\n        else if (len !== 0) len = lps[len - 1];\n        else lps[i++] = 0;\n    }\n    return lps;\n}\n\nfunction kmpSearch(txt, pat) {\n    const n = txt.length, m = pat.length;\n    const lps = computeLps(pat), res = [];\n    let i = 0, j = 0;                              // i → text, j → pattern\n    while (i < n) {\n        if (txt[i] === pat[j]) {\n            i++; j++;\n            if (j === m) {                         // full match ends at i-1\n                res.push(i - j);\n                j = lps[j - 1];                    // keep going: overlapping matches\n            }\n        } else if (j !== 0) {\n            j = lps[j - 1];                        // fall back in the pattern; i does not move\n        } else {\n            i++;                                   // no partial match to reuse\n        }\n    }\n    return res;\n}\n\nfor (const [txt, pat] of [[\"abcdefg\", \"bcd\"], [\"aaaaab\", \"aaaa\"], [\"aaaaabaaaaac\", \"aaaa\"]])\n    console.log(pat, \"in\", txt, \"→\", kmpSearch(txt, pat).join(\" \"));","filename":"JavaScript"},"revision":1},{"id":"faf03490-60cc-7210-9382-187d31c2a764","type":"code","position":"b04","content":{"language":"text","code":"bcd in abcdefg → 1\naaaa in aaaaab → 0 1\naaaa in aaaaabaaaaac → 0 1 6 7","filename":"Output"},"revision":1},{"id":"a5b3271c-143d-7039-a35d-922c9c0eb523","type":"text","position":"b05","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n + m) · Space O(m)"}]}]}},"revision":1},{"id":"08724641-b06c-786e-8500-3c59276c49d5","type":"callout","position":"b06","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After a full match do "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" reset "},{"type":"text","text":"j = 0","marks":[{"type":"code"}]},{"type":"text","text":" — that misses overlapping occurrences ("},{"type":"text","text":"aaaa","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"aaaaab","marks":[{"type":"code"}]},{"type":"text","text":" occurs at both 0 and 1). "},{"type":"text","text":"j = lps[m − 1]","marks":[{"type":"code"}]},{"type":"text","text":" keeps the longest reusable overlap. And guard the mismatch branch with "},{"type":"text","text":"j != 0","marks":[{"type":"code"}]},{"type":"text","text":" before indexing "},{"type":"text","text":"lps[j − 1]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"5e7ee5ad-4923-7d13-a8eb-4cad5ed3deed","type":"heading","position":"b07","content":{"level":1,"content":[{"type":"text","text":"Anagram search"}]},"revision":1},{"id":"3c063e4b-8e23-7be9-bb46-968317e82e51","type":"callout","position":"b08","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"geeksforgeeks\", pat = \"forg\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Yes (window \"forg\" at 5)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"txt = \"geeksforgeeks\", pat = \"rseek\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"No","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"dcfa9a8f-3895-71b7-b036-14bfb9b1018f","type":"text","position":"b09","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does the text contain any "},{"type":"text","text":"permutation","marks":[{"type":"bold"}]},{"type":"text","text":" of the pattern as a substring? Order no longer matters, only the multiset of characters, so hashing by comparison fails and we count instead. Naive: for every window, count the pattern''s characters up and the window''s characters down and check that everything cancels."}]}]}},"revision":1},{"id":"bc77f60c-74b7-7b8c-9074-f68d9a10f93b","type":"code","position":"b0A","content":{"language":"python","code":"CHAR = 256\n\ndef is_anagram_at(txt, pat, i):\n    count = [0] * CHAR\n    for j in range(len(pat)):\n        count[ord(pat[j])] += 1\n        count[ord(txt[i + j])] -= 1\n    return all(c == 0 for c in count)\n\ndef contains_anagram(txt, pat):\n    n, m = len(txt), len(pat)\n    return any(is_anagram_at(txt, pat, i) for i in range(n - m + 1))\n\nprint(\"Yes\" if contains_anagram(\"geeksforgeeks\", \"forg\") else \"No\")\nprint(\"Yes\" if contains_anagram(\"geeksforgeeks\", \"rseek\") else \"No\")","filename":"Python — naive"},"revision":1},{"id":"f5959022-c99c-7872-83c5-08f2796c2aef","type":"code","position":"b0B","content":{"language":"text","code":"Yes\nNo","filename":"Output"},"revision":1},{"id":"a74873d9-fe5f-7f87-88f1-57c9d79649f7","type":"text","position":"b0C","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O((n − m + 1) · (m + CHAR)) · Space O(CHAR)"}]}]}},"revision":1},{"id":"a2f17947-9488-753a-b3df-84b4bd2b3f04","type":"callout","position":"b0D","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sliding window of size "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" with two count arrays: "},{"type":"text","text":"cp","marks":[{"type":"code"}]},{"type":"text","text":" for the pattern (fixed) and "},{"type":"text","text":"ct","marks":[{"type":"code"}]},{"type":"text","text":" for the current window. Moving the window one step changes "},{"type":"text","text":"two","marks":[{"type":"bold"}]},{"type":"text","text":" counts in "},{"type":"text","text":"ct","marks":[{"type":"code"}]},{"type":"text","text":" (one character in, one out) — "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":". After each move compare "},{"type":"text","text":"ct","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"cp","marks":[{"type":"code"}]},{"type":"text","text":"; a window is an anagram exactly when the two arrays are equal."}]}]}},"revision":1},{"id":"11721e9a-e2b9-7d54-b307-9f357b4e8325","type":"code","position":"b0E","content":{"language":"python","code":"CHAR = 256\n\ndef contains_anagram(txt, pat):\n    n, m = len(txt), len(pat)\n    if m > n:\n        return False\n    ct, cp = [0] * CHAR, [0] * CHAR\n    for i in range(m):                     # first window and the pattern\n        ct[ord(txt[i])] += 1\n        cp[ord(pat[i])] += 1\n    for i in range(m, n):\n        if ct == cp:\n            return True\n        ct[ord(txt[i])] += 1               # character entering the window\n        ct[ord(txt[i - m])] -= 1           # character leaving the window\n    return ct == cp                        # the last window\n\nfor txt, pat in [(\"geeksforgeeks\", \"forg\"), (\"geeksforgeeks\", \"rseek\"), (\"cbaebabacd\", \"abc\")]:\n    print(pat, \"in\", txt, \"→\", \"Yes\" if contains_anagram(txt, pat) else \"No\")","filename":"Python"},"revision":1},{"id":"0c587a1a-ae14-7254-b27c-bfeb24251f08","type":"code","position":"b0F","content":{"language":"cpp","code":"#include <array>\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nconst int CHAR = 256;\n\nbool containsAnagram(const string& txt, const string& pat) {\n    int n = txt.size(), m = pat.size();\n    if (m > n) return false;\n    array<int, CHAR> ct{}, cp{};\n    for (int i = 0; i < m; i++) {                      // first window and the pattern\n        ct[(unsigned char)txt[i]]++;\n        cp[(unsigned char)pat[i]]++;\n    }\n    for (int i = m; i < n; i++) {\n        if (ct == cp) return true;\n        ct[(unsigned char)txt[i]]++;                   // character entering the window\n        ct[(unsigned char)txt[i - m]]--;               // character leaving the window\n    }\n    return ct == cp;                                   // the last window\n}\n\nint main() {\n    vector<pair<string, string>> tests = {{\"geeksforgeeks\", \"forg\"}, {\"geeksforgeeks\", \"rseek\"}, {\"cbaebabacd\", \"abc\"}};\n    for (auto& [txt, pat] : tests)\n        cout << pat << \" in \" << txt << \" → \" << (containsAnagram(txt, pat) ? \"Yes\" : \"No\") << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"45e501a9-cc52-7d09-b9d2-9ae354ccf6cc","type":"code","position":"b0G","content":{"language":"java","code":"import java.util.Arrays;\n\npublic class Main {\n    static final int CHAR = 256;\n\n    static boolean containsAnagram(String txt, String pat) {\n        int n = txt.length(), m = pat.length();\n        if (m > n) return false;\n        int[] ct = new int[CHAR], cp = new int[CHAR];\n        for (int i = 0; i < m; i++) {                  // first window and the pattern\n            ct[txt.charAt(i)]++;\n            cp[pat.charAt(i)]++;\n        }\n        for (int i = m; i < n; i++) {\n            if (Arrays.equals(ct, cp)) return true;\n            ct[txt.charAt(i)]++;                       // character entering the window\n            ct[txt.charAt(i - m)]--;                   // character leaving the window\n        }\n        return Arrays.equals(ct, cp);                  // the last window\n    }\n\n    public static void main(String[] args) {\n        String[][] tests = {{\"geeksforgeeks\", \"forg\"}, {\"geeksforgeeks\", \"rseek\"}, {\"cbaebabacd\", \"abc\"}};\n        for (String[] t : tests)\n            System.out.println(t[1] + \" in \" + t[0] + \" → \" + (containsAnagram(t[0], t[1]) ? \"Yes\" : \"No\"));\n    }\n}","filename":"Java"},"revision":1},{"id":"318239dd-32ed-7ca9-bb68-5f40628b2007","type":"code","position":"b0H","content":{"language":"javascript","code":"const CHAR = 256;\n\nfunction sameCounts(a, b) {\n    for (let i = 0; i < CHAR; i++) if (a[i] !== b[i]) return false;\n    return true;\n}\n\nfunction containsAnagram(txt, pat) {\n    const n = txt.length, m = pat.length;\n    if (m > n) return false;\n    const ct = new Array(CHAR).fill(0), cp = new Array(CHAR).fill(0);\n    for (let i = 0; i < m; i++) {                      // first window and the pattern\n        ct[txt.charCodeAt(i)]++;\n        cp[pat.charCodeAt(i)]++;\n    }\n    for (let i = m; i < n; i++) {\n        if (sameCounts(ct, cp)) return true;\n        ct[txt.charCodeAt(i)]++;                       // character entering the window\n        ct[txt.charCodeAt(i - m)]--;                   // character leaving the window\n    }\n    return sameCounts(ct, cp);                         // the last window\n}\n\nfor (const [txt, pat] of [[\"geeksforgeeks\", \"forg\"], [\"geeksforgeeks\", \"rseek\"], [\"cbaebabacd\", \"abc\"]])\n    console.log(pat, \"in\", txt, \"→\", containsAnagram(txt, pat) ? \"Yes\" : \"No\");","filename":"JavaScript"},"revision":1},{"id":"29a84771-31b0-7c8f-86b6-32d732d0f938","type":"code","position":"b0I","content":{"language":"text","code":"forg in geeksforgeeks → Yes\nrseek in geeksforgeeks → No\nabc in cbaebabacd → Yes","filename":"Output"},"revision":1},{"id":"c23ae13f-fba8-705d-99bf-663e2dc4e40b","type":"text","position":"b0J","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n · CHAR) · Space O(CHAR)"}]}]}},"revision":1},{"id":"89905347-02d5-7e16-b330-b53dde42545e","type":"callout","position":"b0K","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CHAR","marks":[{"type":"code"}]},{"type":"text","text":" is a constant, so this is linear — but comparing 256 counters per window is the dominant cost. The standard refinement keeps a single "},{"type":"text","text":"mismatches","marks":[{"type":"code"}]},{"type":"text","text":" counter: when a count in "},{"type":"text","text":"ct","marks":[{"type":"code"}]},{"type":"text","text":" changes, update whether that slot agrees with "},{"type":"text","text":"cp","marks":[{"type":"code"}]},{"type":"text","text":"; the window is an anagram when "},{"type":"text","text":"mismatches == 0","marks":[{"type":"code"}]},{"type":"text","text":". That is "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" with no array comparison at all."}]}]}},"revision":1},{"id":"dfc06798-ae61-79db-8099-5169c5a874bf","type":"heading","position":"b0L","content":{"level":1,"content":[{"type":"text","text":"Lexicographic rank of a string"}]},"revision":1},{"id":"107c705a-f7cc-78db-bebf-9a7b15a90870","type":"callout","position":"b0M","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"ABC\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"BAC\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"STRING\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"598","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"3a8965bf-8872-7f12-82dc-c28ceda8b691","type":"text","position":"b0N","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Among all permutations of the string''s characters listed in dictionary order, which position does the string itself hold (1-based)? For "},{"type":"text","text":"\"ABC\"","marks":[{"type":"code"}]},{"type":"text","text":" the six permutations are:"}]}]}},"revision":1},{"id":"74758a8d-7db4-7e79-b8ea-a611f3deaa9f","type":"table","position":"b0O","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Rank"}],[{"type":"text","text":"Permutation"}]],[[{"type":"text","text":"1"}],[{"type":"text","text":"ABC","marks":[{"type":"code"}]}]],[[{"type":"text","text":"2"}],[{"type":"text","text":"ACB","marks":[{"type":"code"}]}]],[[{"type":"text","text":"3"}],[{"type":"text","text":"BAC","marks":[{"type":"code"}]}]],[[{"type":"text","text":"4"}],[{"type":"text","text":"BCA","marks":[{"type":"code"}]}]],[[{"type":"text","text":"5"}],[{"type":"text","text":"CAB","marks":[{"type":"code"}]}]],[[{"type":"text","text":"6"}],[{"type":"text","text":"CBA","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"479a1d14-4883-7d97-a87e-51590269f9d6","type":"text","position":"b0P","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The pen-and-paper method generates every permutation and counts — "},{"type":"text","text":"O(n · n!)","marks":[{"type":"code"}]},{"type":"text","text":":"}]}]}},"revision":1},{"id":"7382c207-64e3-7b47-ba74-83c435caef93","type":"code","position":"b0Q","content":{"language":"python","code":"from itertools import permutations\n\ndef rank_naive(s):\n    perms = sorted(''''.join(p) for p in permutations(s))     # n! strings, sorted\n    return perms.index(s) + 1\n\nprint(rank_naive(\"ABC\"), rank_naive(\"BAC\"), rank_naive(\"STRING\"))","filename":"Python — naive"},"revision":1},{"id":"24a5cf1d-6f81-7278-8e6c-a624b020980e","type":"code","position":"b0R","content":{"language":"text","code":"1 3 598","filename":"Output"},"revision":1},{"id":"f9e05490-ac52-76ce-9403-90c632fd2588","type":"callout","position":"b0S","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Count how many permutations come "},{"type":"text","text":"before","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":". Every permutation that starts with a character smaller than "},{"type":"text","text":"s[0]","marks":[{"type":"code"}]},{"type":"text","text":" precedes "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" — there are "},{"type":"text","text":"(number of smaller characters) × (n − 1)!","marks":[{"type":"code"}]},{"type":"text","text":" of them. Fix "},{"type":"text","text":"s[0]","marks":[{"type":"code"}]},{"type":"text","text":" and repeat on the remainder: at position "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":", add "},{"type":"text","text":"(smaller unused characters to the right of i) × (n − i − 1)!","marks":[{"type":"code"}]},{"type":"text","text":". A cumulative count array "},{"type":"text","text":"count[c] = number of unused characters ≤ c","marks":[{"type":"code"}]},{"type":"text","text":" answers “how many smaller” in "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":"; after using "},{"type":"text","text":"s[i]","marks":[{"type":"code"}]},{"type":"text","text":", decrement "},{"type":"text","text":"count[c]","marks":[{"type":"code"}]},{"type":"text","text":" for every "},{"type":"text","text":"c ≥ s[i]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"23871ba9-8032-7362-bfd7-5df5a949dc17","type":"code","position":"b0T","content":{"language":"text","code":"s = \"BAC\",  n = 3,  (n-1)! = 2\n\ni = 0, ''B'' : smaller unused chars = {A} → 1 × 2! = 2 permutations start with ''A''\ni = 1, ''A'' : smaller unused chars = {}  → 0 × 1! = 0\nrank = 1 + 2 + 0 = 3","filename":"Rank of \"BAC\""},"revision":1},{"id":"584ebb7e-42b9-753c-a19e-0b38ea4e7dbc","type":"code","position":"b0U","content":{"language":"python","code":"CHAR = 256\n\ndef factorial(n):\n    r = 1\n    for i in range(2, n + 1):\n        r *= i\n    return r\n\ndef lex_rank(s):\n    n = len(s)\n    count = [0] * CHAR\n    for ch in s:\n        count[ord(ch)] += 1\n    for c in range(1, CHAR):                 # cumulative: count[c] = #chars <= c\n        count[c] += count[c - 1]\n    rank = 1\n    mul = factorial(n)\n    for i in range(n - 1):\n        mul //= n - i                        # (n - i - 1)!\n        c = ord(s[i])\n        rank += count[c - 1] * mul           # unused chars smaller than s[i]\n        for j in range(c, CHAR):             # s[i] is used up now\n            count[j] -= 1\n    return rank\n\nfor s in [\"ABC\", \"BAC\", \"CBA\", \"STRING\"]:\n    print(s, \"→\", lex_rank(s))","filename":"Python"},"revision":1},{"id":"6d85076d-fb63-7809-9421-1180c8bb4e84","type":"code","position":"b0V","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\nusing namespace std;\n\nconst int CHAR = 256;\n\nlong long factorial(int n) {\n    long long r = 1;\n    for (int i = 2; i <= n; i++) r *= i;\n    return r;\n}\n\nlong long lexRank(const string& s) {\n    int n = s.size();\n    int count[CHAR] = {0};\n    for (char ch : s) count[(unsigned char)ch]++;\n    for (int c = 1; c < CHAR; c++) count[c] += count[c - 1];   // cumulative: count[c] = #chars <= c\n    long long rank = 1, mul = factorial(n);\n    for (int i = 0; i < n - 1; i++) {\n        mul /= n - i;                                    // (n - i - 1)!\n        int c = (unsigned char)s[i];\n        rank += count[c - 1] * mul;                      // unused chars smaller than s[i]\n        for (int j = c; j < CHAR; j++) count[j]--;       // s[i] is used up now\n    }\n    return rank;\n}\n\nint main() {\n    for (string s : {\"ABC\", \"BAC\", \"CBA\", \"STRING\"})\n        cout << s << \" → \" << lexRank(s) << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"d1da4640-0455-7307-b268-997d1ec217ff","type":"code","position":"b0W","content":{"language":"java","code":"public class Main {\n    static final int CHAR = 256;\n\n    static long factorial(int n) {\n        long r = 1;\n        for (int i = 2; i <= n; i++) r *= i;\n        return r;\n    }\n\n    static long lexRank(String s) {\n        int n = s.length();\n        int[] count = new int[CHAR];\n        for (char ch : s.toCharArray()) count[ch]++;\n        for (int c = 1; c < CHAR; c++) count[c] += count[c - 1];   // cumulative: count[c] = #chars <= c\n        long rank = 1, mul = factorial(n);\n        for (int i = 0; i < n - 1; i++) {\n            mul /= n - i;                                    // (n - i - 1)!\n            int c = s.charAt(i);\n            rank += count[c - 1] * mul;                      // unused chars smaller than s[i]\n            for (int j = c; j < CHAR; j++) count[j]--;       // s[i] is used up now\n        }\n        return rank;\n    }\n\n    public static void main(String[] args) {\n        for (String s : new String[]{\"ABC\", \"BAC\", \"CBA\", \"STRING\"})\n            System.out.println(s + \" → \" + lexRank(s));\n    }\n}","filename":"Java"},"revision":1},{"id":"e592e52e-dfde-70db-8d4e-0b42cd20baf9","type":"code","position":"b0X","content":{"language":"javascript","code":"const CHAR = 256;\n\nfunction factorial(n) {\n    let r = 1;\n    for (let i = 2; i <= n; i++) r *= i;\n    return r;\n}\n\nfunction lexRank(s) {\n    const n = s.length;\n    const count = new Array(CHAR).fill(0);\n    for (const ch of s) count[ch.charCodeAt(0)]++;\n    for (let c = 1; c < CHAR; c++) count[c] += count[c - 1];   // cumulative: count[c] = #chars <= c\n    let rank = 1, mul = factorial(n);\n    for (let i = 0; i < n - 1; i++) {\n        mul /= n - i;                                    // (n - i - 1)!  (exact: mul is a multiple)\n        const c = s.charCodeAt(i);\n        rank += count[c - 1] * mul;                      // unused chars smaller than s[i]\n        for (let j = c; j < CHAR; j++) count[j]--;       // s[i] is used up now\n    }\n    return rank;\n}\n\nfor (const s of [\"ABC\", \"BAC\", \"CBA\", \"STRING\"])\n    console.log(s, \"→\", lexRank(s));","filename":"JavaScript"},"revision":1},{"id":"259b640d-dc51-773e-b49b-7ef6534871ba","type":"code","position":"b0Y","content":{"language":"text","code":"ABC → 1\nBAC → 3\nCBA → 6\nSTRING → 598","filename":"Output"},"revision":1},{"id":"9500d458-52eb-7cfd-9f6c-e6e5ff143c9b","type":"text","position":"b0Z","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n · CHAR) · Space O(CHAR)"}]}]}},"revision":1},{"id":"539df282-3e1c-7c2c-bee5-51873b90c6e9","type":"callout","position":"b0a","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This formula assumes "},{"type":"text","text":"distinct characters","marks":[{"type":"bold"}]},{"type":"text","text":". With repeats ("},{"type":"text","text":"\"AAB\"","marks":[{"type":"code"}]},{"type":"text","text":") the count of permutations starting with a smaller character must be divided by the factorials of the repeated characters'' counts. Also "},{"type":"text","text":"n!","marks":[{"type":"code"}]},{"type":"text","text":" overflows a 32-bit "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"n = 13","marks":[{"type":"code"}]},{"type":"text","text":" — use 64-bit integers (as above), which last until "},{"type":"text","text":"n = 20","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ede7749e-4f29-7b60-ab27-00ec50d77472","type":"heading","position":"b0b","content":{"level":1,"content":[{"type":"text","text":"Longest substring with distinct characters"}]},"revision":1},{"id":"9bfbec78-9750-781c-9a31-a26d4c517fcb","type":"callout","position":"b0c","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"abcdabc\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"4 (\"abcd\")","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"aaa\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"geeksforgeeks\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"7 (\"eksforg\")","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"bcd0fc18-b2bc-7298-8772-335a8673100b","type":"text","position":"b0d","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the length of the longest substring in which no character repeats. The naive version tests every substring; the "},{"type":"text","text":"better","marks":[{"type":"italic"}]},{"type":"text","text":" one notices that once a substring from "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" contains a repeat, no longer substring from "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" can be distinct — so it breaks out of the inner loop."}]}]}},"revision":1},{"id":"3aa118d9-0ae9-7330-845d-0a15216824ed","type":"code","position":"b0e","content":{"language":"python","code":"def longest_distinct_naive(s):                 # O(n^3): every (i, j), each checked in O(n)\n    n, best = len(s), 0\n    for i in range(n):\n        for j in range(i, n):\n            if len(set(s[i:j + 1])) == j - i + 1:\n                best = max(best, j - i + 1)\n    return best\n\ndef longest_distinct_better(s):                # O(n^2): extend from i until the first repeat\n    n, best = len(s), 0\n    for i in range(n):\n        seen = set()\n        for j in range(i, n):\n            if s[j] in seen:\n                break\n            seen.add(s[j])\n            best = max(best, j - i + 1)\n    return best\n\nprint(longest_distinct_naive(\"abcdabc\"), longest_distinct_better(\"abcdabc\"))\nprint(longest_distinct_naive(\"geeksforgeeks\"), longest_distinct_better(\"geeksforgeeks\"))","filename":"Python — naive O(n³) and better O(n²)"},"revision":1},{"id":"d5c45934-0eda-7f25-bba1-ad7bfad8da97","type":"code","position":"b0f","content":{"language":"text","code":"4 4\n7 7","filename":"Output"},"revision":1},{"id":"e6aa6c8a-da45-7fac-acd1-6488613fe34f","type":"callout","position":"b0g","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sliding window with a "},{"type":"text","text":"last-seen index","marks":[{"type":"bold"}]},{"type":"text","text":" per character. Let "},{"type":"text","text":"start","marks":[{"type":"code"}]},{"type":"text","text":" be the left end of the current distinct window and let "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" move right. If "},{"type":"text","text":"s[j]","marks":[{"type":"code"}]},{"type":"text","text":" was last seen at "},{"type":"text","text":"prev[s[j]] ≥ start","marks":[{"type":"code"}]},{"type":"text","text":", the window must begin after that occurrence: "},{"type":"text","text":"start = prev[s[j]] + 1","marks":[{"type":"code"}]},{"type":"text","text":". Taking "},{"type":"text","text":"start = max(start, prev[s[j]] + 1)","marks":[{"type":"code"}]},{"type":"text","text":" handles both cases in one line; "},{"type":"text","text":"j − start + 1","marks":[{"type":"code"}]},{"type":"text","text":" is the length of the longest distinct substring ending at "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":". Each character is visited once."}]}]}},"revision":1},{"id":"f48d5351-1c32-7021-bfb2-ebc9cdff5db3","type":"code","position":"b0h","content":{"language":"text","code":"s     :  a  b  c  d  a  b  c\nj = 4 : ''a'' last seen at 0 → start = 1, window \"bcda\" (length 4)\nj = 5 : ''b'' last seen at 1 → start = 2, window \"cdab\" (length 4)\nj = 6 : ''c'' last seen at 2 → start = 3, window \"dabc\" (length 4)","filename":"The window start only ever moves right"},"revision":1},{"id":"08300586-00cb-755a-a257-cf318cd22a88","type":"code","position":"b0i","content":{"language":"python","code":"def longest_distinct(s):\n    prev = [-1] * 256                 # last index where each character was seen\n    start = 0                         # left end of the current distinct window\n    best = 0\n    for j, ch in enumerate(s):\n        start = max(start, prev[ord(ch)] + 1)   # jump past the previous occurrence\n        best = max(best, j - start + 1)\n        prev[ord(ch)] = j\n    return best\n\nfor s in [\"abcdabc\", \"aaa\", \"geeksforgeeks\", \"abcdefg\"]:\n    print(s, \"→\", longest_distinct(s))","filename":"Python"},"revision":1},{"id":"729ac04e-6e88-7a23-85da-b6f750f85e8b","type":"code","position":"b0j","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <string>\nusing namespace std;\n\nint longestDistinct(const string& s) {\n    int prev[256];\n    fill(prev, prev + 256, -1);                  // last index where each character was seen\n    int start = 0, best = 0;                     // start = left end of the current distinct window\n    int n = s.size();\n    for (int j = 0; j < n; j++) {\n        unsigned char ch = s[j];\n        start = max(start, prev[ch] + 1);        // jump past the previous occurrence\n        best = max(best, j - start + 1);\n        prev[ch] = j;\n    }\n    return best;\n}\n\nint main() {\n    for (string s : {\"abcdabc\", \"aaa\", \"geeksforgeeks\", \"abcdefg\"})\n        cout << s << \" → \" << longestDistinct(s) << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"bc0ba967-7090-7e83-afb7-ecd0cae001a6","type":"code","position":"b0k","content":{"language":"java","code":"import java.util.Arrays;\n\npublic class Main {\n    static int longestDistinct(String s) {\n        int[] prev = new int[256];\n        Arrays.fill(prev, -1);                       // last index where each character was seen\n        int start = 0, best = 0;                     // start = left end of the current distinct window\n        for (int j = 0; j < s.length(); j++) {\n            char ch = s.charAt(j);\n            start = Math.max(start, prev[ch] + 1);   // jump past the previous occurrence\n            best = Math.max(best, j - start + 1);\n            prev[ch] = j;\n        }\n        return best;\n    }\n\n    public static void main(String[] args) {\n        for (String s : new String[]{\"abcdabc\", \"aaa\", \"geeksforgeeks\", \"abcdefg\"})\n            System.out.println(s + \" → \" + longestDistinct(s));\n    }\n}","filename":"Java"},"revision":1},{"id":"ecc0afa8-1c61-70f3-8cc7-5bce4af0643e","type":"code","position":"b0l","content":{"language":"javascript","code":"function longestDistinct(s) {\n    const prev = new Array(256).fill(-1);            // last index where each character was seen\n    let start = 0, best = 0;                         // start = left end of the current distinct window\n    for (let j = 0; j < s.length; j++) {\n        const ch = s.charCodeAt(j);\n        start = Math.max(start, prev[ch] + 1);       // jump past the previous occurrence\n        best = Math.max(best, j - start + 1);\n        prev[ch] = j;\n    }\n    return best;\n}\n\nfor (const s of [\"abcdabc\", \"aaa\", \"geeksforgeeks\", \"abcdefg\"])\n    console.log(s, \"→\", longestDistinct(s));","filename":"JavaScript"},"revision":1},{"id":"bc5a2ead-2805-743a-a80d-2f75c94c6203","type":"code","position":"b0m","content":{"language":"text","code":"abcdabc → 4\naaa → 1\ngeeksforgeeks → 7\nabcdefg → 7","filename":"Output"},"revision":1},{"id":"00a830e5-f78c-7eb2-b15e-1a31c5554d37","type":"text","position":"b0n","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(CHAR)"}]}]}},"revision":1},{"id":"8faf787a-63c6-7a60-a6dc-e78cc0cb038c","type":"callout","position":"b0o","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Writing "},{"type":"text","text":"start = prev[ch] + 1","marks":[{"type":"code"}]},{"type":"text","text":" without the "},{"type":"text","text":"max","marks":[{"type":"code"}]},{"type":"text","text":" is wrong: a repeat that lies "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" the current window ("},{"type":"text","text":"prev[ch] < start","marks":[{"type":"code"}]},{"type":"text","text":") must not pull "},{"type":"text","text":"start","marks":[{"type":"code"}]},{"type":"text","text":" backwards. In "},{"type":"text","text":"\"abba\"","marks":[{"type":"code"}]},{"type":"text","text":" at "},{"type":"text","text":"j = 3","marks":[{"type":"code"}]},{"type":"text","text":" the earlier "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" is at 0, but the window already starts at 2."}]}]}},"revision":1},{"id":"190fb493-ab33-7684-9536-ddc653081000","type":"heading","position":"b0p","content":{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]},"revision":1},{"id":"59f6bbab-6c8c-7b9b-94cb-9f96e426b1be","type":"question","position":"b0q","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KMP or Rabin–Karp — when do you pick which?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KMP gives a guaranteed "},{"type":"text","text":"O(n + m)","marks":[{"type":"code"}]},{"type":"text","text":" for one pattern and is the safe default. Rabin–Karp shines when you search for "},{"type":"text","text":"many patterns of the same length","marks":[{"type":"bold"}]},{"type":"text","text":" at once (hash each pattern into a set, then one rolling pass over the text), or for 2-D / plagiarism-style matching where hashes of many windows must be compared. Its worst case is "},{"type":"text","text":"O(n · m)","marks":[{"type":"code"}]},{"type":"text","text":", so it is a poor fit for adversarial inputs."}]}]}},"revision":1},{"id":"2abd43ec-6960-786f-afa0-b35c80221550","type":"question","position":"b0r","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What exactly does lps[i] mean, and why is it the right amount to fall back?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"lps[i]","marks":[{"type":"code"}]},{"type":"text","text":" is the length of the longest "},{"type":"text","text":"proper","marks":[{"type":"italic"}]},{"type":"text","text":" prefix of "},{"type":"text","text":"pat[0..i]","marks":[{"type":"code"}]},{"type":"text","text":" that is also a suffix of it. On a mismatch after matching "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" characters, the text we just consumed ends with "},{"type":"text","text":"pat[0..j−1]","marks":[{"type":"code"}]},{"type":"text","text":"; its longest proper prefix-suffix ("},{"type":"text","text":"lps[j−1]","marks":[{"type":"code"}]},{"type":"text","text":" characters) is the longest stretch of that text that could still be the "},{"type":"text","text":"beginning","marks":[{"type":"italic"}]},{"type":"text","text":" of a match. Anything longer is ruled out by maximality, and anything shorter would skip a possible match — so "},{"type":"text","text":"lps[j−1]","marks":[{"type":"code"}]},{"type":"text","text":" is exactly the safe shift."}]}]}},"revision":1},{"id":"9bb0b1e9-92dd-79e8-9bd0-8f2c236f46d8","type":"question","position":"b0s","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is KMP O(n + m) when it has a loop that does not advance i?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Charge each iteration to either "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":". Iterations that match advance "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" (at most "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" of them). Iterations that fall back strictly decrease "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" only grows together with "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":", so there can be at most "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" fall-backs in total. The LPS construction is the same argument over "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"0303c770-1a16-7184-9dde-cfdffd820fb6","type":"question","position":"b0t","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Rabin–Karp hash matched but the strings differ — is the algorithm wrong?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No, that is a "},{"type":"text","text":"spurious hit","marks":[{"type":"bold"}]},{"type":"text","text":", expected behaviour of any hash modulo "},{"type":"text","text":"q","marks":[{"type":"code"}]},{"type":"text","text":". Correctness comes from the character-by-character verification that runs only when hashes agree; the hash merely filters candidates. Pick a large prime (and 64-bit arithmetic) so spurious hits are rare, which keeps the "},{"type":"text","text":"expected","marks":[{"type":"italic"}]},{"type":"text","text":" time linear."}]}]}},"revision":1},{"id":"41e0e725-544a-7eb2-832c-b04ea02a8242","type":"question","position":"b0u","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you return the anagram positions instead of Yes/No, and the substring instead of the length?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Anagram search: whenever "},{"type":"text","text":"ct == cp","marks":[{"type":"code"}]},{"type":"text","text":" for the window starting at "},{"type":"text","text":"i − m","marks":[{"type":"code"}]},{"type":"text","text":", record "},{"type":"text","text":"i − m","marks":[{"type":"code"}]},{"type":"text","text":" and continue instead of returning. Longest distinct substring: whenever "},{"type":"text","text":"j − start + 1","marks":[{"type":"code"}]},{"type":"text","text":" improves "},{"type":"text","text":"best","marks":[{"type":"code"}]},{"type":"text","text":", also remember "},{"type":"text","text":"start","marks":[{"type":"code"}]},{"type":"text","text":"; the answer is "},{"type":"text","text":"s[start..start+best−1]","marks":[{"type":"code"}]},{"type":"text","text":". Both keep the same complexity."}]}]}},"revision":1},{"id":"18eeb243-1a8d-729b-a64e-0009bda2f3f3","type":"question","position":"b0v","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lexicographic rank with repeated characters?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Permutations with repeats are counted by the multinomial "},{"type":"text","text":"n! / (c1! · c2! · …)","marks":[{"type":"code"}]},{"type":"text","text":". At position "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":", for each unused character smaller than "},{"type":"text","text":"s[i]","marks":[{"type":"code"}]},{"type":"text","text":", add "},{"type":"text","text":"(n − i − 1)! / Π(count of each remaining character)!","marks":[{"type":"code"}]},{"type":"text","text":" where that character''s count is reduced by one. Same scan, one extra division per step; precompute factorials once."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
