INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'c121717f-29c6-7abf-8b36-32faf6b09064', 'daed7b4d-94f2-7d8c-8144-fb57d2bded98', 1, 'PUBLISHED', 'Trie Data Structure', '[{"id":"a046114c-b661-7ce5-a604-bb696b88ac09","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A trie (prefix tree) stores a set of words as a tree of characters, so that every operation costs time proportional to the "},{"type":"text","text":"length of the word","marks":[{"type":"bold"}]},{"type":"text","text":" — not to the number of words — and so that words sharing a prefix share a path. It is the structure behind autocomplete, spell-checkers and IP routing tables."}]}]}},"revision":1},{"id":"00b1fcd0-c3da-72d9-bc46-2c2e6df79f80","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Trie","marks":[{"type":"bold"}]},{"type":"text","text":" — a rooted tree in which every edge is labelled with a character and every node represents the prefix spelled out by the path from the root. A flag on a node marks that this prefix is a complete word. The root represents the empty string."}]}]}},"revision":1},{"id":"afc5d40c-204b-7f41-89c6-3560b0e75d9c","type":"code","position":"a2","content":{"language":"text","code":"         (root)\n  ┌────────┼────────┐\n  b        c        g\n  │     ┌──┴──┐     │\n  a     a     u     e\n┌─┴─┐   │     │     │\nd*  t*  t*    t*    e\n                    │\n                    k*          * = isEndOfWord\n                    │\n                    s*","filename":"Trie for { geeks, geek, bad, bat, cat, cut } — \"geek\" and \"geeks\" share one path, \"ba\" is a prefix of two words"},"revision":1},{"id":"b11f6208-ef13-7e2a-91d8-a63eeee083a9","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tries are the right choice when a dictionary of words must support these operations efficiently:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Search","marks":[{"type":"bold"}]},{"type":"text","text":" — is this exact word in the dictionary?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Insert","marks":[{"type":"bold"}]},{"type":"text","text":" — add a word."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Delete","marks":[{"type":"bold"}]},{"type":"text","text":" — remove a word (without disturbing words that share its prefix)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefix search","marks":[{"type":"bold"}]},{"type":"text","text":" — does any word start with "},{"type":"text","text":"pre","marks":[{"type":"code"}]},{"type":"text","text":"? List them all (autocomplete)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lexicographic ordering","marks":[{"type":"bold"}]},{"type":"text","text":" — a pre-order traversal visits the words in sorted order for free."}]}]}]}]}},"revision":1},{"id":"5d163287-968c-7612-a3b8-bb17ed04889f","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Trie"}],[{"type":"text","text":"Hash table"}]],[[{"type":"text","text":"Search"}],[{"type":"text","text":"Θ(word_len)"}],[{"type":"text","text":"Θ(word_len) average"}]],[[{"type":"text","text":"Insert"}],[{"type":"text","text":"Θ(word_len)"}],[{"type":"text","text":"Θ(word_len) average"}]],[[{"type":"text","text":"Delete"}],[{"type":"text","text":"Θ(word_len)"}],[{"type":"text","text":"Θ(word_len) average"}]],[[{"type":"text","text":"Prefix search"}],[{"type":"text","text":"Θ(prefix_len)"}],[{"type":"text","text":"not supported"}]],[[{"type":"text","text":"Lexicographic ordering"}],[{"type":"text","text":"Θ(output_len)"}],[{"type":"text","text":"not supported (needs a sort)"}]],[[{"type":"text","text":"Memory"}],[{"type":"text","text":"high — up to 26 pointers per node"}],[{"type":"text","text":"low"}]]]},"revision":1},{"id":"1ecfabf7-f1bc-744f-8e7f-0bdc91d28d83","type":"callout","position":"a5","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A hash table matches a trie on exact-match operations, and uses far less memory. Reach for a trie only when you need "},{"type":"text","text":"prefix","marks":[{"type":"bold"}]},{"type":"text","text":" queries or "},{"type":"text","text":"sorted","marks":[{"type":"bold"}]},{"type":"text","text":" output — those are the operations a hash table simply cannot do."}]}]}},"revision":1},{"id":"5247617d-9c48-71c4-b374-f3cb736b8e30","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Trie representation"}]},"revision":1},{"id":"695e0d04-138c-757d-8849-7b94b69fa65c","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For lowercase English words each node holds an array of 26 child pointers (index "},{"type":"text","text":"ch − ''a''","marks":[{"type":"code"}]},{"type":"text","text":") and a boolean "},{"type":"text","text":"isEndOfWord","marks":[{"type":"code"}]},{"type":"text","text":". The characters themselves are not stored in the nodes — they are implied by the array index on the way down."}]}]}},"revision":1},{"id":"6b28d594-c6f8-7b1b-945e-79172c9995b4","type":"code","position":"a8","content":{"language":"python","code":"class TrieNode:\n    def __init__(self):\n        self.child = [None] * 26          # child[i] → node for chr(ord(''a'') + i), or None\n        self.is_end_of_word = False       # True ⇔ the path from the root spells a stored word\n\nroot = TrieNode()                         # the empty trie: a root with no children\nprint(sum(c is not None for c in root.child), root.is_end_of_word)","filename":"Python"},"revision":1},{"id":"adcb26d5-4c0d-7c9b-abce-e4b27f01c864","type":"code","position":"a9","content":{"language":"text","code":"0 False","filename":"Output"},"revision":1},{"id":"863bdf76-3671-7fe8-84c9-ae83fd600706","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Field"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"child[26]","marks":[{"type":"code"}]}],[{"type":"text","text":"one slot per letter; "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"nullptr","marks":[{"type":"code"}]},{"type":"text","text":" means no word continues with that letter"}]],[[{"type":"text","text":"isEndOfWord","marks":[{"type":"code"}]}],[{"type":"text","text":"marks a complete word — needed because "},{"type":"text","text":"geek","marks":[{"type":"code"}]},{"type":"text","text":" must be found while "},{"type":"text","text":"gee","marks":[{"type":"code"}]},{"type":"text","text":" must not"}]]]},"revision":1},{"id":"853cadc2-c768-7f61-9315-27651b567307","type":"callout","position":"aB","content":{"variant":"note","title":"Variants","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Alphabets larger than 26 letters (Unicode, arbitrary bytes) use a hash map from character to child instead of a fixed array — slower per step, but the memory no longer scales with the alphabet size."}]}]}},"revision":1},{"id":"59247906-ff0f-7fef-ad33-49366eb66e85","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Insert, search and prefix search"}]},"revision":1},{"id":"0a772810-8498-711d-93fe-88bd80e88aec","type":"callout","position":"aD","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"insert geeks, geek, bad, bat, cat, cut; search(\"geek\")","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"search(\"gee\")","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"false (a prefix, not a word)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"startsWith(\"ge\")","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"true","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"89f0770a-1c30-7370-b996-bac69c752cbc","type":"callout","position":"aE","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"All three walk the same path. "},{"type":"text","text":"Insert","marks":[{"type":"bold"}]},{"type":"text","text":" creates the missing child at every step and marks the final node. "},{"type":"text","text":"Search","marks":[{"type":"bold"}]},{"type":"text","text":" stops with "},{"type":"text","text":"false","marks":[{"type":"code"}]},{"type":"text","text":" as soon as a child is missing and, at the end, returns the "},{"type":"text","text":"isEndOfWord","marks":[{"type":"code"}]},{"type":"text","text":" flag. "},{"type":"text","text":"Prefix search","marks":[{"type":"bold"}]},{"type":"text","text":" is search without the final flag check."}]}]}},"revision":1},{"id":"40f6849f-c33f-743d-b6c1-a8c544efdf63","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Start at the root","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"with the first character of the key."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Follow child[ch − ''a'']","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"insert: create the node if it is missing — search: return "},{"type":"text","text":"false","marks":[{"type":"code"}]},{"type":"text","text":" if it is missing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the last character","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"insert: set "},{"type":"text","text":"isEndOfWord = true","marks":[{"type":"code"}]},{"type":"text","text":" — search: return "},{"type":"text","text":"isEndOfWord","marks":[{"type":"code"}]},{"type":"text","text":" — startsWith: return "},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"9761dbb7-2d5d-7e44-b839-d46de594118a","type":"code","position":"aG","content":{"language":"python","code":"class TrieNode:\n    def __init__(self):\n        self.child = [None] * 26\n        self.is_end_of_word = False\n\nclass Trie:\n    def __init__(self):\n        self.root = TrieNode()\n\n    def insert(self, key):\n        node = self.root\n        for ch in key:\n            i = ord(ch) - ord(''a'')\n            if node.child[i] is None:            # extend the path where it stops\n                node.child[i] = TrieNode()\n            node = node.child[i]\n        node.is_end_of_word = True               # mark the complete word\n\n    def _walk(self, key):                        # node where `key` ends, or None\n        node = self.root\n        for ch in key:\n            node = node.child[ord(ch) - ord(''a'')]\n            if node is None:\n                return None\n        return node\n\n    def search(self, key):\n        node = self._walk(key)\n        return node is not None and node.is_end_of_word\n\n    def starts_with(self, prefix):\n        return self._walk(prefix) is not None\n\n    def words(self):                             # pre-order traversal → lexicographic order\n        out = []\n        def dfs(node, prefix):\n            if node.is_end_of_word:\n                out.append(prefix)\n            for i, c in enumerate(node.child):\n                if c is not None:\n                    dfs(c, prefix + chr(ord(''a'') + i))\n        dfs(self.root, \"\")\n        return out\n\ntrie = Trie()\nfor w in [\"geeks\", \"geek\", \"bad\", \"bat\", \"cat\", \"cut\"]:\n    trie.insert(w)\nfor w in [\"geek\", \"gee\", \"cut\", \"dog\"]:\n    print(f\"search {w}:\", \"true\" if trie.search(w) else \"false\")\nfor pre in [\"ge\", \"do\"]:\n    print(f\"startsWith {pre}:\", \"true\" if trie.starts_with(pre) else \"false\")\nprint(\"words:\", \" \".join(trie.words()))","filename":"Python"},"revision":1},{"id":"aabfd797-401c-7775-bed0-5024147da119","type":"code","position":"aH","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct TrieNode {\n    TrieNode* child[26] = {};\n    bool isEndOfWord = false;\n};\n\nclass Trie {\n    TrieNode* root = new TrieNode();\n    TrieNode* walk(const string& key) const {           // node where `key` ends, or nullptr\n        TrieNode* node = root;\n        for (char ch : key) {\n            node = node->child[ch - ''a''];\n            if (!node) return nullptr;\n        }\n        return node;\n    }\n    void dfs(TrieNode* node, string& prefix, vector<string>& out) const {\n        if (node->isEndOfWord) out.push_back(prefix);\n        for (int i = 0; i < 26; i++)\n            if (node->child[i]) {\n                prefix.push_back(''a'' + i);\n                dfs(node->child[i], prefix, out);\n                prefix.pop_back();\n            }\n    }\npublic:\n    void insert(const string& key) {\n        TrieNode* node = root;\n        for (char ch : key) {\n            int i = ch - ''a'';\n            if (!node->child[i]) node->child[i] = new TrieNode();   // extend the path where it stops\n            node = node->child[i];\n        }\n        node->isEndOfWord = true;                                   // mark the complete word\n    }\n    bool search(const string& key) const { TrieNode* n = walk(key); return n && n->isEndOfWord; }\n    bool startsWith(const string& prefix) const { return walk(prefix) != nullptr; }\n    vector<string> words() const { vector<string> out; string p; dfs(root, p, out); return out; }   // sorted\n};\n\nint main() {\n    Trie trie;\n    for (string w : {\"geeks\", \"geek\", \"bad\", \"bat\", \"cat\", \"cut\"}) trie.insert(w);\n    for (string w : {\"geek\", \"gee\", \"cut\", \"dog\"}) cout << \"search \" << w << \": \" << (trie.search(w) ? \"true\" : \"false\") << \"\\n\";\n    for (string p : {\"ge\", \"do\"}) cout << \"startsWith \" << p << \": \" << (trie.startsWith(p) ? \"true\" : \"false\") << \"\\n\";\n    cout << \"words:\";\n    for (const string& w : trie.words()) cout << \" \" << w;\n    cout << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"f6bd06c9-d30d-7ddb-be76-e229fbee76dd","type":"code","position":"aI","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static class TrieNode {\n        TrieNode[] child = new TrieNode[26];\n        boolean isEndOfWord;\n    }\n\n    static class Trie {\n        TrieNode root = new TrieNode();\n\n        void insert(String key) {\n            TrieNode node = root;\n            for (char ch : key.toCharArray()) {\n                int i = ch - ''a'';\n                if (node.child[i] == null) node.child[i] = new TrieNode();   // extend the path where it stops\n                node = node.child[i];\n            }\n            node.isEndOfWord = true;                                          // mark the complete word\n        }\n        TrieNode walk(String key) {                                           // node where key ends, or null\n            TrieNode node = root;\n            for (char ch : key.toCharArray()) {\n                node = node.child[ch - ''a''];\n                if (node == null) return null;\n            }\n            return node;\n        }\n        boolean search(String key) { TrieNode n = walk(key); return n != null && n.isEndOfWord; }\n        boolean startsWith(String prefix) { return walk(prefix) != null; }\n        List<String> words() { List<String> out = new ArrayList<>(); dfs(root, new StringBuilder(), out); return out; }\n        void dfs(TrieNode node, StringBuilder prefix, List<String> out) {     // pre-order → sorted\n            if (node.isEndOfWord) out.add(prefix.toString());\n            for (int i = 0; i < 26; i++)\n                if (node.child[i] != null) {\n                    prefix.append((char) (''a'' + i));\n                    dfs(node.child[i], prefix, out);\n                    prefix.setLength(prefix.length() - 1);\n                }\n        }\n    }\n\n    public static void main(String[] args) {\n        Trie trie = new Trie();\n        for (String w : new String[]{\"geeks\", \"geek\", \"bad\", \"bat\", \"cat\", \"cut\"}) trie.insert(w);\n        for (String w : new String[]{\"geek\", \"gee\", \"cut\", \"dog\"}) System.out.println(\"search \" + w + \": \" + trie.search(w));\n        for (String p : new String[]{\"ge\", \"do\"}) System.out.println(\"startsWith \" + p + \": \" + trie.startsWith(p));\n        System.out.println(\"words: \" + String.join(\" \", trie.words()));\n    }\n}","filename":"Java"},"revision":1},{"id":"c4526376-d053-7f8e-bf03-df8f54856891","type":"code","position":"aJ","content":{"language":"javascript","code":"class TrieNode {\n    constructor() { this.child = new Array(26).fill(null); this.isEndOfWord = false; }\n}\n\nclass Trie {\n    constructor() { this.root = new TrieNode(); }\n    insert(key) {\n        let node = this.root;\n        for (const ch of key) {\n            const i = ch.charCodeAt(0) - 97;\n            if (node.child[i] === null) node.child[i] = new TrieNode();   // extend the path where it stops\n            node = node.child[i];\n        }\n        node.isEndOfWord = true;                                           // mark the complete word\n    }\n    walk(key) {                                                            // node where key ends, or null\n        let node = this.root;\n        for (const ch of key) {\n            node = node.child[ch.charCodeAt(0) - 97];\n            if (node === null) return null;\n        }\n        return node;\n    }\n    search(key) { const n = this.walk(key); return n !== null && n.isEndOfWord; }\n    startsWith(prefix) { return this.walk(prefix) !== null; }\n    words() {                                                              // pre-order → sorted\n        const out = [];\n        const dfs = (node, prefix) => {\n            if (node.isEndOfWord) out.push(prefix);\n            node.child.forEach((c, i) => { if (c !== null) dfs(c, prefix + String.fromCharCode(97 + i)); });\n        };\n        dfs(this.root, \"\");\n        return out;\n    }\n}\n\nconst trie = new Trie();\nfor (const w of [\"geeks\", \"geek\", \"bad\", \"bat\", \"cat\", \"cut\"]) trie.insert(w);\nfor (const w of [\"geek\", \"gee\", \"cut\", \"dog\"]) console.log(`search ${w}:`, trie.search(w));\nfor (const p of [\"ge\", \"do\"]) console.log(`startsWith ${p}:`, trie.startsWith(p));\nconsole.log(\"words:\", trie.words().join(\" \"));","filename":"JavaScript"},"revision":1},{"id":"237bc79b-4078-70fe-abdd-d99e81d712d2","type":"code","position":"aK","content":{"language":"text","code":"search geek: true\nsearch gee: false\nsearch cut: true\nsearch dog: false\nstartsWith ge: true\nstartsWith do: false\nwords: bad bat cat cut geek geeks","filename":"Output"},"revision":1},{"id":"36c1c513-f565-7828-ac4b-e168f0111eef","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(L) per insert / search / startsWith for a word of length L · Space O(total characters × alphabet) for the trie"}]}]}},"revision":1},{"id":"ffca1c83-8d8a-7f1f-a336-6b4a860452af","type":"callout","position":"aM","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Returning "},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"search","marks":[{"type":"code"}]},{"type":"text","text":" as soon as the walk succeeds finds "},{"type":"text","text":"\"gee\"","marks":[{"type":"code"}]},{"type":"text","text":" even though only "},{"type":"text","text":"\"geek\"","marks":[{"type":"code"}]},{"type":"text","text":" was inserted. The final "},{"type":"text","text":"isEndOfWord","marks":[{"type":"code"}]},{"type":"text","text":" check is what separates "},{"type":"text","text":"search","marks":[{"type":"italic"}]},{"type":"text","text":" from "},{"type":"text","text":"startsWith","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"26860103-838a-7dd5-a590-c0ed031a0636","type":"heading","position":"aN","content":{"level":1,"content":[{"type":"text","text":"Delete"}]},"revision":1},{"id":"71104193-72a8-7a5e-af27-ad4a1db0495b","type":"text","position":"aO","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Deleting must remove the word without breaking any other word that shares its path. "},{"type":"text","text":"geeks","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"geek","marks":[{"type":"code"}]},{"type":"text","text":" share "},{"type":"text","text":"g-e-e-k","marks":[{"type":"code"}]},{"type":"text","text":"; deleting "},{"type":"text","text":"geeks","marks":[{"type":"code"}]},{"type":"text","text":" may remove only the "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" node, and deleting "},{"type":"text","text":"geek","marks":[{"type":"code"}]},{"type":"text","text":" must only clear a flag."}]}]}},"revision":1},{"id":"b488614a-b43c-7e1a-96a0-f8eb757a370b","type":"callout","position":"aP","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"insert geeks, geek, bad, bat, cat, cut; delete(\"geeks\")","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"search(\"geeks\") = false, search(\"geek\") = true","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"delete(\"bad\")","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"search(\"bad\") = false, search(\"bat\") = true","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"df6d2705-89ea-7a04-9f80-8bfb53093cc6","type":"callout","position":"aQ","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Write a recursive function that walks down to the last character. On the way "},{"type":"text","text":"back up","marks":[{"type":"bold"}]},{"type":"text","text":": clear "},{"type":"text","text":"isEndOfWord","marks":[{"type":"code"}]},{"type":"text","text":" at the last node; then delete a node only if it is "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" the end of another word "},{"type":"text","text":"and","marks":[{"type":"bold"}]},{"type":"text","text":" has no children. Deletion stops at the first node that is still needed."}]}]}},"revision":1},{"id":"63d7ffd2-5939-7be4-9641-d96402af6a8c","type":"text","position":"aR","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recurse to the node of the last character","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"depth == len(key)","marks":[{"type":"code"}]},{"type":"text","text":": unmark "},{"type":"text","text":"isEndOfWord","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is this node now useless?","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"No children and not the end of any word → return "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" so the parent drops its pointer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk back up","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Each parent re-checks: if it is not a word end and has no children left, it is removed as well. The first node that still serves another word stops the chain."}]}]}]}]}},"revision":1},{"id":"06adbe6e-27ea-7e54-b0d3-8ccb8df188ba","type":"code","position":"aS","content":{"language":"text","code":"delete(\"geeks\")              delete(\"bad\")                 delete(\"geek\")\ng-e-e-k*-s*                  b-a-d*                        g-e-e-k*\n         └ unmark s,         a-t*                                  └ unmark k; k is a leaf → remove\n           s has no          └ unmark d; d is a leaf        e has no children now → remove\n           children →          → remove d; a still has     e → remove, g → remove\n           remove s            child t → stop              root stays (it also has b, c)\nk keeps its * — geek lives on","filename":"The three cases: remove a leaf, stop at a shared node, remove a whole chain"},"revision":1},{"id":"e8c73036-94c9-7a3f-bedd-77be92121149","type":"code","position":"aT","content":{"language":"python","code":"class TrieNode:\n    def __init__(self):\n        self.child = [None] * 26\n        self.is_end_of_word = False\n\nclass Trie:\n    def __init__(self):\n        self.root = TrieNode()\n\n    def insert(self, key):\n        node = self.root\n        for ch in key:\n            i = ord(ch) - ord(''a'')\n            if node.child[i] is None:\n                node.child[i] = TrieNode()\n            node = node.child[i]\n        node.is_end_of_word = True\n\n    def _walk(self, key):\n        node = self.root\n        for ch in key:\n            node = node.child[ord(ch) - ord(''a'')]\n            if node is None:\n                return None\n        return node\n\n    def search(self, key):\n        node = self._walk(key)\n        return node is not None and node.is_end_of_word\n\n    def starts_with(self, prefix):\n        return self._walk(prefix) is not None\n\n    def delete(self, key):\n        def _delete(node, depth):                       # returns the node to keep, or None to drop it\n            if node is None:\n                return None\n            if depth == len(key):\n                node.is_end_of_word = False             # the word itself is gone …\n            else:\n                i = ord(key[depth]) - ord(''a'')\n                node.child[i] = _delete(node.child[i], depth + 1)\n            if node.is_end_of_word or any(c is not None for c in node.child):\n                return node                             # … but this node still serves other words\n            return None                                 # useless node: unlink it\n        self.root = _delete(self.root, 0) or TrieNode()\n\n    def words(self):\n        out = []\n        def dfs(node, prefix):\n            if node.is_end_of_word:\n                out.append(prefix)\n            for i, c in enumerate(node.child):\n                if c is not None:\n                    dfs(c, prefix + chr(ord(''a'') + i))\n        dfs(self.root, \"\")\n        return out\n\nt = Trie()\nfor w in [\"geeks\", \"geek\", \"bad\", \"bat\", \"cat\", \"cut\"]:\n    t.insert(w)\nb = lambda v: \"true\" if v else \"false\"\nt.delete(\"geeks\"); print(f\"after delete(geeks): geeks={b(t.search(''geeks''))} geek={b(t.search(''geek''))}\")\nt.delete(\"bad\");   print(f\"after delete(bad): bad={b(t.search(''bad''))} bat={b(t.search(''bat''))}\")\nt.delete(\"geek\");  print(f\"after delete(geek): geek={b(t.search(''geek''))} startsWith(ge)={b(t.starts_with(''ge''))}\")\nprint(\"words:\", \" \".join(t.words()))","filename":"Python"},"revision":1},{"id":"6a58e2e1-9da7-70a9-a72c-f32b89455332","type":"code","position":"aU","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct TrieNode {\n    TrieNode* child[26] = {};\n    bool isEndOfWord = false;\n    bool hasChild() const { for (TrieNode* c : child) if (c) return true; return false; }\n};\n\nclass Trie {\n    TrieNode* root = new TrieNode();\n    TrieNode* walk(const string& key) const {\n        TrieNode* node = root;\n        for (char ch : key) { node = node->child[ch - ''a'']; if (!node) return nullptr; }\n        return node;\n    }\n    static TrieNode* remove(TrieNode* node, const string& key, size_t depth) {   // node to keep, or nullptr\n        if (!node) return nullptr;\n        if (depth == key.size()) {\n            node->isEndOfWord = false;                              // the word itself is gone …\n        } else {\n            int i = key[depth] - ''a'';\n            node->child[i] = remove(node->child[i], key, depth + 1);\n        }\n        if (node->isEndOfWord || node->hasChild()) return node;     // … but this node still serves other words\n        delete node;                                                // useless node: unlink it\n        return nullptr;\n    }\n    void dfs(TrieNode* node, string& prefix, vector<string>& out) const {\n        if (node->isEndOfWord) out.push_back(prefix);\n        for (int i = 0; i < 26; i++)\n            if (node->child[i]) { prefix.push_back(''a'' + i); dfs(node->child[i], prefix, out); prefix.pop_back(); }\n    }\npublic:\n    void insert(const string& key) {\n        TrieNode* node = root;\n        for (char ch : key) {\n            int i = ch - ''a'';\n            if (!node->child[i]) node->child[i] = new TrieNode();\n            node = node->child[i];\n        }\n        node->isEndOfWord = true;\n    }\n    bool search(const string& key) const { TrieNode* n = walk(key); return n && n->isEndOfWord; }\n    bool startsWith(const string& p) const { return walk(p) != nullptr; }\n    void erase(const string& key) { root = remove(root, key, 0); if (!root) root = new TrieNode(); }\n    vector<string> words() const { vector<string> out; string p; dfs(root, p, out); return out; }\n};\n\nconst char* b(bool v) { return v ? \"true\" : \"false\"; }\n\nint main() {\n    Trie t;\n    for (string w : {\"geeks\", \"geek\", \"bad\", \"bat\", \"cat\", \"cut\"}) t.insert(w);\n    t.erase(\"geeks\"); cout << \"after delete(geeks): geeks=\" << b(t.search(\"geeks\")) << \" geek=\" << b(t.search(\"geek\")) << \"\\n\";\n    t.erase(\"bad\");   cout << \"after delete(bad): bad=\" << b(t.search(\"bad\")) << \" bat=\" << b(t.search(\"bat\")) << \"\\n\";\n    t.erase(\"geek\");  cout << \"after delete(geek): geek=\" << b(t.search(\"geek\")) << \" startsWith(ge)=\" << b(t.startsWith(\"ge\")) << \"\\n\";\n    cout << \"words:\";\n    for (const string& w : t.words()) cout << \" \" << w;\n    cout << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"febe0ccf-3eef-7ff2-a04e-97e597dbd09c","type":"code","position":"aV","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static class TrieNode {\n        TrieNode[] child = new TrieNode[26];\n        boolean isEndOfWord;\n        boolean hasChild() { for (TrieNode c : child) if (c != null) return true; return false; }\n    }\n\n    static class Trie {\n        TrieNode root = new TrieNode();\n\n        void insert(String key) {\n            TrieNode node = root;\n            for (char ch : key.toCharArray()) {\n                int i = ch - ''a'';\n                if (node.child[i] == null) node.child[i] = new TrieNode();\n                node = node.child[i];\n            }\n            node.isEndOfWord = true;\n        }\n        TrieNode walk(String key) {\n            TrieNode node = root;\n            for (char ch : key.toCharArray()) { node = node.child[ch - ''a'']; if (node == null) return null; }\n            return node;\n        }\n        boolean search(String key) { TrieNode n = walk(key); return n != null && n.isEndOfWord; }\n        boolean startsWith(String p) { return walk(p) != null; }\n\n        void delete(String key) { root = delete(root, key, 0); if (root == null) root = new TrieNode(); }\n        TrieNode delete(TrieNode node, String key, int depth) {           // node to keep, or null to drop it\n            if (node == null) return null;\n            if (depth == key.length()) {\n                node.isEndOfWord = false;                                 // the word itself is gone …\n            } else {\n                int i = key.charAt(depth) - ''a'';\n                node.child[i] = delete(node.child[i], key, depth + 1);\n            }\n            if (node.isEndOfWord || node.hasChild()) return node;         // … but this node still serves other words\n            return null;                                                  // useless node: unlink it\n        }\n        List<String> words() { List<String> out = new ArrayList<>(); dfs(root, new StringBuilder(), out); return out; }\n        void dfs(TrieNode node, StringBuilder prefix, List<String> out) {\n            if (node.isEndOfWord) out.add(prefix.toString());\n            for (int i = 0; i < 26; i++)\n                if (node.child[i] != null) {\n                    prefix.append((char) (''a'' + i)); dfs(node.child[i], prefix, out); prefix.setLength(prefix.length() - 1);\n                }\n        }\n    }\n\n    public static void main(String[] args) {\n        Trie t = new Trie();\n        for (String w : new String[]{\"geeks\", \"geek\", \"bad\", \"bat\", \"cat\", \"cut\"}) t.insert(w);\n        t.delete(\"geeks\"); System.out.println(\"after delete(geeks): geeks=\" + t.search(\"geeks\") + \" geek=\" + t.search(\"geek\"));\n        t.delete(\"bad\");   System.out.println(\"after delete(bad): bad=\" + t.search(\"bad\") + \" bat=\" + t.search(\"bat\"));\n        t.delete(\"geek\");  System.out.println(\"after delete(geek): geek=\" + t.search(\"geek\") + \" startsWith(ge)=\" + t.startsWith(\"ge\"));\n        System.out.println(\"words: \" + String.join(\" \", t.words()));\n    }\n}","filename":"Java"},"revision":1},{"id":"8212ba56-8678-747f-b5c8-098a409cb32f","type":"code","position":"aW","content":{"language":"javascript","code":"class TrieNode {\n    constructor() { this.child = new Array(26).fill(null); this.isEndOfWord = false; }\n    hasChild() { return this.child.some(c => c !== null); }\n}\n\nclass Trie {\n    constructor() { this.root = new TrieNode(); }\n    insert(key) {\n        let node = this.root;\n        for (const ch of key) {\n            const i = ch.charCodeAt(0) - 97;\n            if (node.child[i] === null) node.child[i] = new TrieNode();\n            node = node.child[i];\n        }\n        node.isEndOfWord = true;\n    }\n    walk(key) {\n        let node = this.root;\n        for (const ch of key) { node = node.child[ch.charCodeAt(0) - 97]; if (node === null) return null; }\n        return node;\n    }\n    search(key) { const n = this.walk(key); return n !== null && n.isEndOfWord; }\n    startsWith(p) { return this.walk(p) !== null; }\n\n    delete(key) {\n        const rec = (node, depth) => {                              // node to keep, or null to drop it\n            if (node === null) return null;\n            if (depth === key.length) {\n                node.isEndOfWord = false;                           // the word itself is gone …\n            } else {\n                const i = key.charCodeAt(depth) - 97;\n                node.child[i] = rec(node.child[i], depth + 1);\n            }\n            if (node.isEndOfWord || node.hasChild()) return node;   // … but this node still serves other words\n            return null;                                            // useless node: unlink it\n        };\n        this.root = rec(this.root, 0) ?? new TrieNode();\n    }\n    words() {\n        const out = [];\n        const dfs = (node, prefix) => {\n            if (node.isEndOfWord) out.push(prefix);\n            node.child.forEach((c, i) => { if (c !== null) dfs(c, prefix + String.fromCharCode(97 + i)); });\n        };\n        dfs(this.root, \"\");\n        return out;\n    }\n}\n\nconst t = new Trie();\nfor (const w of [\"geeks\", \"geek\", \"bad\", \"bat\", \"cat\", \"cut\"]) t.insert(w);\nt.delete(\"geeks\"); console.log(`after delete(geeks): geeks=${t.search(\"geeks\")} geek=${t.search(\"geek\")}`);\nt.delete(\"bad\");   console.log(`after delete(bad): bad=${t.search(\"bad\")} bat=${t.search(\"bat\")}`);\nt.delete(\"geek\");  console.log(`after delete(geek): geek=${t.search(\"geek\")} startsWith(ge)=${t.startsWith(\"ge\")}`);\nconsole.log(\"words:\", t.words().join(\" \"));","filename":"JavaScript"},"revision":1},{"id":"397c192d-26dd-722c-8467-a6d6cba97a38","type":"code","position":"aX","content":{"language":"text","code":"after delete(geeks): geeks=false geek=true\nafter delete(bad): bad=false bat=true\nafter delete(geek): geek=false startsWith(ge)=false\nwords: bat cat cut","filename":"Output"},"revision":1},{"id":"91d270ca-fa24-7df7-b1b3-f4d7254846ea","type":"text","position":"aY","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(L) — one pass down and one pass back up · Space O(L) recursion depth"}]}]}},"revision":1},{"id":"dfb2940e-ae70-7b3f-80f3-373b29b7e493","type":"callout","position":"aZ","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Only clearing "},{"type":"text","text":"isEndOfWord","marks":[{"type":"code"}]},{"type":"text","text":" (\"lazy delete\") keeps "},{"type":"text","text":"search","marks":[{"type":"code"}]},{"type":"text","text":" correct but leaves dead branches in memory and makes "},{"type":"text","text":"startsWith(\"ge\")","marks":[{"type":"code"}]},{"type":"text","text":" wrongly return "},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":" after every "},{"type":"text","text":"ge…","marks":[{"type":"code"}]},{"type":"text","text":" word is gone. Deleting a node that is still a word end or still has children breaks other words — check both conditions before unlinking."}]}]}},"revision":1},{"id":"a6dce0dd-4513-7d32-a630-df5faf5eebef","type":"heading","position":"aa","content":{"level":1,"content":[{"type":"text","text":"Count distinct rows in a binary matrix"}]},"revision":1},{"id":"4789c2da-bd24-7a92-861f-2ced2f91719b","type":"text","position":"ab","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given a binary matrix (every entry "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":"), count how many "},{"type":"text","text":"distinct","marks":[{"type":"bold"}]},{"type":"text","text":" rows it has."}]}]}},"revision":1},{"id":"822b2646-1326-7e51-adc4-0ebe5081c2b4","type":"callout","position":"ac","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"matrix = [[1,0,0], [1,1,1], [1,0,0], [1,1,1]]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"2","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"a004cbf1-cb0f-755a-8135-9cf4728eec15","type":"text","position":"ad","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive:","marks":[{"type":"bold"}]},{"type":"text","text":" for every row, compare it with every earlier row; count it if it matches none. "},{"type":"text","text":"R","marks":[{"type":"code"}]},{"type":"text","text":" rows, each compared with up to "},{"type":"text","text":"R","marks":[{"type":"code"}]},{"type":"text","text":" others, "},{"type":"text","text":"C","marks":[{"type":"code"}]},{"type":"text","text":" entries per comparison."}]}]}},"revision":1},{"id":"9376edd5-537f-7567-a8bc-68495ec14f82","type":"code","position":"ae","content":{"language":"python","code":"def count_distinct_rows(matrix):\n    res = 0\n    for i, row in enumerate(matrix):\n        if all(row != matrix[j] for j in range(i)):     # matches no earlier row → new\n            res += 1\n    return res\n\nprint(count_distinct_rows([[1, 0, 0], [1, 1, 1], [1, 0, 0], [1, 1, 1]]))","filename":"Python"},"revision":1},{"id":"14b21a3e-e4cb-7f83-9fac-d8f6078fee09","type":"code","position":"af","content":{"language":"text","code":"2","filename":"Output"},"revision":1},{"id":"8bbf18a7-3096-7835-b1f6-47679c7de090","type":"text","position":"ag","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(R² · C) · Space O(1)"}]}]}},"revision":1},{"id":"203d190a-c707-7447-9265-460cba1545f6","type":"callout","position":"ah","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Treat every row as a "},{"type":"text","text":"word","marks":[{"type":"italic"}]},{"type":"text","text":" over the alphabet "},{"type":"text","text":"{0, 1}","marks":[{"type":"code"}]},{"type":"text","text":" and insert it into a "},{"type":"text","text":"binary trie","marks":[{"type":"bold"}]},{"type":"text","text":" (two children per node). Insertion of a row that is already present ends at a node that is already marked — so "},{"type":"text","text":"insert","marks":[{"type":"code"}]},{"type":"text","text":" can report whether the row was new. Every row is inserted once: "},{"type":"text","text":"O(R · C)","marks":[{"type":"code"}]},{"type":"text","text":" in total."}]}]}},"revision":1},{"id":"cab79dca-d143-7ba8-a57b-2e4da0da710e","type":"code","position":"ai","content":{"language":"text","code":"rows: 1 0 0 / 1 1 1 / 1 0 0 / 1 1 1\n\n         (root)\n           │ 1\n           ●\n      0 ┌──┴──┐ 1\n        ●     ●\n      0 │     │ 1\n        ●*    ●*          two marked leaves → 2 distinct rows","filename":"A binary trie of the rows: equal rows walk the same path and hit the same leaf"},"revision":1},{"id":"082bf1a1-d0fd-7fdb-b31f-a3b38ce75224","type":"code","position":"aj","content":{"language":"python","code":"class Node:\n    def __init__(self):\n        self.child = [None, None]          # child[0] for a 0, child[1] for a 1\n        self.is_end = False\n\ndef insert_row(root, row):                 # True if the row was not present before\n    node = root\n    for bit in row:\n        if node.child[bit] is None:\n            node.child[bit] = Node()\n        node = node.child[bit]\n    if node.is_end:\n        return False                       # an identical row ended here already\n    node.is_end = True\n    return True\n\ndef count_distinct_rows(matrix):\n    root = Node()\n    return sum(1 for row in matrix if insert_row(root, row))\n\nmatrix = [[1, 0, 0], [1, 1, 1], [1, 0, 0], [1, 1, 1]]\nprint(\"distinct rows:\", count_distinct_rows(matrix))","filename":"Python"},"revision":1},{"id":"5c2191d0-dbca-71c1-b465-acac708ed742","type":"code","position":"ak","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    Node* child[2] = {nullptr, nullptr};   // child[0] for a 0, child[1] for a 1\n    bool isEnd = false;\n};\n\nbool insertRow(Node* root, const vector<int>& row) {   // true if the row was not present before\n    Node* node = root;\n    for (int bit : row) {\n        if (!node->child[bit]) node->child[bit] = new Node();\n        node = node->child[bit];\n    }\n    if (node->isEnd) return false;                     // an identical row ended here already\n    node->isEnd = true;\n    return true;\n}\n\nint countDistinctRows(const vector<vector<int>>& matrix) {\n    Node* root = new Node();\n    int res = 0;\n    for (const auto& row : matrix)\n        if (insertRow(root, row)) res++;\n    return res;\n}\n\nint main() {\n    vector<vector<int>> matrix = {{1, 0, 0}, {1, 1, 1}, {1, 0, 0}, {1, 1, 1}};\n    cout << \"distinct rows: \" << countDistinctRows(matrix) << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"91037b7b-cc88-7e13-b474-5bd3c45ca478","type":"code","position":"al","content":{"language":"java","code":"public class Main {\n    static class Node {\n        Node[] child = new Node[2];        // child[0] for a 0, child[1] for a 1\n        boolean isEnd;\n    }\n\n    static boolean insertRow(Node root, int[] row) {   // true if the row was not present before\n        Node node = root;\n        for (int bit : row) {\n            if (node.child[bit] == null) node.child[bit] = new Node();\n            node = node.child[bit];\n        }\n        if (node.isEnd) return false;                  // an identical row ended here already\n        node.isEnd = true;\n        return true;\n    }\n\n    static int countDistinctRows(int[][] matrix) {\n        Node root = new Node();\n        int res = 0;\n        for (int[] row : matrix)\n            if (insertRow(root, row)) res++;\n        return res;\n    }\n\n    public static void main(String[] args) {\n        int[][] matrix = {{1, 0, 0}, {1, 1, 1}, {1, 0, 0}, {1, 1, 1}};\n        System.out.println(\"distinct rows: \" + countDistinctRows(matrix));\n    }\n}","filename":"Java"},"revision":1},{"id":"a2f9531a-3f26-7c5e-80a5-e70bec618eb4","type":"code","position":"am","content":{"language":"javascript","code":"class Node {\n    constructor() { this.child = [null, null]; this.isEnd = false; }   // child[0] for a 0, child[1] for a 1\n}\n\nfunction insertRow(root, row) {               // true if the row was not present before\n    let node = root;\n    for (const bit of row) {\n        if (node.child[bit] === null) node.child[bit] = new Node();\n        node = node.child[bit];\n    }\n    if (node.isEnd) return false;             // an identical row ended here already\n    node.isEnd = true;\n    return true;\n}\n\nfunction countDistinctRows(matrix) {\n    const root = new Node();\n    let res = 0;\n    for (const row of matrix) if (insertRow(root, row)) res++;\n    return res;\n}\n\nconst matrix = [[1, 0, 0], [1, 1, 1], [1, 0, 0], [1, 1, 1]];\nconsole.log(\"distinct rows:\", countDistinctRows(matrix));","filename":"JavaScript"},"revision":1},{"id":"d4f166eb-04f6-73a1-b6f4-dc99c41df1e1","type":"code","position":"an","content":{"language":"text","code":"distinct rows: 2","filename":"Output"},"revision":1},{"id":"2a2d2b87-6baf-702d-adef-52269e87fba8","type":"text","position":"ao","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(R · C) · Space O(R · C) for the trie in the worst case"}]}]}},"revision":1},{"id":"2d5a2345-f16d-70e5-bf7e-e2148fab0202","type":"callout","position":"ap","content":{"variant":"note","title":"Alternative","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A hash set of rows (as tuples / strings) also solves this in "},{"type":"text","text":"O(R · C)","marks":[{"type":"code"}]},{"type":"text","text":" expected time and is shorter to write. The trie answers two things the set cannot: it can list the distinct rows in "},{"type":"text","text":"sorted order","marks":[{"type":"bold"}]},{"type":"text","text":", and its memory is shared across rows with equal prefixes."}]}]}},"revision":1},{"id":"4460a3c7-db2b-79b4-9a40-1148fd4e69f2","type":"heading","position":"aq","content":{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]},"revision":1},{"id":"b8afb482-1bdb-7c0f-ad5f-86c8bd323472","type":"question","position":"ar","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you choose a trie over a hash map?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the workload needs "},{"type":"text","text":"prefix","marks":[{"type":"bold"}]},{"type":"text","text":" operations — autocomplete, \"does any key start with…\", longest-prefix match (IP routing) — or "},{"type":"text","text":"sorted","marks":[{"type":"bold"}]},{"type":"text","text":" enumeration of the keys. For pure exact-match lookups a hash map is faster and uses far less memory."}]}]}},"revision":1},{"id":"061ec4f7-df22-78d0-835a-bf5a7d808ddc","type":"question","position":"as","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the space complexity of a trie, and how can it be reduced?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Worst case "},{"type":"text","text":"O(N · L · A)","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"N","marks":[{"type":"code"}]},{"type":"text","text":" words of length "},{"type":"text","text":"L","marks":[{"type":"code"}]},{"type":"text","text":" over an alphabet of size "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":", because every node reserves "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":" child slots. Reduce it with a hash map or sorted list of children per node (only the children that exist), with a "},{"type":"text","text":"compressed trie / radix tree","marks":[{"type":"bold"}]},{"type":"text","text":" that merges chains of single-child nodes, or with a "},{"type":"text","text":"ternary search tree","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"09fa3da9-3359-7f07-8faa-c952242efd21","type":"question","position":"at","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you implement autocomplete with a trie?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk down the prefix ("},{"type":"text","text":"O(P)","marks":[{"type":"code"}]},{"type":"text","text":"); if the walk fails there are no completions. Otherwise do a DFS from that node, appending characters, and emit every node with "},{"type":"text","text":"isEndOfWord","marks":[{"type":"code"}]},{"type":"text","text":". The DFS visits the children in alphabetical order, so the suggestions come out sorted. Store a "},{"type":"text","text":"count","marks":[{"type":"italic"}]},{"type":"text","text":" or "},{"type":"text","text":"top-k","marks":[{"type":"italic"}]},{"type":"text","text":" list in each node to rank suggestions without a full traversal."}]}]}},"revision":1},{"id":"d8c71117-3d50-7a21-9fe2-a4c1fa839cf3","type":"question","position":"au","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does a trie give lexicographic order for free?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A pre-order traversal that visits the children in index order ("},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" before "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" before "},{"type":"text","text":"c","marks":[{"type":"code"}]},{"type":"text","text":"…) reaches every word end in dictionary order, because a shorter word is a prefix of the longer ones below it and siblings are visited alphabetically. This is also why "},{"type":"text","text":"words()","marks":[{"type":"code"}]},{"type":"text","text":" above prints "},{"type":"text","text":"bad bat cat cut geek geeks","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"83032c5a-5830-73d4-ac19-92534e936ce1","type":"question","position":"av","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What goes wrong if delete just clears the end-of-word flag?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Searches stay correct, but memory for dead branches is never reclaimed, and "},{"type":"text","text":"startsWith","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":" for prefixes that no longer lead to any word. Proper deletion removes nodes bottom-up while they are unmarked and childless, stopping at the first node another word still uses."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'daed7b4d-94f2-7d8c-8144-fb57d2bded98' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
