SELECT '1342ed89-4283-7090-85a3-1776d3db0dcf', 'cec69b52-08d5-7521-abe2-39bdd69edb79', 1, 'PUBLISHED', 'Regular Expression Matching', '[{"id":"d0e42483-2ff5-7149-9352-30e22eb9e834","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Hard","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 10","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/regular-expression-matching/"}}]}]}]}},"revision":1},{"id":"0856941f-4365-7c52-a5c6-96c53ecef2bb","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"0865e43c-0db1-7e2a-ad75-a921040f78d8","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given input string "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" and pattern "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":", implement regex matching with "},{"type":"text","text":"''.''","marks":[{"type":"code"}]},{"type":"text","text":" (matches any single char) and "},{"type":"text","text":"''*''","marks":[{"type":"code"}]},{"type":"text","text":" (matches zero or more of preceding element)."}]}]}},"revision":1},{"id":"dfb13d26-59fa-7d05-aec2-3a91ef984b4f","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"1832ff13-ee52-7de5-a8ee-60e677ac6b3e","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursive branching occurs whenever "},{"type":"text","text":"*","marks":[{"type":"code"}]},{"type":"text","text":" appears in pattern. State is represented by pair of indices "},{"type":"text","text":"(i, j)","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"2232979c-43b4-7012-a51d-4c35f451abb1","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"888b52a9-e032-74b6-a4f5-24fb6d9a9362","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cache recursive subproblems with hash table "},{"type":"text","text":"memo[(i, j)]","marks":[{"type":"code"}]},{"type":"text","text":" storing boolean results for matching "},{"type":"text","text":"s[i:]","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"p[j:]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"984644d8-143f-7906-a45f-1cce2cc36c2a","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"33310e75-b2c4-71e7-8913-17d55339570a","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize "},{"type":"text","text":"memo = {}","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In "},{"type":"text","text":"dfs(i, j)","marks":[{"type":"code"}]},{"type":"text","text":": check if "},{"type":"text","text":"(i, j)","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"memo","marks":[{"type":"code"}]},{"type":"text","text":". If "},{"type":"text","text":"j == len(p)","marks":[{"type":"code"}]},{"type":"text","text":" return "},{"type":"text","text":"i == len(s)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check "},{"type":"text","text":"first_match = i < len(s) and (p[j] == s[i] or p[j] == ''.'')","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"j + 1 < len(p) and p[j+1] == ''*''","marks":[{"type":"code"}]},{"type":"text","text":": set "},{"type":"text","text":"answer = dfs(i, j+2) or (first_match and dfs(i+1, j))","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Else: set "},{"type":"text","text":"answer = first_match and dfs(i+1, j+1)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Store "},{"type":"text","text":"memo[(i, j)] = answer","marks":[{"type":"code"}]},{"type":"text","text":" and return."}]}]}]}]}},"revision":1},{"id":"c07b0f7f-5722-71d5-a038-11186d67c04f","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Recursion"}]},"revision":1},{"id":"e2bef14a-e090-7884-b584-813aaed24660","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursive branching when "},{"type":"text","text":"*","marks":[{"type":"code"}]},{"type":"text","text":" appears in pattern."}]}]}},"revision":1},{"id":"5a8f87eb-e52d-77ac-b9f3-b7dd96a01b38","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def isMatch(self, s, p):\n\n        def dfs(i, j):\n\n            if j == len(p):\n                return i == len(s)\n\n            first_match = (\n                i < len(s)\n                and (\n                    p[j] == s[i]\n                    or p[j] == \".\"\n                )\n            )\n\n            if (\n                j + 1 < len(p)\n                and p[j + 1] == \"*\"\n            ):\n                return (\n                    dfs(i, j + 2)\n                    or\n                    (\n                        first_match\n                        and dfs(i + 1, j)\n                    )\n                )\n\n            return (\n                first_match\n                and dfs(i + 1, j + 1)\n            )\n\n        return dfs(0, 0)","filename":"Python"},"revision":1},{"id":"2156deff-5927-7d8e-b392-68553e01a276","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    bool isMatch(string s, string p) {\n        return dfs(s, p, 0, 0);\n    }\n\nprivate:\n    bool dfs(const string& s, const string& p, int i, int j) {\n        if (j == (int)p.size()) return i == (int)s.size();\n\n        bool firstMatch = i < (int)s.size() && (p[j] == s[i] || p[j] == ''.'');\n\n        if (j + 1 < (int)p.size() && p[j + 1] == ''*'') {\n            return dfs(s, p, i, j + 2) || (firstMatch && dfs(s, p, i + 1, j));\n        }\n\n        return firstMatch && dfs(s, p, i + 1, j + 1);\n    }\n};","filename":"C++"},"revision":1},{"id":"45e29e24-1450-7f0c-bac9-87e10734ee3c","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public boolean isMatch(String s, String p) {\n        return dfs(s, p, 0, 0);\n    }\n\n    private boolean dfs(String s, String p, int i, int j) {\n        if (j == p.length()) return i == s.length();\n\n        boolean firstMatch = i < s.length()\n            && (p.charAt(j) == s.charAt(i) || p.charAt(j) == ''.'');\n\n        if (j + 1 < p.length() && p.charAt(j + 1) == ''*'') {\n            return dfs(s, p, i, j + 2) || (firstMatch && dfs(s, p, i + 1, j));\n        }\n\n        return firstMatch && dfs(s, p, i + 1, j + 1);\n    }\n}","filename":"Java"},"revision":1},{"id":"0788e6c8-7690-7082-aa7c-edf1c7a3c430","type":"code","position":"aE","content":{"language":"javascript","code":"var isMatch = function(s, p) {\n    const dfs = (i, j) => {\n        if (j === p.length) return i === s.length;\n\n        const firstMatch = i < s.length && (p[j] === s[i] || p[j] === \".\");\n\n        if (j + 1 < p.length && p[j + 1] === \"*\") {\n            return dfs(i, j + 2) || (firstMatch && dfs(i + 1, j));\n        }\n\n        return firstMatch && dfs(i + 1, j + 1);\n    };\n\n    return dfs(0, 0);\n};","filename":"JavaScript"},"revision":1},{"id":"517d6c32-63b6-7baf-a75b-e9c0d4bc3c06","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: Exponential · Aux Space: O(m+n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"e1fefcb9-254d-7271-943c-7402afe9f85b","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"3ebba87c-3277-7684-96ad-792b52d35ad4","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def isMatch(self, s, p):\n\n        memo = {}\n\n        def dfs(i, j):\n\n            if (i, j) in memo:\n                return memo[(i, j)]\n\n            if j == len(p):\n                return i == len(s)\n\n            first_match = (\n                i < len(s)\n                and (\n                    p[j] == s[i]\n                    or p[j] == \".\"\n                )\n            )\n\n            if (\n                j + 1 < len(p)\n                and p[j + 1] == \"*\"\n            ):\n                answer = (\n                    dfs(i, j + 2)\n                    or\n                    (\n                        first_match\n                        and dfs(i + 1, j)\n                    )\n                )\n\n            else:\n                answer = (\n                    first_match\n                    and dfs(i + 1, j + 1)\n                )\n\n            memo[(i, j)] = answer\n            return answer\n\n        return dfs(0, 0)","filename":"Python"},"revision":1},{"id":"e75cf2b7-dda3-759c-8330-0f75ac4e5f82","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    bool isMatch(string s, string p) {\n        // memo[i][j]: -1 = not computed, 0 = false, 1 = true\n        memo.assign(s.size() + 1, vector<int>(p.size() + 1, -1));\n        return dfs(s, p, 0, 0);\n    }\n\nprivate:\n    vector<vector<int>> memo;\n\n    bool dfs(const string& s, const string& p, int i, int j) {\n        if (memo[i][j] != -1) return memo[i][j];\n\n        if (j == (int)p.size()) return i == (int)s.size();\n\n        bool firstMatch = i < (int)s.size() && (p[j] == s[i] || p[j] == ''.'');\n        bool answer;\n\n        if (j + 1 < (int)p.size() && p[j + 1] == ''*'') {\n            answer = dfs(s, p, i, j + 2) || (firstMatch && dfs(s, p, i + 1, j));\n        } else {\n            answer = firstMatch && dfs(s, p, i + 1, j + 1);\n        }\n\n        memo[i][j] = answer;\n        return answer;\n    }\n};","filename":"C++"},"revision":1},{"id":"a1c3314a-e79e-7e87-b315-8cb18f92746c","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    // memo[i][j]: null = not computed yet\n    private Boolean[][] memo;\n\n    public boolean isMatch(String s, String p) {\n        memo = new Boolean[s.length() + 1][p.length() + 1];\n        return dfs(s, p, 0, 0);\n    }\n\n    private boolean dfs(String s, String p, int i, int j) {\n        if (memo[i][j] != null) return memo[i][j];\n\n        if (j == p.length()) return i == s.length();\n\n        boolean firstMatch = i < s.length()\n            && (p.charAt(j) == s.charAt(i) || p.charAt(j) == ''.'');\n        boolean answer;\n\n        if (j + 1 < p.length() && p.charAt(j + 1) == ''*'') {\n            answer = dfs(s, p, i, j + 2) || (firstMatch && dfs(s, p, i + 1, j));\n        } else {\n            answer = firstMatch && dfs(s, p, i + 1, j + 1);\n        }\n\n        memo[i][j] = answer;\n        return answer;\n    }\n}","filename":"Java"},"revision":1},{"id":"d3ea54c4-7aa7-72db-8075-ddcfe179ea52","type":"code","position":"aK","content":{"language":"javascript","code":"var isMatch = function(s, p) {\n    const memo = new Map();\n\n    const dfs = (i, j) => {\n        const key = `${i},${j}`;\n        if (memo.has(key)) return memo.get(key);\n\n        if (j === p.length) return i === s.length;\n\n        const firstMatch = i < s.length && (p[j] === s[i] || p[j] === \".\");\n        let answer;\n\n        if (j + 1 < p.length && p[j + 1] === \"*\") {\n            answer = dfs(i, j + 2) || (firstMatch && dfs(i + 1, j));\n        } else {\n            answer = firstMatch && dfs(i + 1, j + 1);\n        }\n\n        memo.set(key, answer);\n        return answer;\n    };\n\n    return dfs(0, 0);\n};","filename":"JavaScript"},"revision":1},{"id":"3b6f5ad1-2b93-715f-8d20-f4884eae699f","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(mn) · Space: O(mn)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"a7da809f-5cc0-75db-a907-71749f2aab84","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"b7de68c8-4b6f-74d0-8d78-fff3c1ca038e","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"2D State DP / DFS + Memoization","marks":[{"type":"bold"}]},{"type":"text","text":" — Handles wildcard matching by memoizing "},{"type":"text","text":"(i, j)","marks":[{"type":"code"}]},{"type":"text","text":" states across recursive branches."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
