  ('0865e43c-0db1-7e2a-ad75-a921040f78d8', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given input string "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" and pattern "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":", implement regex matching with "},{"type":"text","text":"''.''","marks":[{"type":"code"}]},{"type":"text","text":" (matches any single char) and "},{"type":"text","text":"''*''","marks":[{"type":"code"}]},{"type":"text","text":" (matches zero or more of preceding element)."}]}]}}'),
