  ('1832ff13-ee52-7de5-a8ee-60e677ac6b3e', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursive branching occurs whenever "},{"type":"text","text":"*","marks":[{"type":"code"}]},{"type":"text","text":" appears in pattern. State is represented by pair of indices "},{"type":"text","text":"(i, j)","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
