  ('888b52a9-e032-74b6-a4f5-24fb6d9a9362', 'a6', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cache recursive subproblems with hash table "},{"type":"text","text":"memo[(i, j)]","marks":[{"type":"code"}]},{"type":"text","text":" storing boolean results for matching "},{"type":"text","text":"s[i:]","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"p[j:]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
