  ('33310e75-b2c4-71e7-8913-17d55339570a', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize "},{"type":"text","text":"memo = {}","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In "},{"type":"text","text":"dfs(i, j)","marks":[{"type":"code"}]},{"type":"text","text":": check if "},{"type":"text","text":"(i, j)","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"memo","marks":[{"type":"code"}]},{"type":"text","text":". If "},{"type":"text","text":"j == len(p)","marks":[{"type":"code"}]},{"type":"text","text":" return "},{"type":"text","text":"i == len(s)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check "},{"type":"text","text":"first_match = i < len(s) and (p[j] == s[i] or p[j] == ''.'')","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"j + 1 < len(p) and p[j+1] == ''*''","marks":[{"type":"code"}]},{"type":"text","text":": set "},{"type":"text","text":"answer = dfs(i, j+2) or (first_match and dfs(i+1, j))","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Else: set "},{"type":"text","text":"answer = first_match and dfs(i+1, j+1)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Store "},{"type":"text","text":"memo[(i, j)] = answer","marks":[{"type":"code"}]},{"type":"text","text":" and return."}]}]}]}]}}'),
  ('c07b0f7f-5722-71d5-a038-11186d67c04f', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Naive Solution — Recursion"}]}'),
  ('e2bef14a-e090-7884-b584-813aaed24660', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursive branching when "},{"type":"text","text":"*","marks":[{"type":"code"}]},{"type":"text","text":" appears in pattern."}]}]}}'),
  ('5a8f87eb-e52d-77ac-b9f3-b7dd96a01b38', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def isMatch(self, s, p):\n\n        def dfs(i, j):\n\n            if j == len(p):\n                return i == len(s)\n\n            first_match = (\n                i < len(s)\n                and (\n                    p[j] == s[i]\n                    or p[j] == \".\"\n                )\n            )\n\n            if (\n                j + 1 < len(p)\n                and p[j + 1] == \"*\"\n            ):\n                return (\n                    dfs(i, j + 2)\n                    or\n                    (\n                        first_match\n                        and dfs(i + 1, j)\n                    )\n                )\n\n            return (\n                first_match\n                and dfs(i + 1, j + 1)\n            )\n\n        return dfs(0, 0)","filename":"Python"}'),
  ('2156deff-5927-7d8e-b392-68553e01a276', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    bool isMatch(string s, string p) {\n        return dfs(s, p, 0, 0);\n    }\n\nprivate:\n    bool dfs(const string& s, const string& p, int i, int j) {\n        if (j == (int)p.size()) return i == (int)s.size();\n\n        bool firstMatch = i < (int)s.size() && (p[j] == s[i] || p[j] == ''.'');\n\n        if (j + 1 < (int)p.size() && p[j + 1] == ''*'') {\n            return dfs(s, p, i, j + 2) || (firstMatch && dfs(s, p, i + 1, j));\n        }\n\n        return firstMatch && dfs(s, p, i + 1, j + 1);\n    }\n};","filename":"C++"}'),
  ('45e29e24-1450-7f0c-bac9-87e10734ee3c', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public boolean isMatch(String s, String p) {\n        return dfs(s, p, 0, 0);\n    }\n\n    private boolean dfs(String s, String p, int i, int j) {\n        if (j == p.length()) return i == s.length();\n\n        boolean firstMatch = i < s.length()\n            && (p.charAt(j) == s.charAt(i) || p.charAt(j) == ''.'');\n\n        if (j + 1 < p.length() && p.charAt(j + 1) == ''*'') {\n            return dfs(s, p, i, j + 2) || (firstMatch && dfs(s, p, i + 1, j));\n        }\n\n        return firstMatch && dfs(s, p, i + 1, j + 1);\n    }\n}","filename":"Java"}'),
  ('0788e6c8-7690-7082-aa7c-edf1c7a3c430', 'aE', 'code', '{"language":"javascript","code":"var isMatch = function(s, p) {\n    const dfs = (i, j) => {\n        if (j === p.length) return i === s.length;\n\n        const firstMatch = i < s.length && (p[j] === s[i] || p[j] === \".\");\n\n        if (j + 1 < p.length && p[j + 1] === \"*\") {\n            return dfs(i, j + 2) || (firstMatch && dfs(i + 1, j));\n        }\n\n        return firstMatch && dfs(i + 1, j + 1);\n    };\n\n    return dfs(0, 0);\n};","filename":"JavaScript"}'),
  ('517d6c32-63b6-7baf-a75b-e9c0d4bc3c06', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: Exponential · Aux Space: O(m+n)","marks":[{"type":"bold"}]}]}]}}'),
  ('e1fefcb9-254d-7271-943c-7402afe9f85b', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
