or<int>> result;\n        dfs(root, 0, result);\n        return result;\n    }\n\nprivate:\n    void dfs(TreeNode* node, int level, vector<vector<int>>& result) {\n        if (!node) return;\n\n        if (level == (int)result.size()) result.push_back({});\n\n        result[level].push_back(node->val);\n\n        dfs(node->left, level + 1, result);\n        dfs(node->right, level + 1, result);\n    }\n};","filename":"C++"},"revision":1},{"id":"c73def73-2973-7581-b787-73ed8ab9fb4e","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public List<List<Integer>> levelOrder(TreeNode root) {\n        List<List<Integer>> result = new ArrayList<>();\n        dfs(root, 0, result);\n        return result;\n    }\n\n    private void dfs(TreeNode node, int level, List<List<Integer>> result) {\n        if (node == null) return;\n\n        if (level == result.size()) result.add(new ArrayList<>());\n\n        result.get(level).add(node.val);\n\n        dfs(node.left, level + 1, result);\n        dfs(node.right, level + 1, result);\n    }\n}","filename":"Java"},"revision":1},{"id":"b5fe1bb6-21a0-7a7c-861c-6967a03633c9","type":"code","position":"aE","content":{"language":"javascript","code":"var levelOrder = function(root) {\n    const result = [];\n\n    const dfs = (node, level) => {\n        if (!node) return;\n\n        if (level === result.length) result.push([]);\n\n        result[level].push(node.val);\n\n        dfs(node.left, level + 1);\n        dfs(node.right, level + 1);\n    };\n\n    dfs(root, 0);\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"816702f8-8bbc-7e61-80dc-9e044315fc77","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Aux Space: O(h)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"928944fd-479c-70ff-9a75-70088b6ebbeb","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"4438b18d-36f0-7cad-a0c0-c32f39996d31","type":"code","position":"aH","content":{"language":"python","code":"from collections import deque\n\nclass Solution:\n    def levelOrder(self, root):\n        if not root:\n            return []\n\n        result = []\n        queue = deque([root])\n\n        while queue:\n            level = []\n\n            for _ in range(len(queue)):\n                node = queue.popleft()\n                level.append(node.val)\n\n                if node.left:\n                    queue.append(node.left)\n\n                if node.right:\n                    queue.append(node.right)\n\n            result.append(level)\n\n        return result","filename":"Python"},"revision":1},{"id":"49d98706-fe9c-72bb-b144-2933ac4b51b7","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<vector<int>> levelOrder(TreeNode* root) {\n        if (!root) return {};\n\n        vector<vector<int>> result;\n        queue<TreeNode*> q;\n        q.push(root);\n\n        while (!q.empty()) {\n            vector<int> level;\n\n            for (int i = q.size(); i > 0; i--) {\n                TreeNode* node = q.front();\n                q.pop();\n                level.push_back(node->val);\n\n                if (node->left) q.push(node->left);\n                if (node->right) q.push(node->right);\n            }\n\n            result.push_back(level);\n        }\n\n        return result;\n    }\n};","filename":"C++"},"revision":1},{"id":"77a295a4-60fb-7826-892d-831790c64b20","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public List<List<Integer>> levelOrder(TreeNode root) {\n        List<List<Integer>> result = new ArrayList<>();\n        if (root == null) return result;\n\n        Deque<TreeNode> queue = new ArrayDeque<>();\n        queue.offer(root);\n\n        while (!queue.isEmpty()) {\n            List<Integer> level = new ArrayList<>();\n\n            for (int i = queue.size(); i > 0; i--) {\n                TreeNode node = queue.poll();\n                level.add(node.val);\n\n                if (node.left != null) queue.offer(node.left);\n                if (node.right != null) queue.offer(node.right);\n            }\n\n            result.add(level);\n        }\n\n        return result;\n    }\n}","filename":"Java"},"revision":1},{"id":"77eb38a7-2c19-706a-b356-c7fcaa238441","type":"code","position":"aK","content":{"language":"javascript","code":"var levelOrder = function(root) {\n    if (!root) return [];\n\n    const result = [];\n    let queue = [root];\n\n    while (queue.length) {\n        const level = [];\n        const next = [];\n\n        for (const node of queue) {\n            level.push(node.val);\n\n            if (node.left) next.push(node.left);\n            if (node.right) next.push(node.right);\n        }\n\n        result.push(level);\n        queue = next;\n    }\n\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"939f0379-d771-716f-9857-06b499cf5f5d","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Aux Space: O(w) · Output Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
