SELECT '6e3d23ee-9825-7a9b-98e8-d9718535b57a', '8d4466c2-7cd6-7e93-b6f8-73af2ab12e59', 1, 'PUBLISHED', 'Last Stone Weight', '[{"id":"4f40aba6-691a-7069-acc9-bda5e9315c0e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Easy","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 1046","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/last-stone-weight/"}}]}]}]}},"revision":1},{"id":"787bd465-83ea-7d05-812a-3ae414c4abdb","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"68c238af-0f67-7b88-8033-ce5d2e351d3c","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Simulate stone smashing: each step choose the two heaviest stones "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":" (with "},{"type":"text","text":"x <= y","marks":[{"type":"code"}]},{"type":"text","text":"). If "},{"type":"text","text":"x == y","marks":[{"type":"code"}]},{"type":"text","text":" both destroyed, else remaining stone is "},{"type":"text","text":"y - x","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"85467020-58c2-720c-bbbc-e18f87b32229","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"fe0f0bff-1a46-7f7c-88ab-2b0be32de29e","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Repeatedly extract the 2 maximum elements until at most 1 stone remains."}]}]}},"revision":1},{"id":"4fcb1b7b-c8e0-76c5-87ed-08bb31a2469a","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"d5c1e9f1-8cdd-7f98-b92b-956c5fa52056","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use a Max Heap. In Python, invert stone weights (negate values) to build a max heap with "},{"type":"text","text":"heapq","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"b1fa318e-ea00-75cb-8df7-612f9660fdac","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"3f805afc-7815-73fc-bb6e-f2e6541d3587","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Convert stones to negative values: "},{"type":"text","text":"heap = [-s for s in stones]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Heapify array in O(n) time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"While "},{"type":"text","text":"len(heap) > 1","marks":[{"type":"code"}]},{"type":"text","text":": pop "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"y != x","marks":[{"type":"code"}]},{"type":"text","text":", push negated difference "},{"type":"text","text":"-(y - x)","marks":[{"type":"code"}]},{"type":"text","text":" back into heap."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"-heap[0]","marks":[{"type":"code"}]},{"type":"text","text":" if heap non-empty else 0."}]}]}]}]}},"revision":1},{"id":"7ab9bb87-b93f-73d9-b91e-70bf99720ad1","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"c0121589-3d84-752b-a6ff-73680e8ddb1c","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sort the stones array descending on every iteration and pop the two largest."}]}]}},"revision":1},{"id":"5b344cbb-04c2-7bdb-8264-fa6dfeb98318","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def lastStoneWeight(self, stones):\n\n        while len(stones) > 1:\n            stones.sort()\n\n            y = stones.pop()\n            x = stones.pop()\n\n            if y != x:\n                stones.append(y - x)\n\n        return stones[0] if stones else 0","filename":"Python"},"revision":1},{"id":"b6fdb39c-a004-7218-b987-5a2a77497d62","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int lastStoneWeight(vector<int>& stones) {\n        while (stones.size() > 1) {\n            sort(stones.begin(), stones.end());\n\n            int y = stones.back(); stones.pop_back();\n            int x = stones.back(); stones.pop_back();\n\n            if (y != x) stones.push_back(y - x);\n        }\n\n        return stones.empty() ? 0 : stones[0];\n    }\n};","filename":"C++"},"revision":1},{"id":"42d155ef-b221-70a3-bec5-65bbddef3c89","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int lastStoneWeight(int[] stones) {\n        List<Integer> list = new ArrayList<>();\n        for (int stone : stones) list.add(stone);\n\n        while (list.size() > 1) {\n            Collections.sort(list);\n\n            int y = list.remove(list.size() - 1);\n            int x = list.remove(list.size() - 1);\n\n            if (y != x) list.add(y - x);\n        }\n\n        return list.isEmpty() ? 0 : list.get(0);\n    }\n}","filename":"Java"},"revision":1},{"id":"8b3d1ff2-9642-7140-8298-1339d298c338","type":"code","position":"aE","content":{"language":"javascript","code":"var lastStoneWeight = function(stones) {\n    while (stones.length > 1) {\n        stones.sort((a, b) => a - b);\n\n        const y = stones.pop();\n        const x = stones.pop();\n\n        if (y !== x) stones.push(y - x);\n    }\n\n    return stones.length ? stones[0] : 0;\n};","filename":"JavaScript"},"revision":1},{"id":"f07969cd-46c5-7ed0-ae41-87e41312b40a","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n² log n) · Space: O(1) aux","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"374efbe0-99be-7ae0-9055-16d6cccf4454","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"3191a716-9470-728e-b849-b8012670505d","type":"code","position":"aH","content":{"language":"python","code":"import heapq\n\nclass Solution:\n    def lastStoneWeight(self, stones):\n\n        heap = [-stone for stone in stones]\n        heapq.heapify(heap)\n\n        while len(heap) > 1:\n            y = -heapq.heappop(heap)\n            x = -heapq.heappop(heap)\n\n            if y != x:\n                heapq.heappush(\n                    heap,\n                    -(y - x)\n                )\n\n        return -heap[0] if heap else 0","filename":"Python"},"revision":1},{"id":"8e734157-3604-786c-be90-afb3ab5a068d","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int lastStoneWeight(vector<int>& stones) {\n        priority_queue<int> heap(stones.begin(), stones.end());  // max-heap\n\n        while (heap.size() > 1) {\n            int y = heap.top(); heap.pop();\n            int x = heap.top(); heap.pop();\n\n            if (y != x) heap.push(y - x);\n        }\n\n        return heap.empty() ? 0 : heap.top();\n    }\n};","filename":"C++"},"revision":1},{"id":"b7f01904-5da6-7d58-8b68-ba3f4e3afa86","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int lastStoneWeight(int[] stones) {\n        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());  // max-heap\n        for (int stone : stones) heap.offer(stone);\n\n        while (heap.size() > 1) {\n            int y = heap.poll();\n            int x = heap.poll();\n\n            if (y != x) heap.offer(y - x);\n        }\n\n        return heap.isEmpty() ? 0 : heap.peek();\n    }\n}","filename":"Java"},"revision":1},{"id":"913555ea-7785-77c9-aef1-1473dc061afa","type":"code","position":"aK","content":{"language":"javascript","code":"class MinHeap {\n    constructor(compare = (a, b) => a - b, items = []) {\n        this.compare = compare;\n        this.data = items;\n        for (let i = (items.length >> 1) - 1; i >= 0; i--) this.siftDown(i);\n    }\n\n    size() { return this.data.length; }\n\n    peek() { return this.data[0]; }\n\n    push(value) {\n        const data = this.data;\n        data.push(value);\n        let i = data.length - 1;\n        while (i > 0) {\n            const parent = (i - 1) >> 1;\n            if (this.compare(data[i], data[parent]) >= 0) break;\n            [data[i], data[parent]] = [data[parent], data[i]];\n            i = parent;\n        }\n    }\n\n    pop() {\n        const data = this.data;\n        const top = data[0];\n        const last = data.pop();\n        if (data.length > 0) {\n            data[0] = last;\n            this.siftDown(0);\n        }\n        return top;\n    }\n\n    siftDown(i) {\n        const data = this.data;\n        while (true) {\n            const left = 2 * i + 1, right = left + 1;\n            let smallest = i;\n            if (left < data.length && this.compare(data[left], data[smallest]) < 0) smallest = left;\n            if (right < data.length && this.compare(data[right], data[smallest]) < 0) smallest = right;\n            if (smallest === i) return;\n            [data[i], data[smallest]] = [data[smallest], data[i]];\n            i = smallest;\n        }\n    }\n}\n\nvar lastStoneWeight = function(stones) {\n    const heap = new MinHeap((a, b) => b - a, [...stones]);  // max-heap\n\n    while (heap.size() > 1) {\n        const y = heap.pop();\n        const x = heap.pop();\n\n        if (y !== x) heap.push(y - x);\n    }\n\n    return heap.size() ? heap.peek() : 0;\n};","filename":"JavaScript"},"revision":1},{"id":"29a44877-f20c-7464-bc6c-89e7c7598d7f","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n log n) · Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"c2b773cb-558b-7bb7-a292-28b328b64364","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"4407abd7-ca5e-70d7-b5bf-bb7251365a8f","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Repeatedly extract maximum element → Max Heap"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
