  ('8e734157-3604-786c-be90-afb3ab5a068d', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int lastStoneWeight(vector<int>& stones) {\n        priority_queue<int> heap(stones.begin(), stones.end());  // max-heap\n\n        while (heap.size() > 1) {\n            int y = heap.top(); heap.pop();\n            int x = heap.top(); heap.pop();\n\n            if (y != x) heap.push(y - x);\n        }\n\n        return heap.empty() ? 0 : heap.top();\n    }\n};","filename":"C++"}'),
  ('b7f01904-5da6-7d58-8b68-ba3f4e3afa86', 'aJ', 'code', '{"language":"java","code":"class Solution {\n    public int lastStoneWeight(int[] stones) {\n        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());  // max-heap\n        for (int stone : stones) heap.offer(stone);\n\n        while (heap.size() > 1) {\n            int y = heap.poll();\n            int x = heap.poll();\n\n            if (y != x) heap.offer(y - x);\n        }\n\n        return heap.isEmpty() ? 0 : heap.peek();\n    }\n}","filename":"Java"}'),
