  ('032b5a73-08a3-7498-9545-3e6ff925147d', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def numDistinct(self, s, t):\n\n        def dfs(i, j):\n            if j == len(t):\n                return 1\n\n            if i == len(s):\n                return 0\n\n            if s[i] == t[j]:\n                return (\n                    dfs(i + 1, j + 1)\n                    +\n                    dfs(i + 1, j)\n                )\n\n            return dfs(i + 1, j)\n\n        return dfs(0, 0)","filename":"Python"}'),
  ('1fdd9bf4-1813-7819-968d-0653b2cecd4e', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int numDistinct(string s, string t) {\n        return dfs(s, t, 0, 0);\n    }\n\nprivate:\n    int dfs(const string& s, const string& t, int i, int j) {\n        if (j == (int)t.size()) return 1;\n        if (i == (int)s.size()) return 0;\n\n        if (s[i] == t[j]) {\n            return dfs(s, t, i + 1, j + 1) + dfs(s, t, i + 1, j);\n        }\n\n        return dfs(s, t, i + 1, j);\n    }\n};","filename":"C++"}'),
  ('01330184-1117-77df-82d9-8b0b463a50f1', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public int numDistinct(String s, String t) {\n        return dfs(s, t, 0, 0);\n    }\n\n    private int dfs(String s, String t, int i, int j) {\n        if (j == t.length()) return 1;\n        if (i == s.length()) return 0;\n\n        if (s.charAt(i) == t.charAt(j)) {\n            return dfs(s, t, i + 1, j + 1) + dfs(s, t, i + 1, j);\n        }\n\n        return dfs(s, t, i + 1, j);\n    }\n}","filename":"Java"}'),
  ('d921ba6e-75ca-7098-bf06-ac151111cf6a', 'aE', 'code', '{"language":"javascript","code":"var numDistinct = function(s, t) {\n    const dfs = (i, j) => {\n        if (j === t.length) return 1;\n        if (i === s.length) return 0;\n\n        if (s[i] === t[j]) {\n            return dfs(i + 1, j + 1) + dfs(i + 1, j);\n        }\n\n        return dfs(i + 1, j);\n    };\n\n    return dfs(0, 0);\n};","filename":"JavaScript"}'),
  ('7e669e3b-1bf7-73bd-b18e-981253aeb146', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(2^n) · Aux Space: O(n)","marks":[{"type":"bold"}]}]}]}}'),
