Problem
Return length of shortest transformation sequence from beginWord to endWord using wordList.
Understanding the problem
Unweighted shortest path problem solved via BFS with pattern wildcard matching.
Intuition
Group words into pattern dict neighbors[''*ot''] = [''hot'', ''dot'', ''lot''] to reduce edge lookup to O(L^2 × N).
Approach
Build wildcard pattern map for wordList.
Queue with (beginWord, 1), visited set with beginWord.
BFS layer-by-layer: for current word, generate patterns, visit unvisited neighbor words, push to queue with dist+1.
Naive Solution
Compare all pairs of words for 1-char difference to build graph.
from collections import deque

class Solution:
    def ladderLength(self, beginWord, endWord, wordList):
        if endWord not in wordList:
            return 0

        words = wordList + [beginWord]
        n = len(words)

        def one_apart(a, b):
            diff = 0

            for x, y in zip(a, b):
                if x != y:
                    diff += 1
                    if diff > 1:
                        return False

            return diff == 1

        # Compare every pair of words to build the graph
        graph = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                if one_apart(words[i], words[j]):
                    graph[i].append(j)
                    graph[j].append(i)

        visited = [False] * n
        visited[n - 1] = True
        queue = deque([(n - 1, 1)])

        while queue:
            i, distance = queue.popleft()

            if words[i] == endWord:
                return distance

            for j in graph[i]:
                if not visited[j]:
                    visited[j] = True
                    queue.append((j, distance + 1))

        return 0
class Solution {
public:
    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
        if (find(wordList.begin(), wordList.end(), endWord) == wordList.end())
            return 0;

        vector<string> words = wordList;
        words.push_back(beginWord);
        int n = words.size();

        auto oneApart = [](const string& a, const string& b) {
            int diff = 0;
            for (int i = 0; i < (int)a.size() && diff <= 1; i++)
                if (a[i] != b[i]) diff++;
            return diff == 1;
        };

        // Compare every pair of words to build the graph
        vector<vector<int>> graph(n);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (oneApart(words[i], words[j])) {
                    graph[i].push_back(j);
                    graph[j].push_back(i);
                }
            }
        }

        vector<bool> visited(n, false);
        queue<pair<int, int>> q;
        q.push({n - 1, 1});
        visited[n - 1] = true;

        while (!q.empty()) {
            auto [i, distance] = q.front();
            q.pop();

            if (words[i] == endWord) return distance;

            for (int j : graph[i]) {
                if (!visited[j]) {
                    visited[j] = true;
                    q.push({j, distance + 1});
                }
            }
        }

        return 0;
    }
};
class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        if (!wordList.contains(endWord)) return 0;

        List<String> words = new ArrayList<>(wordList);
        words.add(beginWord);
        int n = words.size();

        // Compare every pair of words to build the graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (oneApart(words.get(i), words.get(j))) {
                    graph.get(i).add(j);
                    graph.get(j).add(i);
                }
            }
        }

        boolean[] visited = new boolean[n];
        Deque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{n - 1, 1});
        visited[n - 1] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int i = cur[0], distance = cur[1];

            if (words.get(i).equals(endWord)) return distance;

            for (int j : graph.get(i)) {
                if (!visited[j]) {
                    visited[j] = true;
                    queue.offer(new int[]{j, distance + 1});
                }
            }
        }

        return 0;
    }

    private boolean oneApart(String a, String b) {
        int diff = 0;
        for (int i = 0; i < a.length() && diff <= 1; i++)
            if (a.charAt(i) != b.charAt(i)) diff++;
        return diff == 1;
    }
}
