SELECT '8d7ffb52-66ac-7a56-ba41-eb1fd0c2339b', 'f7903c0e-b87b-776a-8de4-14f43e5d2ca0', 1, 'PUBLISHED', 'Surrounded Regions', '[{"id":"a0541d9b-ef45-7485-92e1-cffb749008f8","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 130","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/surrounded-regions/"}}]}]}]}},"revision":1},{"id":"5295d9a1-225e-7642-9214-a06e2db7248f","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"c3acdc55-931d-7c9e-98c3-bc5a2a994744","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Capture all regions surrounded by "},{"type":"text","text":"''X''","marks":[{"type":"code"}]},{"type":"text","text":". Modify "},{"type":"text","text":"''O''","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"''X''","marks":[{"type":"code"}]},{"type":"text","text":" if completely surrounded."}]}]}},"revision":1},{"id":"8409533c-fceb-747b-9cc2-4cf1fff959e9","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"74858dd9-5759-7eb0-a94c-e2478c2cb035","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Any "},{"type":"text","text":"''O''","marks":[{"type":"code"}]},{"type":"text","text":" connected to border boundary CANNOT be captured. All other "},{"type":"text","text":"''O''","marks":[{"type":"code"}]},{"type":"text","text":" cells will be flipped to "},{"type":"text","text":"''X''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"c850a241-3a8c-7de4-986b-bafcc1bdabfd","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"e70397b8-3678-7662-8028-cfd1c3868fa6","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Boundary-first DFS marking boundary-connected "},{"type":"text","text":"''O''","marks":[{"type":"code"}]},{"type":"text","text":"s as "},{"type":"text","text":"''#''","marks":[{"type":"code"}]},{"type":"text","text":", then flipping remaining "},{"type":"text","text":"''O''","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"''X''","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"''#''","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"''O''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"17304d11-fcd6-7ba8-992f-168fc36bacf9","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"8e65068a-4faa-7489-b221-394b079cc32a","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Run DFS on all 4 borders to mark safe "},{"type":"text","text":"''O''","marks":[{"type":"code"}]},{"type":"text","text":"s as "},{"type":"text","text":"''#''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Traverse grid: convert any remaining "},{"type":"text","text":"''O''","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"''X''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Restore "},{"type":"text","text":"''#''","marks":[{"type":"code"}]},{"type":"text","text":" back to "},{"type":"text","text":"''O''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"3abb9cee-819a-7aed-aea9-a07b6f94f85d","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution"}]},"revision":1},{"id":"35b01fcc-9ccc-7965-b4c9-494ee23269f8","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DFS from every "},{"type":"text","text":"''O''","marks":[{"type":"code"}]},{"type":"text","text":" checking if boundary reachable."}]}]}},"revision":1},{"id":"d50cf333-ed4a-7c92-9e53-cb41ad15abc8","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def solve(self, board):\n        rows = len(board)\n        cols = len(board[0])\n\n        # Can this ''O'' reach the border through other ''O''s?\n        def reaches_border(r, c, visited):\n            if r < 0 or r >= rows or c < 0 or c >= cols:\n                return True\n\n            if board[r][c] != \"O\" or (r, c) in visited:\n                return False\n\n            visited.add((r, c))\n\n            return (\n                reaches_border(r + 1, c, visited)\n                or reaches_border(r - 1, c, visited)\n                or reaches_border(r, c + 1, visited)\n                or reaches_border(r, c - 1, visited)\n            )\n\n        for r in range(rows):\n            for c in range(cols):\n                if board[r][c] != \"O\":\n                    continue\n\n                if not reaches_border(r, c, set()):\n                    board[r][c] = \"X\"","filename":"Python"},"revision":1},{"id":"759f7e13-d8f3-7f3d-ae50-e92415e2772d","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    void solve(vector<vector<char>>& board) {\n        int rows = board.size(), cols = board[0].size();\n        vector<vector<bool>> visited;\n\n        // Can this ''O'' reach the border through other ''O''s?\n        function<bool(int, int)> reachesBorder = [&](int r, int c) -> bool {\n            if (r < 0 || r >= rows || c < 0 || c >= cols) return true;\n            if (board[r][c] != ''O'' || visited[r][c]) return false;\n\n            visited[r][c] = true;\n\n            return reachesBorder(r + 1, c) || reachesBorder(r - 1, c) ||\n                   reachesBorder(r, c + 1) || reachesBorder(r, c - 1);\n        };\n\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                if (board[r][c] != ''O'') continue;\n\n                visited.assign(rows, vector<bool>(cols, false));\n\n                if (!reachesBorder(r, c)) board[r][c] = ''X'';\n            }\n        }\n    }\n};","filename":"C++"},"revision":1},{"id":"9b0a6484-8404-73eb-91bb-cc712d3b9060","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    private char[][] board;\n    private boolean[][] visited;\n    private int rows, cols;\n\n    public void solve(char[][] board) {\n        this.board = board;\n        rows = board.length;\n        cols = board[0].length;\n\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                if (board[r][c] != ''O'') continue;\n\n                visited = new boolean[rows][cols];\n\n                if (!reachesBorder(r, c)) board[r][c] = ''X'';\n            }\n        }\n    }\n\n    // Can this ''O'' reach the border through other ''O''s?\n    private boolean reachesBorder(int r, int c) {\n        if (r < 0 || r >= rows || c < 0 || c >= cols) return true;\n        if (board[r][c] != ''O'' || visited[r][c]) return false;\n\n        visited[r][c] = true;\n\n        return reachesBorder(r + 1, c) || reachesBorder(r - 1, c) ||\n               reachesBorder(r, c + 1) || reachesBorder(r, c - 1);\n    }\n}","filename":"Java"},"revision":1},{"id":"a1f7758e-2843-7daa-9599-adb8e6fe6889","type":"code","position":"aE","content":{"language":"javascript","code":"var solve = function(board) {\n    const rows = board.length;\n    const cols = board[0].length;\n    let visited;\n\n    // Can this ''O'' reach the border through other ''O''s?\n    const reachesBorder = (r, c) => {\n        if (r < 0 || r >= rows || c < 0 || c >= cols) return true;\n        if (board[r][c] !== \"O\" || visited[r][c]) return false;\n\n        visited[r][c] = true;\n\n        return reachesBorder(r + 1, c) || reachesBorder(r - 1, c) ||\n               reachesBorder(r, c + 1) || reachesBorder(r, c - 1);\n    };\n\n    for (let r = 0; r < rows; r++) {\n        for (let c = 0; c < cols; c++) {\n            if (board[r][c] !== \"O\") continue;\n\n            visited = Array.from({ length: rows }, () => new Array(cols).fill(false));\n\n            if (!reachesBorder(r, c)) board[r][c] = \"X\";\n        }\n    }\n};","filename":"JavaScript"},"revision":1},{"id":"8768fee2-90c0-7c3c-885b-eddd15099121","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O((R × C)^2) · Aux Space: O(R × C)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"37611579-acd9-71ae-8ac3-ce2dd4e4bb78","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"a8613ccd-f0c6-7805-a7e2-cc6d52b2d519","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def solve(self, board):\n        rows = len(board)\n        cols = len(board[0])\n\n        def dfs(r, c):\n            if (\n                r < 0 or r >= rows or\n                c < 0 or c >= cols or\n                board[r][c] != \"O\"\n            ):\n                return\n\n            board[r][c] = \"#\"\n\n            dfs(r + 1, c)\n            dfs(r - 1, c)\n            dfs(r, c + 1)\n            dfs(r, c - 1)\n\n        # Mark boundary-connected O''s\n        for r in range(rows):\n            dfs(r, 0)\n            dfs(r, cols - 1)\n\n        for c in range(cols):\n            dfs(0, c)\n            dfs(rows - 1, c)\n\n        # Capture surrounded regions\n        for r in range(rows):\n            for c in range(cols):\n                if board[r][c] == \"O\":\n                    board[r][c] = \"X\"\n                elif board[r][c] == \"#\":\n                    board[r][c] = \"O\"","filename":"Python"},"revision":1},{"id":"f8d2bd52-6c1d-786e-9fe3-b680a75dadb1","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    void solve(vector<vector<char>>& board) {\n        int rows = board.size(), cols = board[0].size();\n\n        function<void(int, int)> dfs = [&](int r, int c) {\n            if (r < 0 || r >= rows || c < 0 || c >= cols || board[r][c] != ''O'')\n                return;\n\n            board[r][c] = ''#'';\n\n            dfs(r + 1, c);\n            dfs(r - 1, c);\n            dfs(r, c + 1);\n            dfs(r, c - 1);\n        };\n\n        // Mark boundary-connected O''s\n        for (int r = 0; r < rows; r++) {\n            dfs(r, 0);\n            dfs(r, cols - 1);\n        }\n\n        for (int c = 0; c < cols; c++) {\n            dfs(0, c);\n            dfs(rows - 1, c);\n        }\n\n        // Capture surrounded regions\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                if (board[r][c] == ''O'') board[r][c] = ''X'';\n                else if (board[r][c] == ''#'') board[r][c] = ''O'';\n            }\n        }\n    }\n};","filename":"C++"},"revision":1},{"id":"17f78ec0-ac15-79ee-8066-1a58420c78cc","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    private char[][] board;\n    private int rows, cols;\n\n    public void solve(char[][] board) {\n        this.board = board;\n        rows = board.length;\n        cols = board[0].length;\n\n        // Mark boundary-connected O''s\n        for (int r = 0; r < rows; r++) {\n            dfs(r, 0);\n            dfs(r, cols - 1);\n        }\n\n        for (int c = 0; c < cols; c++) {\n            dfs(0, c);\n            dfs(rows - 1, c);\n        }\n\n        // Capture surrounded regions\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                if (board[r][c] == ''O'') board[r][c] = ''X'';\n                else if (board[r][c] == ''#'') board[r][c] = ''O'';\n            }\n        }\n    }\n\n    private void dfs(int r, int c) {\n        if (r < 0 || r >= rows || c < 0 || c >= cols || board[r][c] != ''O'')\n            return;\n\n        board[r][c] = ''#'';\n\n        dfs(r + 1, c);\n        dfs(r - 1, c);\n        dfs(r, c + 1);\n        dfs(r, c - 1);\n    }\n}","filename":"Java"},"revision":1},{"id":"1e82caa4-41ec-7968-b571-ed320f27a222","type":"code","position":"aK","content":{"language":"javascript","code":"var solve = function(board) {\n    const rows = board.length;\n    const cols = board[0].length;\n\n    const dfs = (r, c) => {\n        if (\n            r < 0 || r >= rows ||\n            c < 0 || c >= cols ||\n            board[r][c] !== \"O\"\n        ) return;\n\n        board[r][c] = \"#\";\n\n        dfs(r + 1, c);\n        dfs(r - 1, c);\n        dfs(r, c + 1);\n        dfs(r, c - 1);\n    };\n\n    // Mark boundary-connected O''s\n    for (let r = 0; r < rows; r++) {\n        dfs(r, 0);\n        dfs(r, cols - 1);\n    }\n\n    for (let c = 0; c < cols; c++) {\n        dfs(0, c);\n        dfs(rows - 1, c);\n    }\n\n    // Capture surrounded regions\n    for (let r = 0; r < rows; r++) {\n        for (let c = 0; c < cols; c++) {\n            if (board[r][c] === \"O\") board[r][c] = \"X\";\n            else if (board[r][c] === \"#\") board[r][c] = \"O\";\n        }\n    }\n};","filename":"JavaScript"},"revision":1},{"id":"b7225ef0-8c7f-7ac5-8fb1-b00dbdf2cdd6","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(R × C) · Aux Space: O(R × C)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"363ac70e-e5bd-7d9e-872f-ca3317c61025","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"e1c6be24-b934-702f-ab15-e66c647b14f6","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern:","marks":[{"type":"bold"}]},{"type":"text","text":" Boundary-first DFS/BFS."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
