  ('369cd41d-ddf0-7422-a15c-4eb7fbc1d616', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Partition a string such that every substring is a palindrome. Example for "},{"type":"text","text":"\"aab\"","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"[\"a\", \"a\", \"b\"]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"[\"aa\", \"b\"]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
