  ('7b5aafee-28c7-7fc4-bf56-b8e635fc2aa5', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Intuition"}]}'),
  ('5e298048-3eaf-780c-ac3d-b58b57fc7fab', 'a6', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Precompute whether every substring is a palindrome using 2D Dynamic Programming in O(n^2) time before backtracking."}]}]}}'),
