  ('ea9e84dc-f1ff-71bb-9f16-24361f5446d5', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build 2D boolean array "},{"type":"text","text":"palindrome[n][n]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set single characters "},{"type":"text","text":"palindrome[i][i] = True","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill DP table for lengths 2 to n: "},{"type":"text","text":"palindrome[left][right] = True","marks":[{"type":"code"}]},{"type":"text","text":" if characters match and inner substring is palindrome."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Backtrack from "},{"type":"text","text":"start = 0","marks":[{"type":"code"}]},{"type":"text","text":", using "},{"type":"text","text":"palindrome[start][end]","marks":[{"type":"code"}]},{"type":"text","text":" for O(1) checks."}]}]}]}]}}'),
  ('1a1511d0-f047-738b-987b-ae46f490a997', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Naive Solution"}]}'),
  ('d90c1869-12eb-74fb-bc3f-5ad5d4da9453', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At every position, try every possible substring and check whether it is a palindrome with "},{"type":"text","text":"string == string[::-1]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('99b60bfb-3540-7abf-bf4c-a4202df020d5', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def partition(self, s):\n        result = []\n\n        def is_palindrome(string):\n            return string == string[::-1]\n\n        def backtrack(start, current):\n            if start == len(s):\n                result.append(current[:])\n                return\n\n            for end in range(start + 1, len(s) + 1):\n                substring = s[start:end]\n\n                if is_palindrome(substring):\n                    current.append(substring)\n                    backtrack(end, current)\n                    current.pop()\n\n        backtrack(0, [])\n        return result","filename":"Python"}'),
  ('4894d8b4-68ad-7ba5-83d6-f69a09166aef', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    vector<vector<string>> partition(string s) {\n        vector<vector<string>> result;\n        vector<string> current;\n        backtrack(s, 0, current, result);\n        return result;\n    }\n\nprivate:\n    bool isPalindrome(const string& str) {\n        return str == string(str.rbegin(), str.rend());\n    }\n\n    void backtrack(const string& s, int start, vector<string>& current, vector<vector<string>>& result) {\n        if (start == (int)s.size()) {\n            result.push_back(current);\n            return;\n        }\n\n        for (int end = start + 1; end <= (int)s.size(); end++) {\n            string substring = s.substr(start, end - start);\n\n            if (isPalindrome(substring)) {\n                current.push_back(substring);\n                backtrack(s, end, current, result);\n                current.pop_back();\n            }\n        }\n    }\n};","filename":"C++"}'),
  ('a8cb655e-efc9-7e3d-ab09-bf6c11dd97fa', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public List<List<String>> partition(String s) {\n        List<List<String>> result = new ArrayList<>();\n        backtrack(s, 0, new ArrayList<>(), result);\n        return result;\n    }\n\n    private boolean isPalindrome(String str) {\n        return str.equals(new StringBuilder(str).reverse().toString());\n    }\n\n    private void backtrack(String s, int start, List<String> current, List<List<String>> result) {\n        if (start == s.length()) {\n            result.add(new ArrayList<>(current));\n            return;\n        }\n\n        for (int end = start + 1; end <= s.length(); end++) {\n            String substring = s.substring(start, end);\n\n            if (isPalindrome(substring)) {\n                current.add(substring);\n                backtrack(s, end, current, result);\n                current.remove(current.size() - 1);\n            }\n        }\n    }\n}","filename":"Java"}'),
  ('eff9c007-b62c-75fa-903e-79ebff01140c', 'aE', 'code', '{"language":"javascript","code":"var partition = function(s) {\n    const result = [];\n\n    const isPalindrome = (str) => str === [...str].reverse().join('''');\n\n    const backtrack = (start, current) => {\n        if (start === s.length) {\n            result.push([...current]);\n            return;\n        }\n\n        for (let end = start + 1; end <= s.length; end++) {\n            const substring = s.slice(start, end);\n\n            if (isPalindrome(substring)) {\n                current.push(substring);\n                backtrack(end, current);\n                current.pop();\n            }\n        }\n    };\n\n    backtrack(0, []);\n    return result;\n};","filename":"JavaScript"}'),
  ('acf9f049-61d1-7b1a-bd68-2dd8771bc785', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n × 2^n) approximately · Aux Space: O(n) · Output Space: O(n × 2^n)","marks":[{"type":"bold"}]}]}]}}'),
  ('46dacd5c-1b51-7d22-99b7-6d6f2901fe56', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Code (Optimized)"}]}'),
  ('b645066b-4527-79d5-885b-e9a4cfb0f0d0', 'aH', 'code', '{"language":"python","code":"class Solution:\n    def partition(self, s):\n        n = len(s)\n\n        palindrome = [[False] * n for _ in range(n)]\n\n        for i in range(n):\n            palindrome[i][i] = True\n\n        for length in range(2, n + 1):\n            for left in range(n - length + 1):\n                right = left + length - 1\n\n                if s[left] == s[right]:\n                    if length == 2 or palindrome[left + 1][right - 1]:\n                        palindrome[left][right] = True\n\n        result = []\n\n        def backtrack(start, current):\n            if start == n:\n                result.append(current[:])\n                return\n\n            for end in range(start, n):\n                if palindrome[start][end]:\n                    current.append(s[start:end + 1])\n                    backtrack(end + 1, current)\n                    current.pop()\n\n        backtrack(0, [])\n        return result","filename":"Python"}'),
  ('c9688b4d-b760-71c5-8374-601a4c1775f6', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    vector<vector<string>> partition(string s) {\n        int n = s.size();\n\n        vector<vector<bool>> palindrome(n, vector<bool>(n, false));\n\n        for (int i = 0; i < n; i++) palindrome[i][i] = true;\n\n        for (int length = 2; length <= n; length++) {\n            for (int left = 0; left <= n - length; left++) {\n                int right = left + length - 1;\n\n                if (s[left] == s[right]) {\n                    if (length == 2 || palindrome[left + 1][right - 1]) {\n                        palindrome[left][right] = true;\n                    }\n                }\n            }\n        }\n\n        vector<vector<string>> result;\n        vector<string> current;\n        backtrack(s, 0, palindrome, current, result);\n        return result;\n    }\n\nprivate:\n    void backtrack(const string& s, int start, vector<vector<bool>>& palindrome,\n                   vector<string>& current, vector<vector<string>>& result) {\n        int n = s.size();\n\n        if (start == n) {\n            result.push_back(current);\n            return;\n        }\n\n        for (int end = start; end < n; end++) {\n            if (palindrome[start][end]) {\n                current.push_back(s.substr(start, end - start + 1));\n                backtrack(s, end + 1, palindrome, current, result);\n                current.pop_back();\n            }\n        }\n    }\n};","filename":"C++"}'),
  ('8aef939b-ead0-7e6e-b6c3-b680ac3b9529', 'aJ', 'code', '{"language":"java","code":"class Solution {\n    public List<List<String>> partition(String s) {\n        int n = s.length();\n\n        boolean[][] palindrome = new boolean[n][n];\n\n        for (int i = 0; i < n; i++) palindrome[i][i] = true;\n\n        for (int length = 2; length <= n; length++) {\n            for (int left = 0; left <= n - length; left++) {\n                int right = left + length - 1;\n\n                if (s.charAt(left) == s.charAt(right)) {\n                    if (length == 2 || palindrome[left + 1][right - 1]) {\n                        palindrome[left][right] = true;\n                    }\n                }\n            }\n        }\n\n        List<List<String>> result = new ArrayList<>();\n        backtrack(s, 0, palindrome, new ArrayList<>(), result);\n        return result;\n    }\n\n    private void backtrack(String s, int start, boolean[][] palindrome,\n                           List<String> current, List<List<String>> result) {\n        int n = s.length();\n\n        if (start == n) {\n            result.add(new ArrayList<>(current));\n            return;\n        }\n\n        for (int end = start; end < n; end++) {\n            if (palindrome[start][end]) {\n                current.add(s.substring(start, end + 1));\n                backtrack(s, end + 1, palindrome, current, result);\n                current.remove(current.size() - 1);\n            }\n        }\n    }\n}","filename":"Java"}'),
  ('217f9b4e-c1d2-76e1-ae3b-f8401192d57a', 'aK', 'code', '{"language":"javascript","code":"var partition = function(s) {\n    const n = s.length;\n\n    const palindrome = Array.from({ length: n }, () => new Array(n).fill(false));\n\n    for (let i = 0; i < n; i++) palindrome[i][i] = true;\n\n    for (let length = 2; length <= n; length++) {\n        for (let left = 0; left <= n - length; left++) {\n            const right = left + length - 1;\n\n            if (s[left] === s[right]) {\n                if (length === 2 || palindrome[left + 1][right - 1]) {\n                    palindrome[left][right] = true;\n                }\n            }\n        }\n    }\n\n    const result = [];\n\n    const backtrack = (start, current) => {\n        if (start === n) {\n            result.push([...current]);\n            return;\n        }\n\n        for (let end = start; end < n; end++) {\n            if (palindrome[start][end]) {\n                current.push(s.slice(start, end + 1));\n                backtrack(end + 1, current);\n                current.pop();\n            }\n        }\n    };\n\n    backtrack(0, []);\n    return result;\n};","filename":"JavaScript"}'),
  ('4df9a77f-c351-7870-9e83-0a217a54cbec', 'aL', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Palindrome DP: O(n^2) · Time: O(n^2 + n × 2^n) · Aux Space: O(n^2) DP + O(n) recursion · Output Space: O(n × 2^n)","marks":[{"type":"bold"}]}]}]}}'),
  ('526de765-7afe-7335-87fa-322bf7a9af4e', 'aM', 'heading', '{"level":1,"content":[{"type":"text","text":"Takeaway"}]}'),
