  let current = head;\n\n    while (current) {\n        copies.set(current, new _Node(current.val, null, null));\n        current = current.next;\n    }\n\n    current = head;\n\n    while (current) {\n        copies.get(current).next = copies.get(current.next) || null;\n        copies.get(current).random = copies.get(current.random) || null;\n\n        current = current.next;\n    }\n\n    return copies.get(head);\n};","filename":"JavaScript"},"revision":1},{"id":"0507d88f-ce50-7410-8643-6df8ab077d8d","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"3559fa8f-6aa5-7196-9119-d57d168a2486","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"29df5e31-cc6d-7ee2-b2e7-85e3e4441841","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def copyRandomList(self, head):\n        if not head:\n            return None\n\n        current = head\n\n        # Create copied nodes\n        while current:\n            copy = Node(current.val)\n\n            copy.next = current.next\n            current.next = copy\n\n            current = copy.next\n\n        # Set random pointers\n        current = head\n\n        while current:\n            if current.random:\n                current.next.random = (\n                    current.random.next\n                )\n\n            current = current.next.next\n\n        # Separate lists\n        dummy = Node(0)\n        copy_current = dummy\n        current = head\n\n        while current:\n            copy = current.next\n\n            copy_current.next = copy\n            copy_current = copy\n\n            current.next = copy.next\n            current = current.next\n\n        return dummy.next","filename":"Python"},"revision":1},{"id":"2ee81db5-e6bc-7d92-8de7-99d3