SELECT '1416ac34-1314-743e-83e8-9727bc74eb80', 'a928a651-7e68-703a-bf9a-17e86fa80312', 1, 'PUBLISHED', 'Reorder List', '[{"id":"9e4fe9ee-edb1-7e5a-aadb-7c5666f02bac","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 143","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/reorder-list/"}}]}]}]}},"revision":1},{"id":"a67d76a1-8027-7e7f-8743-21dcb00d7ef6","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"b591df50-04ec-7699-9385-d0cb3b10d9c2","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reorder list to follow: L0 → Ln → L1 → Ln-1 → L2 → ..."}]}]}},"revision":1},{"id":"c32c3c70-6dc4-7319-be17-60de6045c021","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"5270031d-ae0d-7323-8938-f39de7d70b77","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Interleave first half with reversed second half."}]}]}},"revision":1},{"id":"7aecfca7-ae2a-7479-bacb-f0812201d5c7","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"0fb49752-703f-71ad-9138-db3e06e90135","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three steps in O(1) space: 1. Find middle (Fast/Slow) -> 2. Reverse second half -> 3. Interleave merge."}]}]}},"revision":1},{"id":"0ed66721-77b9-7135-96f2-b4e6518d0795","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"505d450f-9515-77b7-9b60-21e4de052f30","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find middle: "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" pointers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reverse second half starting at "},{"type":"text","text":"slow.next","marks":[{"type":"code"}]},{"type":"text","text":", split list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interleave merge two lists "},{"type":"text","text":"first","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"second","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"e57e7602-a354-787c-88ad-ef04ace1a7bc","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"c0ca53c7-98a7-77ae-a002-99d02513cb3e","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Store node references in array, set left/right pointers to re-link."}]}]}},"revision":1},{"id":"2f4728e8-0e1f-784b-a94d-0ff648419804","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def reorderList(self, head):\n        nodes = []\n\n        current = head\n\n        while current:\n            nodes.append(current)\n            current = current.next\n\n        left = 0\n        right = len(nodes) - 1\n\n        while left < right:\n            nodes[left].next = nodes[right]\n            left += 1\n\n            if left == right:\n                break\n\n            nodes[right].next = nodes[left]\n            right -= 1\n\n        nodes[left].next = None","filename":"Python"},"revision":1},{"id":"3b6517b3-1965-7149-aac1-77dbd5c1e7e2","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    void reorderList(ListNode* head) {\n        vector<ListNode*> nodes;\n\n        ListNode* current = head;\n\n        while (current) {\n            nodes.push_back(current);\n            current = current->next;\n        }\n\n        int left = 0;\n        int right = nodes.size() - 1;\n\n        while (left < right) {\n            nodes[left]->next = nodes[right];\n            left++;\n\n            if (left == right) {\n                break;\n            }\n\n            nodes[right]->next = nodes[left];\n            right--;\n        }\n\n        nodes[left]->next = nullptr;\n    }\n};","filename":"C++"},"revision":1},{"id":"33b1e6eb-c3e6-7d00-808b-f3ad7422094c","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public void reorderList(ListNode head) {\n        List<ListNode> nodes = new ArrayList<>();\n\n        ListNode current = head;\n\n        while (current != null) {\n            nodes.add(current);\n            current = current.next;\n        }\n\n        int left = 0;\n        int right = nodes.size() - 1;\n\n        while (left < right) {\n            nodes.get(left).next = nodes.get(right);\n            left++;\n\n            if (left == right) {\n                break;\n            }\n\n            nodes.get(right).next = nodes.get(left);\n            right--;\n        }\n\n        nodes.get(left).next = null;\n    }\n}","filename":"Java"},"revision":1},{"id":"6cb63c14-e2d1-796c-a586-cfde4d62131d","type":"code","position":"aE","content":{"language":"javascript","code":"var reorderList = function(head) {\n    const nodes = [];\n\n    let current = head;\n\n    while (current) {\n        nodes.push(current);\n        current = current.next;\n    }\n\n    let left = 0;\n    let right = nodes.length - 1;\n\n    while (left < right) {\n        nodes[left].next = nodes[right];\n        left++;\n\n        if (left === right) {\n            break;\n        }\n\n        nodes[right].next = nodes[left];\n        right--;\n    }\n\n    nodes[left].next = null;\n};","filename":"JavaScript"},"revision":1},{"id":"790fa30b-7b74-771b-82e5-85ea6d8e24a3","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"f01096ff-e4ef-758c-9dbb-5115ecf533ac","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"383991b9-f485-7a5f-9b52-26db74b7c910","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def reorderList(self, head):\n        if not head or not head.next:\n            return\n\n        # Find middle\n        slow = head\n        fast = head\n\n        while fast and fast.next:\n            slow = slow.next\n            fast = fast.next.next\n\n        # Reverse second half\n        second = slow.next\n        slow.next = None\n\n        previous = None\n\n        while second:\n            next_node = second.next\n            second.next = previous\n            previous = second\n            second = next_node\n\n        second = previous\n        first = head\n\n        # Merge\n        while second:\n            first_next = first.next\n            second_next = second.next\n\n            first.next = second\n            second.next = first_next\n\n            first = first_next\n            second = second_next","filename":"Python"},"revision":1},{"id":"30fb9004-4368-717e-8be0-eebe50f8c02d","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    void reorderList(ListNode* head) {\n        if (!head || !head->next) {\n            return;\n        }\n\n        // Find middle\n        ListNode* slow = head;\n        ListNode* fast = head;\n\n        while (fast && fast->next) {\n            slow = slow->next;\n            fast = fast->next->next;\n        }\n\n        // Reverse second half\n        ListNode* second = slow->next;\n        slow->next = nullptr;\n\n        ListNode* previous = nullptr;\n\n        while (second) {\n            ListNode* nextNode = second->next;\n            second->next = previous;\n            previous = second;\n            second = nextNode;\n        }\n\n        second = previous;\n        ListNode* first = head;\n\n        // Merge\n        while (second) {\n            ListNode* firstNext = first->next;\n            ListNode* secondNext = second->next;\n\n            first->next = second;\n            second->next = firstNext;\n\n            first = firstNext;\n            second = secondNext;\n        }\n    }\n};","filename":"C++"},"revision":1},{"id":"2c40b3d6-b9e0-7048-985e-5bc7cca71159","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public void reorderList(ListNode head) {\n        if (head == null || head.next == null) {\n            return;\n        }\n\n        // Find middle\n        ListNode slow = head;\n        ListNode fast = head;\n\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n\n        // Reverse second half\n        ListNode second = slow.next;\n        slow.next = null;\n\n        ListNode previous = null;\n\n        while (second != null) {\n            ListNode nextNode = second.next;\n            second.next = previous;\n            previous = second;\n            second = nextNode;\n        }\n\n        second = previous;\n        ListNode first = head;\n\n        // Merge\n        while (second != null) {\n            ListNode firstNext = first.next;\n            ListNode secondNext = second.next;\n\n            first.next = second;\n            second.next = firstNext;\n\n            first = firstNext;\n            second = secondNext;\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"5b699795-51d4-713e-9b61-996cbfc78292","type":"code","position":"aK","content":{"language":"javascript","code":"var reorderList = function(head) {\n    if (!head || !head.next) {\n        return;\n    }\n\n    // Find middle\n    let slow = head;\n    let fast = head;\n\n    while (fast && fast.next) {\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n\n    // Reverse second half\n    let second = slow.next;\n    slow.next = null;\n\n    let previous = null;\n\n    while (second) {\n        const nextNode = second.next;\n        second.next = previous;\n        previous = second;\n        second = nextNode;\n    }\n\n    second = previous;\n    let first = head;\n\n    // Merge\n    while (second) {\n        const firstNext = first.next;\n        const secondNext = second.next;\n\n        first.next = second;\n        second.next = firstNext;\n\n        first = firstNext;\n        second = secondNext;\n    }\n};","filename":"JavaScript"},"revision":1},{"id":"c9025743-e9c2-7404-8814-bafb123b7e1a","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(1)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"80fae8f9-9506-7d40-bafa-75b806c72a8c","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"b2db80a4-ff79-7326-aa81-3300f3603b64","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Find Middle + Reverse Second Half + Interleave Merge"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
