":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"21526c62-dbb9-7bf0-a6eb-da2e5336fb8a","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use doubly linked list nodes "},{"type":"text","text":"(key, value, prev, next)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dummy "},{"type":"text","text":"left","marks":[{"type":"code"}]},{"type":"text","text":" (LRU) and "},{"type":"text","text":"right","marks":[{"type":"code"}]},{"type":"text","text":" (Most Recent)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"get(key)","marks":[{"type":"code"}]},{"type":"text","text":": remove node from list, insert at right, return value."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"put(key, val)","marks":[{"type":"code"}]},{"type":"text","text":": remove existing if present, insert new node at right. If capacity exceeded, remove "},{"type":"text","text":"left.next","marks":[{"type":"code"}]},{"type":"text","text":" node from list & cache."}]}]}]}]}},"revision":1},{"id":"bfb9f3df-fd87-7da4-b63b-a3f62ab76897","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"2bdb49e2-4207-7eca-a766-2be7dfd21054","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use a hash map for key-value store and a list for access order (O(n) list removal)."}]}]}},"revision":1},{"id":"b5d6e33b-8476-7789-a152-9dc887bbb6f7","type":"code","position":"aB","content":{"language":"python","code":"class LRUCache:\n\n    def __init__(self, capacity):\n        self.capacity = capacity\n        self.cache = {}\n        self.order = []\n\n    def get(self, key):\n        if key not in self.cache:\n            return -1\n\n        self.order.remove(key)\n        self.order.append(key)\n\n        return self.cache[key]\n\n    def put(self, key, value):\n        if key in self.cache:\n            self.order.remove(key)\n\n        self.cache[key] = value\n        self.order.append(key)\n\n        if len(self.cache) > self.capacity:\n            oldest = self.order.pop(0)\n            del self.cache[oldest]","filename":"Python"},"revision":1},{"id":"1b1b2e90-9bf4-7756-a7d3-807dd2635d95","type":"code","position":"aC","content":{"language":"cpp","code":"class LRUCache {\n    int capacity;\n    unordered_map<int, int> cache;\n    deque<int> order;\n\npublic:\n    LRUCache(int capacity) : capacity(capacity) {}\n\n    int get(int key) {\n        if (!cache.count(key)) {\n            return -1;\n        }\n\n        order.erase(find(order.begin(), order.end(), key));\n        order.push_back(key);\n\n        return cache[key];\n    }\n\n    void put(int key, int value) {\n        if (cache.count(key)) {\n            order.erase(find(order.begin(), order.end(), key));\n        }\n\n        cache[key] = value;\n        order.push_back(key);\n\n        if (cache.size() > capacity) {\n            int oldest = order.front();\n            order.pop_front();\n            cache.erase(oldest);\n        }\n    }\n};","filename":"C++"},"revision":1},{"id":"87bd4c90-191d-7bef-a190-26fdc205c3cf","type":"code","position":"aD","content":{"language":"java","code":"class LRUCache {\n    private int capacity;\n    private Map<Integer, Integer> cache;\n    private LinkedList<Integer> order;\n\n    public LRUCache(int capacity) {\n        this.capacity = capacity;\n        this.cache = new HashMap<>();\n        this.order = new LinkedList<>();\n    }\n\n    public int get(int key) {\n        if (!cache.containsKey(key)) {\n            return -1;\n        }\n\n        order.remove((Integer) key);\n        order.addLast(key);\n\n        return cache.get(key);\n    }\n\n    public void put(int key, int value) {\n        if (cache.containsKey(key)) {\n            order.remove((Integer) key);\n        }\n\n        cache.put(key, value);\n        order.addLast(key);\n\n        if (cache.size() > capacity) {\n            int oldest = order.removeFirst();\n            cache.remove(oldest);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"5d8e4bbd-a5b9-70a6-8e92-296765b46e2f","type":"code","position":"aE","content":{"language":"javascript","code":"class LRUCache {\n    constructor(capacity) {\n        this.capacity = capacity;\n        this.cache = new Map();\n        this.order = [];\n    }\n\n    get(key) {\n        if (!this.cache.has(key)) {\n            return -1;\n        }\n\n        this.order.splice(this.order.indexOf(key), 1);\n        this.order.push(key);\n\n        return this.cache.get(key);\n    }\n\n    put(key, value) {\n        if (this.cache.has(key)) {\n            this.order.splice(this.order.indexOf(key), 1);\n        }\n\n        this.cache.set(key, value);\n        this.order.push(key);\n\n        if (this.cache.size > this.capacity) {\n            const oldest = this.order.shift();\n            this.cache.delete(oldest);\n        }\n    }\n}","filename":"JavaScript"},"revision":1},{"id":"90e5f1bb-1a8f-7e82-9a9f-0528326d9d24","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Get: O(n), Put: O(n) · Space: O(capacity)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"f09df801-9cb6-7f63-b2ba-6fab4bd42d35","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"3e2d3f8b-79e5-719a-8dc2-9c05c521323b","type":"code","position":"aH","content":{"language":"python","code":"class Node:\n    def __init__(self, key=0, value=0):\n        self.key = key\n        self.value = value\n        self.prev = None\n        self.next = None\n\n\nclass LRUCache:\n\n    def __init__(self, capacity):\n        self.capacity = capacity\n        self.cache = {}\n\n        self.left = Node()\n        self.right = Node()\n\n        self.left.next = self.right\n        self.right.prev = self.left\n\n    def remove(self, node):\n        previous = node.prev\n        next_node = node.next\n\n        previous.next = next_node\n        next_node.prev = previous\n\n    def insert(self, node):\n        previous = self.right.prev\n\n        previous.next = node\n        node.prev = previous\n\n        node.next = self.right\n        self.right.prev = node\n\n    def get(self, key):\n        if key not in self.cache:\n            return -1\n\n        node = self.cache[key]\n\n        self.remove(node)\n        self.insert(node)\n\n        return node.value\n\n    def put(self, key, value):\n        if key in self.cache:\n            self.remove(self.cache[key])\n\n        node = Node(key, value)\n\n        self.cache[key] = node\n        self.insert(node)\n\n        if len(self.cache) > self.capacity:\n            lru = self.left.next\n\n            self.remove(lru)\n            del self.cache[lru.key]","filename":"Python"},"revision":1},{"id":"99c7bbe6-f71c-7809-9f9d-894a390151c9","type":"code","position":"aI","content":{"language":"cpp","code":"class LRUCache {\n    struct Node {\n        int key, value;\n        Node* prev = nullptr;\n        Node* next = nullptr;\n        Node(int key = 0, int value = 0) : key(key), value(value) {}\n    };\n\n    int capacity;\n    unordered_map<int, Node*> cache;\n    Node* left;\n    Node* right;\n\n    void remove(Node* node) {\n        Node* previous = node->prev;\n        Node* nextNode = node->next;\n\n        previous->next = nextNode;\n        nextNode->prev = previous;\n    }\n\n    void insert(Node* node) {\n        Node* previous = right->prev;\n\n        previous->next = node;\n        node->prev = previous;\n\n        node->next = right;\n        right->prev = node;\n    }\n\npublic:\n    LRUCache(int capacity) : capacity(capacity) {\n        left = new Node();\n        right = new Node();\n\n        left->next = right;\n        right->prev = left;\n    }\n\n    int get(int key) {\n        if (!cache.count(key)) {\n            return -1;\n        }\n\n        Node* node = cache[key];\n\n        remove(node);\n        insert(node);\n\n        return node->value;\n    }\n\n    void put(int key, int value) {\n        if (cache.count(key)) {\n            remove(cache[key]);\n            delete cache[key];\n        }\n\n        Node* node = new Node(key, value);\n\n        cache[key] = node;\n        insert(node);\n\n        if (cache.size() > capacity) {\n            Node* lru = left->next;\n\n            remove(lru);\n            cache.erase(lru->key);\n            delete lru;\n        }\n    }\n};","filename":"C++"},"revision":1},{"id":"b0418001-7758-79b6-9c73-b5380add51db","type":"code","position":"aJ","content":{"language":"java","code":"class LRUCache {\n    private static class Node {\n        int key, value;\n        Node prev, next;\n\n        Node(int key, int value) {\n            this.key = key;\n            this.value = value;\n        }\n    }\n\n    private int capacity;\n    private Map<Integer, Node> cache;\n    private Node left;\n    private Node right;\n\n    public LRUCache(int capacity) {\n        this.capacity = capacity;\n        this.cache = new HashMap<>();\n\n        this.left = new Node(0, 0);\n        this.right = new Node(0, 0);\n\n        left.next = right;\n        right.prev = left;\n    }\n\n    private void remove(Node node) {\n        Node previous = node.prev;\n        Node nextNode = node.next;\n\n        previous.next = nextNode;\n        nextNode.prev = previous;\n    }\n\n    private void insert(Node node) {\n        Node previous = right.prev;\n\n        previous.next = node;\n        node.prev = previous;\n\n        node.next = right;\n        right.prev = node;\n    }\n\n    public int get(int key) {\n        if (!cache.containsKey(key)) {\n            return -1;\n        }\n\n        Node node = cache.get(key);\n\n        remove(node);\n        insert(node);\n\n        return node.value;\n    }\n\n    public void put(int key, int value) {\n        if (cache.containsKey(key)) {\n            remove(cache.get(key));\n        }\n\n        Node node = new Node(key, value);\n\n        cache.put(key, node);\n        insert(node);\n\n        if (cache.size() > capacity) {\n            Node lru = left.next;\n\n            remove(lru);\n            cache.remove(lru.key);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"fe4050c7-c0d2-7844-9a81-e28f6224ebd7","type":"code","position":"aK","content":{"language":"javascript","code":"class DLLNode {\n    constructor(key = 0, value = 0) {\n        this.key = key;\n        this.value = value;\n        this.prev = null;\n        this.next = null;\n    }\n}\n\nclass LRUCache {\n    constructor(capacity) {\n        this.capacity = capacity;\n        this.cache = new Map();\n\n        this.left = new DLLNode();\n        this.right = new DLLNode();\n\n        this.left.next = this.right;\n        this.right.prev = this.left;\n    }\n\n    remove(node) {\n        const previous = node.prev;\n        const nextNode = node.next;\n\n        previous.next = nextNode;\n        nextNode.prev = previous;\n    }\n\n    insert(node) {\n        const previous = this.right.prev;\n\n        previous.next = node;\n        node.prev = previous;\n\n        node.next = this.right;\n        this.right.prev = node;\n    }\n\n    get(key) {\n        if (!this.cache.has(key)) {\n            return -1;\n        }\n\n        const node = this.cache.get(key);\n\n        this.remove(node);\n        this.insert(node);\n\n        return node.value;\n    }\n\n    put(key, value) {\n        if (this.cache.has(key)) {\n            this.remove(this.cache.get(key));\n        }\n\n        const node = new DLLNode(key, value);\n\n        this.cache.set(key, node);\n        this.insert(node);\n\n        if (this.cache.size > this.capacity) {\n            const lru = this.left.next;\n\n            this.remove(lru);\n            this.cache.delete(lru.key);\n        }\n    }\n}","filename":"JavaScript"},"revision":1},{"id":"e2ba547e-0d38-7372-8262-1caee5bf1d25","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Get: O(1), Put: O(1) · Space: O(capacity)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"5abcccc7-ed4b-743b-a64f-c569955f79c7","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"1628d2ff-5885-773e-9911-ffc2d33b2289","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — HashMap + Doubly Linked List for O(1) lookup & order manipulation"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
