  ('2bdb49e2-4207-7eca-a766-2be7dfd21054', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use a hash map for key-value store and a list for access order (O(n) list removal)."}]}]}}'),
  ('b5d6e33b-8476-7789-a152-9dc887bbb6f7', 'aB', 'code', '{"language":"python","code":"class LRUCache:\n\n    def __init__(self, capacity):\n        self.capacity = capacity\n        self.cache = {}\n        self.order = []\n\n    def get(self, key):\n        if key not in self.cache:\n            return -1\n\n        self.order.remove(key)\n        self.order.append(key)\n\n        return self.cache[key]\n\n    def put(self, key, value):\n        if key in self.cache:\n            self.order.remove(key)\n\n        self.cache[key] = value\n        self.order.append(key)\n\n        if len(self.cache) > self.capacity:\n            oldest = self.order.pop(0)\n            del self.cache[oldest]","filename":"Python"}'),
  ('1b1b2e90-9bf4-7756-a7d3-807dd2635d95', 'aC', 'code', '{"language":"cpp","code":"class LRUCache {\n    int capacity;\n    unordered_map<int, int> cache;\n    deque<int> order;\n\npublic:\n    LRUCache(int capacity) : capacity(capacity) {}\n\n    int get(int key) {\n        if (!cache.count(key)) {\n            return -1;\n        }\n\n        order.erase(find(order.begin(), order.end(), key));\n        order.push_back(key);\n\n        return cache[key];\n    }\n\n    void put(int key, int value) {\n        if (cache.count(key)) {\n            order.erase(find(order.begin(), order.end(), key));\n        }\n\n        cache[key] = value;\n        order.push_back(key);\n\n        if (cache.size() > capacity) {\n            int oldest = order.front();\n            order.pop_front();\n            cache.erase(oldest);\n        }\n    }\n};","filename":"C++"}'),
  ('87bd4c90-191d-7bef-a190-26fdc205c3cf', 'aD', 'code', '{"language":"java","code":"class LRUCache {\n    private int capacity;\n    private Map<Integer, Integer> cache;\n    private LinkedList<Integer> order;\n\n    public LRUCache(int capacity) {\n        this.capacity = capacity;\n        this.cache = new HashMap<>();\n        this.order = new LinkedList<>();\n    }\n\n    public int get(int key) {\n        if (!cache.containsKey(key)) {\n            return -1;\n        }\n\n        order.remove((Integer) key);\n        order.addLast(key);\n\n        return cache.get(key);\n    }\n\n    public void put(int key, int value) {\n        if (cache.containsKey(key)) {\n            order.remove((Integer) key);\n        }\n\n        cache.put(key, value);\n        order.addLast(key);\n\n        if (cache.size() > capacity) {\n            int oldest = order.removeFirst();\n            cache.remove(oldest);\n        }\n    }\n}","filename":"Java"}'),
  ('5d8e4bbd-a5b9-70a6-8e92-296765b46e2f', 'aE', 'code', '{"language":"javascript","code":"class LRUCache {\n    constructor(capacity) {\n        this.capacity = capacity;\n        this.cache = new Map();\n        this.order = [];\n    }\n\n    get(key) {\n        if (!this.cache.has(key)) {\n            return -1;\n        }\n\n        this.order.splice(this.order.indexOf(key), 1);\n        this.order.push(key);\n\n        return this.cache.get(key);\n    }\n\n    put(key, value) {\n        if (this.cache.has(key)) {\n            this.order.splice(this.order.indexOf(key), 1);\n        }\n\n        this.cache.set(key, value);\n        this.order.push(key);\n\n        if (this.cache.size > this.capacity) {\n            const oldest = this.order.shift();\n            this.cache.delete(oldest);\n        }\n    }\n}","filename":"JavaScript"}'),
