SELECT 'a4a998bf-e790-7fb4-8243-7158d21088ad', '4853f46f-45ef-7c77-b4a7-c2695d8de430', 1, 'PUBLISHED', 'Evaluate Reverse Polish Notation', '[{"id":"ce5f4bb8-118a-75ac-9c1f-22b607cddce6","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 150","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/evaluate-reverse-polish-notation/"}}]}]}]}},"revision":1},{"id":"4eecdf86-55ee-71f1-9968-77cb44942cde","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"cd6d3a07-2c23-777d-a283-159a2e1a141c","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Evaluate the value of an arithmetic expression in Reverse Polish Notation (postfix). Valid operators are "},{"type":"text","text":"''+''","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"''-''","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"''*''","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"''/''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"a601ffea-abfc-7166-a37f-9610b5258a32","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"b6b7a824-fd5a-7129-a361-c6b5567ba834","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In RPN, operators follow their operands: e.g. "},{"type":"text","text":"[''2'', ''1'', ''+'', ''3'', ''*'']","marks":[{"type":"code"}]},{"type":"text","text":" = "},{"type":"text","text":"(2 + 1) * 3 = 9","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"cf9a02dd-9ef1-7402-a87b-3ba5e0fbb13a","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"d884b14b-001c-7457-aaef-b0c21968c0ae","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use an operand stack. Push numbers. On operator, pop top 2 numbers (second popped is left operand), evaluate result, and push back."}]}]}},"revision":1},{"id":"d7a04ac1-a2ea-7363-b669-d6a667bf7072","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"42f4ce51-4a7e-75ae-a1ca-d5da68df5c3d","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize empty "},{"type":"text","text":"stack","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Iterate through "},{"type":"text","text":"tokens","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If integer: push "},{"type":"text","text":"int(token)","marks":[{"type":"code"}]},{"type":"text","text":" to stack."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If operator: pop "},{"type":"text","text":"b = stack.pop()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"a = stack.pop()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Perform operation (truncating division toward zero "},{"type":"text","text":"int(a / b)","marks":[{"type":"code"}]},{"type":"text","text":"), push result to stack."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"stack[-1]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"04eff161-2685-7f4f-9a01-b796695886cd","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"14fba38a-1b0f-7d8c-8d8f-14b4fc90b42d","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Repeatedly scan token array, find first operator, evaluate previous 2 operands, and replace sub-slice in token list."}]}]}},"revision":1},{"id":"1735b711-fcd5-7552-b0dd-0974aef379e5","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def evalRPN(self, tokens):\n\n        tokens = tokens[:]\n\n        operators = {\"+\", \"-\", \"*\", \"/\"}\n\n        while len(tokens) > 1:\n            for i, token in enumerate(tokens):\n\n                if token not in operators:\n                    continue\n\n                a = int(tokens[i - 2])\n                b = int(tokens[i - 1])\n\n                if token == \"+\":\n                    result = a + b\n                elif token == \"-\":\n                    result = a - b\n                elif token == \"*\":\n                    result = a * b\n                else:\n                    result = int(a / b)\n\n                tokens[i - 2:i + 1] = [str(result)]\n                break\n\n        return int(tokens[0])","filename":"Python"},"revision":1},{"id":"f0041635-7624-7048-9f56-fe4babc07c9a","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int evalRPN(vector<string>& tokens) {\n        vector<string> t = tokens;\n        while (t.size() > 1) {\n            for (int i = 0; i < t.size(); i++) {\n                const string& token = t[i];\n                if (token != \"+\" && token != \"-\" && token != \"*\" && token != \"/\") continue;\n                int a = stoi(t[i - 2]), b = stoi(t[i - 1]);\n                int result;\n                if (token == \"+\") result = a + b;\n                else if (token == \"-\") result = a - b;\n                else if (token == \"*\") result = a * b;\n                else result = a / b;\n                t.erase(t.begin() + i - 2, t.begin() + i + 1);\n                t.insert(t.begin() + i - 2, to_string(result));\n                break;\n            }\n        }\n        return stoi(t[0]);\n    }\n};","filename":"C++"},"revision":1},{"id":"9841ae1a-62f2-7873-8d17-b88f78b3cc6b","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int evalRPN(String[] tokens) {\n        List<String> t = new ArrayList<>(Arrays.asList(tokens));\n        Set<String> operators = Set.of(\"+\", \"-\", \"*\", \"/\");\n        while (t.size() > 1) {\n            for (int i = 0; i < t.size(); i++) {\n                String token = t.get(i);\n                if (!operators.contains(token)) continue;\n                int a = Integer.parseInt(t.get(i - 2));\n                int b = Integer.parseInt(t.get(i - 1));\n                int result;\n                if (token.equals(\"+\")) result = a + b;\n                else if (token.equals(\"-\")) result = a - b;\n                else if (token.equals(\"*\")) result = a * b;\n                else result = a / b;\n                t.subList(i - 2, i + 1).clear();\n                t.add(i - 2, String.valueOf(result));\n                break;\n            }\n        }\n        return Integer.parseInt(t.get(0));\n    }\n}","filename":"Java"},"revision":1},{"id":"39a9672c-98c3-710b-a661-f1de2244b6a7","type":"code","position":"aE","content":{"language":"javascript","code":"var evalRPN = function(tokens) {\n    tokens = tokens.slice();\n    const operators = new Set([\"+\", \"-\", \"*\", \"/\"]);\n    while (tokens.length > 1) {\n        for (let i = 0; i < tokens.length; i++) {\n            const token = tokens[i];\n            if (!operators.has(token)) continue;\n            const a = parseInt(tokens[i - 2]), b = parseInt(tokens[i - 1]);\n            let result;\n            if (token === \"+\") result = a + b;\n            else if (token === \"-\") result = a - b;\n            else if (token === \"*\") result = a * b;\n            else result = Math.trunc(a / b);\n            tokens.splice(i - 2, 3, String(result));\n            break;\n        }\n    }\n    return parseInt(tokens[0]);\n};","filename":"JavaScript"},"revision":1},{"id":"7e3841d7-db3d-7e35-9c4f-215cafeb5d55","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n²) · Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"e7709958-b5cf-7221-b7c5-023df4ab01a1","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"c1951744-9fed-70c5-a84d-66d63c30778c","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def evalRPN(self, tokens):\n        stack = []\n\n        operators = {\"+\", \"-\", \"*\", \"/\"}\n\n        for token in tokens:\n\n            if token not in operators:\n                stack.append(int(token))\n                continue\n\n            b = stack.pop()\n            a = stack.pop()\n\n            if token == \"+\":\n                result = a + b\n            elif token == \"-\":\n                result = a - b\n            elif token == \"*\":\n                result = a * b\n            else:\n                result = int(a / b)\n\n            stack.append(result)\n\n        return stack[-1]","filename":"Python"},"revision":1},{"id":"4467b164-6652-7deb-8580-15980a7b29e1","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int evalRPN(vector<string>& tokens) {\n        stack<int> st;\n        for (const string& token : tokens) {\n            if (token != \"+\" && token != \"-\" && token != \"*\" && token != \"/\") {\n                st.push(stoi(token));\n                continue;\n            }\n            int b = st.top(); st.pop();\n            int a = st.top(); st.pop();\n            int result;\n            if (token == \"+\") result = a + b;\n            else if (token == \"-\") result = a - b;\n            else if (token == \"*\") result = a * b;\n            else result = a / b;\n            st.push(result);\n        }\n        return st.top();\n    }\n};","filename":"C++"},"revision":1},{"id":"77ba2352-0e76-7a14-a259-0bdb419e6f90","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int evalRPN(String[] tokens) {\n        Deque<Integer> stack = new ArrayDeque<>();\n        Set<String> operators = Set.of(\"+\", \"-\", \"*\", \"/\");\n        for (String token : tokens) {\n            if (!operators.contains(token)) {\n                stack.push(Integer.parseInt(token));\n                continue;\n            }\n            int b = stack.pop();\n            int a = stack.pop();\n            int result;\n            if (token.equals(\"+\")) result = a + b;\n            else if (token.equals(\"-\")) result = a - b;\n            else if (token.equals(\"*\")) result = a * b;\n            else result = a / b;\n            stack.push(result);\n        }\n        return stack.peek();\n    }\n}","filename":"Java"},"revision":1},{"id":"9c58a6bb-f4ab-79d1-9f0f-da87adbddaf7","type":"code","position":"aK","content":{"language":"javascript","code":"var evalRPN = function(tokens) {\n    const stack = [];\n    const operators = new Set([\"+\", \"-\", \"*\", \"/\"]);\n    for (const token of tokens) {\n        if (!operators.has(token)) {\n            stack.push(parseInt(token));\n            continue;\n        }\n        const b = stack.pop();\n        const a = stack.pop();\n        let result;\n        if (token === \"+\") result = a + b;\n        else if (token === \"-\") result = a - b;\n        else if (token === \"*\") result = a * b;\n        else result = Math.trunc(a / b);\n        stack.push(result);\n    }\n    return stack[stack.length - 1];\n};","filename":"JavaScript"},"revision":1},{"id":"2ed3377d-8590-7e7d-a54d-2cafeeff95f9","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"08faa1b2-e3a9-715c-9ddd-790c6913c7e1","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"57ff7943-330c-78ee-b0cc-9e1198671978","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Operand → push; Operator → pop two → calculate → push result"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
