"}]},{"type":"text","text":" and "},{"type":"text","text":"current_min","marks":[{"type":"code"}]},{"type":"text","text":". When "},{"type":"text","text":"num < 0","marks":[{"type":"code"}]},{"type":"text","text":", swap "},{"type":"text","text":"current_max","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"current_min","marks":[{"type":"code"}]},{"type":"text","text":" before updating."}]}]}},"revision":1},{"id":"4f487b18-5247-7273-957d-9348510fb42b","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"5e76a697-990b-7481-a9da-c9a47c952ab1","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize "},{"type":"text","text":"current_max = nums[0]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"current_min = nums[0]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"answer = nums[0]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For "},{"type":"text","text":"num","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"nums[1:]","marks":[{"type":"code"}]},{"type":"text","text":": if "},{"type":"text","text":"num < 0","marks":[{"type":"code"}]},{"type":"text","text":", swap "},{"type":"text","text":"current_max, current_min","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Update "},{"type":"text","text":"current_max = max(num, current_max * num)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"current_min = min(num, current_min * num)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Update "},{"type":"text","text":"answer = max(answer, current_max)","marks":[{"type":"code"}]},{"type":"text","text":". Return "},{"type":"text","text":"answer","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"a10a6bd8-1752-7eb9-ba25-534a204abf5c","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"e244ca44-2dbc-78f3-bc42-04036598684e","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Calculate product of every subarray using nested loops."}]}]}},"revision":1},{"id":"cd422ffe-f7dd-76b3-9e25-701ce07a5bdb","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def maxProduct(self, nums):\n\n        answer = nums[0]\n\n        for i in range(len(nums)):\n            product = 1\n\n            for j in range(i, len(nums)):\n                product *= nums[j]\n                answer = max(answer, product)\n\n        return answer","filename":"Python"},"revision":1},{"id":"ca3d7572-5dc0-7cb0-947a-5bb776bad6d2","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int maxProduct(vector<int>& nums) {\n        long long answer = nums[0];\n\n        for (int i = 0; i < (int)nums.size(); i++) {\n            long long product = 1;\n\n            for (int j = i; j < (int)nums.size(); j++) {\n                product *= nums[j];\n                answer = max(answer, product);\n            }\n        }\n\n        return (int)answer;\n    }\n};","filename":"C++"},"revision":1},{"id":"7b21d886-d2da-7a82-9ce1-059c146cbe31","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int maxProduct(int[] nums) {\n        long answer = nums[0];\n\n        for (int i = 0; i < nums.length; i++) {\n            long product = 1;\n\n            for (int j = i; j < nums.length; j++) {\n                product *= nums[j];\n                answer = Math.max(answer, product);\n            }\n        }\n\n        return (int) answer;\n    }\n}","filename":"Java"},"revision":1},{"id":"02c8b17e-733e-74d4-a6db-ab4c165e7da0","type":"code","position":"aE","content":{"language":"javascript","code":"var maxProduct = function(nums) {\n    let answer = nums[0];\n\n    for (let i = 0; i < nums.length; i++) {\n        let product = 1;\n\n        for (let j = i; j < nums.length; j++) {\n            product *= nums[j];\n            answer = Math.max(answer, product);\n        }\n    }\n\n    return answer;\n};","filename":"JavaScript"},"revision":1},{"id":"e2294570-4fe0-7382-a67b-046bb14014ce","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n²) · Aux Space: O(1)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"57ada390-0719-74db-97a5-dfffeee73b72","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"cc04449c-f326-789f-ae90-7e66e77965a9","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def maxProduct(self, nums):\n\n        current_max = nums[0]\n        current_min = nums[0]\n        answer = nums[0]\n\n        for num in nums[1:]:\n\n            if num < 0:\n                current_max, current_min = (\n                    current_min,\n                    current_max\n                )\n\n            current_max = max(\n                num,\n                current_max * num\n            )\n\n            current_min = min(\n                num,\n                current_min * num\n            )\n\n            answer = max(answer, current_max)\n\n        return answer","filename":"Python"},"revision":1},{"id":"6a1cbb21-464e-7ccc-9308-55e428a4a9b3","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int maxProduct(vector<int>& nums) {\n        long long currentMax = nums[0];\n        long long currentMin = nums[0];\n        long long answer = nums[0];\n\n        for (int i = 1; i < (int)nums.size(); i++) {\n            long long num = nums[i];\n\n            if (num < 0) swap(currentMax, currentMin);\n\n            currentMax = max(num, currentMax * num);\n            currentMin = min(num, currentMin * num);\n\n            answer = max(answer, currentMax);\n        }\n\n        return (int)answer;\n    }\n};","filename":"C++"},"revision":1},{"id":"96b61e45-3b43-7a1d-acf7-bab589867ac6","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int maxProduct(int[] nums) {\n        long currentMax = nums[0];\n        long currentMin = nums[0];\n        long answer = nums[0];\n\n        for (int i = 1; i < nums.length; i++) {\n            long num = nums[i];\n\n            if (num < 0) {\n                long temp = currentMax;\n                currentMax = currentMin;\n                currentMin = temp;\n            }\n\n            currentMax = Math.max(num, currentMax * num);\n            currentMin = Math.min(num, currentMin * num);\n\n            answer = Math.max(answer, currentMax);\n        }\n\n        return (int) answer;\n    }\n}","filename":"Java"},"revision":1},{"id":"e3d1cec9-1d4b-74a8-aa8d-c6451e5b358b","type":"code","position":"aK","content":{"language":"javascript","code":"var maxProduct = function(nums) {\n    let currentMax = nums[0];\n    let currentMin = nums[0];\n    let answer = nums[0];\n\n    for (let i = 1; i < nums.length; i++) {\n        const num = nums[i];\n\n        if (num < 0) {\n            [currentMax, currentMin] = [currentMin, currentMax];\n        }\n\n        currentMax = Math.max(num, currentMax * num);\n        currentMin = Math.min(num, currentMin * num);\n\n        answer = Math.max(answer, currentMax);\n    }\n\n    return answer;\n};","filename":"JavaScript"},"revision":1},{"id":"ab925079-e285-713e-a743-cc996edeea99","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(1)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"9d133573-f7d3-7206-ad58-88cfe5502a84","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"dd68ee66-8080-7140-ac50-38abcbbcbd3d","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the operation can flip states, track both max and min.","marks":[{"type":"bold"}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
