class MinStack:

    def __init__(self):
        self.stack = []
        self.minimum = []

    def push(self, val):
        self.stack.append(val)

        if not self.minimum:
            self.minimum.append(val)
        else:
            self.minimum.append(
                min(val, self.minimum[-1])
            )

    def pop(self):
        self.minimum.pop()
        return self.stack.pop()

    def top(self):
        return self.stack[-1]

    def getMin(self):
        return self.minimum[-1]
