        total_cost = 0
        used = 0

        for dist, i, j in edges:
            root_i = find(i)
            root_j = find(j)

            if root_i == root_j:
                continue

            parent[root_i] = root_j
            total_cost += dist
            used += 1

            if used == n - 1:
                break

        return total_cost
class Solution {
public:
    int minCostConnectPoints(vector<vector<int>>& points) {
        int n = points.size();

        // Build every edge (dist, i, j) and sort them
        vector<array<int, 3>> edges;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int dist = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1]);
                edges.push_back({dist, i, j});
            }
        }
        sort(edges.begin(), edges.end());

        vector<int> parent(n);
        iota(parent.begin(), parent.end(), 0);

        function<int(int)> find = [&](int x) {
            return parent[x] == x ? x : parent[x] = find(parent[x]);
        };

        int totalCost = 0, used = 0;

        for (auto& [dist, i, j] : edges) {
            int rootI = find(i), rootJ = find(j);
            if (rootI == rootJ) continue;

            parent[rootI] = rootJ;
            totalCost += dist;

            if (++used == n - 1) break;
        }

        return totalCost;
    }
};
class Solution {
    private int[] parent;

    public int minCostConnectPoints(int[][] points) {
        int n = points.length;

        // Build every edge (dist, i, j) and sort them
        List<int[]> edges = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int dist = Math.abs(points[i][0] - points[j][0]) + Math.abs(points[i][1] - points[j][1]);
                edges.add(new int[]{dist, i, j});
            }
        }
        edges.sort((a, b) -> Integer.compare(a[0], b[0]));

        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        int totalCost = 0, used = 0;

        for (int[] e : edges) {
            int rootI = find(e[1]), rootJ = find(e[2]);
            if (rootI == rootJ) continue;

            parent[rootI] = rootJ;
            totalCost += e[0];

            if (++used == n - 1) break;
        }

        return totalCost;
    }

    private int find(int x) {
        while (x != parent[x]) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
}
var minCostConnectPoints = function(points) {
    const n = points.length;

    // Build every edge [dist, i, j] and sort them
    const edges = [];
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            const dist = Math.abs(points[i][0] - points[j][0]) + Math.abs(points[i][1] - points[j][1]);
            edges.push([dist, i, j]);
        }
    }
    edges.sort((a, b) => a[0] - b[0]);

    const parent = Array.from({ length: n }, (_, i) => i);

    const find = (x) => {
        while (x !== parent[x]) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    let totalCost = 0, used = 0;

    for (const [dist, i, j] of edges) {
        const rootI = find(i), rootJ = find(j);
        if (rootI === rootJ) continue;

        parent[rootI] = rootJ;
        totalCost += dist;

        if (++used === n - 1) break;
    }

    return totalCost;
};
