list of mappings and construct the string directly with index offsets ("},{"type":"text","text":"ord(digits[index]) - ord(''0'')","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"95047e9d-850e-7c80-b6a8-763e6317b905","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"16c78997-7066-716b-a0bb-b1e320522502","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"[]","marks":[{"type":"code"}]},{"type":"text","text":" if "},{"type":"text","text":"digits","marks":[{"type":"code"}]},{"type":"text","text":" is empty."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize array "},{"type":"text","text":"phone","marks":[{"type":"code"}]},{"type":"text","text":" indexed from 0 to 9."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Define "},{"type":"text","text":"backtrack(index, current)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"index == len(digits)","marks":[{"type":"code"}]},{"type":"text","text":", append "},{"type":"text","text":"\"\".join(current)","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"result","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Get mapped string using "},{"type":"text","text":"phone[ord(digits[index]) - ord(''0'')]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loop through characters, append, recurse "},{"type":"text","text":"index + 1","marks":[{"type":"code"}]},{"type":"text","text":", and pop."}]}]}]}]}},"revision":1},{"id":"dbeaf2f1-7bd5-7b10-98bb-742a253a3072","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution"}]},"revision":1},{"id":"deb00b0d-d3c0-7171-abae-45b30e3e8183","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Build all combinations using recursion with a dictionary lookup for key mapping."}]}]}},"revision":1},{"id":"f33eb225-d595-77f3-a6d1-b463a676abd6","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def letterCombinations(self, digits):\n        if not digits:\n            return []\n\n        phone = {\n            ''2'': ''abc'',\n            ''3'': ''def'',\n            ''4'': ''ghi'',\n            ''5'': ''jkl'',\n            ''6'': ''mno'',\n            ''7'': ''pqrs'',\n            ''8'': ''tuv'',\n            ''9'': ''wxyz''\n        }\n\n        result = []\n\n        def backtrack(index, current):\n            if index == len(digits):\n                result.append(\"\".join(current))\n                return\n\n            for char in phone[digits[index]]:\n                current.append(char)\n                backtrack(index + 1, current)\n                current.pop()\n\n        backtrack(0, [])\n        return result","filename":"Python"},"revision":1},{"id":"f6fc8ff4-efe8-7106-86f5-8f870a0cfd9f","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<string> letterCombinations(string digits) {\n        if (digits.empty()) return {};\n\n        unordered_map<char, string> phone = {\n            {''2'', \"abc\"}, {''3'', \"def\"}, {''4'', \"ghi\"}, {''5'', \"jkl\"},\n            {''6'', \"mno\"}, {''7'', \"pqrs\"}, {''8'', \"tuv\"}, {''9'', \"wxyz\"}\n        };\n\n        vector<string> result;\n        string current;\n        backtrack(digits, 0, phone, current, result);\n        return result;\n    }\n\nprivate:\n    void backtrack(const string& digits, int index, unordered_map<char, string>& phone,\n                   string& current, vector<string>& result) {\n        if (index == (int)digits.size()) {\n            result.push_back(current);\n            return;\n        }\n\n        for (char ch : phone[digits[index]]) {\n            current.push_back(ch);\n            backtrack(digits, index + 1, phone, current, result);\n            current.pop_back();\n        }\n    }\n};","filename":"C++"},"revision":1},{"id":"e2081126-6c4e-77d5-aaeb-d7fd79fd075b","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public List<String> letterCombinations(String digits) {\n        List<String> result = new ArrayList<>();\n        if (digits.isEmpty()) return result;\n\n        Map<Character, String> phone = Map.of(\n            ''2'', \"abc\", ''3'', \"def\", ''4'', \"ghi\", ''5'', \"jkl\",\n            ''6'', \"mno\", ''7'', \"pqrs\", ''8'', \"tuv\", ''9'', \"wxyz\"\n        );\n\n        backtrack(digits, 0, phone, new StringBuilder(), result);\n        return result;\n    }\n\n    private void backtrack(String digits, int index, Map<Character, String> phone,\n                           StringBuilder current, List<String> result) {\n        if (index == digits.length()) {\n            result.add(current.toString());\n            return;\n        }\n\n        for (char ch : phone.get(digits.charAt(index)).toCharArray()) {\n            current.append(ch);\n            backtrack(digits, index + 1, phone, current, result);\n            current.deleteCharAt(current.length() - 1);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"7dc6913a-13f3-7e6a-a859-dac44c54fa54","type":"code","position":"aE","content":{"language":"javascript","code":"var letterCombinations = function(digits) {\n    if (!digits) return [];\n\n    const phone = {\n        ''2'': ''abc'',\n        ''3'': ''def'',\n        ''4'': ''ghi'',\n        ''5'': ''jkl'',\n        ''6'': ''mno'',\n        ''7'': ''pqrs'',\n        ''8'': ''tuv'',\n        ''9'': ''wxyz''\n    };\n\n    const result = [];\n\n    const backtrack = (index, current) => {\n        if (index === digits.length) {\n            result.push(current.join(''''));\n            return;\n        }\n\n        for (const ch of phone[digits[index]]) {\n            current.push(ch);\n            backtrack(index + 1, current);\n            current.pop();\n        }\n    };\n\n    backtrack(0, []);\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"faefc02a-9786-7381-b32d-bdb77fe86535","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(4^n × n) · Aux Space: O(n) · Output Space: O(4^n × n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"6bf37d35-6c7a-7bb0-9b5c-3e758ede7fdb","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Code (Optimized)"}]},"revision":1},{"id":"20c96e90-4177-74d9-bfe1-091533065670","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def letterCombinations(self, digits):\n        if not digits:\n            return []\n\n        phone = [\n            \"\",\n            \"\",\n            \"abc\",\n            \"def\",\n            \"ghi\",\n            \"jkl\",\n            \"mno\",\n            \"pqrs\",\n            \"tuv\",\n            \"wxyz\"\n        ]\n\n        result = []\n\n        def backtrack(index, current):\n            if index == len(digits):\n                result.append(\"\".join(current))\n                return\n\n            letters = phone[ord(digits[index]) - ord(''0'')]\n\n            for char in letters:\n                current.append(char)\n                backtrack(index + 1, current)\n                current.pop()\n\n        backtrack(0, [])\n        return result","filename":"Python"},"revision":1},{"id