  ('06c26fec-b1be-7f99-83e5-ae2312178501', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def mergeTriplets(self, triplets, target):\n        n = len(triplets)\n\n        def dfs(index, current):\n            if current == target:\n                return True\n\n            if index == n:\n                return False\n\n            if dfs(index + 1, current):\n                return True\n\n            triplet = triplets[index]\n\n            if all(\n                triplet[i] <= target[i]\n                for i in range(3)\n            ):\n                merged = [\n                    max(current[i], triplet[i])\n                    for i in range(3)\n                ]\n\n                if dfs(index + 1, merged):\n                    return True\n\n            return False\n\n        return dfs(0, [0, 0, 0])","filename":"Python"}'),
  ('af78079b-0c1e-7ed6-a909-6192b0099da9', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    bool mergeTriplets(vector<vector<int>>& triplets, vector<int>& target) {\n        return dfs(triplets, target, 0, {0, 0, 0});\n    }\n\nprivate:\n    bool dfs(vector<vector<int>>& triplets, vector<int>& target, int index, vector<int> current) {\n        if (current == target) {\n            return true;\n        }\n\n        if (index == (int)triplets.size()) {\n            return false;\n        }\n\n        if (dfs(triplets, target, index + 1, current)) {\n            return true;\n        }\n\n        vector<int>& triplet = triplets[index];\n\n        if (triplet[0] <= target[0] && triplet[1] <= target[1] && triplet[2] <= target[2]) {\n            vector<int> merged(3);\n            for (int i = 0; i < 3; i++) {\n                merged[i] = max(current[i], triplet[i]);\n            }\n\n            if (dfs(triplets, target, index + 1, merged)) {\n                return true;\n            }\n        }\n\n        return false;\n    }\n};","filename":"C++"}'),
  ('1bc91725-fe67-76eb-b1f7-31e51f900ca5', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public boolean mergeTriplets(int[][] triplets, int[] target) {\n        return dfs(triplets, target, 0, new int[]{0, 0, 0});\n    }\n\n    private boolean dfs(int[][] triplets, int[] target, int index, int[] current) {\n        if (Arrays.equals(current, target)) {\n            return true;\n        }\n\n        if (index == triplets.length) {\n            return false;\n        }\n\n        if (dfs(triplets, target, index + 1, current)) {\n            return true;\n        }\n\n        int[] triplet = triplets[index];\n\n        if (triplet[0] <= target[0] && triplet[1] <= target[1] && triplet[2] <= target[2]) {\n            int[] merged = new int[3];\n            for (int i = 0; i < 3; i++) {\n                merged[i] = Math.max(current[i], triplet[i]);\n            }\n\n            if (dfs(triplets, target, index + 1, merged)) {\n                return true;\n            }\n        }\n\n        return false;\n    }\n}","filename":"Java"}'),
  ('6381d282-8e7e-78be-991a-4df07bb7f182', 'aE', 'code', '{"language":"javascript","code":"var mergeTriplets = function(triplets, target) {\n    const n = triplets.length;\n\n    const dfs = (index, current) => {\n        if (current.every((v, i) => v === target[i])) {\n            return true;\n        }\n\n        if (index === n) {\n            return false;\n        }\n\n        if (dfs(index + 1, current)) {\n            return true;\n        }\n\n        const triplet = triplets[index];\n\n        if (triplet.every((v, i) => v <= target[i])) {\n            const merged = current.map((v, i) => Math.max(v, triplet[i]));\n\n            if (dfs(index + 1, merged)) {\n                return true;\n            }\n        }\n\n        return false;\n    };\n\n    return dfs(0, [0, 0, 0]);\n};","filename":"JavaScript"}'),
  ('72c0786c-0e79-74da-b4ac-d24600ea1130', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(2ⁿ) · Space: O(n) recursion","marks":[{"type":"bold"}]}]}]}}'),
