  ('a0158c79-0cb2-7236-a0ce-df2845697f55', 'aH', 'code', '{"language":"python","code":"class Solution:\n    def mergeTriplets(self, triplets, target):\n        found = [False, False, False]\n\n        for triplet in triplets:\n            if any(\n                triplet[i] > target[i]\n                for i in range(3)\n            ):\n                continue\n\n            for i in range(3):\n                if triplet[i] == target[i]:\n                    found[i] = True\n\n        return all(found)","filename":"Python"}'),
  ('85230557-7100-73a6-8a53-ad89a25e8bf7', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    bool mergeTriplets(vector<vector<int>>& triplets, vector<int>& target) {\n        bool found[3] = {false, false, false};\n\n        for (auto& triplet : triplets) {\n            if (triplet[0] > target[0] || triplet[1] > target[1] || triplet[2] > target[2]) {\n                continue;\n            }\n\n            for (int i = 0; i < 3; i++) {\n                if (triplet[i] == target[i]) {\n                    found[i] = true;\n                }\n            }\n        }\n\n        return found[0] && found[1] && found[2];\n    }\n};","filename":"C++"}'),
  ('d518c384-c431-7593-a20c-6f06fbf1d106', 'aJ', 'code', '{"language":"java","code":"class Solution {\n    public boolean mergeTriplets(int[][] triplets, int[] target) {\n        boolean[] found = new boolean[3];\n\n        for (int[] triplet : triplets) {\n            if (triplet[0] > target[0] || triplet[1] > target[1] || triplet[2] > target[2]) {\n                continue;\n            }\n\n            for (int i = 0; i < 3; i++) {\n                if (triplet[i] == target[i]) {\n                    found[i] = true;\n                }\n            }\n        }\n\n        return found[0] && found[1] && found[2];\n    }\n}","filename":"Java"}'),
  ('6ed8678e-fa7e-79bc-9a0c-c8a990d1669f', 'aK', 'code', '{"language":"javascript","code":"var mergeTriplets = function(triplets, target) {\n    const found = [false, false, false];\n\n    for (const triplet of triplets) {\n        if (triplet.some((v, i) => v > target[i])) {\n            continue;\n        }\n\n        for (let i = 0; i < 3; i++) {\n            if (triplet[i] === target[i]) {\n                found[i] = true;\n            }\n        }\n    }\n\n    return found.every(Boolean);\n};","filename":"JavaScript"}'),
