        }

        const triplet = triplets[index];

        if (triplet.every((v, i) => v <= target[i])) {
            const merged = current.map((v, i) => Math.max(v, triplet[i]));

            if (dfs(index + 1, merged)) {
                return true;
            }
        }

        return false;
    };

    return dfs(0, [0, 0, 0]);
};
