ks":[{"type":"code"}]},{"type":"text","text":" flips the lowest set bit and all bits below it. So "},{"type":"text","text":"n & (n-1)","marks":[{"type":"code"}]},{"type":"text","text":" removes exactly the lowest 1-bit. Each iteration costs one set bit — loop runs exactly "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" times where "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" is the Hamming weight."}]}]}},"revision":1},{"id":"60adaae9-ca34-7752-a165-eb0cba1c7122","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"29cf559f-1dad-70f0-bbeb-2af5afce66f5","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize "},{"type":"text","text":"count = 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"While "},{"type":"text","text":"n != 0","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"n &= n - 1","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"count += 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"count","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"07f1398b-6b6d-7a73-9ded-6bb5f30c4ea7","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"d417a3f7-9a9c-7b87-a1dc-c19f698ec3b6","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Check all 32 bits one by one using "},{"type":"text","text":"n & 1","marks":[{"type":"code"}]},{"