SELECT '76eb0fa8-a34c-776f-9ba3-f2821ea39028', 'b1c41a69-47f2-796c-aaea-23fa03a12939', 1, 'PUBLISHED', 'House Robber', '[{"id":"57841ce9-b1b8-7655-81bb-461fda541c0c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 198","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/house-robber/"}}]}]}]}},"revision":1},{"id":"1e71d723-73d5-7248-9cb5-ddd524fb6fdc","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"90d96fe0-d58a-73c4-a855-cbcd88e17608","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You are a professional robber planning to rob houses along a street. Each house has a certain amount of money stashed. Adjacent houses have security systems connected, so you cannot rob two adjacent houses. Return maximum money you can rob."}]}]}},"revision":1},{"id":"745ea38e-1dc7-743a-88d6-3b65b191b18b","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"f4ae3d76-cdc9-7edb-962a-7922a77ea6e5","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At every house: Rob it (gain "},{"type":"text","text":"nums[i]","marks":[{"type":"code"}]},{"type":"text","text":" + profit from house "},{"type":"text","text":"i-2","marks":[{"type":"code"}]},{"type":"text","text":") OR skip it (keep profit from house "},{"type":"text","text":"i-1","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"bd80e4f8-13a3-71ac-b420-fce2b926cc58","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{