SELECT '43e6e138-33e6-79ff-888a-c432fde68e9c', '57f4718e-3a02-7928-a5a3-21734caf8c13', 1, 'PUBLISHED', 'Add Two Numbers', '[{"id":"a7dea650-b825-740f-bb45-17e5fd2438cd","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 2","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/add-two-numbers/"}}]}]}]}},"revision":1},{"id":"a19294af-5e07-7d6b-bf7d-bc43b373d0b0","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"30f73778-1907-76de-b938-f659ff75f766","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given two non-empty linked lists representing two non-negative integers in reverse order, add the numbers and return the sum as a linked list."}]}]}},"revision":1},{"id":"a041d27b-5059-7976-b904-5d32d7e0183a","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"13c4d64a-28f0-7a45-9a03-58d6f70c783f","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Digits are stored in reverse order; add digit by digit with carry."}]}]}},"revision":1},{"id":"6111c53b-b1f0-79e7-8829-1a2793c28181","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"092aa5cc-8b74-7e6b-940b-a128042b6d09","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Elementary digit-by-digit addition traversing both lists simultaneously with a carry variable."}]}]}},"revision":1},{"id":"1e9988bb-573c-7244-88a6-23e0b3a6572d","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"16fbf0f6-4fa0-776e-baec-8f3c666875ca","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"dummy = ListNode()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"carry = 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loop while "},{"type":"text","text":"l1","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"l2","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"carry","marks":[{"type":"code"}]},{"type":"text","text":":"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sum values + carry, update "},{"type":"text","text":"carry = total // 10","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Append "},{"type":"text","text":"ListNode(total % 10)","marks":[{"type":"code"}]},{"type":"text","text":" to result list."}]}]}]}]}},"revision":1},{"id":"41755fed-8412-78a9-a8c0-4b62b427497e","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"91d6d787-64a8-793f-aa2f-88bd89dd9a1e","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Convert lists to Python integers, add numbers, convert sum back to linked list."}]}]}},"revision":1},{"id":"12fac262-e546-7802-9516-651af9afb24a","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def addTwoNumbers(self, l1, l2):\n        def to_number(node):\n            number = 0\n            multiplier = 1\n\n            while node:\n                number += node.val * multiplier\n                multiplier *= 10\n                node = node.next\n\n            return number\n\n        total = to_number(l1) + to_number(l2)\n\n        dummy = ListNode()\n        current = dummy\n\n        if total == 0:\n            return ListNode(0)\n\n        while total:\n            current.next = ListNode(total % 10)\n            total //= 10\n            current = current.next\n\n        return dummy.next","filename":"Python"},"revision":1},{"id":"f77f90f2-5639-7329-8111-c81c64426c51","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n        // Up to 100 digits overflows any built-in integer (Python has big ints),\n        // so each number is kept as a digit string, least significant digit first.\n        auto toNumber = [](ListNode* node) {\n            string number;\n\n            while (node) {\n                number += char(''0'' + node->val);\n                node = node->next;\n            }\n\n            return number;\n        };\n\n        string a = toNumber(l1);\n        string b = toNumber(l2);\n\n        string total;\n        int carry = 0;\n\n        for (int i = 0; i < max(a.size(), b.size()) || carry; i++) {\n            int digit = carry;\n            if (i < a.size()) digit += a[i] - ''0'';\n            if (i < b.size()) digit += b[i] - ''0'';\n\n            total += char(''0'' + digit % 10);\n            carry = digit / 10;\n        }\n\n        ListNode dummy;\n        ListNode* current = &dummy;\n\n        for (char digit : total) {\n            current->next = new ListNode(digit - ''0'');\n            current = current->next;\n        }\n\n        return dummy.next;\n    }\n};","filename":"C++"},"revision":1},{"id":"052f6341-c383-7675-86ab-e1a6ee88d956","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        // Up to 100 digits overflows long, so use java.math.BigInteger (like Python''s int)\n        java.math.BigInteger total = toNumber(l1).add(toNumber(l2));\n\n        if (total.signum() == 0) {\n            return new ListNode(0);\n        }\n\n        ListNode dummy = new ListNode();\n        ListNode current = dummy;\n\n        while (total.signum() > 0) {\n            java.math.BigInteger[] parts = total.divideAndRemainder(java.math.BigInteger.TEN);\n            current.next = new ListNode(parts[1].intValue());\n            total = parts[0];\n            current = current.next;\n        }\n\n        return dummy.next;\n    }\n\n    private java.math.BigInteger toNumber(ListNode node) {\n        java.math.BigInteger number = java.math.BigInteger.ZERO;\n        java.math.BigInteger multiplier = java.math.BigInteger.ONE;\n\n        while (node != null) {\n            number = number.add(multiplier.multiply(java.math.BigInteger.valueOf(node.val)));\n            multiplier = multiplier.multiply(java.math.BigInteger.TEN);\n            node = node.next;\n        }\n\n        return number;\n    }\n}","filename":"Java"},"revision":1},{"id":"b73acfcd-f954-7ac0-80e9-2199644520bf","type":"code","position":"aE","content":{"language":"javascript","code":"var addTwoNumbers = function(l1, l2) {\n    // Up to 100 digits exceeds Number precision, so use BigInt\n    const toNumber = (node) => {\n        let number = 0n;\n        let multiplier = 1n;\n\n        while (node) {\n            number += BigInt(node.val) * multiplier;\n            multiplier *= 10n;\n            node = node.next;\n        }\n\n        return number;\n    };\n\n    let total = toNumber(l1) + toNumber(l2);\n\n    const dummy = new ListNode();\n    let current = dummy;\n\n    if (total === 0n) {\n        return new ListNode(0);\n    }\n\n    while (total) {\n        current.next = new ListNode(Number(total % 10n));\n        total /= 10n;\n        current = current.next;\n    }\n\n    return dummy.next;\n};","filename":"JavaScript"},"revision":1},{"id":"3aac06e9-0065-741c-aee8-f6941d3c8081","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n + m) · Space: O(n + m)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"f65524b1-f976-7b4a-938b-707c37a8f06a","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"51a16d5b-0a96-7d5d-87bd-355ace7880e7","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def addTwoNumbers(self, l1, l2):\n        dummy = ListNode()\n        current = dummy\n\n        carry = 0\n\n        while l1 or l2 or carry:\n            a = l1.val if l1 else 0\n            b = l2.val if l2 else 0\n\n            total = a + b + carry\n\n            carry = total // 10\n\n            current.next = ListNode(\n                total % 10\n            )\n\n            current = current.next\n\n            if l1:\n                l1 = l1.next\n\n            if l2:\n                l2 = l2.next\n\n        return dummy.next","filename":"Python"},"revision":1},{"id":"d4869b06-49d1-745d-8ba3-332190e4f30f","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n        ListNode dummy;\n        ListNode* current = &dummy;\n\n        int carry = 0;\n\n        while (l1 || l2 || carry) {\n            int a = l1 ? l1->val : 0;\n            int b = l2 ? l2->val : 0;\n\n            int total = a + b + carry;\n\n            carry = total / 10;\n\n            current->next = new ListNode(total % 10);\n\n            current = current->next;\n\n            if (l1) l1 = l1->next;\n            if (l2) l2 = l2->next;\n        }\n\n        return dummy.next;\n    }\n};","filename":"C++"},"revision":1},{"id":"7064a183-85a8-754c-a4f3-926f1936fd04","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode();\n        ListNode current = dummy;\n\n        int carry = 0;\n\n        while (l1 != null || l2 != null || carry != 0) {\n            int a = l1 != null ? l1.val : 0;\n            int b = l2 != null ? l2.val : 0;\n\n            int total = a + b + carry;\n\n            carry = total / 10;\n\n            current.next = new ListNode(total % 10);\n\n            current = current.next;\n\n            if (l1 != null) l1 = l1.next;\n            if (l2 != null) l2 = l2.next;\n        }\n\n        return dummy.next;\n    }\n}","filename":"Java"},"revision":1},{"id":"f7043488-a4c6-73ca-8de1-ec6802b724fc","type":"code","position":"aK","content":{"language":"javascript","code":"var addTwoNumbers = function(l1, l2) {\n    const dummy = new ListNode();\n    let current = dummy;\n\n    let carry = 0;\n\n    while (l1 || l2 || carry) {\n        const a = l1 ? l1.val : 0;\n        const b = l2 ? l2.val : 0;\n\n        const total = a + b + carry;\n\n        carry = Math.floor(total / 10);\n\n        current.next = new ListNode(total % 10);\n\n        current = current.next;\n\n        if (l1) l1 = l1.next;\n        if (l2) l2 = l2.next;\n    }\n\n    return dummy.next;\n};","filename":"JavaScript"},"revision":1},{"id":"2e57475d-752e-7798-a59e-c9267fe1e62b","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(max(n,m)) · Space: O(max(n,m))","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"d1de965c-bd67-784c-9ec4-653ee940b977","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"c1a1d609-cef8-7411-aab4-0be3e8b3ae05","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","cont