  ('51a16d5b-0a96-7d5d-87bd-355ace7880e7', 'aH', 'code', '{"language":"python","code":"class Solution:\n    def addTwoNumbers(self, l1, l2):\n        dummy = ListNode()\n        current = dummy\n\n        carry = 0\n\n        while l1 or l2 or carry:\n            a = l1.val if l1 else 0\n            b = l2.val if l2 else 0\n\n            total = a + b + carry\n\n            carry = total // 10\n\n            current.next = ListNode(\n                total % 10\n            )\n\n            current = current.next\n\n            if l1:\n                l1 = l1.next\n\n            if l2:\n                l2 = l2.next\n\n        return dummy.next","filename":"Python"}'),
  ('d4869b06-49d1-745d-8ba3-332190e4f30f', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n        ListNode dummy;\n        ListNode* current = &dummy;\n\n        int carry = 0;\n\n        while (l1 || l2 || carry) {\n            int a = l1 ? l1->val : 0;\n            int b = l2 ? l2->val : 0;\n\n            int total = a + b + carry;\n\n            carry = total / 10;\n\n            current->next = new ListNode(total % 10);\n\n            current = current->next;\n\n            if (l1) l1 = l1->next;\n            if (l2) l2 = l2->next;\n        }\n\n        return dummy.next;\n    }\n};","filename":"C++"}'),
  ('7064a183-85a8-754c-a4f3-926f1936fd04', 'aJ', 'code', '{"language":"java","code":"class Solution {\n    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode();\n        ListNode current = dummy;\n\n        int carry = 0;\n\n        while (l1 != null || l2 != null || carry != 0) {\n            int a = l1 != null ? l1.val : 0;\n            int b = l2 != null ? l2.val : 0;\n\n            int total = a + b + carry;\n\n            carry = total / 10;\n\n            current.next = new ListNode(total % 10);\n\n            current = current.next;\n\n            if (l1 != null) l1 = l1.next;\n            if (l2 != null) l2 = l2.next;\n        }\n\n        return dummy.next;\n    }\n}","filename":"Java"}'),
  ('f7043488-a4c6-73ca-8de1-ec6802b724fc', 'aK', 'code', '{"language":"javascript","code":"var addTwoNumbers = function(l1, l2) {\n    const dummy = new ListNode();\n    let current = dummy;\n\n    let carry = 0;\n\n    while (l1 || l2 || carry) {\n        const a = l1 ? l1.val : 0;\n        const b = l2 ? l2.val : 0;\n\n        const total = a + b + carry;\n\n        carry = Math.floor(total / 10);\n\n        current.next = new ListNode(total % 10);\n\n        current = current.next;\n\n        if (l1) l1 = l1.next;\n        if (l2) l2 = l2.next;\n    }\n\n    return dummy.next;\n};","filename":"JavaScript"}'),
