            int digit = carry;
            if (i < a.size()) digit += a[i] - ''0'';
            if (i < b.size()) digit += b[i] - ''0'';

            total += char(''0'' + digit % 10);
            carry = digit / 10;
        }

        ListNode dummy;
        ListNode* current = &dummy;

        for (char digit : total) {
            current->next = new ListNode(digit - ''0'');
            current = current->next;
        }

        return dummy.next;
    }
