f (grid[r][c] == ''1'' && !visited[r][c]) {\n                    count++;\n                    dfs(r, c);\n                }\n            }\n        }\n\n        return count;\n    }\n\n    private void dfs(int r, int c) {\n        if (r < 0 || r >= rows || c < 0 || c >= cols ||\n            grid[r][c] == ''0'' || visited[r][c])\n            return;\n\n        visited[r][c] = true;\n\n        dfs(r + 1, c);\n        dfs(r - 1, c);\n        dfs(r, c + 1);\n        dfs(r, c - 1);\n    }\n}","filename":"Java"},"revision":1},{"id":"65903401-6907-7d72-9eb3-34341134164d","type":"code","position":"aE","content":{"language":"javascript","code":"var numIslands = function(grid) {\n    const rows = grid.length;\n    const cols = grid[0].length;\n\n    const visited = new Set();\n\n    const dfs = (r, c) => {\n        if (\n            r < 0 || r >= rows ||\n            c < 0 || c >= cols ||\n            grid[r][c] === \"0\" ||\n            visited.has(r * cols + c)\n        ) return;\n\n        visited.add(r * cols + c);\n\n        dfs(r + 1, c);\n        dfs(r - 1, c);\n        dfs(r, c + 1);\n        dfs(r, c - 1);\n    };\n\n    let count = 0;\n\n    for (let r = 0; r < rows; r++) {\n        for (let c = 0; c < cols; c++) {\n            if (grid[r][c] === \"1\" && !visited.has(r * cols + c)) {\n                count++;\n                dfs(r, c);\n            }\n        }\n    }\n\n    return count;\n};","filename":"JavaScript"},"revision":1},{"id":"bae3eb70-dc35-7d49-b320-c5c5ddc6e5ca","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(R × C) · Aux Space: O(R × C)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"3df89572-ed79-7148-8c64-d2c50dc6142d","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"a77e840e-fbaf-750e-a85d-d93727476a84","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def numIslands(self, grid):\n        rows = len(grid)\n        cols = len(grid[0])\n\n        def dfs(r, c):\n            if (\n                r < 0 or r >= rows or\n                c < 0 or c >= cols or\n                grid[r][c] == \"0\"\n            ):\n                return\n\n            grid[r][c] = \"0\"\n\n            dfs(r + 1, c)\n            dfs(r - 1, c)\n            dfs(r, c + 1)\n            dfs(r, c - 1)\n\n        count = 0\n\n        for r in range(rows):\n            for c in range(cols):\n                if grid[r][c] == \"1\":\n                    count += 1\n                    dfs(r, c)\n\n        return count","filename":"Python"},"revision":1},{"id":"8b58aef8-4fcc-7ba1-a3bd-9faeea9b32a8","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int numIslands(vector<vector<char>>& grid) {\n        int rows = grid.size(), cols = grid[0].size();\n\n        function<void(int, int)> dfs = [&](int r, int c) {\n            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == ''0'')\n                return;\n\n            grid[r][c] = ''0'';\n\n            dfs(r + 1, c);\n            dfs(r - 1, c);\n            dfs(r, c + 1);\n            dfs(r, c - 1);\n        };\n\n        int count = 0;\n\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                if (grid[r][c] == ''1'') {\n                    count++;\n                    dfs(r, c);\n                }\n            }\n        }\n\n        return count;\n    }\n};","filename":"C++"},"revision":1},{"id":"32250b12-086b-7f9a-b505-5be96ee43a5a","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    private char[][] grid;\n    private int rows, cols;\n\n    public int numIslands(char[][] grid) {\n        this.grid = grid;\n        rows = grid.length;\n        cols = grid[0].length;\n\n        int count = 0;\n\n        for (int r = 0; r < rows; r++