SELECT 'e751159d-e8a2-7c43-9ddb-da64f58a170d', 'f76b7761-d795-7b88-af39-cb88d84d2bdb', 1, 'PUBLISHED', 'Detect Squares', '[{"id":"1cbc714f-f5da-7a2e-b6b4-a8329a3f2043","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 2013","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/detect-squares/"}}]}]}]}},"revision":1},{"id":"5f148aa2-e4e2-788c-bdb7-5cac5102f67e","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"db777fc9-2145-7888-9727-efa617746069","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Design a data structure that supports "},{"type":"text","text":"add(point)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"count(point)","marks":[{"type":"code"}]},{"type":"text","text":". For "},{"type":"text","text":"count","marks":[{"type":"code"}]},{"type":"text","text":", return the number of axis-aligned squares that can be formed using the query point as one corner."}]}]}},"revision":1},{"id":"ee0100a7-0c03-7384-b07d-0bd7f729bbbe","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"e1e3c99f-0450-7478-a81a-4cdeab15dcdb","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For a query point "},{"type":"text","text":"(x, y)","marks":[{"type":"code"}]},{"type":"text","text":" and a diagonal point "},{"type":"text","text":"(x2, y2)","marks":[{"type":"code"}]},{"type":"text","text":" to form an axis-aligned square: "},{"type":"text","text":"|x2-x| == |y2-y|","marks":[{"type":"code"}]},{"type":"text","text":" (non-zero). The other two corners are then "},{"type":"text","text":"(x2, y)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"(x, y2)","marks":[{"type":"code"}]},{"type":"text","text":". Count = product of frequencies of all three non-query corners."}]}]}},"revision":1},{"id":"ced2e20f-287d-7117-962f-65cff7e73af4","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"25266c57-7885-77a9-bba2-e6d1322b6833","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Group points by their "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":"-coordinate. For each unique "},{"type":"text","text":"x2 ≠ x","marks":[{"type":"code"}]},{"type":"text","text":", the diagonal candidate''s "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":" value must be exactly "},{"type":"text","text":"y ± side","marks":[{"type":"code"}]},{"type":"text","text":" where "},{"type":"text","text":"side = |x2 - x|","marks":[{"type":"code"}]},{"type":"text","text":". Only two candidate "},{"type":"text","text":"y2","marks":[{"type":"code"}]},{"type":"text","text":" values need checking — constant per "},{"type":"text","text":"x2","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"f377bd0b-87fb-77a9-a211-2e50ff76bbed","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"9985eff7-2ac0-7286-9f96-475f81d0c7f1","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Store "},{"type":"text","text":"self.points = defaultdict(Counter)","marks":[{"type":"code"}]},{"type":"text","text":" where "},{"type":"text","text":"self.points[x][y]","marks":[{"type":"code"}]},{"type":"text","text":" = frequency."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"add(x, y)","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"self.points[x][y] += 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"count(x, y)","marks":[{"type":"code"}]},{"type":"text","text":": iterate over all distinct "},{"type":"text","text":"x2","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"self.points","marks":[{"type":"code"}]},{"type":"text","text":" (skip "},{"type":"text","text":"x2 == x","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"side = abs(x2 - x)","marks":[{"type":"code"}]},{"type":"text","text":". Check "},{"type":"text","text":"y2 ∈ {y + side, y - side}","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For each valid "},{"type":"text","text":"y2","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"answer += points[x2][y2] × points[x][y2] × points[x2][y]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"answer","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"7f3042ff-e171-75b5-a0a5-ad328db94e8d","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"0ffb2d23-3dbd-76ed-9015-fa4fdac44010","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Store all points in a list; for each "},{"type":"text","text":"count","marks":[{"type":"code"}]},{"type":"text","text":" query, scan all pairs and check the square condition."}]}]}},"revision":1},{"id":"c9c16f2d-f21b-7b47-8374-74baa7381481","type":"code","position":"aB","content":{"language":"python","code":"from collections import Counter\n\nclass DetectSquares:\n\n    def __init__(self):\n        self.points = Counter()\n\n    def add(self, point):\n        self.points[tuple(point)] += 1\n\n    def count(self, point):\n        x, y = point\n        answer = 0\n\n        for (x2, y2), cnt_diag in self.points.items():\n            if x2 == x or y2 == y:\n                continue\n\n            if abs(x2 - x) != abs(y2 - y):\n                continue\n\n            answer += (\n                cnt_diag\n                * self.points[(x2, y)]\n                * self.points[(x, y2)]\n            )\n\n        return answer","filename":"Python"},"revision":1},{"id":"946e6624-a315-77be-8ee4-fb511f14e89c","type":"code","position":"aC","content":{"language":"cpp","code":"class DetectSquares {\npublic:\n    DetectSquares() {}\n\n    void add(vector<int> point) {\n        points[{point[0], point[1]}]++;\n    }\n\n    int count(vector<int> point) {\n        int x = point[0], y = point[1];\n        int answer = 0;\n\n        for (auto& [p, cntDiag] : points) {\n            auto [x2, y2] = p;\n            if (x2 == x || y2 == y) {\n                continue;\n            }\n\n            if (abs(x2 - x) != abs(y2 - y)) {\n                continue;\n            }\n\n            answer += cntDiag * get(x2, y) * get(x, y2);\n        }\n\n        return answer;\n    }\n\nprivate:\n    map<pair<int, int>, int> points;\n\n    int get(int x, int y) {\n        auto it = points.find({x, y});\n        return it == points.end() ? 0 : it->second;\n    }\n};","filename":"C++"},"revision":1},{"id":"27ebc146-9fc7-7ca5-8de1-86119ef7cf28","type":"code","position":"aD","content":{"language":"java","code":"class DetectSquares {\n    private Map<List<Integer>, Integer> points;\n\n    public DetectSquares() {\n        points = new HashMap<>();\n    }\n\n    public void add(int[] point) {\n        points.merge(Arrays.asList(point[0], point[1]), 1, Integer::sum);\n    }\n\n    public int count(int[] point) {\n        int x = point[0], y = point[1];\n        int answer = 0;\n\n        for (Map.Entry<List<Integer>, Integer> entry : points.entrySet()) {\n            int x2 = entry.getKey().get(0);\n            int y2 = entry.getKey().get(1);\n            int cntDiag = entry.getValue();\n\n            if (x2 == x || y2 == y) {\n                continue;\n            }\n\n            if (Math.abs(x2 - x) != Math.abs(y2 - y)) {\n                continue;\n            }\n\n            answer += cntDiag\n                * points.getOrDefault(Arrays.asList(x2, y), 0)\n                * points.getOrDefault(Arrays.asList(x, y2), 0);\n        }\n\n        return answer;\n    }\n}","filename":"Java"},"revision":1},{"id":"ca9e2a73-aa64-7839-bce1-2b063eedb712","type":"code","position":"aE","content":{"language":"javascript","code":"var DetectSquares = function() {\n    this.points = new Map();  // \"x,y\" -> frequency\n};\n\nDetectSquares.prototype.add = function(point) {\n    const key = point.join(\",\");\n    this.points.set(key, (this.points.get(key) || 0) + 1);\n};\n\nDetectSquares.prototype.count = function(point) {\n    const [x, y] = point;\n    let answer = 0;\n\n    for (const [key, cntDiag] of this.points) {\n        const [x2, y2] = key.split(\",\").map(Number);\n        if (x2 === x || y2 === y) {\n            continue;\n        }\n\n        if (Math.abs(x2 - x) !== Math.abs(y2 - y)) {\n            continue;\n        }\n\n        answer +=\n            cntDiag *\n            (this.points.get(`${x2},${y}`) || 0) *\n            (this.points.get(`${x},${y2}`) || 0);\n    }\n\n    return answer;\n};","filename":"JavaScript"},"revision":1},{"id":"9f0fc833-ba0b-794a-91ad-1ad17447c78f","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"add: O(1), count: O(P) — P = distinct points · Space: O(P)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"edc87f57-d22e-7f3b-ab46-7617168ec9aa","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"59a90c1a-8081-74b3-94c3-b03d69df95d3","type":"code","position":"aH","content":{"language":"python","code":"from collections import defaultdict, Counter\n\nclass DetectSquares:\n\n    def __init__(self):\n        # points[x][y] = frequency\n        self.points = defaultdict(Counter)\n\n    def add(self, point):\n        x, y = point\n        self.points[x][y] += 1\n\n    def count(self, point):\n        x, y = point\n        answer = 0\n\n        for x2, ys in self.points.items():\n            if x2 == x:\n                continue\n\n            side = abs(x2 - x)\n\n            # Two possible diagonal y-coords\n            for y2 in (y + side, y - side):\n                if y2 not in ys:\n                    continue\n\n                cnt_diag   = ys[y2]           # (x2, y2)\n                cnt_corner = self.points[x][y2] # (x,  y2)\n                cnt_base   = self.points[x2][y] # (x2, y )\n\n                answer += cnt_diag * cnt_corner * cnt_base\n\n        return answer","filename":"Python"},"revision":1},{"id":"f1868b55-6ed0-70d3-a7e3-14a89709c36e","type":"code","position":"aI","content":{"language":"cpp","code":"class DetectSquares {\npublic:\n    DetectSquares() {}\n\n    void add(vector<int> point) {\n        int x = point[0], y = point[1];\n        points[x][y]++;\n    }\n\n    int count(vector<int> point) {\n        int x = point[0], y = point[1];\n        int answer = 0;\n\n        for (auto& [x2, ys] : points) {\n            if (x2 == x) {\n                continue;\n            }\n\n            int side = abs(x2 - x);\n\n            // Two possible diagonal y-coords\n            for (int y2 : {y + side, y - side}) {\n                auto it = ys.find(y2);\n                if (it == ys.end()) {\n                    continue;\n                }\n\n                int cntDiag   = it->second;     // (x2, y2)\n                int cntCorner = get(x, y2);     // (x,  y2)\n                int cntBase   = get(x2, y);     // (x2, y )\n\n                answer += cntDiag * cntCorner * cntBase;\n            }\n        }\n\n        return answer;\n    }\n\nprivate:\n    // points[x][y] = frequency\n    unordered_map<int, unordered_map<int, int>> points;\n\n    // lookup without inserting (inserting would invalidate the loop''s iterators)\n    int get(int x, int y) {\n        auto row = points.find(x);\n        if (row == points.end()) return 0;\n        auto it = row->second.find(y);\n        return it == row->second.end() ? 0 : it->second;\n    }\n};","filename":"C++"},"revision":1},{"id":"f43d39eb-04ac-72f6-be89-30053a477f36","type":"code","position":"aJ","content":{"language":"java","code":"class DetectSquares {\n    // points[x][y] = frequency\n    private Map<Integer, Map<Integer, Integer>> points;\n\n    public DetectSquares() {\n        points = new HashMap<>();\n    }\n\n    public void add(int[] point) {\n        int x = point[0], y = point[1];\n        points.computeIfAbsent(x, k -> new HashMap<>()).merge(y, 1, Integer::sum);\n    }\n\n    public int count(int[] point) {\n        int x = point[0], y = point[1];\n        int answer = 0;\n\n        for (Map.Entry<Integer, Map<Integer, Integer>> entry : points.entrySet()) {\n            int x2 = entry.getKey();\n            Map<Integer, Integer> ys = entry.getValue();\n\n            if (x2 == x) {\n                continue;\n            }\n\n            int side = Math.abs(x2 - x);\n\n            // Two possible diagonal y-coords\n            for (int y2 : new int[]{y + side, y - side}) {\n                if (!ys.containsKey(y2)) {\n                    continue;\n                }\n\n                int cntDiag   = ys.get(y2);      // (x2, y2)\n                int cntCorner = get(x, y2);      // (x,  y2)\n                int cntBase   = get(x2, y);      // (x2, y )\n\n                answer += cntDiag * cntCorner * cntBase;\n            }\n        }\n\n        return answer;\n    }\n\n    private int get(int x, int y) {\n        Map<Integer, Integer> ys = points.get(x);\n        return ys == null ? 0 : ys.getOrDefault(y, 0);\n    }\n}","filename":"Java"},"revision":1},{"id":"020ed11e-7190-7d79-b209-2a983e3c5819","type":"code","position":"aK","content":{"language":"javascript","code":"var DetectSquares = function() {\n    // points.get(x).get(y) = frequency\n    this.points = new Map();\n};\n\nDetectSquares.prototype.add = function(point) {\n    const [x, y] = point;\n    if (!this.points.has(x)) {\n        this.points.set(x, new Map());\n    }\n    const ys = this.points.get(x);\n    ys.set(y, (ys.get(y) || 0) + 1);\n};\n\nDetectSquares.prototype.count = function(point) {\n    const [x, y] = point;\n    const get = (px, py) => this.points.get(px)?.get(py) || 0;\n    let answer = 0;\n\n    for (const [x2, ys] of this.points) {\n        if (x2 === x) {\n            continue;\n        }\n\n        const side = Math.abs(x2 - x);\n\n        // Two possible diagonal y-coords\n        for (const y2 of [y + side, y - side]) {\n            if (!ys.has(y2)) {\n                continue;\n            }\n\n            const cntDiag   = ys.get(y2);    // (x2, y2)\n            const cntCorner = get(x, y2);    // (x,  y2)\n            const cntBase   = get(x2, y);    // (x2, y )\n\n            answer += cntDiag * cntCorner * cntBase;\n        }\n    }\n\n    return answer;\n};","filename":"JavaScript"},"revision":1},{"id":"2a87f098-0e73-73fc-be9c-11f6b176421b","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"add: O(1), count: O(distinct x-coords) · Space: O(P)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"d96ce1bd-1960-7a58-97f5-4f1858a3cc19","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"b80a0f29-b05d-7256-826d-a2bb9138d74a","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Coordinate frequency map — axis-aligned square: |Δx| == |Δy|; count = product of three corner frequencies"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
