 addWord(string word) {\n        words.push_back(word);\n    }\n\n    bool search(string word) {\n        for (const string& candidate : words) {\n            if (candidate.size() != word.size()) continue;\n\n            bool match = true;\n\n            for (int i = 0; i < (int)word.size(); i++) {\n                if (word[i] != ''.'' && word[i] != candidate[i]) {\n                    match = false;\n                    break;\n                }\n            }\n\n            if (match) return true;\n        }\n\n        return false;\n    }\n\nprivate:\n    vector<string> words;\n};","filename":"C++"},"revision":1},{"id":"243dbb77-7f98-74b4-80f0-62e2479e1181","type":"code","position":"aD","content":{"language":"java","code":"class WordDictionary {\n    private List<String> words;\n\n    public WordDictionary() {\n        words = new ArrayList<>();\n    }\n\n    public void addWord(String word) {\n        words.add(word);\n    }\n\n    public boolean search(String word) {\n        for (String candidate : words) {\n            if (candidate.length() != word.length()) continue;\n\n            boolean match = true;\n\n            for (int i = 0; i < word.length(); i++) {\n                if (word.charAt(i) != ''.'' && word.charAt(i) != candidate.charAt(i)) {\n                    match = false;\n                    break;\n                }\n            }\n\n            if (match) return true;\n        }\n\n        return false;\n    }\n}","filename":"Java"},"revision":1},{"id":"d42803d0-2424-7145-8877-330f00613de5","type":"code","position":"aE","content":{"language":"javascript","code":"class WordDictionary {\n    constructor() {\n        this.words = [];\n    }\n\n    addWord(word) {\n        this.words.push(word);\n    }\n\n    search(word) {\n        for (const candidate of this.words) {\n            if (candidate.length !== word.length) continue;\n\n            let match = true;\n\n            for (let i = 0; i < word.length; i++) {\n                if (word[i] !== \".\" && word[i] !== candidate[i]) {\n                    match = false;\n                    break;\n                }\n            }\n\n            if (match) return true;\n        }\n\n        return false;\n    }\n}","filename":"JavaScript"},"revision":1},{"id":"0d2c54f5-fed5-7b3c-8ce2-feff65a52a7a","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"addWord: O(1), search: O(N × L) · Space: O(N × L)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"61dee49f-5933-7acc-934d-5bb2438832c4","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"f9e85d10-4a18-7d2b-833f-d973118ad711","type":"code","position":"aH","content":{"language":"python","code":"class TrieNode:\n\n    def __init__(self):\n        self.children = {}\n        self.is_word = False\n\n\nclass WordDictionary:\n\n    def __init__(self):\n        self.root = TrieNode()\n\n    def addWord(self, word):\n\n        node = self.root\n\n        for char in word:\n\n            if char not in node.children:\n                node.children[char] = TrieNode()\n\n            node = node.children[char]\n\n        node.is_word = True\n\n    def search(self, word):\n\n        def dfs(index, node):\n\n            if index == len(word):\n                return node.is_word\n\n            char = word[index]\n\n            if char != \".\":\n\n                if char not in node.children:\n                    return False\n\n                return dfs(\n                    index + 1,\n                    node.children[char]\n                )\n\n            # Wildcard: try all children\n            for child in node.children.values():\n\n                if dfs(index + 1, child):\n                    return True\n\n            return False\n\n        return dfs(0, self.root)","filename":"Python"},"revision":1},{"id":"15fa06d0-9fe2-751f-b0b5-efe857b695be","type":"code","position":"aI","content":{"language":"cpp","code":"struct TrieNode {\n    unordered_map<char, TrieNode*> children;\n    bool isWord = false;\n};\n\nclass WordDictionary {\npublic:\n    WordDictionary() : root(new TrieNode()) {}\n\n    void addWord(string word) {\n        TrieNode* node = root;\n\n        for (char c : word) {\n            if (!node->children.count(c)) node->children[c] = new TrieNode();\n\n            node = node->children[c];\n        }\n\n        node->isWord = true;\n    }\n\n    bool search(string word) {\n        return dfs(word, 0, root);\n    }\n\nprivate:\n    TrieNode* root;\n\n    bool dfs(const string& word, int index, TrieNode* node) {\n        if (index == (int)word.size()) return node->isWord;\n\n        char c = word[index];\n\n        if (c != ''.'') {\n            if (!node->children.count(c)) return false;\n\n            return dfs(word, index + 1, node->children[c]);\n        }\n\n        // Wildcard: try all children\n        for (auto& [_, child] : node->children) {\n            if (dfs(word, index + 1, child)) return true;\n        }\n\n        return false;\n    }\n};","filename":"C++"},"revision":1},{"id":"2eab92e2-640c-72fd-a24c-a8c4aedca236","type":"code","position":"aJ","content":{"language":"java","code":"class TrieNode {\n    Map<Character, TrieNode> children = new HashMap<>();\n    boolean isWord = false;\n}\n\nclass WordDictionary {\n    private TrieNode root;\n\n    public WordDictionary() {\n        root = new TrieNode();\n    }\n\n    public void addWord(String word) {\n        TrieNode node = root;\n\n        for (char c : word.toCharArray()) {\n            if (!node.children.containsKey(c)) node.children.put(c, new TrieNode());\n\n            node = node.children.get(c);\n        }\n\n        node.isWord = true;\n    }\n\n    public boolean search(String word) {\n        return dfs(word, 0, root);\n    }\n\n    private boolean dfs(String word, int index, TrieNode node) {\n        if (index == word.length()) return node.isWord;\n\n        char c = word.charAt(index);\n\n        if (c != ''.'') {\n            if (!node.children.containsKey(c)) return false;\n\n            return dfs(word, index + 1, node.children.get(c));\n        }\n\n        // Wildcard: try all children\n        for (TrieNode child : node.children.values()) {\n            if (dfs(word, index + 1, child)) return true;\n        }\n\n        return false;\n    }\n}","filename":"Java"},"revision":1},{"id":"09926e9c-94e4-739c-bcf7-41245000be82","type":"code","position":"aK","content":{"language":"javascript","code":"class TrieNode {\n    constructor() {\n        this.children = new Map();\n        this.isWord = false;\n    }\n}\n\nclass WordDictionary {\n    constructor() {\n        this.root = new TrieNode();\n    }\n\n    addWord(word) {\n        let node = this.root;\n\n        for (const char of word) {\n            if (!node.children.has(char)) node.children.set(char, new TrieNode());\n\n            node = node.children.get(char);\n        }\n\n        node.isWord = true;\n    }\n\n    search(word) {\n        const dfs = (index, node) => {\n            if (index === word.length) return node.isWord;\n\n            const char = word[index];\n\n            if (char !== \".\") {\n                if (!node.children.has(char)) return false;\n\n                return dfs(index + 1, node.children.get(char));\n            }\n\n            // Wildcard: try all children\n            for (const child of node.children.values()) {\n                if (dfs(index + 1, child)) return true;\n            }\n\n            return false;\n        };\n\n        return dfs(0, this.root);\n    }\n}","filename":"JavaScript"},"revision":1},{"id":"32fe9346-3c26-77bf-a3a7-d34c65083905","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"addWord: O(L), search: O(L) normal / O(26^L) worst with wildcards · Space: O(total chars) + O(L) DFS stack","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"6ebd9bba-34ff-707f-8ac5-1a845c428d95","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"bf1ee0a7-e27c-76cc-8525-e0a408765252","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Trie + DFS Backtracking for wildcard branching"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
