Optimized Code (Python 3)
class TrieNode:

    def __init__(self):
        self.children = {}
        self.is_word = False


class WordDictionary:

    def __init__(self):
        self.root = TrieNode()

    def addWord(self, word):

        node = self.root

        for char in word:

            if char not in node.children:
                node.children[char] = TrieNode()

            node = node.children[char]

        node.is_word = True

    def search(self, word):

        def dfs(index, node):

            if index == len(word):
                return node.is_word

            char = word[index]

            if char != ".":

                if char not in node.children:
                    return False

                return dfs(
                    index + 1,
                    node.children[char]
                )

            # Wildcard: try all children
            for child in node.children.values():

                if dfs(index + 1, child):
                    return True

            return False

        return dfs(0, self.root)
struct TrieNode {
    unordered_map<char, TrieNode*> children;
    bool isWord = false;
};

class WordDictionary {
public:
    WordDictionary() : root(new TrieNode()) {}

    void addWord(string word) {
        TrieNode* node = root;

        for (char c : word) {
            if (!node->children.count(c)) node->children[c] = new TrieNode();

            node = node->children[c];
        }

        node->isWord = true;
    }

    bool search(string word) {
        return dfs(word, 0, root);
    }

private:
    TrieNode* root;

    bool dfs(const string& word, int index, TrieNode* node) {
        if (index == (int)word.size()) return node->isWord;

        char c = word[index];

        if (c != ''.'') {
            if (!node->children.count(c)) return false;

            return dfs(word, index + 1, node->children[c]);
        }

        // Wildcard: try all children
        for (auto& [_, child] : node->children) {
            if (dfs(word, index + 1, child)) return true;
        }

        return false;
    }
};
class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();
    boolean isWord = false;
}

class WordDictionary {
    private TrieNode root;

    public WordDictionary() {
        root = new TrieNode();
    }

    public void addWord(String word) {
        TrieNode node = root;

        for (char c : word.toCharArray()) {
            if (!node.children.containsKey(c)) node.children.put(c, new TrieNode());

            node = node.children.get(c);
        }

        node.isWord = true;
    }

    public boolean search(String word) {
        return dfs(word, 0, root);
    }

    private boolean dfs(String word, int index, TrieNode node) {
        if (index == word.length()) return node.isWord;

        char c = word.charAt(index);

        if (c != ''.'') {
            if (!node.children.containsKey(c)) return false;

            return dfs(word, index + 1, node.children.get(c));
        }

        // Wildcard: try all children
        for (TrieNode child : node.children.values()) {
            if (dfs(word, index + 1, child)) return true;
        }

        return false;
    }
}
class TrieNode {
    constructor() {
        this.children = new Map();
        this.isWord = false;
    }
}

class WordDictionary {
    constructor() {
        this.root = new TrieNode();
    }

    addWord(word) {
        let node = this.root;

        for (const char of word) {
            if (!node.children.has(char)) node.children.set(char, new TrieNode());

            node = node.children.get(char);
        }

        node.isWord = true;
    }

    search(word) {
        const dfs = (index, node) => {
            if (index === word.length) return node.isWord;

            const char = word[index];

            if (char !== ".") {
                if (!node.children.has(char)) return false;

                return dfs(index + 1, node.children.get(char));
            }

            // Wildcard: try all children
            for (const child of node.children.values()) {
                if (dfs(index + 1, child)) return true;
            }

            return false;
        };

        return dfs(0, this.root);
    }
}
