e\n\n            return False\n\n        for word in words:\n            if exists(word):\n                result.append(word)\n\n        return result","filename":"Python"},"revision":1},{"id":"a560ddbc-fc94-79fa-8cf1-b72162adca59","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {\n        vector<string> result;\n\n        for (const string& word : words) {\n            if (exists(board, word)) result.push_back(word);\n        }\n\n        return result;\n    }\n\nprivate:\n    bool exists(vector<vector<char>>& board, const string& word) {\n        int rows = board.size(), cols = board[0].size();\n\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                if (board[r][c] == word[0] && dfs(board, word, r, c, 0)) return true;\n            }\n        }\n\n        return false;\n    }\n\n    bool dfs(vector<vector<char>>& board, const string& word, int r, int c, int index) {\n        if (index == (int)word.size()) return true;\n\n        if (r < 0 || r >= (int)board.size() || c < 0 || c >= (int)board[0].size()\n            || board[r][c] != word[index]) {\n            return false;\n        }\n\n        char temp = board[r][c];\n        board[r][c] = ''#'';\n\n        bool found = dfs(board, word, r + 1, c, index + 1)\n                  || dfs(board, word, r - 1, c, index + 1)\n                  || dfs(board, word, r, c + 1, index + 1)\n                  || dfs(board, word, r, c - 1, index + 1);\n\n        board[r][c] = temp;\n        return found;\n    }\n};","filename":"C++"},"revision":1},{"id":"77abf9a7-2436-78ce-aeef-c7dc8caaff52","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public List<String> findWords(char[][] board, String[] words) {\n        List<String> result = new ArrayList<>();\n\n        for (String word : words) {\n            if (exists(board, word)) result.add(word);\n        }\n\n        return result;\n    }\n\n    private boolean exists(char[][] board, String word) {\n        int rows = board.length, cols = board[0].length;\n\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                if (board[r][c] == word.charAt(0) && dfs(board, word, r, c, 0)) return true;\n            }\n        }\n\n        return false;\n    }\n\n    private boolean dfs(char[][] board, String word, int r, int c, int index) {\n        if (index == word.length()) return true;\n\n        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length\n            || board[r][c] != word.charAt(index)) {\n            return false;\n        }\n\n        char temp = board[r][c];\n        board[r][c] = ''#'';\n\n        boolean found = dfs(board, word, r + 1, c, index + 1)\n                     || dfs(board, word, r - 1, c, index + 1)\n                     || dfs(board, word, r, c + 1, index + 1)\n                     || dfs(board, word, r, c - 1, index + 1);\n\n        board[r][c] = temp;\n        return found;\n    }\n}","filename":"Java"},"revision":1},{"id":"2943ff5e-f8c7-7a84-b291-8c6ad8e6df56","type":"code","position":"aE","content":{"language":"javascript","code":"var findWords = function(board, words) {\n    const rows = board.length;\n    const cols = board[0].length;\n    const result = [];\n\n    const exists = (word) => {\n        const dfs = (r, c, index) => {\n            if (index === word.length) return true;\n\n            if (\n                r < 0 || r >= rows || c < 0 || c >= cols\n                || board[r][c] !== word[index]\n            ) {\n                return false;\n            }\n\n            const temp = board[r][c];\n            board[r][c] = \"#\";\n\n            const found = dfs(r + 1, c, index + 1)\n                || dfs(r - 1, c, index + 1)\n                || dfs(r, c + 1, index + 1)\n                || dfs(r, c - 1, index + 1);\n\n            board[r][c] = temp;\n            return found;\n        };\n\n        for (let r = 0; r < rows; r++) {\n            for (let c = 0; c < cols; c++) {\n                if (board[r][c] === word[0] && dfs(r, c, 0)) return true;\n            }\n        }\n\n        return false;\n    };\n\n    for (const word of words) {\n        if (exists(word)) result.push(word);\n    }\n\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"e4e99de6-c76d-74b5-aa32-85ee36b2e1f1","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(W × R × C × 4^L) · Space: O(L) recursion","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"8d0e278a-c036-7bbc-b67d-85e98ab0d37d","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"7f4468ca-71fd-79ae-beae-820627780a25","type":"code","position":"aH","content":{"language":"python","code":"class TrieNode:\n\n    def __init__(self):\n        self.children = {}\n        self.word = None\n\n\nclass Solution:\n\n    def findWords(self, board, words):\n\n        root = TrieNode()\n\n        # Build Trie from all words\n        for word in words:\n\n            node = root\n\n            for char in word:\n\n                if char not in node.children:\n                    node.children[char] = TrieNode()\n\n                node = node.children[char]\n\n            node.word = word\n\n        rows = len(board)\n        cols = len(board[0])\n        result = []\n\n        def dfs(r, c, node):\n\n            if r < 0 or r >= rows or c < 0 or c >= cols:\n                return\n\n            char = board[r][c]\n\n            if char == \"#\":\n                return\n\n            if char not in node.children:\n                return\n\n            next_node = node.children[char]\n\n            # Complete word found\n            if next_node.word is not None:\n                result.append(next_node.word)\n                next_node.word = None  # prevent duplicates\n\n            board[r][c] = \"#\"  # mark visited\n\n            dfs(r + 1, c, next_node)\n            dfs(r - 1, c, next_node)\n            dfs(r, c + 1, next_node)\n            dfs(r, c - 1, next_node)\n\n            board[r][c] = char  # restore\n\n        for r in range(rows):\n            for c in range(cols):\n                dfs(r, c, root)\n\n        return result","filename":"Python"},"revision":1},{"id":"48a61962-2309-7ef1-a870-ac9756eb50f6","type":"code","position":"aI","content":{"language":"cpp","code":"struct TrieNode {\n    unordered_map<char, TrieNode*> children;\n    string word;  // empty means \"no word ends here\"\n};\n\nclass Solution {\npublic:\n    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {\n        TrieNode* root = new TrieNode();\n\n        // Build Trie from all words\n        for (const string& word : words) {\n            TrieNode* node = root;\n\n            for (char c : word) {\n                if (!node->children.count(c)) node->children[c] = new TrieNode();\n\n                node = node->children[c];\n            }\n\n            node->word = word;\n        }\n\n        vector<string> result;\n\n        for (int r = 0; r < (int)board.size(); r++) {\n            for (int c = 0; c < (int)board[0].size(); c++) {\n                dfs(board, r, c, root, result);\n            }\n        }\n\n        return result;\n    }\n\nprivate:\n    void dfs(vector<vector<char>>& board, int r, int c, TrieNode* node, vector<string>& result) {\n        if (r < 0 || r >= (int)board.size() || c < 0 || c >= (int)board[0].size()) return;\n\n        char ch = board[r][c];\n\n        if (ch == ''#'') return;\n\n        if (!node->children.count(ch)) return;\n\n        TrieNode* next = node->children[ch];\n\n        // Complete word found\n        if (!next->word.empty()) {\n            result.push_back(next->word);\n            next->word.clear();  // prevent duplicates\n        }\n\n        board[r][c] = ''#'';  // mark visited\n\n        dfs(board, r + 1, c, next, result);\n        dfs(board, r - 1, c, next, result);\n        dfs(board, r, c + 1, next, result);\n        dfs(board, r, c - 1, next, result);\n\n        board[r][c] = ch;  // restore\n    }\n};","filename":"C++"},"revision":1},{"id":"bfef5705-1758-7539-af1e-d3dc84e5cd61","type":"code","position":"aJ","content":{"language":"java","code":"class TrieNode {\n    Map<Character, TrieNode> children = new HashMap<>();\n    String word = null;\n}\n\nclass Solution {\n    private char[][] board;\n    private List<String> result;\n\n    public List<String> findWords(char[][] board, String[] words) {\n        TrieNode root = new TrieNode();\n\n        // Build Trie from all words\n        for (String word : words) {\n            TrieNode node = root;\n\n            for (char c : word.toCharArray()) {\n                if (!node.children.containsKey(c)) node.children.put(c, new TrieNode());\n\n                node = node.children.get(c);\n            }\n\n            node.word = word;\n        }\n\n        this.board = board;\n        result = new ArrayList<>();\n\n        for (int r = 0; r < board.length; r++) {\n            for (int c = 0; c < board[0].length; c++) {\n                dfs(r, c, root);\n            }\n        }\n\n        return result;\n    }\n\n    private void dfs(int r, int c, TrieNode node) {\n        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) return;\n\n        char ch = board[r][c];\n\n        if (ch == ''#'') return;\n\n        if (!node.children.containsKey(ch)) return;\n\n        TrieNode next = node.children.get(ch);\n\n        // Complete word found\n        if (next.word != null) {\n            result.add(next.word);\n            next.word = null;  // prevent duplicates\n        }\n\n        board[r][c] = ''#'';  // mark visited\n\n        dfs(r + 1, c, next);\n        dfs(r - 1, c, next);\n        dfs(r, c + 1, next);\n        dfs(r, c - 1, next);\n\n        board[r][c] = ch;  // restore\n    }\n}","filename":"Java"},"revision":1},{"id":"d39dcffb-6d6a-7775-9245-39442ad86297","type":"code","position":"aK","content":{"language":"javascript","code":"class TrieNode {\n    constructor() {\n        this.children = new Map();\n        this.word = null;\n    }\n}\n\nvar findWords = function(board, words) {\n    const root = new TrieNode();\n\n    // Build Trie from all words\n    for (const word of words) {\n        let node = root;\n\n        for (const char of word) {\n            if (!node.children.has(char)) node.children.set(char, new TrieNode());\n\n            node = node.children.get(char);\n        }\n\n        node.word = word;\n    }\n\n    const rows = board.length;\n    const cols = board[0].length;\n    const result = [];\n\n    const dfs = (r, c, node) => {\n        if (r < 0 || r >= rows || c < 0 || c >= cols) return;\n\n        const char = board[r][c];\n\n        if (char === \"#\") return;\n\n        if (!node.children.has(char)) return;\n\n        const nextNode = node.children.get(char);\n\n        // Complete word found\n        if (nextNode.word !== null) {\n            result.push(nextNode.word);\n            nextNode.word = null; // prevent duplicates\n        }\n\n        board[r][c] = \"#\"; // mark visited\n\n        dfs(r + 1, c, nextNode);\n        dfs(r - 1, c, nextNode);\n        dfs(r, c + 1, nextNode);\n        dfs(r, c - 1, nextNode);\n\n        board[r][c] = char; // restore\n    };\n\n    for (let r = 0; r < rows; r++) {\n        for (let c = 0; c < cols; c++) {\n            dfs(r, c, root);\n        }\n    }\n\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"e2226873-7c76-7e3b-8411-1750311dcba3","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(R × C × 4^L) with prefix pruning · Space: O(total chars in words) + O(L) stack","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"57543584-6a00-7ee8-ae3c-a11f7c68e7a7","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"3e77850f-302e-7969-a6ae-047f2c3be1a9","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Multi-word board search → Trie + DFS + Backtracking + Prefix Pruning"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
