SELECT c.id::uuid, '6971fcc3-6f0e-7efb-b774-b57caa650fdd', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('6e72cdbc-f00b-7d71-8ebf-4cfaa7e28e97', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Hard","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 212","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/word-search-ii/"}}]}]}]}}'),
  ('58c26a8a-403b-7b30-9e28-3364e4dc1be9', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Problem"}]}'),
  ('096df455-e35c-7910-b058-5f9d855013a8', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given an "},{"type":"text","text":"m x n","marks":[{"type":"code"}]},{"type":"text","text":" board of characters and a list of strings "},{"type":"text","text":"words","marks":[{"type":"code"}]},{"type":"text","text":", return all words from the list that can be found in the board (adjacent horizontal/vertical cells, no cell reused)."}]}]}}'),
  ('f491a569-f744-747d-862b-8a317f4e050d', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]}'),
  ('380d0881-ec3f-7478-a3f0-b92f677c967a', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Running separate board-DFS for each word is wasteful when words share prefixes. A Trie over all words enables prefix pruning — a non-matching prefix stops all further exploration."}]}]}}'),
  ('ff7aec1e-5f2d-7f3b-a09d-9e12b6d15270', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Intuition"}]}'),
  ('a5dc9273-d0dd-759a-afdc-1414bc73b2a8', 'a6', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Build a single Trie from all words. Run one DFS from every board cell navigating the Trie simultaneously. When the current character is not in the Trie node''s children, prune immediately — this avoids exploring invalid prefixes shared across many words."}]}]}}'),
  ('4b75f52a-c40a-77ce-aa9d-0cd8545c479a', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"Approach"}]}'),
  ('f19ac2f6-40dc-7691-8ee9-ff292836131f', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build Trie from all words, storing "},{"type":"text","text":"node.word = word","marks":[{"type":"code"}]},{"type":"text","text":" (not "},{"type":"text","text":"is_word","marks":[{"type":"code"}]},{"type":"text","text":") at terminal nodes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Outer loops: iterate every board cell "},{"type":"text","text":"(r, c)","marks":[{"type":"code"}]},{"type":"text","text":" and call "},{"type":"text","text":"dfs(r, c, root)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"DFS checks: out-of-bounds, visited marker "},{"type":"text","text":"''#''","marks":[{"type":"code"}]},{"type":"text","text":", or char not in "},{"type":"text","text":"node.children","marks":[{"type":"code"}]},{"type":"text","text":" → return immediately."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"next_node.word is not None","marks":[{"type":"code"}]},{"type":"text","text":": append to result and set "},{"type":"text","text":"next_node.word = None","marks":[{"type":"code"}]},{"type":"text","text":" to prevent duplicates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark cell "},{"type":"text","text":"board[r][c] = ''#''","marks":[{"type":"code"}]},{"type":"text","text":", recurse in 4 directions with "},{"type":"text","text":"next_node","marks":[{"type":"code"}]},{"type":"text","text":", then restore cell."}]}]}]}]}}'),
  ('23770887-4d5b-7bf6-a9ab-48d51e8f3f58', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]}'),
  ('2f4cf445-7098-74e9-b4e4-00d0c7286b22', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For every word, start a full board DFS from every matching cell."}]}]}}'),
  ('d2220492-35d1-7599-84f3-e8738590cb8d', 'aB', 'code', '{"language":"python","code":"class Solution:\n\n    def findWords(self, board, words):\n\n        rows = len(board)\n        cols = len(board[0])\n        result = []\n\n        def exists(word):\n\n            def dfs(r, c, index):\n                if index == len(word):\n                    return True\n\n                if (\n                    r < 0 or r >= rows or c < 0 or c >= cols\n                    or board[r][c] != word[index]\n                ):\n                    return False\n\n                temp = board[r][c]\n                board[r][c] = \"#\"\n\n                found = (\n                    dfs(r + 1, c, index + 1)\n                    or dfs(r - 1, c, index + 1)\n                    or dfs(r, c + 1, index + 1)\n                    or dfs(r, c - 1, index + 1)\n                )\n\n                board[r][c] = temp\n                return found\n\n            for r in range(rows):\n                for c in range(cols):\n                    if board[r][c] == word[0]:\n                        if dfs(r, c, 0):\n                            return True\n\n            return False\n\n        for word in words:\n            if exists(word):\n                result.append(word)\n\n        return result","filename":"Python"}'),
  ('a560ddbc-fc94-79fa-8cf1-b72162adca59', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {\n        vector<string> result;\n\n        for (const string& word : words) {\n            if (exists(board, word)) result.push_back(word);\n        }\n\n        return result;\n    }\n\nprivate:\n    bool exists(vector<vector<char>>& board, const string& word) {\n        int rows = board.size(), cols = board[0].size();\n\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                if (board[r][c] == word[0] && dfs(board, word, r, c, 0)) return true;\n            }\n        }\n\n        return false;\n    }\n\n    bool dfs(vector<vector<char>>& board, const string& word, int r, int c, int index) {\n        if (index == (int)word.size()) return true;\n\n        if (r < 0 || r >= (int)board.size() || c < 0 || c >= (int)board[0].size()\n            || board[r][c] != word[index]) {\n            return false;\n        }\n\n        char temp = board[r][c];\n        board[r][c] = ''#'';\n\n        bool found = dfs(board, word, r + 1, c, index + 1)\n                  || dfs(board, word, r - 1, c, index + 1)\n                  || dfs(board, word, r, c + 1, index + 1)\n                  || dfs(board, word, r, c - 1, index + 1);\n\n        board[r][c] = temp;\n        return found;\n    }\n};","filename":"C++"}'),
  ('77abf9a7-2436-78ce-aeef-c7dc8caaff52', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public List<String> findWords(char[][] board, String[] words) {\n        List<String> result = new ArrayList<>();\n\n        for (String word : words) {\n            if (exists(board, word)) result.add(word);\n        }\n\n        return result;\n    }\n\n    private boolean exists(char[][] board, String word) {\n        int rows = board.length, cols = board[0].length;\n\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                if (board[r][c] == word.charAt(0) && dfs(board, word, r, c, 0)) return true;\n            }\n        }\n\n        return false;\n    }\n\n    private boolean dfs(char[][] board, String word, int r, int c, int index) {\n        if (index == word.length()) return true;\n\n        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length\n            || board[r][c] != word.charAt(index)) {\n            return false;\n        }\n\n        char temp = board[r][c];\n        board[r][c] = ''#'';\n\n        boolean found = dfs(board, word, r + 1, c, index + 1)\n                     || dfs(board, word, r - 1, c, index + 1)\n                     || dfs(board, word, r, c + 1, index + 1)\n                     || dfs(board, word, r, c - 1, index + 1);\n\n        board[r][c] = temp;\n        return found;\n    }\n}","filename":"Java"}'),
  ('2943ff5e-f8c7-7a84-b291-8c6ad8e6df56', 'aE', 'code', '{"language":"javascript","code":"var findWords = function(board, words) {\n    const rows = board.length;\n    const cols = board[0].length;\n    const result = [];\n\n    const exists = (word) => {\n        const dfs = (r, c, index) => {\n            if (index === word.length) return true;\n\n            if (\n                r < 0 || r >= rows || c < 0 || c >= cols\n                || board[r][c] !== word[index]\n            ) {\n                return false;\n            }\n\n            const temp = board[r][c];\n            board[r][c] = \"#\";\n\n            const found = dfs(r + 1, c, index + 1)\n                || dfs(r - 1, c, index + 1)\n                || dfs(r, c + 1, index + 1)\n                || dfs(r, c - 1, index + 1);\n\n            board[r][c] = temp;\n            return found;\n        };\n\n        for (let r = 0; r < rows; r++) {\n            for (let c = 0; c < cols; c++) {\n                if (board[r][c] === word[0] && dfs(r, c, 0)) return true;\n            }\n        }\n\n        return false;\n    };\n\n    for (const word of words) {\n        if (exists(word)) result.push(word);\n    }\n\n    return result;\n};","filename":"JavaScript"}'),
  ('e4e99de6-c76d-74b5-aa32-85ee36b2e1f1', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(W × R × C × 4^L) · Space: O(L) recursion","marks":[{"type":"bold"}]}]}]}}'),
  ('8d0e278a-c036-7bbc-b67d-85e98ab0d37d', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
  ('7f4468ca-71fd-79ae-beae-820627780a25', 'aH', 'code', '{"language":"python","code":"class TrieNode:\n\n    def __init__(self):\n        self.children = {}\n        self.word = None\n\n\nclass Solution:\n\n    def findWords(self, board, words):\n\n        root = TrieNode()\n\n        # Build Trie from all words\n        for word in words:\n\n            node = root\n\n            for char in word:\n\n                if char not in node.children:\n                    node.children[char] = TrieNode()\n\n                node = node.children[char]\n\n            node.word = word\n\n        rows = len(board)\n        cols = len(board[0])\n        result = []\n\n        def dfs(r, c, node):\n\n            if r < 0 or r >= rows or c < 0 or c >= cols:\n                return\n\n            char = board[r][c]\n\n            if char == \"#\":\n                return\n\n            if char not in node.children:\n                return\n\n            next_node = node.children[char]\n\n            # Complete word found\n            if next_node.word is not None:\n                result.append(next_node.word)\n                next_node.word = None  # prevent duplicates\n\n            board[r][c] = \"#\"  # mark visited\n\n            dfs(r + 1, c, next_node)\n            dfs(r - 1, c, next_node)\n            dfs(r, c + 1, next_node)\n            dfs(r, c - 1, next_node)\n\n            board[r][c] = char  # restore\n\n        for r in range(rows):\n            for c in range(cols):\n                dfs(r, c, root)\n\n        return result","filename":"Python"}'),
  ('48a61962-2309-7ef1-a870-ac9756eb50f6', 'aI', 'code', '{"language":"cpp","code":"struct TrieNode {\n    unordered_map<char, TrieNode*> children;\n    string word;  // empty means \"no word ends here\"\n};\n\nclass Solution {\npublic:\n    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {\n        TrieNode* root = new TrieNode();\n\n        // Build Trie from all words\n        for (const string& word : words) {\n            TrieNode* node = root;\n\n            for (char c : word) {\n                if (!node->children.count(c)) node->children[c] = new TrieNode();\n\n                node = node->children[c];\n            }\n\n            node->word = word;\n        }\n\n        vector<string> result;\n\n        for (int r = 0; r < (int)board.size(); r++) {\n            for (int c = 0; c < (int)board[0].size(); c++) {\n                dfs(board, r, c, root, result);\n            }\n        }\n\n        return result;\n    }\n\nprivate:\n    void dfs(vector<vector<char>>& board, int r, int c, TrieNode* node, vector<string>& result) {\n        if (r < 0 || r >= (int)board.size() || c < 0 || c >= (int)board[0].size()) return;\n\n        char ch = board[r][c];\n\n        if (ch == ''#'') return;\n\n        if (!node->children.count(ch)) return;\n\n        TrieNode* next = node->children[ch];\n\n        // Complete word found\n        if (!next->word.empty()) {\n            result.push_back(next->word);\n            next->word.clear();  // prevent duplicates\n        }\n\n        board[r][c] = ''#'';  // mark visited\n\n        dfs(board, r + 1, c, next, result);\n        dfs(board, r - 1, c, next, result);\n        dfs(board, r, c + 1, next, result);\n        dfs(board, r, c - 1, next, result);\n\n        board[r][c] = ch;  // restore\n    }\n};","filename":"C++"}'),
  ('bfef5705-1758-7539-af1e-d3dc84e5cd61', 'aJ', 'code', '{"language":"java","code":"class TrieNode {\n    Map<Character, TrieNode> children = new HashMap<>();\n    String word = null;\n}\n\nclass Solution {\n    private char[][] board;\n    private List<String> result;\n\n    public List<String> findWords(char[][] board, String[] words) {\n        TrieNode root = new TrieNode();\n\n        // Build Trie from all words\n        for (String word : words) {\n            TrieNode node = root;\n\n            for (char c : word.toCharArray()) {\n                if (!node.children.containsKey(c)) node.children.put(c, new TrieNode());\n\n                node = node.children.get(c);\n            }\n\n            node.word = word;\n        }\n\n        this.board = board;\n        result = new ArrayList<>();\n\n        for (int r = 0; r < board.length; r++) {\n            for (int c = 0; c < board[0].length; c++) {\n                dfs(r, c, root);\n            }\n        }\n\n        return result;\n    }\n\n    private void dfs(int r, int c, TrieNode node) {\n        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) return;\n\n        char ch = board[r][c];\n\n        if (ch == ''#'') return;\n\n        if (!node.children.containsKey(ch)) return;\n\n        TrieNode next = node.children.get(ch);\n\n        // Complete word found\n        if (next.word != null) {\n            result.add(next.word);\n            next.word = null;  // prevent duplicates\n        }\n\n        board[r][c] = ''#'';  // mark visited\n\n        dfs(r + 1, c, next);\n        dfs(r - 1, c, next);\n        dfs(r, c + 1, next);\n        dfs(r, c - 1, next);\n\n        board[r][c] = ch;  // restore\n    }\n}","filename":"Java"}'),
  ('d39dcffb-6d6a-7775-9245-39442ad86297', 'aK', 'code', '{"language":"javascript","code":"class TrieNode {\n    constructor() {\n        this.children = new Map();\n        this.word = null;\n    }\n}\n\nvar findWords = function(board, words) {\n    const root = new TrieNode();\n\n    // Build Trie from all words\n    for (const word of words) {\n        let node = root;\n\n        for (const char of word) {\n            if (!node.children.has(char)) node.children.set(char, new TrieNode());\n\n            node = node.children.get(char);\n        }\n\n        node.word = word;\n    }\n\n    const rows = board.length;\n    const cols = board[0].length;\n    const result = [];\n\n    const dfs = (r, c, node) => {\n        if (r < 0 || r >= rows || c < 0 || c >= cols) return;\n\n        const char = board[r][c];\n\n        if (char === \"#\") return;\n\n        if (!node.children.has(char)) return;\n\n        const nextNode = node.children.get(char);\n\n        // Complete word found\n        if (nextNode.word !== null) {\n            result.push(nextNode.word);\n            nextNode.word = null; // prevent duplicates\n        }\n\n        board[r][c] = \"#\"; // mark visited\n\n        dfs(r + 1, c, nextNode);\n        dfs(r - 1, c, nextNode);\n        dfs(r, c + 1, nextNode);\n        dfs(r, c - 1, nextNode);\n\n        board[r][c] = char; // restore\n    };\n\n    for (let r = 0; r < rows; r++) {\n        for (let c = 0; c < cols; c++) {\n            dfs(r, c, root);\n        }\n    }\n\n    return result;\n};","filename":"JavaScript"}'),
  ('e2226873-7c76-7e3b-8411-1750311dcba3', 'aL', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(R × C × 4^L) with prefix pruning · Space: O(total chars in words) + O(L) stack","marks":[{"type":"bold"}]}]}]}}'),
  ('57543584-6a00-7ee8-ae3c-a11f7c68e7a7', 'aM', 'heading', '{"level":1,"content":[{"type":"text","text":"Takeaway"}]}'),
  ('3e77850f-302e-7969-a6ae-047f2c3be1a9', 'aN', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Multi-word board search → Trie + DFS + Backtracking + Prefix Pruning"}]}]}}')
) AS c(id, position, type, content)
