lename":"Python"},"revision":1},{"id":"40c2967d-7d8e-779a-a150-8884a174463a","type":"code","position":"aQ","content":{"language":"cpp","code":"class Solution {\npublic:\n    bool containsDuplicate(vector<int>& nums) {\n        unordered_set<int> seen;\n        for (int num : nums) {\n            if (seen.count(num)) return true;\n            seen.insert(num);\n        }\n        return false;\n    }\n};","filename":"C++"},"revision":1},{"id":"d937e5ae-807f-7ea1-bdcd-ec682b13b1b7","type":"code","position":"aR","content":{"language":"java","code":"class Solution {\n    public boolean containsDuplicate(int[] nums) {\n        Set<Integer> seen = new HashSet<>();\n        for (int num : nums)\n            if (!seen.add(num)) return true;\n        return false;\n    }\n}","filename":"Java"},"revision":1},{"id":"f957b651-61f9-7857-83a3-e14abd2a4391","type":"code","position":"aS","content":{"language":"javascript","code":"var containsDuplicate = function(nums) {\n    const seen = new Set();\n    for (const num of nums) {\n        if (seen.has(num)) return true;\n        seen.add(num);\n    }\n    return false;\n};","filename":"JavaScript"},"revision":1},{"id":"a16aea1b-2911-7673-a456-3936e77f5f82","type":"text","position":"aT","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"d42fd5d9-452e-789e-8e1a-1949baea397c","type":"heading","position":"aU","content":{"level":1,"content":[{"type":"text","text":"Variants"}]},"revision":1},{"id":"48195647-9556-71f5-bdee-56c79652802d","type":"callout","position":"aV","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Method 1 — Hash Set · O(n) / O(n) ✓ Recommended"}]},{"type":"paragraph","content":[{"type":"text","text":"Build a hash set on-the-fly. O(1) lookup with early exit."}]}]}},"revision":1},{"id":"73a0fdb1-0537-790f-9205-a846a735e97c","type":"callout","position":"aW","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Method 2 — Sorting · O(n log n) / O(1)"}]},{"type":"paragraph","content":[{"type":"text","text":"Sort in-place, check adjacent elements. Better space, worse time."}]}]}},"revision":1},{"id":"7a5c2e78-5753-7643-babb-83f49c019191","type":"callout","position":"aX","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Method 3 — Python One-liner · O(n) / O(n)"}]},{"type":"paragraph","content":[{"type":"text","text":"return len(nums) != len(set(nums))","marks":[{"type":"code"}]},{"type":"text","text":" — No early exit though."}]}]}},"revision":1},{"id":"2f42d7ae-419b-770d-bb71-416c5b8305e3","type":"heading","position":"aY","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"ae3cae07-2ff0-76f0-8ef1-a4f978281782","type":"text","position":"aZ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern: Frequency Hashing","marks":[{"type":"bold"}]},{"type":"text","text":" — \"Have I seen this before?\" → "},{"type":"text","text":"Hash Set","marks":[{"type":"bold"}]},{"type":"text","text":". This is the #1 most common array pattern, foundational to Two Sum, Group Anagrams, Longest Consecutive Sequence, and hundreds more problems."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
