SELECT '7c5c7157-9830-7d68-bcb1-647ca8eb0980', '3c2659aa-4ca6-7ab5-9d86-10a40d67c7a3', 1, 'PUBLISHED', 'Generate Parentheses', '[{"id":"1ca5ec75-4f3c-79b4-9741-8a539506bda5","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 22","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/generate-parentheses/"}}]}]}]}},"revision":1},{"id":"4400f95a-597d-7aa1-84a2-fec05b1b2105","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"85e22237-06da-7cc4-8a22-6bc0b9041f8e","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" pairs of parentheses, write a function to generate all combinations of well-formed parentheses."}]}]}},"revision":1},{"id":"d67535a3-06b1-7cb9-a821-653e63e65d47","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"577f62e1-6d0d-7aa4-9447-a66be8cd0141","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generate valid strings of length $2n$ where open count $\\le n$ and close count $\\le$ open count at all steps."}]}]}},"revision":1},{"id":"5f4b231f-141b-705b-9941-2aa9e81455b0","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"afa2ca01-e808-780c-a69e-348abcd8c6d5","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Backtracking with constraints: only add "},{"type":"text","text":"''(''","marks":[{"type":"code"}]},{"type":"text","text":" if "},{"type":"text","text":"open_count < n","marks":[{"type":"code"}]},{"type":"text","text":"; only add "},{"type":"text","text":"'')''","marks":[{"type":"code"}]},{"type":"text","text":" if "},{"type":"text","text":"close_count < open_count","marks":[{"type":"code"}]},{"type":"text","text":". Prunes invalid branches early."}]}]}},"revision":1},{"id":"fa4ae358-799c-7881-909f-2b9ec7a5c77f","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"8da494c0-31ba-79c7-ac41-054a487ce7e1","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursive helper "},{"type":"text","text":"backtrack(current, open_count, close_count)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Base Case: "},{"type":"text","text":"len(current) == 2 * n","marks":[{"type":"code"}]},{"type":"text","text":", append to "},{"type":"text","text":"result","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Branch 1: If "},{"type":"text","text":"open_count < n","marks":[{"type":"code"}]},{"type":"text","text":", recurse with "},{"type":"text","text":"''(''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Branch 2: If "},{"type":"text","text":"close_count < open_count","marks":[{"type":"code"}]},{"type":"text","text":", recurse with "},{"type":"text","text":"'')''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Number of valid strings is given by the $n$th Catalan number $C_n = \\frac{1}{n+1}\\binom{2n}{n}$."}]}]}]}]}},"revision":1},{"id":"eb84659c-200f-70ee-b5d6-9218c4ef5eaf","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"dbd72a90-2b76-7622-ae3a-e4e00f35ac5c","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generate all $2^{2n}$ possible bracket strings recursively and validate each using a balance counter."}]}]}},"revision":1},{"id":"4cdad922-2146-76a3-ad06-55ad133b76d3","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def generateParenthesis(self, n):\n\n        result = []\n\n        def valid(s):\n            balance = 0\n\n            for char in s:\n                if char == \"(\":\n                    balance += 1\n                else:\n                    balance -= 1\n\n                if balance < 0:\n                    return False\n\n            return balance == 0\n\n        def generate(s):\n            if len(s) == 2 * n:\n                if valid(s):\n                    result.append(s)\n                return\n\n            generate(s + \"(\")\n            generate(s + \")\")\n\n        generate(\"\")\n\n        return result","filename":"Python"},"revision":1},{"id":"51f3f4a6-0483-708d-a994-28050f0b3dee","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<string> generateParenthesis(int n) {\n        vector<string> result;\n        generate(\"\", n, result);\n        return result;\n    }\n\nprivate:\n    bool valid(const string& s) {\n        int balance = 0;\n        for (char c : s) {\n            if (c == ''('') balance++;\n            else balance--;\n            if (balance < 0) return false;\n        }\n        return balance == 0;\n    }\n\n    void generate(const string& s, int n, vector<string>& result) {\n        if (s.size() == 2 * n) {\n            if (valid(s)) result.push_back(s);\n            return;\n        }\n        generate(s + \"(\", n, result);\n        generate(s + \")\", n, result);\n    }\n};","filename":"C++"},"revision":1},{"id":"1deef9b4-8f1a-7546-81aa-dc30eee8adcf","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public List<String> generateParenthesis(int n) {\n        List<String> result = new ArrayList<>();\n        generate(\"\", n, result);\n        return result;\n    }\n\n    private boolean valid(String s) {\n        int balance = 0;\n        for (char c : s.toCharArray()) {\n            if (c == ''('') balance++;\n            else balance--;\n            if (balance < 0) return false;\n        }\n        return balance == 0;\n    }\n\n    private void generate(String s, int n, List<String> result) {\n        if (s.length() == 2 * n) {\n            if (valid(s)) result.add(s);\n            return;\n        }\n        generate(s + \"(\", n, result);\n        generate(s + \")\", n, result);\n    }\n}","filename":"Java"},"revision":1},{"id":"a8e9bc94-8651-7e60-9582-f90408a2f2c2","type":"code","position":"aE","content":{"language":"javascript","code":"var generateParenthesis = function(n) {\n    const result = [];\n    const valid = s => {\n        let balance = 0;\n        for (const c of s) {\n            if (c === \"(\") balance++;\n            else balance--;\n            if (balance < 0) return false;\n        }\n        return balance === 0;\n    };\n    const generate = s => {\n        if (s.length === 2 * n) {\n            if (valid(s)) result.push(s);\n            return;\n        }\n        generate(s + \"(\");\n        generate(s + \")\");\n    };\n    generate(\"\");\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"7e1dde11-e5af-7d01-b7b4-c2a35c52b646","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(2^(2n) × n) · Space: O(n) recursion","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"0410ca0e-4992-7378-8dc4-cba03adf892a","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"b9b915a2-533f-72fa-9701-9bb16c0b8ad8","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def generateParenthesis(self, n):\n\n        result = []\n\n        def backtrack(current, open_count, close_count):\n\n            if len(current) == 2 * n:\n                result.append(current)\n                return\n\n            if open_count < n:\n                backtrack(\n                    current + \"(\",\n                    open_count + 1,\n                    close_count\n                )\n\n            if close_count < open_count:\n                backtrack(\n                    current + \")\",\n                    open_count,\n                    close_count + 1\n                )\n\n        backtrack(\"\", 0, 0)\n\n        return result","filename":"Python"},"revision":1},{"id":"86490a38-f8c6-7d8e-92b8-a46d7c0d27da","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    vector<string> generateParenthesis(int n) {\n        vector<string> result;\n        backtrack(\"\", 0, 0, n, result);\n        return result;\n    }\n\nprivate:\n    void backtrack(const string& current, int openCount, int closeCount, int n, vector<string>& result) {\n        if (current.size() == 2 * n) {\n            result.push_back(current);\n            return;\n        }\n        if (openCount < n) backtrack(current + \"(\", openCount + 1, closeCount, n, result);\n        if (closeCount < openCount) backtrack(current + \")\", openCount, closeCount + 1, n, result);\n    }\n};","filename":"C++"},"revision":1},{"id":"92f04bf7-e7c2-7fe1-905f-b1a5b1bc289e","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public List<String> generateParenthesis(int n) {\n        List<String> result = new ArrayList<>();\n        backtrack(\"\", 0, 0, n, result);\n        return result;\n    }\n\n    private void backtrack(String current, int openCount, int closeCount, int n, List<String> result) {\n        if (current.length() == 2 * n) {\n            result.add(current);\n            return;\n        }\n        if (openCount < n) backtrack(current + \"(\", openCount + 1, closeCount, n, result);\n        if (closeCount < openCount) backtrack(current + \")\", openCount, closeCount + 1, n, result);\n    }\n}","filename":"Java"},"revision":1},{"id":"62e3defa-29ad-7d0e-bc9e-047035e0bb6b","type":"code","position":"aK","content":{"language":"javascript","code":"var generateParenthesis = function(n) {\n    const result = [];\n    const backtrack = (current, openCount, closeCount) => {\n        if (current.length === 2 * n) {\n            result.push(current);\n            return;\n        }\n        if (openCount < n) backtrack(current + \"(\", openCount + 1, closeCount);\n        if (closeCount < openCount) backtrack(current + \")\", openCount, closeCount + 1);\n    };\n    backtrack(\"\", 0, 0);\n    return result;\n};","filename":"JavaScript"},"revision":1},{"id":"00ed0cdd-5f1d-7294-88a4-f2c28835329a","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(C(n) × n) · Space: O(n) recursion","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"729cfe0f-1af5-737c-bbe0-50101f515a33","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"1ed59fe1-76e5-7e4c-9454-826c54384b67","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Backtracking with constraints (prune impossible branches)"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
