w ListNode();\n    let current = dummy;\n\n    for (const value of values) {\n        current.next = new ListNode(value);\n        current = current.next;\n    }\n\n    return dummy.next;\n};","filename":"JavaScript"},"revision":1},{"id":"9fe9c04d-7249-775e-a666-cd0af635edb7","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(N log N) · Space: O(N)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"0f36ab2f-c570-74ac-9826-2f5bda95fb89","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"0d108340-29e7-7705-a4c6-92629e6e40d0","type":"code","position":"aH","content":{"language":"python","code":"import heapq\n\nclass Solution:\n    def mergeKLists(self, lists):\n        heap = []\n\n        for i, node in enumerate(lists):\n            if node:\n                heapq.heappush(\n                    heap,\n                    (node.val, i, node)\n                )\n\n        dummy = ListNode()\n        current = dummy\n\n        while heap:\n            value, i, node = heapq.heappop(heap)\n\n            current.next = node\n            current = current.next\n\n            if node.next:\n                heapq.heappush(\n                    heap,\n                    (\n                        node.next.val,\n                        i,\n                        node.next\n                    )\n                )\n\n        return dummy.next","filename":"Python"},"revision":1},{"id":"ae08a745-428f-76e7-b44e-6be725906922","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    ListNode* mergeKLists(vector<ListNode*>& lists) {\n        using Entry = tuple<int, int, ListNode*>;\n        priority_queue<Entry, vector<Entry>, greater<Entry>> heap;\n\n        for (int i = 0; i < lists.size(); i++) {\n            if (lists[i]) {\n                heap.push({lists[i]->val, i, lists[i]});\n            }\n        }\n\n        ListNode dummy;\n        ListNode* current = &dummy;\n\n        while (!heap.empty()) {\n            auto [value, i, node] = heap.top();\n            heap.pop();\n\n            current->next = node;\n            current = current->next;\n\n            if (node->next) {\n                heap.push({node->next->val, i, node->next});\n            }\n        }\n\n        return dummy.next;\n    }\n};","filename":"C++"},"revision":1},{"id":"a2d7dcfa-5617-7451-b1ff-184508f28f28","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public ListNode mergeKLists(ListNode[] lists) {\n        PriorityQueue<ListNode> heap = new PriorityQueue<>((a, b) -> Integer.compare(a.val, b.val));\n\n        for (ListNode node : lists) {\n            if (node != null) {\n                heap.offer(node);\n            }\n        }\n\n        ListNode dummy = new ListNode();\n        ListNode current = dummy;\n\n        while (!heap.isEmpty()) {\n            ListNode node = heap.poll();\n\n            current.next = node;\n            current = current.next;\n\n            if (node.next != null) {\n                heap.offer(node.next);\n            }\n        }\n\n        return dummy.next;\n    }\n}","filename":"Java"},"revision":1},{"id":"b45c36bb-5eac-7d14-9c17-42e9c78527aa","type":"code","position":"aK","content":{"language":"javascript","code":"var mergeKLists = function(lists) {\n    // Minimal binary min-heap of nodes keyed by val\n    const heap = [];\n\n    const push = (node) => {\n        heap.push(node);\n        let i = heap.length - 1;\n        while (i > 0) {\n            const parent = (i - 1) >> 1;\n            if (heap[parent].val <= heap[i].val) break;\n            [heap[parent], heap[i]] = [heap[i], heap[parent]];\n            i = parent;\n        }\n    };\n\n    const pop = () => {\n        const top = heap[0];\n        const last = heap.pop();\n        if (heap.length) {\n            heap[0] = last;\n            let i = 0;\n            while (true) {\n                const l = 2 * i + 1, r = l + 1;\n                let smallest = i;\n                if (l < heap.length && heap[l].val < heap[smallest].val) smallest = l;\n                if (r < heap.length && heap[r].val < heap[smallest].val) smallest = r;\n                if (smallest === i) break;\n                [heap[smallest], heap[i]] = [heap[i], heap[smallest]];\n                i = smallest;\n            }\n        }\n        return top;\n    };\n\n    for (const node of lists) {\n        if (node) {\n            push(node);\n        }\n    }\n\n    const dummy = new ListNode();\n    let current = dummy;\n\n    while (heap.length) {\n        const node = pop();\n\n        current.next = node;\n        current = current.next;\n\n        if (node.next) {\n            push(node.next);\n        }\n    }\n\n    return dummy.next;\n};","filename":"JavaScript"},"revision":1},{"id":"79af59e6-ce37-7869-b2de-0d5ab6f766c1","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(N log k) · Space: O(k)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"b997ccd4-76fd-7bbf-8bbb-3012b7a4e182","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"3e9433d9-97e6-7b41-8d5c-bedbcc5283c4","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Multiple sorted streams → Min Heap"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
