SELECT '4b24a2ba-c924-75d8-a61a-4c2d8c5c5b18', '33f423de-c144-7e8a-b980-3a3a44064a79', 'Merge k Sorted Lists', 'Merge k Sorted Lists', 'Difficulty: Hard · LeetCode 23
Problem
You are given an array of k linked-lists, each sorted in ascending order. Merge all into one sorted list.
Understanding the problem
Merge multiple sorted streams efficiently.
Intuition
Min Heap: maintain a heap of size k holding current head of each list (node.val, i, node).
Approach
Push initial head node of each non-empty list into min heap.
Pop min element from heap, append to merged list.
If popped node has a next node, push (next.val, i, next) into heap.
Repeat until heap is empty.
Naive Solution — Brute Force
Extract all node values into an array, sort array, build new list.
class Solution:
    def mergeKLists(self, lists):
        values = []

        for head in lists:
            while head:
                values.append(head.val)
                head = head.next

        values.sort()

        dummy = ListNode()
        current = dummy

        for value in values:
            current.next = ListNode(value)
            current = current.next

        return dummy.next
class Solution {
public:
    ListNode* mergeKLists(vector<ListNode*>& lists) {
        vector<int> values;

        for (ListNode* head : lists) {
            while (head) {
                values.push_back(head->val);
                head = head->next;
            }
        }

        sort(values.begin(), values.end());

        ListNode dummy;
        ListNode* current = &dummy;

        for (int value : values) {
            current->next = new ListNode(value);
            current = current->next;
        }

        return dummy.next;
    }
};
class Solution {
    public ListNode mergeKLists(ListNode[] lists) {
        List<Integer> values = new ArrayList<>();

        for (ListNode head : lists) {
            while (head != null) {
                values.add(head.val);
                head = head.next;
            }
        }

        Collections.sort(values);

        ListNode dummy = new ListNode();
        ListNode current = dummy;

        for (int value : values) {
            current.next = new ListNode(value);
            current = current.next;
        }

        return dummy.next;
    }
}
var mergeKLists = function(lists) {
    const values = [];

    for (let head of lists) {
        while (head) {
            values.push(head.val);
            head = head.next;
        }
    }

    values.sort((a, b) => a - b);

    const dummy = new ListNode();
    let current = dummy;

    for (const value of values) {
        current.next = new ListNode(value);
        current = current.next;
    }

    return dummy.next;
};
Time: O(N log N) · Space: O(N)
Optimized Code (Python 3)
import heapq

class Solution:
    def mergeKLists(self, lists):
        heap = []

        for i, node in enumerate(lists):
            if node:
                heapq.heappush(
                    heap,
                    (node.val, i, node)
                )

        dummy = ListNode()
        current = dummy

        while heap:
            value, i, node = heapq.heappop(heap)

            current.next = node
            current = current.next

            if node.next:
                heapq.heappush(
                    heap,
                    (
                        node.next.val,
                        i,
                        node.next
                    )
                )

        return dummy.next
class Solution {
public:
    ListNode* mergeKLists(vector<ListNode*>& lists) {
        using Entry = tuple<int, int, ListNode*>;
        priority_queue<Entry, vector<Entry>, greater<Entry>> heap;

        for (int i = 0; i < lists.size(); i++) {
            if (lists[i]) {
                heap.push({lists[i]->val, i, lists[i]});
            }
        }

        ListNode dummy;
        ListNode* current = &dummy;

        while (!heap.empty()) {
            auto [value, i, node] = heap.top();
            heap.pop();

            current->next = node;
            current = current->next;

            if (node->next) {
                heap.push({node->next->val, i, node->next});
            }
        }

        return dummy.next;
    }
};
class Solution {
    public ListNode mergeKLists(ListNode[] lists) {
        PriorityQueue<ListNode> heap = new PriorityQueue<>((a, b) -> Integer.compare(a.val, b.val));

        for (ListNode node : lists) {
            if (node != null) {
                heap.offer(node);
            }
        }

        ListNode dummy = new ListNode();
        ListNode current = dummy;

        while (!heap.isEmpty()) {
            ListNode node = heap.poll();

            current.next = node;
            current = current.next;

            if (node.next != null) {
                heap.offer(node.next);
            }
        }

        return dummy.next;
    }
}
var mergeKLists = function(lists) {
    // Minimal binary min-heap of nodes keyed by val
    const heap = [];

    const push = (node) => {
        heap.push(node);
        let i = heap.length - 1;
        while (i > 0) {
            const parent = (i - 1) >> 1;
            if (heap[parent].val <= heap[i].val) break;
            [heap[parent], heap[i]] = [heap[i], heap[parent]];
            i = parent;
        }
    };

    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                const l = 2 * i + 1, r = l + 1;
                let smallest = i;
                if (l < heap.length && heap[l].val < heap[smallest].val) smallest = l;
                if (r < heap.length && heap[r].val < heap[smallest].val) smallest = r;
                if (smallest === i) break;
                [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
                i = smallest;
            }
        }
        return top;
    };

    for (const node of lists) {
        if (node) {
            push(node);
        }
    }

    const dummy = new ListNode();
    let current = dummy;

    while (heap.length) {
        const node = pop();

        current.next = node;
        current = current.next;

        if (node.next) {
            push(node.next);
        }
    }

    return dummy.next;
};
Time: O(N log k) · Space: O(k)
