     }\n\n        return path;\n    }\n};","filename":"C++"},"revision":1},{"id":"254fb3a4-b4d7-7d8a-844f-2b226079d0d9","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n        List<TreeNode> pPath = pathTo(root, p);\n        List<TreeNode> qPath = pathTo(root, q);\n\n        TreeNode answer = root;\n\n        for (int i = 0; i < Math.min(pPath.size(), qPath.size()); i++) {\n            if (pPath.get(i) != qPath.get(i)) break;\n            answer = pPath.get(i);\n        }\n\n        return answer;\n    }\n\n    private List<TreeNode> pathTo(TreeNode node, TreeNode target) {\n        List<TreeNode> path = new ArrayList<>();\n\n        while (node != null) {\n            path.add(node);\n\n            if (target.val < node.val) node = node.left;\n            else if (target.val > node.val) node = node.right;\n            else break;\n        }\n\n        return path;\n    }\n}","filename":"Java"},"revision":1},{"id":"eccf82d5-5350-76f8-8938-80c33179e35d","type":"code","position":"aE","content":{"language":"javascript","code":"var lowestCommonAncestor = function(root, p, q) {\n    const pathTo = (node, target) => {\n        const path = [];\n\n        while (node) {\n            path.push(node);\n\n            if (target.val < node.val) node = node.left;\n            else if (target.val > node.val) node = node.right;\n            else break;\n        }\n\n        return path;\n    };\n\n    const pPath = pathTo(root, p);\n    const qPath = pathTo(root, q);\n\n    let answer = root;\n\n    for (let i = 0; i < Math.min(pPath.length, qPath.length); i++) {\n        if (pPath[i] !== qPath[i]) break;\n        answer = pPath[i];\n    }\n\n    return answer;\n};","filename":"JavaScript"},"revision":1},{"id":"64578f3f-8026-7f80-b404-927ed28dfc10","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"tex