nst c of s) map[c] = (map[c]||0) + 1;\n    for (const c of t) { if (!map[c]) return false; map[c]--; }\n    return true;\n};","filename":"JavaScript"},"revision":1},{"id":"73d1cacf-1585-7bbd-a9ec-4e0a875407ff","type":"text","position":"aT","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(1)*","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"33084507-798a-732b-850b-d866f47c25c4","type":"heading","position":"aU","content":{"level":1,"content":[{"type":"text","text":"Variants"}]},"revision":1},{"id":"8aace960-a989-7574-8f36-835ba6700f94","type":"callout","position":"aV","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Method 1 — Counter · O(n) / O(1) ✓"}]},{"type":"paragraph","content":[{"type":"text","text":"Counter(s) == Counter(t)","marks":[{"type":"code"}]},{"type":"text","text":" — cleanest Python one-liner."}]}]}},"revision":1},{"id":"8e985aa9-f72e-7782-9ede-ddd7be8d23c1","type":"callout","position":"aW","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Method 2 — Fixed Array[26] · O(n) / O(1)"}]},{"type":"paragraph","content":[{"type":"text","text":"Integer array of size 26. Faster in practice due to cache locality."}]}]}},"revision":1},{"id":"cfc3b071-0134-74bf-9eaa-c3d669c43136","type":"callout","position":"aX","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Method 3 — Sorting · O(n log n) / O(1)"}]},{"type":"paragraph","content":[{"type":"text","text":"Sort both strings and compare. Simple but suboptimal."}]}]}},"revision":1},{"id":"1cef4bd8-a1ef-711f-b5f0-fbebf14d6c7e","type":"heading","position":"aY","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"78aba9dd-4cb2-77d3-9f9d-a5c2d32733a9","type":"text","position":"aZ","content":{"doc":{"type":"doc","content":[{