SELECT '79c87e49-e4d4-746e-b9bb-ba3207dd71df', '624619f0-1a67-7c56-a513-b8036e1b6a8a', 1, 'PUBLISHED', 'Reverse Nodes in k-Group', '[{"id":"83ecc209-491e-7b85-abad-be8536a4e3b8","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Hard","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 25","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/reverse-nodes-in-k-group/"}}]}]}]}},"revision":1},{"id":"808da485-541b-7d72-8e71-6d8ed1340ca0","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"ac68d61e-9282-7af9-895b-d8c60f96e2ee","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reverse the nodes of a linked list "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" at a time and return its modified list."}]}]}},"revision":1},{"id":"65de8296-6a2e-736e-bf72-50af57159c7b","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"45dddb09-42f3-71b3-aa68-e571456d614f","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reverse groups of size "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" in-place; if remaining nodes < "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":", keep as is."}]}]}},"revision":1},{"id":"813459dc-f459-773f-be67-1b7bbd0cf1f3","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"0f82acb6-c561-7f86-8f7c-4fab926e53fc","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In-place group reversal: check if k nodes exist using helper "},{"type":"text","text":"get_kth","marks":[{"type":"code"}]},{"type":"text","text":". Reverse group and reconnect links."}]}]}},"revision":1},{"id":"00fefd39-2ea4-7551-8c6b-db466ca7139b","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"be325263-7c8c-72df-ae5a-5bb2a372cfa5","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"dummy = ListNode(0, head)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"group_prev = dummy","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find kth node: "},{"type":"text","text":"kth = get_kth(group_prev, k)","marks":[{"type":"code"}]},{"type":"text","text":". If None, break."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Save "},{"type":"text","text":"group_next = kth.next","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reverse subsegment from "},{"type":"text","text":"group_prev.next","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"group_next","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reconnect "},{"type":"text","text":"group_prev.next","marks":[{"type":"code"}]},{"type":"text","text":" and set "},{"type":"text","text":"group_prev","marks":[{"type":"code"}]},{"type":"text","text":" for next group."}]}]}]}]}},"revision":1},{"id":"fb491fe1-cbb2-775e-ae7e-0a6af698dc36","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]},"revision":1},{"id":"ef1cc6d1-c5db-71b4-828b-837350cfeecd","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Store node references in array, reverse sub-slices of length k, reconnect pointers."}]}]}},"revision":1},{"id":"fa17220a-3e22-7851-ac8a-20fc92d03144","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def reverseKGroup(self, head, k):\n        nodes = []\n\n        current = head\n\n        while current:\n            nodes.append(current)\n            current = current.next\n\n        for start in range(0, len(nodes), k):\n            end = min(\n                start + k,\n                len(nodes)\n            )\n\n            if end - start < k:\n                break\n\n            nodes[start:end] = reversed(\n                nodes[start:end]\n            )\n\n        for i in range(len(nodes) - 1):\n            nodes[i].next = nodes[i + 1]\n\n        if nodes:\n            nodes[-1].next = None\n\n        return nodes[0] if nodes else None","filename":"Python"},"revision":1},{"id":"cbc17670-9ba0-7f44-9397-70fbabac9dd3","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    ListNode* reverseKGroup(ListNode* head, int k) {\n        vector<ListNode*> nodes;\n\n        ListNode* current = head;\n\n        while (current) {\n            nodes.push_back(current);\n            current = current->next;\n        }\n\n        int n = nodes.size();\n\n        for (int start = 0; start < n; start += k) {\n            int end = min(start + k, n);\n\n            if (end - start < k) {\n                break;\n            }\n\n            reverse(nodes.begin() + start, nodes.begin() + end);\n        }\n\n        for (int i = 0; i + 1 < n; i++) {\n            nodes[i]->next = nodes[i + 1];\n        }\n\n        if (!nodes.empty()) {\n            nodes.back()->next = nullptr;\n        }\n\n        return nodes.empty() ? nullptr : nodes[0];\n    }\n};","filename":"C++"},"revision":1},{"id":"e5b8315a-85e3-7a4a-b606-0d80e87282ed","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public ListNode reverseKGroup(ListNode head, int k) {\n        List<ListNode> nodes = new ArrayList<>();\n\n        ListNode current = head;\n\n        while (current != null) {\n            nodes.add(current);\n            current = current.next;\n        }\n\n        int n = nodes.size();\n\n        for (int start = 0; start < n; start += k) {\n            int end = Math.min(start + k, n);\n\n            if (end - start < k) {\n                break;\n            }\n\n            Collections.reverse(nodes.subList(start, end));\n        }\n\n        for (int i = 0; i + 1 < n; i++) {\n            nodes.get(i).next = nodes.get(i + 1);\n        }\n\n        if (!nodes.isEmpty()) {\n            nodes.get(n - 1).next = null;\n        }\n\n        return nodes.isEmpty() ? null : nodes.get(0);\n    }\n}","filename":"Java"},"revision":1},{"id":"8547db35-2826-79bf-9965-9272303b171a","type":"code","position":"aE","content":{"language":"javascript","code":"var reverseKGroup = function(head, k) {\n    const nodes = [];\n\n    let current = head;\n\n    while (current) {\n        nodes.push(current);\n        current = current.next;\n    }\n\n    for (let start = 0; start < nodes.length; start += k) {\n        const end = Math.min(start + k, nodes.length);\n\n        if (end - start < k) {\n            break;\n        }\n\n        nodes.splice(start, k, ...nodes.slice(start, end).reverse());\n    }\n\n    for (let i = 0; i < nodes.length - 1; i++) {\n        nodes[i].next = nodes[i + 1];\n    }\n\n    if (nodes.length) {\n        nodes[nodes.length - 1].next = null;\n    }\n\n    return nodes.length ? nodes[0] : null;\n};","filename":"JavaScript"},"revision":1},{"id":"bb215a2d-e288-71ed-b2d1-b5cb2fd99764","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"23988e1e-39af-7c95-9478-efca55f6315e","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"2777ac90-3598-7cfe-aeef-85a07c1348f1","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def reverseKGroup(self, head, k):\n\n        def get_kth(node, k):\n            while node and k > 0:\n                node = node.next\n                k -= 1\n\n            return node\n\n        dummy = ListNode(0, head)\n        group_prev = dummy\n\n        while True:\n            kth = get_kth(group_prev, k)\n\n            if not kth:\n                break\n\n            group_next = kth.next\n\n            # Reverse group\n            previous = group_next\n            current = group_prev.next\n\n            while current != group_next:\n                next_node = current.next\n\n                current.next = previous\n\n                previous = current\n                current = next_node\n\n            old_start = group_prev.next\n\n            group_prev.next = kth\n            group_prev = old_start\n\n        return dummy.next","filename":"Python"},"revision":1},{"id":"645aa231-ec70-702c-95f2-39ed12c10f6c","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    ListNode* reverseKGroup(ListNode* head, int k) {\n        auto getKth = [](ListNode* node, int k) {\n            while (node && k > 0) {\n                node = node->next;\n                k--;\n            }\n\n            return node;\n        };\n\n        ListNode dummy(0, head);\n        ListNode* groupPrev = &dummy;\n\n        while (true) {\n            ListNode* kth = getKth(groupPrev, k);\n\n            if (!kth) {\n                break;\n            }\n\n            ListNode* groupNext = kth->next;\n\n            // Reverse group\n            ListNode* previous = groupNext;\n            ListNode* current = groupPrev->next;\n\n            while (current != groupNext) {\n                ListNode* nextNode = current->next;\n\n                current->next = previous;\n\n                previous = current;\n                current = nextNode;\n            }\n\n            ListNode* oldStart = groupPrev->next;\n\n            groupPrev->next = kth;\n            groupPrev = oldStart;\n        }\n\n        return dummy.next;\n    }\n};","filename":"C++"},"revision":1},{"id":"335ed51e-5186-7cba-9ee2-e6608c8522d1","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public ListNode reverseKGroup(ListNode head, int k) {\n        ListNode dummy = new ListNode(0, head);\n        ListNode groupPrev = dummy;\n\n        while (true) {\n            ListNode kth = getKth(groupPrev, k);\n\n            if (kth == null) {\n                break;\n            }\n\n            ListNode groupNext = kth.next;\n\n            // Reverse group\n            ListNode previous = groupNext;\n            ListNode current = groupPrev.next;\n\n            while (current != groupNext) {\n                ListNode nextNode = current.next;\n\n                current.next = previous;\n\n                previous = current;\n                current = nextNode;\n            }\n\n            ListNode oldStart = groupPrev.next;\n\n            groupPrev.next = kth;\n            groupPrev = oldStart;\n        }\n\n        return dummy.next;\n    }\n\n    private ListNode getKth(ListNode node, int k) {\n        while (node != null && k > 0) {\n            node = node.next;\n            k--;\n        }\n\n        return node;\n    }\n}","filename":"Java"},"revision":1},{"id":"595053e6-0a0b-7548-8a03-4e18aebde1c8","type":"code","position":"aK","content":{"language":"javascript","code":"var reverseKGroup = function(head, k) {\n    const getKth = (node, k) => {\n        while (node && k > 0) {\n            node = node.next;\n            k--;\n        }\n\n        return node;\n    };\n\n    const dummy = new ListNode(0, head);\n    let groupPrev = dummy;\n\n    while (true) {\n        const kth = getKth(groupPrev, k);\n\n        if (!kth) {\n            break;\n        }\n\n        const groupNext = kth.next;\n\n        // Reverse group\n        let previous = groupNext;\n        let current = groupPrev.next;\n\n        while (current !== groupNext) {\n            const nextNode = current.next;\n\n            current.next = previous;\n\n            previous = current;\n            current = nextNode;\n        }\n\n        const oldStart = groupPrev.next;\n\n        groupPrev.next = kth;\n        groupPrev = oldStart;\n    }\n\n    return dummy.next;\n};","filename":"JavaScript"},"revision":1},{"id":"7b723172-950e-7f6d-96b9-f8154d39fd59","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Aux Space: O(1)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"0bddbe88-77a0-7ccb-aea0-915563cbfc20","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"53365855-239b-7465-97a3-7c8e19621663","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pattern","marks":[{"type":"bold"}]},{"type":"text","text":" — Group size validation + In-place subsegment pointer reversal"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
