  ('00fefd39-2ea4-7551-8c6b-db466ca7139b', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"Approach"}]}'),
  ('be325263-7c8c-72df-ae5a-5bb2a372cfa5', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"dummy = ListNode(0, head)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"group_prev = dummy","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find kth node: "},{"type":"text","text":"kth = get_kth(group_prev, k)","marks":[{"type":"code"}]},{"type":"text","text":". If None, break."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Save "},{"type":"text","text":"group_next = kth.next","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reverse subsegment from "},{"type":"text","text":"group_prev.next","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"group_next","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reconnect "},{"type":"text","text":"group_prev.next","marks":[{"type":"code"}]},{"type":"text","text":" and set "},{"type":"text","text":"group_prev","marks":[{"type":"code"}]},{"type":"text","text":" for next group."}]}]}]}]}}'),
  ('fb491fe1-cbb2-775e-ae7e-0a6af698dc36', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Naive Solution — Brute Force"}]}'),
  ('ef1cc6d1-c5db-71b4-828b-837350cfeecd', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Store node references in array, reverse sub-slices of length k, reconnect pointers."}]}]}}'),
  ('fa17220a-3e22-7851-ac8a-20fc92d03144', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def reverseKGroup(self, head, k):\n        nodes = []\n\n        current = head\n\n        while current:\n            nodes.append(current)\n            current = current.next\n\n        for start in range(0, len(nodes), k):\n            end = min(\n                start + k,\n                len(nodes)\n            )\n\n            if end - start < k:\n                break\n\n            nodes[start:end] = reversed(\n                nodes[start:end]\n            )\n\n        for i in range(len(nodes) - 1):\n            nodes[i].next = nodes[i + 1]\n\n        if nodes:\n            nodes[-1].next = None\n\n        return nodes[0] if nodes else None","filename":"Python"}'),
  ('cbc17670-9ba0-7f44-9397-70fbabac9dd3', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    ListNode* reverseKGroup(ListNode* head, int k) {\n        vector<ListNode*> nodes;\n\n        ListNode* current = head;\n\n        while (current) {\n            nodes.push_back(current);\n            current = current->next;\n        }\n\n        int n = nodes.size();\n\n        for (int start = 0; start < n; start += k) {\n            int end = min(start + k, n);\n\n            if (end - start < k) {\n                break;\n            }\n\n            reverse(nodes.begin() + start, nodes.begin() + end);\n        }\n\n        for (int i = 0; i + 1 < n; i++) {\n            nodes[i]->next = nodes[i + 1];\n        }\n\n        if (!nodes.empty()) {\n            nodes.back()->next = nullptr;\n        }\n\n        return nodes.empty() ? nullptr : nodes[0];\n    }\n};","filename":"C++"}'),
  ('e5b8315a-85e3-7a4a-b606-0d80e87282ed', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public ListNode reverseKGroup(ListNode head, int k) {\n        List<ListNode> nodes = new ArrayList<>();\n\n        ListNode current = head;\n\n        while (current != null) {\n            nodes.add(current);\n            current = current.next;\n        }\n\n        int n = nodes.size();\n\n        for (int start = 0; start < n; start += k) {\n            int end = Math.min(start + k, n);\n\n            if (end - start < k) {\n                break;\n            }\n\n            Collections.reverse(nodes.subList(start, end));\n        }\n\n        for (int i = 0; i + 1 < n; i++) {\n            nodes.get(i).next = nodes.get(i + 1);\n        }\n\n        if (!nodes.isEmpty()) {\n            nodes.get(n - 1).next = null;\n        }\n\n        return nodes.isEmpty() ? null : nodes.get(0);\n    }\n}","filename":"Java"}'),
  ('8547db35-2826-79bf-9965-9272303b171a', 'aE', 'code', '{"language":"javascript","code":"var reverseKGroup = function(head, k) {\n    const nodes = [];\n\n    let current = head;\n\n    while (current) {\n        nodes.push(current);\n        current = current.next;\n    }\n\n    for (let start = 0; start < nodes.length; start += k) {\n        const end = Math.min(start + k, nodes.length);\n\n        if (end - start < k) {\n            break;\n        }\n\n        nodes.splice(start, k, ...nodes.slice(start, end).reverse());\n    }\n\n    for (let i = 0; i < nodes.length - 1; i++) {\n        nodes[i].next = nodes[i + 1];\n    }\n\n    if (nodes.length) {\n        nodes[nodes.length - 1].next = null;\n    }\n\n    return nodes.length ? nodes[0] : null;\n};","filename":"JavaScript"}'),
  ('bb215a2d-e288-71ed-b2d1-b5cb2fd99764', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(n)","marks":[{"type":"bold"}]}]}]}}'),
  ('23988e1e-39af-7c95-9478-efca55f6315e', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
