  ('34d76b2a-12ff-7827-8f14-f8d8a34e3182', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def validTree(self, n, edges):\n        if len(edges) != n - 1:\n            return False\n\n        graph = [[] for _ in range(n)]\n\n        for a, b in edges:\n            graph[a].append(b)\n            graph[b].append(a)\n\n        visited = set()\n\n        def dfs(node, parent):\n            if node in visited:\n                return False\n\n            visited.add(node)\n\n            for neighbor in graph[node]:\n                if neighbor == parent:\n                    continue\n\n                if not dfs(neighbor, node):\n                    return False\n\n            return True\n\n        return dfs(0, -1) and len(visited) == n","filename":"Python"}'),
  ('9aa20577-f0d4-784e-bc62-55766bf1fcfe', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    bool validTree(int n, vector<vector<int>>& edges) {\n        if ((int)edges.size() != n - 1) return false;\n\n        vector<vector<int>> graph(n);\n\n        for (auto& e : edges) {\n            graph[e[0]].push_back(e[1]);\n            graph[e[1]].push_back(e[0]);\n        }\n\n        vector<bool> visited(n, false);\n        int count = 0;\n\n        function<bool(int, int)> dfs = [&](int node, int parent) -> bool {\n            if (visited[node]) return false;\n\n            visited[node] = true;\n            count++;\n\n            for (int neighbor : graph[node]) {\n                if (neighbor == parent) continue;\n                if (!dfs(neighbor, node)) return false;\n            }\n\n            return true;\n        };\n\n        return dfs(0, -1) && count == n;\n    }\n};","filename":"C++"}'),
  ('e670b782-c488-7e0f-b7c6-4dd20909fe15', 'aD', 'code', '{"language":"java","code":"class Solution {\n    private List<List<Integer>> graph = new ArrayList<>();\n    private boolean[] visited;\n    private int count = 0;\n\n    public boolean validTree(int n, int[][] edges) {\n        if (edges.length != n - 1) return false;\n\n        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());\n\n        for (int[] e : edges) {\n            graph.get(e[0]).add(e[1]);\n            graph.get(e[1]).add(e[0]);\n        }\n\n        visited = new boolean[n];\n\n        return dfs(0, -1) && count == n;\n    }\n\n    private boolean dfs(int node, int parent) {\n        if (visited[node]) return false;\n\n        visited[node] = true;\n        count++;\n\n        for (int neighbor : graph.get(node)) {\n            if (neighbor == parent) continue;\n            if (!dfs(neighbor, node)) return false;\n        }\n\n        return true;\n    }\n}","filename":"Java"}'),
  ('a907fcf6-7e1d-7759-9dde-3753877fe741', 'aE', 'code', '{"language":"javascript","code":"var validTree = function(n, edges) {\n    if (edges.length !== n - 1) return false;\n\n    const graph = Array.from({ length: n }, () => []);\n\n    for (const [a, b] of edges) {\n        graph[a].push(b);\n        graph[b].push(a);\n    }\n\n    const visited = new Set();\n\n    const dfs = (node, parent) => {\n        if (visited.has(node)) return false;\n\n        visited.add(node);\n\n        for (const neighbor of graph[node]) {\n            if (neighbor === parent) continue;\n            if (!dfs(neighbor, node)) return false;\n        }\n\n        return true;\n    };\n\n    return dfs(0, -1) && visited.size === n;\n};","filename":"JavaScript"}'),
  ('895d6287-2c09-7861-9e1a-771b23974b18', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(V + E) · Aux Space: O(V + E)","marks":[{"type":"bold"}]}]}]}}'),
  ('b2df491a-75ca-75d5-8a46-b73fff4bb460', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
  ('063752ea-2c79-7e48-82d2-84ccf5a1ef87', 'aH', 'code', '{"language":"python","code":"class Solution:\n    def validTree(self, n, edges):\n        if len(edges) != n - 1:\n            return False\n\n        parent = list(range(n))\n        rank = [1] * n\n\n        def find(x):\n            while x != parent[x]:\n                parent[x] = parent[parent[x]]\n                x = parent[x]\n\n            return x\n\n        def union(a, b):\n            root_a = find(a)\n            root_b = find(b)\n\n            if root_a == root_b:\n                return False\n\n            if rank[root_a] < rank[root_b]:\n                root_a, root_b = root_b, root_a\n\n            parent[root_b] = root_a\n            rank[root_a] += rank[root_b]\n\n            return True\n\n        for a, b in edges:\n            if not union(a, b):\n                return False\n\n        return True","filename":"Python"}'),
  ('9e8cbd20-6e6c-7a12-b1cf-aab8414638cc', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    bool validTree(int n, vector<vector<int>>& edges) {\n        if ((int)edges.size() != n - 1) return false;\n\n        vector<int> parent(n), rank(n, 1);\n        iota(parent.begin(), parent.end(), 0);\n\n        auto find = [&](int x) {\n            while (x != parent[x]) {\n                parent[x] = parent[parent[x]];\n                x = parent[x];\n            }\n            return x;\n        };\n\n        auto unite = [&](int a, int b) {\n            int rootA = find(a), rootB = find(b);\n\n            if (rootA == rootB) return false;\n\n            if (rank[rootA] < rank[rootB]) swap(rootA, rootB);\n\n            parent[rootB] = rootA;\n            rank[rootA] += rank[rootB];\n\n            return true;\n        };\n\n        for (auto& e : edges)\n            if (!unite(e[0], e[1])) return false;\n\n        return true;\n    }\n};","filename":"C++"}'),
  ('66e80b6f-6771-724b-a3cd-53afe35219b3', 'aJ', 'code', '{"language":"java","code":"class Solution {\n    private int[] parent, rank;\n\n    public boolean validTree(int n, int[][] edges) {\n        if (edges.length != n - 1) return false;\n\n        parent = new int[n];\n        rank = new int[n];\n        for (int i = 0; i < n; i++) {\n            parent[i] = i;\n            rank[i] = 1;\n        }\n\n        for (int[] e : edges)\n            if (!union(e[0], e[1])) return false;\n\n        return true;\n    }\n\n    private int find(int x) {\n        while (x != parent[x]) {\n            parent[x] = parent[parent[x]];\n            x = parent[x];\n        }\n        return x;\n    }\n\n    private boolean union(int a, int b) {\n        int rootA = find(a), rootB = find(b);\n\n        if (rootA == rootB) return false;\n\n        if (rank[rootA] < rank[rootB]) {\n            int tmp = rootA; rootA = rootB; rootB = tmp;\n        }\n\n        parent[rootB] = rootA;\n        rank[rootA] += rank[rootB];\n\n        return true;\n    }\n}","filename":"Java"}'),
  ('312543f8-cecf-74db-80f8-67b03c7592f4', 'aK', 'code', '{"language":"javascript","code":"var validTree = function(n, edges) {\n    if (edges.length !== n - 1) return false;\n\n    const parent = Array.from({ length: n }, (_, i) => i);\n    const rank = new Array(n).fill(1);\n\n    const find = (x) => {\n        while (x !== parent[x]) {\n            parent[x] = parent[parent[x]];\n            x = parent[x];\n        }\n        return x;\n    };\n\n    const union = (a, b) => {\n        let rootA = find(a), rootB = find(b);\n\n        if (rootA === rootB) return false;\n\n        if (rank[rootA] < rank[rootB]) [rootA, rootB] = [rootB, rootA];\n\n        parent[rootB] = rootA;\n        rank[rootA] += rank[rootB];\n\n        return true;\n    };\n\n    for (const [a, b] of edges)\n        if (!union(a, b)) return false;\n\n    return true;\n};","filename":"JavaScript"}'),
  ('7de7849a-8faf-75e7-b64c-742552fecc6b', 'aL', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(E α(V)) · Aux Space: O(V)","marks":[{"type":"bold"}]}]}]}}')
