class Solution {
public:
    int missingNumber(vector<int>& nums) {
        int n = nums.size();
        int answer = n;

        for (int i = 0; i < n; i++) {
            answer ^= i;
            answer ^= nums[i];
        }

        return answer;
    }
};
class Solution {
    public int missingNumber(int[] nums) {
        int n = nums.length;
        int answer = n;

        for (int i = 0; i < n; i++) {
            answer ^= i;
            answer ^= nums[i];
        }

        return answer;
    }
}
var missingNumber = function(nums) {
    const n = nums.length;
    let answer = n;

    for (let i = 0; i < n; i++) {
        answer ^= i;
        answer ^= nums[i];
    }

    return answer;
};
Time: O(n) · Space: O(1)
