SELECT '2bc71692-20be-7aab-af04-4953fb5bd601', '0292ea78-c667-7708-9fed-53eaea4c5210', 1, 'PUBLISHED', 'Alien Dictionary', '[{"id":"d0127cd0-8b2b-79ee-96bd-3627f2f445f2","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Hard","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 269","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/alien-dictionary/"}}]}]}]}},"revision":1},{"id":"8e7c3fb7-432d-74ec-9c92-c6b22ee9527d","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"70ca58e9-ef68-7ce8-a929-8e293da015d5","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given sorted dictionary of alien language words, return valid ordering of letters in alien alphabet. If invalid return "},{"type":"text","text":"\"\"","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"d56069ea-84ad-7c10-bef7-2b0a517a7e98","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"049b5056-3bf2-79c9-be88-10c38b6b0e40","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Topological Sort on DAG formed by directed edges comparing adjacent words in dictionary."}]}]}},"revision":1},{"id":"18a678af-8cba-706d-839d-0344e9d5e27e","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"ccbd799b-82e6-72f0-9524-97b34e47d268","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare adjacent words to extract directed character edges. Post-order DFS topological sort with cycle detection."}]}]}},"revision":1},{"id":"600cecff-4246-7936-9f30-bf5717256650","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"7d7de9d7-4864-7339-9d48-d8899f9d55b2","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare adjacent words w1, w2. If w1 starts with w2 and len(w1) > len(w2) return \"\"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find first differing char and add edge w1[j] -> w2[j]."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Post-order DFS with cycle detection. Return reversed post-order list."}]}]}]}]}},"revision":1},{"id":"63fff2cb-d850-77d6-bcb4-196af2c900b0","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution"}]},"revision":1},{"id":"c09aab1d-6d09-72c9-a46a-7ee785a22595","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Character permutation brute force."}]}]}},"revision":1},{"id":"853be258-a188-75d4-a1ec-6471dc8f87c4","type":"code","position":"aB","content":{"language":"python","code":"from itertools import permutations\n\nclass Solution:\n    def alienOrder(self, words):\n        chars = sorted(set(\"\".join(words)))\n\n        # Are the words sorted under this alphabet order?\n        def is_sorted(order):\n            rank = {char: i for i, char in enumerate(order)}\n\n            for w1, w2 in zip(words, words[1:]):\n                j = 0\n\n                while j < len(w1) and j < len(w2) and w1[j] == w2[j]:\n                    j += 1\n\n                if j == len(w1) or j == len(w2):\n                    if len(w1) > len(w2):\n                        return False  # longer word before its prefix\n                elif rank[w1[j]] > rank[w2[j]]:\n                    return False\n\n            return True\n\n        # Try every ordering of the letters\n        for order in permutations(chars):\n            if is_sorted(order):\n                return \"\".join(order)\n\n        return \"\"","filename":"Python"},"revision":1},{"id":"885dbdce-5b4c-7903-b72c-0a8722042b58","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    string alienOrder(vector<string>& words) {\n        string chars;\n        for (auto& word : words)\n            for (char c : word)\n                if (chars.find(c) == string::npos) chars += c;\n\n        sort(chars.begin(), chars.end());\n\n        // Try every ordering of the letters\n        do {\n            if (isSorted(words, chars)) return chars;\n        } while (next_permutation(chars.begin(), chars.end()));\n\n        return \"\";\n    }\n\nprivate:\n    // Are the words sorted under this alphabet order?\n    bool isSorted(const vector<string>& words, const string& order) {\n        int rank[26] = {};\n        for (int i = 0; i < (int)order.size(); i++) rank[order[i] - ''a''] = i;\n\n        for (int i = 0; i + 1 < (int)words.size(); i++) {\n            const string& w1 = words[i];\n            const string& w2 = words[i + 1];\n            int j = 0;\n\n            while (j < (int)w1.size() && j < (int)w2.size() && w1[j] == w2[j]) j++;\n\n            if (j == (int)w1.size() || j == (int)w2.size()) {\n                if (w1.size() > w2.size()) return false;  // longer word before its prefix\n            } else if (rank[w1[j] - ''a''] > rank[w2[j] - ''a'']) {\n                return false;\n            }\n        }\n\n        return true;\n    }\n};","filename":"C++"},"revision":1},{"id":"c68a1f62-f87d-7ed0-bb75-b0cdbdb9ce44","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    private String[] words;\n    private String chars;\n    private int[] rank = new int[26];\n\n    public String alienOrder(String[] words) {\n        this.words = words;\n\n        StringBuilder sb = new StringBuilder();\n        for (String word : words)\n            for (char c : word.toCharArray())\n                if (sb.indexOf(String.valueOf(c)) == -1) sb.append(c);\n        chars = sb.toString();\n\n        // Try every ordering of the letters\n        String result = permute(new StringBuilder(), new boolean[chars.length()]);\n        return result == null ? \"\" : result;\n    }\n\n    private String permute(StringBuilder order, boolean[] used) {\n        if (order.length() == chars.length())\n            return isSorted(order) ? order.toString() : null;\n\n        for (int i = 0; i < chars.length(); i++) {\n            if (used[i]) continue;\n\n            used[i] = true;\n            order.append(chars.charAt(i));\n\n            String result = permute(order, used);\n            if (result != null) return result;\n\n            order.deleteCharAt(order.length() - 1);\n            used[i] = false;\n        }\n\n        return null;\n    }\n\n    // Are the words sorted under this alphabet order?\n    private boolean isSorted(StringBuilder order) {\n        for (int i = 0; i < order.length(); i++) rank[order.charAt(i) - ''a''] = i;\n\n        for (int i = 0; i + 1 < words.length; i++) {\n            String w1 = words[i], w2 = words[i + 1];\n            int j = 0;\n\n            while (j < w1.length() && j < w2.length() && w1.charAt(j) == w2.charAt(j)) j++;\n\n            if (j == w1.length() || j == w2.length()) {\n                if (w1.length() > w2.length()) return false;  // longer word before its prefix\n            } else if (rank[w1.charAt(j) - ''a''] > rank[w2.charAt(j) - ''a'']) {\n                return false;\n            }\n        }\n\n        return true;\n    }\n}","filename":"Java"},"revision":1},{"id":"7b1d48ff-840d-7999-8964-92d103fe9e03","type":"code","position":"aE","content":{"language":"javascript","code":"var alienOrder = function(words) {\n    const chars = [...new Set(words.join(\"\"))];\n\n    // Are the words sorted under this alphabet order?\n    const isSorted = (order) => {\n        const rank = {};\n        order.forEach((c, i) => rank[c] = i);\n\n        for (let i = 0; i + 1 < words.length; i++) {\n            const w1 = words[i], w2 = words[i + 1];\n            let j = 0;\n\n            while (j < w1.length && j < w2.length && w1[j] === w2[j]) j++;\n\n            if (j === w1.length || j === w2.length) {\n                if (w1.length > w2.length) return false;  // longer word before its prefix\n            } else if (rank[w1[j]] > rank[w2[j]]) {\n                return false;\n            }\n        }\n\n        return true;\n    };\n\n    // Try every ordering of the letters\n    const used = new Array(chars.length).fill(false);\n    const order = [];\n\n    const permute = () => {\n        if (order.length === chars.length) return isSorted(order);\n\n        for (let i = 0; i < chars.length; i++) {\n            if (used[i]) continue;\n\n            used[i] = true;\n            order.push(chars[i]);\n\n            if (permute()) return true;\n\n            order.pop();\n            used[i] = false;\n        }\n\n        return false;\n    };\n\n    return permute() ? order.join(\"\") : \"\";\n};","filename":"JavaScript"},"revision":1},{"id":"ed9a0816-689f-7cfc-8612-48ee73cd5919","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(26!) · Aux Space: O(1)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"86a9ccb2-8773-7449-b112-42a5fb56bd4c","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"8e267cd7-615d-74c4-8c49-557b83ec14c1","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def alienOrder(self, words):\n        graph = {\n            char: set()\n            for word in words\n            for char in word\n        }\n\n        for i in range(len(words) - 1):\n            w1, w2 = words[i], words[i + 1]\n            min_length = min(len(w1), len(w2))\n\n            if len(w1) > len(w2) and w1[:min_length] == w2[:min_length]:\n                return \"\"\n\n            for j in range(min_length):\n                if w1[j] != w2[j]:\n                    graph[w1[j]].add(w2[j])\n                    break\n\n        visited = {}\n        result = []\n\n        def dfs(char):\n            if char in visited:\n                return visited[char]\n\n            visited[char] = True\n\n            for neighbor in graph[char]:\n                if dfs(neighbor):\n                    return True\n\n            visited[char] = False\n            result.append(char)\n\n            return False\n\n        for char in graph:\n            if dfs(char):\n                return \"\"\n\n        return \"\".join(result[::-1])","filename":"Python"},"revision":1},{"id":"a7fbf7be-5f2e-79fe-bfb0-63b2e936bd24","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    string alienOrder(vector<string>& words) {\n        unordered_map<char, unordered_set<char>> graph;\n        for (auto& word : words)\n            for (char c : word) graph[c];\n\n        for (int i = 0; i + 1 < (int)words.size(); i++) {\n            const string& w1 = words[i];\n            const string& w2 = words[i + 1];\n            int minLength = min(w1.size(), w2.size());\n\n            if (w1.size() > w2.size() && w1.compare(0, minLength, w2, 0, minLength) == 0)\n                return \"\";\n\n            for (int j = 0; j < minLength; j++) {\n                if (w1[j] != w2[j]) {\n                    graph[w1[j]].insert(w2[j]);\n                    break;\n                }\n            }\n        }\n\n        // true = on the current path (cycle), false = finished\n        unordered_map<char, bool> visited;\n        string result;\n\n        function<bool(char)> dfs = [&](char c) -> bool {\n            if (visited.count(c)) return visited[c];\n\n            visited[c] = true;\n\n            for (char neighbor : graph[c])\n                if (dfs(neighbor)) return true;\n\n            visited[c] = false;\n            result += c;\n\n            return false;\n        };\n\n        for (auto& [c, _] : graph)\n            if (dfs(c)) return \"\";\n\n        reverse(result.begin(), result.end());\n        return result;\n    }\n};","filename":"C++"},"revision":1},{"id":"f415a785-1402-7a1d-af38-2e972e4fd421","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    private Map<Character, Set<Character>> graph = new LinkedHashMap<>();\n    // true = on the current path (cycle), false = finished\n    private Map<Character, Boolean> visited = new HashMap<>();\n    private StringBuilder result = new StringBuilder();\n\n    public String alienOrder(String[] words) {\n        for (String word : words)\n            for (char c : word.toCharArray())\n                graph.putIfAbsent(c, new HashSet<>());\n\n        for (int i = 0; i + 1 < words.length; i++) {\n            String w1 = words[i], w2 = words[i + 1];\n            int minLength = Math.min(w1.length(), w2.length());\n\n            if (w1.length() > w2.length() && w1.startsWith(w2))\n                return \"\";\n\n            for (int j = 0; j < minLength; j++) {\n                if (w1.charAt(j) != w2.charAt(j)) {\n                    graph.get(w1.charAt(j)).add(w2.charAt(j));\n                    break;\n                }\n            }\n        }\n\n        for (char c : graph.keySet())\n            if (dfs(c)) return \"\";\n\n        return result.reverse().toString();\n    }\n\n    private boolean dfs(char c) {\n        if (visited.containsKey(c)) return visited.get(c);\n\n        visited.put(c, true);\n\n        for (char neighbor : graph.get(c))\n            if (dfs(neighbor)) return true;\n\n        visited.put(c, false);\n        result.append(c);\n\n        return false;\n    }\n}","filename":"Java"},"revision":1},{"id":"0cc61cec-3632-72b6-bb13-b91422cfd6d1","type":"code","position":"aK","content":{"language":"javascript","code":"var alienOrder = function(words) {\n    const graph = new Map();\n    for (const word of words)\n        for (const c of word)\n            if (!graph.has(c)) graph.set(c, new Set());\n\n    for (let i = 0; i + 1 < words.length; i++) {\n        const w1 = words[i], w2 = words[i + 1];\n        const minLength = Math.min(w1.length, w2.length);\n\n        if (w1.length > w2.length && w1.startsWith(w2)) return \"\";\n\n        for (let j = 0; j < minLength; j++) {\n            if (w1[j] !== w2[j]) {\n                graph.get(w1[j]).add(w2[j]);\n                break;\n            }\n        }\n    }\n\n    // true = on the current path (cycle), false = finished\n    const visited = new Map();\n    const result = [];\n\n    const dfs = (c) => {\n        if (visited.has(c)) return visited.get(c);\n\n        visited.set(c, true);\n\n        for (const neighbor of graph.get(c))\n            if (dfs(neighbor)) return true;\n\n        visited.set(c, false);\n        result.push(c);\n\n        return false;\n    };\n\n    for (const c of graph.keys())\n        if (dfs(c)) return \"\";\n\n    return result.reverse().join(\"\");\n};","filename":"JavaScript"},"revision":1},{"id":"f77cf456-bcce-7450-877a-46b94e315389","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(C) total characters · Aux Space: O(1) bounded by 26 letters","marks":[{"type":"bold"}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
