class Solution:
    def wallsAndGates(self, rooms):
        rows = len(rooms)
        cols = len(rooms[0])

        queue = deque()

        for r in range(rows):
            for c in range(cols):
                if rooms[r][c] == 0:
                    queue.append((r, c))

