  ('a2cdd859-e2bc-7c73-86b3-ccc820133e8d', 'aB', 'code', '{"language":"python","code":"class MedianFinder:\n\n    def __init__(self):\n        self.nums = []\n\n    def addNum(self, num):\n        self.nums.append(num)\n\n    def findMedian(self):\n        self.nums.sort()\n\n        n = len(self.nums)\n\n        if n % 2:\n            return self.nums[n // 2]\n\n        return (\n            self.nums[n // 2 - 1]\n            + self.nums[n // 2]\n        ) / 2","filename":"Python"}'),
  ('ce5323d0-aefe-76f0-8423-6c539e1570e1', 'aC', 'code', '{"language":"cpp","code":"class MedianFinder {\n    vector<int> nums;\n\npublic:\n    MedianFinder() {}\n\n    void addNum(int num) {\n        nums.push_back(num);\n    }\n\n    double findMedian() {\n        sort(nums.begin(), nums.end());\n\n        int n = nums.size();\n\n        if (n % 2) return nums[n / 2];\n\n        return (nums[n / 2 - 1] + nums[n / 2]) / 2.0;\n    }\n};","filename":"C++"}'),
  ('51f5bdd0-efcb-7b57-a4b7-ab3fe69fc008', 'aD', 'code', '{"language":"java","code":"class MedianFinder {\n    private List<Integer> nums = new ArrayList<>();\n\n    public MedianFinder() {}\n\n    public void addNum(int num) {\n        nums.add(num);\n    }\n\n    public double findMedian() {\n        Collections.sort(nums);\n\n        int n = nums.size();\n\n        if (n % 2 == 1) return nums.get(n / 2);\n\n        return (nums.get(n / 2 - 1) + nums.get(n / 2)) / 2.0;\n    }\n}","filename":"Java"}'),
  ('17a83b90-eba2-7004-8d1c-d00d75829d4e', 'aE', 'code', '{"language":"javascript","code":"class MedianFinder {\n    constructor() {\n        this.nums = [];\n    }\n\n    addNum(num) {\n        this.nums.push(num);\n    }\n\n    findMedian() {\n        this.nums.sort((a, b) => a - b);\n\n        const n = this.nums.length;\n\n        if (n % 2) return this.nums[n >> 1];\n\n        return (this.nums[n / 2 - 1] + this.nums[n / 2]) / 2;\n    }\n}","filename":"JavaScript"}'),
