  ('63c24c8a-97ac-7163-ace1-022bd573e0e2', 'aH', 'code', '{"language":"python","code":"import heapq\n\nclass MedianFinder:\n\n    def __init__(self):\n        self.small = []  # max heap\n        self.large = []  # min heap\n\n    def addNum(self, num):\n\n        heapq.heappush(\n            self.small,\n            -num\n        )\n\n        # Ensure every small <= every large\n        if (\n            self.small\n            and self.large\n            and -self.small[0] > self.large[0]\n        ):\n            value = -heapq.heappop(self.small)\n\n            heapq.heappush(\n                self.large,\n                value\n            )\n\n        # Balance sizes\n        if len(self.small) > len(self.large) + 1:\n            value = -heapq.heappop(self.small)\n\n            heapq.heappush(\n                self.large,\n                value\n            )\n\n        elif len(self.large) > len(self.small):\n            value = heapq.heappop(self.large)\n\n            heapq.heappush(\n                self.small,\n                -value\n            )\n\n    def findMedian(self):\n\n        if len(self.small) > len(self.large):\n            return -self.small[0]\n\n        return (\n            -self.small[0]\n            + self.large[0]\n        ) / 2","filename":"Python"}'),
  ('7ee433c9-432e-7b9b-ac26-41518d246e17', 'aI', 'code', '{"language":"cpp","code":"class MedianFinder {\n    priority_queue<int> small;                             // max-heap\n    priority_queue<int, vector<int>, greater<int>> large;  // min-heap\n\npublic:\n    MedianFinder() {}\n\n    void addNum(int num) {\n        small.push(num);\n\n        // Ensure every small <= every large\n        if (!small.empty() && !large.empty() && small.top() > large.top()) {\n            large.push(small.top());\n            small.pop();\n        }\n\n        // Balance sizes\n        if (small.size() > large.size() + 1) {\n            large.push(small.top());\n            small.pop();\n        } else if (large.size() > small.size()) {\n            small.push(large.top());\n            large.pop();\n        }\n    }\n\n    double findMedian() {\n        if (small.size() > large.size()) return small.top();\n\n        return (small.top() + large.top()) / 2.0;\n    }\n};","filename":"C++"}'),
  ('d51ff3be-361b-7642-8e06-e920cb7af913', 'aJ', 'code', '{"language":"java","code":"class MedianFinder {\n    private PriorityQueue<Integer> small = new PriorityQueue<>(Collections.reverseOrder());  // max-heap\n    private PriorityQueue<Integer> large = new PriorityQueue<>();                            // min-heap\n\n    public MedianFinder() {}\n\n    public void addNum(int num) {\n        small.offer(num);\n\n        // Ensure every small <= every large\n        if (!small.isEmpty() && !large.isEmpty() && small.peek() > large.peek()) {\n            large.offer(small.poll());\n        }\n\n        // Balance sizes\n        if (small.size() > large.size() + 1) {\n            large.offer(small.poll());\n        } else if (large.size() > small.size()) {\n            small.offer(large.poll());\n        }\n    }\n\n    public double findMedian() {\n        if (small.size() > large.size()) return small.peek();\n\n        return (small.peek() + large.peek()) / 2.0;\n    }\n}","filename":"Java"}'),
  ('7caa62e8-d825-7512-b851-eace5c7f8f3f', 'aK', 'code', '{"language":"javascript","code":"class MinHeap {\n    constructor(compare = (a, b) => a - b, items = []) {\n        this.compare = compare;\n        this.data = items;\n        for (let i = (items.length >> 1) - 1; i >= 0; i--) this.siftDown(i);\n    }\n\n    size() { return this.data.length; }\n\n    peek() { return this.data[0]; }\n\n    push(value) {\n        const data = this.data;\n        data.push(value);\n        let i = data.length - 1;\n        while (i > 0) {\n            const parent = (i - 1) >> 1;\n            if (this.compare(data[i], data[parent]) >= 0) break;\n            [data[i], data[parent]] = [data[parent], data[i]];\n            i = parent;\n        }\n    }\n\n    pop() {\n        const data = this.data;\n        const top = data[0];\n        const last = data.pop();\n        if (data.length > 0) {\n            data[0] = last;\n            this.siftDown(0);\n        }\n        return top;\n    }\n\n    siftDown(i) {\n        const data = this.data;\n        while (true) {\n            const left = 2 * i + 1, right = left + 1;\n            let smallest = i;\n            if (left < data.length && this.compare(data[left], data[smallest]) < 0) smallest = left;\n            if (right < data.length && this.compare(data[right], data[smallest]) < 0) smallest = right;\n            if (smallest === i) return;\n            [data[i], data[smallest]] = [data[smallest], data[i]];\n            i = smallest;\n        }\n    }\n}\n\nclass MedianFinder {\n    constructor() {\n        this.small = new MinHeap((a, b) => b - a);  // max-heap\n        this.large = new MinHeap((a, b) => a - b);  // min-heap\n    }\n\n    addNum(num) {\n        this.small.push(num);\n\n        // Ensure every small <= every large\n        if (this.small.size() && this.large.size() && this.small.peek() > this.large.peek()) {\n            this.large.push(this.small.pop());\n        }\n\n        // Balance sizes\n        if (this.small.size() > this.large.size() + 1) {\n            this.large.push(this.small.pop());\n        } else if (this.large.size() > this.small.size()) {\n            this.small.push(this.large.pop());\n        }\n    }\n\n    findMedian() {\n        if (this.small.size() > this.large.size()) return this.small.peek();\n\n        return (this.small.peek() + this.large.peek()) / 2;\n    }\n}","filename":"JavaScript"}'),
