d","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"cooldown","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"1b5c3247-50d1-7b88-8da6-7353d21201c9","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"ec963397-7bd6-7a99-b045-160aa6388551","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize "},{"type":"text","text":"hold = -prices[0]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"sold = 0","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"cooldown = 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For "},{"type":"text","text":"price","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"prices[1:]","marks":[{"type":"code"}]},{"type":"text","text":": update state variables according to transitions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"max(sold, cooldown)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"6381620d-9003-7639-a7ca-559c91dbfc49","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Recursion"}]},"revision":1},{"id":"83cc4718-1408-7d23-9421-35ab18412a3a","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Branch recursively between buy, sell, and cooldown choices."}]}]}},"revision":1},{"id":"8a1ba7b3-6cbf-74e6-b43a-1f88603e464f","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def maxProfit(self, prices):\n\n        def dfs(i, buying):\n            if i >= len(prices):\n                return 0\n\n            if buying:\n                buy = -prices[i] + dfs(i + 1, False)\n                skip = dfs(i + 1, True)\n\n                return max(buy, skip)\n\n            sell = prices[i] + dfs(i + 2, True)\n            hold = dfs(i + 1, False)\n\n            return max(sell, hold)\n\n        return dfs(0, True)","filename":"Python"},"revision":1},{"id":"60a42adc-4ae2-7032-814f-3ca7c98d5b5a","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int maxProfit(vector<int>& prices) {\n        return dfs(prices, 0, true);\n    }\n\nprivate:\n    int dfs(vector<int>& prices, int i, bool buying) {\n        if (i >= (int)prices.size()) return 0;\n\n        if (buying) {\n            int buy = -prices[i] + dfs(prices, i + 1, false);\n            int skip = dfs(prices, i + 1, true);\n            return max(buy, skip);\n        }\n\n        int sell = prices[i] + dfs(prices, i + 2, true);\n        int hold = dfs(prices, i + 1, false);\n        return max(sell, hold);\n    }\n};","filename":"C++"},"revision":1},{"id":"413e1d3a-92f7-77fa-84b8-94ed268af465","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int maxProfit(int[] prices) {\n        return dfs(prices, 0, true);\n    }\n\n    private int dfs(int[] prices, int i, boolean buying) {\n        if (i >= prices.length) return 0;\n\n        if (buying) {\n            int buy = -prices[i] + dfs(prices, i + 1, false);\n            int skip = dfs(prices, i + 1, true);\n            return Math.max(buy, skip);\n        }\n\n        int sell = prices[i] + dfs(prices, i + 2, true);\n        int hold = dfs(prices, i + 1, false);\n        return Math.max(sell, hold);\n    }\n}","filename":"Java"},"revision":1},{"id":"891023db-b48e-72fd-af61-f574ce9d1429","type":"code","position":"aE","content":{"language":"javascript","code":"var maxProfit = function(prices) {\n    const dfs = (i, buying) => {\n        if (i >= prices.length) return 0;\n\n        if (buying) {\n            const buy = -prices[i] + dfs(i + 1, false);\n            const skip = dfs(i + 1, true);\n            return Math.max(buy, skip);\n        }\n\n        const sell = prices[i] + dfs(i + 2, true);\n        const hold = dfs(i + 1, false);\n        return Math.max(sell, hold);\n    };\n\n    return dfs(0, true);\n};","filename":"JavaScript"},"revision":1},{"id":"be5bdefc-1ba5-7989-91e8-a42be56217f9","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(2^n) · Aux Space: O(n)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"1db9db7c-212c-7b62-8de7-3e5746480dfb","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"80c4cab0-e62b-7e63-9cc7-b33f5c012066","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def maxProfit(self, prices):\n\n        memo = {}\n\n        def dfs(i, buying):\n            if i >= len(prices):\n                return 0\n\n            key = (i, buying)\n\n            if key in memo:\n                return memo[key]\n\n            if buying:\n                buy = -prices[i] + dfs(i + 1, False)\n                skip = dfs(i + 1, True)\n\n                memo[key] = max(buy, skip)\n\n            else:\n                sell = prices[i] + dfs(i + 2, True)\n                hold = dfs(i + 1, False)\n\n                memo[key] = max(sell, hold)\n\n            return memo[key]\n\n        return dfs(0, True)","filename":"Python"},"revision":1},{"id":"b7a9a965-688c-7c63-bb93-4001159bf80f","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int maxProfit(vector<int>& prices) {\n        // memo[i][buying], -1 = not computed yet\n        memo.assign(prices.size(), vector<int>(2, -1));\n        return dfs(prices, 0, true);\n    }\n\nprivate:\n    vector<vector<int>> memo;\n\n    int dfs(vector<int>& prices, int i, bool buying) {\n        if (i >= (int)prices.size()) return 0;\n\n        int& cached = memo[i][buying];\n        if (cached != -1) return cached;\n\n        if (buying) {\n            int buy = -prices[i] + dfs(prices, i + 1, false);\n            int skip = dfs(prices, i + 1, true);\n            cached = max(buy, skip);\n        } else {\n            int sell = prices[i] + dfs(prices, i + 2, true);\n            int hold = dfs(prices, i + 1, false);\n            cached = max(sell, hold);\n        }\n\n        return cached;\n    }\n};","filename":"C++"},"revision":1},{"id":"5e877c9c-c1a0-749f-90ac-5d0dc35d8d77","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    // memo[i][buying ? 1 : 0], null = not computed yet\n    private Integer[][] memo;\n\n    public int maxProfit(int[] prices) {\n        memo = new Integer[prices.length][2];\n        return dfs(prices, 0, true);\n    }\n\n    private int dfs(int[] prices, int i, boolean buying) {\n        if (i >= prices.length) return 0;\n\n        int b = buying ? 1 : 0;\n        if (memo[i][b] != null) return memo[i][b];\n\n        if (buying) {\n            int buy = -prices[i] + dfs(prices, i + 1, false);\n            int skip = dfs(prices, i + 1, true);\n            memo[i][b] = Math.max(buy, skip);\n        } else {\n            int sell = prices[i] + dfs(prices, i + 2, true);\n            int hold = dfs(prices, i + 1, false);\n            memo[i][b] = Math.max(sell, hold);\n        }\n\n        return memo[i][b];\n    }\n}","filename":"Java"},"revision":1},{"id":"48a8852c-e06b-78c6-9385-792ef1e21df1","type":"code","position":"aK","content":{"language":"javascript","code":"var maxProfit = function(prices) {\n    const memo = new Map();\n\n    const dfs = (i, buying) => {\n        if (i >= prices.length) return 0;\n\n        const key = `${i},${buying}`;\n        if (memo.has(key)) return memo.get(key);\n\n        let result;\n\n        if (buying) {\n            const buy = -prices[i] + dfs(i + 1, false);\n            const skip = dfs(i + 1, true);\n            result = Math.max(buy, skip);\n        } else {\n            const sell = prices[i] + dfs(i + 2, true);\n            const hold = dfs(i + 1, false);\n            result = Math.max(sell, hold);\n        }\n\n        memo.set(key, result);\n        return result;\n    };\n\n    return dfs(0, true);\n};","filename":"JavaScript"},"revision":1},{"id":"e84d9aa4-270a-7f00-b8e2-fdd31497b0ce","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n) · Space: O(1) (State Machine) / O(n) (Memoization)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"027abaed-2777-7a64-a410-81ac0bcdc13a","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"4f115e32-0575-7b2d-b8b1-a3b8cd6cd413","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"State Machine DP","marks":[{"type":"bold"}]},{"type":"text","text":" — Model transitions between BUY, SELL, and COOLDOWN explicitly."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
