  ('48a8852c-e06b-78c6-9385-792ef1e21df1', 'aK', 'code', '{"language":"javascript","code":"var maxProfit = function(prices) {\n    const memo = new Map();\n\n    const dfs = (i, buying) => {\n        if (i >= prices.length) return 0;\n\n        const key = `${i},${buying}`;\n        if (memo.has(key)) return memo.get(key);\n\n        let result;\n\n        if (buying) {\n            const buy = -prices[i] + dfs(i + 1, false);\n            const skip = dfs(i + 1, true);\n            result = Math.max(buy, skip);\n        } else {\n            const sell = prices[i] + dfs(i + 2, true);\n            const hold = dfs(i + 1, false);\n            result = Math.max(sell, hold);\n        }\n\n        memo.set(key, result);\n        return result;\n    };\n\n    return dfs(0, true);\n};","filename":"JavaScript"}'),
