SELECT '59ec4947-c08c-7401-bf8f-6546e9e744f8', 'dcdd1103-aac1-714e-ad48-b39050acc7ac', 1, 'PUBLISHED', 'Burst Balloons', '[{"id":"70ae3243-3c9f-70e8-aa25-cf4f7110cb08","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Hard","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 312","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/burst-balloons/"}}]}]}]}},"revision":1},{"id":"d2f4f0de-e900-7709-8fc6-7c64c55bbfe8","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"8e74d411-5936-71a5-9737-691246d1c188","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Burst balloon "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" to gain "},{"type":"text","text":"nums[i-1] * nums[i] * nums[i+1]","marks":[{"type":"code"}]},{"type":"text","text":" coins. Return max total coins."}]}]}},"revision":1},{"id":"bf0ebf1b-7789-7980-941e-41ff379f80db","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"faf13f73-a9ed-7161-b23c-e922f6f0d07a","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Instead of choosing the first balloon to burst, choose the LAST balloon to burst in an interval "},{"type":"text","text":"(left, right)","marks":[{"type":"code"}]},{"type":"text","text":"!"}]}]}},"revision":1},{"id":"c6ffbe9b-523b-7a44-9f1a-12a21aa5e672","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"d587171d-48c4-7a90-b997-ff14e4ea8d7f","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pad array with 1 at both ends: "},{"type":"text","text":"nums = [1] + nums + [1]","marks":[{"type":"code"}]},{"type":"text","text":". Evaluate interval lengths from 2 to "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":". Choose balloon "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" burst last in "},{"type":"text","text":"(left, right)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"4dd8ab71-4740-7881-bfd6-065b32f7f30a","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"694f5c7d-89e7-727c-936b-507a2527ac95","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pad array with boundary 1s: "},{"type":"text","text":"nums = [1] + nums + [1]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create 2D DP matrix "},{"type":"text","text":"dp","marks":[{"type":"code"}]},{"type":"text","text":" of size "},{"type":"text","text":"n x n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Outer loop "},{"type":"text","text":"length","marks":[{"type":"code"}]},{"type":"text","text":" from 2 to "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":"; inner loop "},{"type":"text","text":"left","marks":[{"type":"code"}]},{"type":"text","text":" from 0 to "},{"type":"text","text":"n - length","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"right = left + length","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loop "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"left + 1","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"right - 1","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"coins = nums[left] * nums[k] * nums[right]","marks":[{"type":"code"}]},{"type":"text","text":". Update "},{"type":"text","text":"dp[left][right] = max(dp[left][right], dp[left][k] + coins + dp[k][right])","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"dp[0][n - 1]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"38387af1-3624-7bbe-b9e7-f16cc68e2ef5","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Recursion"}]},"revision":1},{"id":"2ed276e1-0c9e-7ef1-854e-d21e3bba954d","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Try every balloon as the first balloon to burst recursively."}]}]}},"revision":1},{"id":"908c84c5-aded-7b64-a35c-5e6ce83dfba9","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def maxCoins(self, nums):\n\n        def dfs(nums):\n            if not nums:\n                return 0\n\n            answer = 0\n\n            for i in range(len(nums)):\n                left = nums[i - 1] if i > 0 else 1\n                right = nums[i + 1] if i + 1 < len(nums) else 1\n\n                coins = (\n                    left *\n                    nums[i] *\n                    right\n                )\n\n                remaining = nums[:i] + nums[i + 1:]\n\n                answer = max(\n                    answer,\n                    coins + dfs(remaining)\n                )\n\n            return answer\n\n        return dfs(nums)","filename":"Python"},"revision":1},{"id":"bcdbba0c-f737-79ed-bbce-092d69b59a45","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int maxCoins(vector<int>& nums) {\n        return dfs(nums);\n    }\n\nprivate:\n    int dfs(vector<int> nums) {\n        if (nums.empty()) return 0;\n\n        int n = nums.size();\n        int answer = 0;\n\n        for (int i = 0; i < n; i++) {\n            int left = i > 0 ? nums[i - 1] : 1;\n            int right = i + 1 < n ? nums[i + 1] : 1;\n\n            int coins = left * nums[i] * right;\n\n            vector<int> remaining(nums.begin(), nums.begin() + i);\n            remaining.insert(remaining.end(), nums.begin() + i + 1, nums.end());\n\n            answer = max(answer, coins + dfs(remaining));\n        }\n\n        return answer;\n    }\n};","filename":"C++"},"revision":1},{"id":"cb82396a-3268-796f-9cfa-158d6d87083b","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int maxCoins(int[] nums) {\n        List<Integer> list = new ArrayList<>();\n        for (int num : nums) list.add(num);\n        return dfs(list);\n    }\n\n    private int dfs(List<Integer> nums) {\n        if (nums.isEmpty()) return 0;\n\n        int n = nums.size();\n        int answer = 0;\n\n        for (int i = 0; i < n; i++) {\n            int left = i > 0 ? nums.get(i - 1) : 1;\n            int right = i + 1 < n ? nums.get(i + 1) : 1;\n\n            int coins = left * nums.get(i) * right;\n\n            List<Integer> remaining = new ArrayList<>(nums.subList(0, i));\n            remaining.addAll(nums.subList(i + 1, n));\n\n            answer = Math.max(answer, coins + dfs(remaining));\n        }\n\n        return answer;\n    }\n}","filename":"Java"},"revision":1},{"id":"f4ea647c-c2c9-7089-a667-01f3e53b363b","type":"code","position":"aE","content":{"language":"javascript","code":"var maxCoins = function(nums) {\n    const dfs = (nums) => {\n        if (nums.length === 0) return 0;\n\n        let answer = 0;\n\n        for (let i = 0; i < nums.length; i++) {\n            const left = i > 0 ? nums[i - 1] : 1;\n            const right = i + 1 < nums.length ? nums[i + 1] : 1;\n\n            const coins = left * nums[i] * right;\n\n            const remaining = [...nums.slice(0, i), ...nums.slice(i + 1)];\n\n            answer = Math.max(answer, coins + dfs(remaining));\n        }\n\n        return answer;\n    };\n\n    return dfs(nums);\n};","filename":"JavaScript"},"revision":1},{"id":"a7ea6401-680f-7c3d-b1af-61bc246e3f18","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: Approximately O(n!) · Aux Space: O(n²)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"b6526794-1638-738a-a91d-0d17175c14c5","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"4fe7bb6d-7569-75ed-916d-c9aa7056a815","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def maxCoins(self, nums):\n\n        nums = [1] + nums + [1]\n        n = len(nums)\n\n        dp = [\n            [0] * n\n            for _ in range(n)\n        ]\n\n        for length in range(2, n):\n\n            for left in range(\n                0,\n                n - length\n            ):\n                right = left + length\n\n                for k in range(\n                    left + 1,\n                    right\n                ):\n                    coins = (\n                        nums[left]\n                        * nums[k]\n                        * nums[right]\n                    )\n\n                    dp[left][right] = max(\n                        dp[left][right],\n                        dp[left][k]\n                        + coins\n                        + dp[k][right]\n                    )\n\n        return dp[0][n - 1]","filename":"Python"},"revision":1},{"id":"ab3e8175-9390-7aee-819f-44978d8764f5","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int maxCoins(vector<int>& input) {\n        vector<int> nums = {1};\n        nums.insert(nums.end(), input.begin(), input.end());\n        nums.push_back(1);\n\n        int n = nums.size();\n        vector<vector<int>> dp(n, vector<int>(n, 0));\n\n        for (int length = 2; length < n; length++) {\n            for (int left = 0; left < n - length; left++) {\n                int right = left + length;\n\n                for (int k = left + 1; k < right; k++) {\n                    int coins = nums[left] * nums[k] * nums[right];\n\n                    dp[left][right] = max(dp[left][right],\n                                          dp[left][k] + coins + dp[k][right]);\n                }\n            }\n        }\n\n        return dp[0][n - 1];\n    }\n};","filename":"C++"},"revision":1},{"id":"93500e83-214b-7547-89e8-eaceb83ef71b","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int maxCoins(int[] input) {\n        int n = input.length + 2;\n        int[] nums = new int[n];\n        nums[0] = 1;\n        nums[n - 1] = 1;\n        for (int i = 0; i < input.length; i++) nums[i + 1] = input[i];\n\n        int[][] dp = new int[n][n];\n\n        for (int length = 2; length < n; length++) {\n            for (int left = 0; left < n - length; left++) {\n                int right = left + length;\n\n                for (int k = left + 1; k < right; k++) {\n                    int coins = nums[left] * nums[k] * nums[right];\n\n                    dp[left][right] = Math.max(dp[left][right],\n                                               dp[left][k] + coins + dp[k][right]);\n                }\n            }\n        }\n\n        return dp[0][n - 1];\n    }\n}","filename":"Java"},"revision":1},{"id":"19afbcfc-27b8-7827-bfa0-906c01c6916b","type":"code","position":"aK","content":{"language":"javascript","code":"var maxCoins = function(nums) {\n    nums = [1, ...nums, 1];\n    const n = nums.length;\n\n    const dp = Array.from({ length: n }, () => new Array(n).fill(0));\n\n    for (let length = 2; length < n; length++) {\n        for (let left = 0; left < n - length; left++) {\n            const right = left + length;\n\n            for (let k = left + 1; k < right; k++) {\n                const coins = nums[left] * nums[k] * nums[right];\n\n                dp[left][right] = Math.max(\n                    dp[left][right],\n                    dp[left][k] + coins + dp[k][right]\n                );\n            }\n        }\n    }\n\n    return dp[0][n - 1];\n};","filename":"JavaScript"},"revision":1},{"id":"a75fdf13-41b5-71f4-b287-05e751e070e6","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n³) · Space: O(n²)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"622729bc-24bc-71a7-af2a-5dcfafd47be2","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"96944276-69da-76eb-822f-03a0f0847b3d","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Interval DP → choose the last operation inside an interval.","marks":[{"type":"bold"}]},{"type":"text","text":" This is one of the most important advanced DP patterns."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
