  ('694f5c7d-89e7-727c-936b-507a2527ac95', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pad array with boundary 1s: "},{"type":"text","text":"nums = [1] + nums + [1]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create 2D DP matrix "},{"type":"text","text":"dp","marks":[{"type":"code"}]},{"type":"text","text":" of size "},{"type":"text","text":"n x n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Outer loop "},{"type":"text","text":"length","marks":[{"type":"code"}]},{"type":"text","text":" from 2 to "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":"; inner loop "},{"type":"text","text":"left","marks":[{"type":"code"}]},{"type":"text","text":" from 0 to "},{"type":"text","text":"n - length","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"right = left + length","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loop "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"left + 1","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"right - 1","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"coins = nums[left] * nums[k] * nums[right]","marks":[{"type":"code"}]},{"type":"text","text":". Update "},{"type":"text","text":"dp[left][right] = max(dp[left][right], dp[left][k] + coins + dp[k][right])","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"dp[0][n - 1]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}}'),
  ('38387af1-3624-7bbe-b9e7-f16cc68e2ef5', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Naive Solution — Recursion"}]}'),
  ('2ed276e1-0c9e-7ef1-854e-d21e3bba954d', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Try every balloon as the first balloon to burst recursively."}]}]}}'),
  ('908c84c5-aded-7b64-a35c-5e6ce83dfba9', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def maxCoins(self, nums):\n\n        def dfs(nums):\n            if not nums:\n                return 0\n\n            answer = 0\n\n            for i in range(len(nums)):\n                left = nums[i - 1] if i > 0 else 1\n                right = nums[i + 1] if i + 1 < len(nums) else 1\n\n                coins = (\n                    left *\n                    nums[i] *\n                    right\n                )\n\n                remaining = nums[:i] + nums[i + 1:]\n\n                answer = max(\n                    answer,\n                    coins + dfs(remaining)\n                )\n\n            return answer\n\n        return dfs(nums)","filename":"Python"}'),
  ('bcdbba0c-f737-79ed-bbce-092d69b59a45', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int maxCoins(vector<int>& nums) {\n        return dfs(nums);\n    }\n\nprivate:\n    int dfs(vector<int> nums) {\n        if (nums.empty()) return 0;\n\n        int n = nums.size();\n        int answer = 0;\n\n        for (int i = 0; i < n; i++) {\n            int left = i > 0 ? nums[i - 1] : 1;\n            int right = i + 1 < n ? nums[i + 1] : 1;\n\n            int coins = left * nums[i] * right;\n\n            vector<int> remaining(nums.begin(), nums.begin() + i);\n            remaining.insert(remaining.end(), nums.begin() + i + 1, nums.end());\n\n            answer = max(answer, coins + dfs(remaining));\n        }\n\n        return answer;\n    }\n};","filename":"C++"}'),
  ('cb82396a-3268-796f-9cfa-158d6d87083b', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public int maxCoins(int[] nums) {\n        List<Integer> list = new ArrayList<>();\n        for (int num : nums) list.add(num);\n        return dfs(list);\n    }\n\n    private int dfs(List<Integer> nums) {\n        if (nums.isEmpty()) return 0;\n\n        int n = nums.size();\n        int answer = 0;\n\n        for (int i = 0; i < n; i++) {\n            int left = i > 0 ? nums.get(i - 1) : 1;\n            int right = i + 1 < n ? nums.get(i + 1) : 1;\n\n            int coins = left * nums.get(i) * right;\n\n            List<Integer> remaining = new ArrayList<>(nums.subList(0, i));\n            remaining.addAll(nums.subList(i + 1, n));\n\n            answer = Math.max(answer, coins + dfs(remaining));\n        }\n\n        return answer;\n    }\n}","filename":"Java"}'),
  ('f4ea647c-c2c9-7089-a667-01f3e53b363b', 'aE', 'code', '{"language":"javascript","code":"var maxCoins = function(nums) {\n    const dfs = (nums) => {\n        if (nums.length === 0) return 0;\n\n        let answer = 0;\n\n        for (let i = 0; i < nums.length; i++) {\n            const left = i > 0 ? nums[i - 1] : 1;\n            const right = i + 1 < nums.length ? nums[i + 1] : 1;\n\n            const coins = left * nums[i] * right;\n\n            const remaining = [...nums.slice(0, i), ...nums.slice(i + 1)];\n\n            answer = Math.max(answer, coins + dfs(remaining));\n        }\n\n        return answer;\n    };\n\n    return dfs(nums);\n};","filename":"JavaScript"}'),
  ('a7ea6401-680f-7c3d-b1af-61bc246e3f18', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: Approximately O(n!) · Aux Space: O(n²)","marks":[{"type":"bold"}]}]}]}}'),
  ('b6526794-1638-738a-a91d-0d17175c14c5', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
  ('4fe7bb6d-7569-75ed-916d-c9aa7056a815', 'aH', 'code', '{"language":"python","code":"class Solution:\n    def maxCoins(self, nums):\n\n        nums = [1] + nums + [1]\n        n = len(nums)\n\n        dp = [\n            [0] * n\n            for _ in range(n)\n        ]\n\n        for length in range(2, n):\n\n            for left in range(\n                0,\n                n - length\n            ):\n                right = left + length\n\n                for k in range(\n                    left + 1,\n                    right\n                ):\n                    coins = (\n                        nums[left]\n                        * nums[k]\n                        * nums[right]\n                    )\n\n                    dp[left][right] = max(\n                        dp[left][right],\n                        dp[left][k]\n                        + coins\n                        + dp[k][right]\n                    )\n\n        return dp[0][n - 1]","filename":"Python"}'),
