pe":"code"}]},{"type":"text","text":" array of size "},{"type":"text","text":"amount + 1","marks":[{"type":"code"}]},{"type":"text","text":" with infinity (or "},{"type":"text","text":"amount + 1","marks":[{"type":"code"}]},{"type":"text","text":") and "},{"type":"text","text":"dp[0] = 0","marks":[{"type":"code"}]},{"type":"text","text":". Fill from 1 to "},{"type":"text","text":"amount","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"cabaa1d2-b61f-777b-8b77-bcbef2f5fef2","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"bd52d511-8002-7691-90ec-4783d7c07774","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create "},{"type":"text","text":"dp = [amount + 1] * (amount + 1)","marks":[{"type":"code"}]},{"type":"text","text":", set "},{"type":"text","text":"dp[0] = 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For "},{"type":"text","text":"current","marks":[{"type":"code"}]},{"type":"text","text":" from 1 to "},{"type":"text","text":"amount","marks":[{"type":"code"}]},{"type":"text","text":": for each "},{"type":"text","text":"coin","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"coins","marks":[{"type":"code"}]},{"type":"text","text":": if "},{"type":"text","text":"coin <= current","marks":[{"type":"code"}]},{"type":"text","text":", update "},{"type":"text","text":"dp[current] = min(dp[current], dp[current - coin] + 1)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"dp[amount]","marks":[{"type":"code"}]},{"type":"text","text":" if "},{"type":"text","text":"dp[amount] <= amount","marks":[{"type":"code"}]},{"type":"text","text":" else -1."}]}]}]}]}},"revision":1},{"id":"cf604b71-dbc5-7c3f-9b04-65dbdd3aae75","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution — Recursion"}]},"revision":1},{"id":"f9ea4de8-3534-7520-9ceb-a61046b32e8b","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Try every coin denomination recursively at each remaining target amount."}]}]}},"revision":1},{"id":"c91809a6-30f8-76ef-b57c-e53558e345d4","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def coinChange(self, coins, amount):\n\n        def dfs(remaining):\n            if remaining == 0:\n                return 0\n\n            if remaining < 0:\n                return float(\"inf\")\n\n            answer = float(\"inf\")\n\n            for coin in coins:\n                answer = min(\n                    answer,\n                    1 + dfs(remaining - coin)\n                )\n\n            return answer\n\n        result = dfs(amount)\n\n        return -1 if result == float(\"inf\") else result","filename":"Python"},"revision":1},{"id":"59b78285-72c0-740e-a461-94fc4dfb21c7","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int coinChange(vector<int>& coins, int amount) {\n        int result = dfs(coins, amount);\n        return result == INT_MAX ? -1 : result;\n    }\n\nprivate:\n    int dfs(vector<int>& coins, int remaining) {\n        if (remaining == 0) return 0;\n        if (remaining < 0) return INT_MAX;\n\n        int answer = INT_MAX;\n\n        for (int coin : coins) {\n            int sub = dfs(coins, remaining - coin);\n            if (sub != INT_MAX) {\n                answer = min(answer, 1 + sub);\n            }\n        }\n\n        return answer;\n    }\n};","filename":"C++"},"revision":1},{"id":"2f1338c1-b5c3-7bb2-845a-2d9931650560","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    public int coinChange(int[] coins, int amount) {\n        int result = dfs(coins, amount);\n        return result == Integer.MAX_VALUE ? -1 : result;\n    }\n\n    private int dfs(int[] coins, int remaining) {\n        if (remaining == 0) return 0;\n        if (remaining < 0) return Integer.MAX_VALUE;\n\n        int answer = Integer.MAX_VALUE;\n\n        for (int coin : coins) {\n            int sub = dfs(coins, remaining - coin);\n            if (sub != Integer.MAX_VALUE) {\n                answer = Math.min(answer, 1 + sub);\n            }\n        }\n\n        return answer;\n    }\n}","filename":"Java"},"revision":1},{"id":"2561eed8-d573-72f1-95d2-72071c28608d","type":"code","position":"aE","content":{"language":"javascript","code":"var coinChange = function(coins, amount) {\n    const dfs = (remaining) => {\n        if (remaining === 0) return 0;\n        if (remaining < 0) return Infinity;\n\n        let answer = Infinity;\n\n        for (const coin of coins) {\n            answer = Math.min(answer, 1 + dfs(remaining - coin));\n        }\n\n        return answer;\n    };\n\n    const result = dfs(amount);\n\n    return result === Infinity ? -1 : result;\n};","filename":"JavaScript"},"revision":1},{"id":"35df81c2-8a25-7379-b5d7-f665b95879a8","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n^amount) · Aux Space: O(amount)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"6c5bce40-ccd7-78b9-aea6-48b7b7c36fcb","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"8de463b9-af75-78b9-9d18-d19570efca10","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def coinChange(self, coins, amount):\n\n        dp = [amount + 1] * (amount + 1)\n        dp[0] = 0\n\n        for current in range(1, amount + 1):\n            for coin in coins:\n\n                if coin <= current:\n                    dp[current] = min(\n                        dp[current],\n                        dp[current - coin] + 1\n                    )\n\n        return -1 if dp[amount] > amount else dp[amount]","filename":"Python"},"revision":1},{"id":"ec6930d2-a183-7570-b679-618da2471518","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int coinChange(vector<int>& coins, int amount) {\n        vector<int> dp(amount + 1, amount + 1);\n        dp[0] = 0;\n\n        for (int current = 1; current <= amount; current++) {\n            for (int coin : coins) {\n                if (coin <= current) {\n                    dp[current] = min(dp[current], dp[current - coin] + 1);\n                }\n            }\n        }\n\n        return dp[amount] > amount ? -1 : dp[amount];\n    }\n};","filename":"C++"},"revision":1},{"id":"23d219e2-7f5c-7cc1-b9f8-bd1ea58dcfcd","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    public int coinChange(int[] coins, int amount) {\n        int[] dp = new int[amount + 1];\n        Arrays.fill(dp, amount + 1);\n        dp[0] = 0;\n\n        for (int current = 1; current <= amount; current++) {\n            for (int coin : coins) {\n                if (coin <= current) {\n                    dp[current] = Math.min(dp[current], dp[current - coin] + 1);\n                }\n            }\n        }\n\n        return dp[amount] > amount ? -1 : dp[amount];\n    }\n}","filename":"Java"},"revision":1},{"id":"9576e2dc-a230-796c-bcbc-57d4303a4002","type":"code","position":"aK","content":{"language":"javascript","code":"var coinChange = function(coins, amount) {\n    const dp = new Array(amount + 1).fill(amount + 1);\n    dp[0] = 0;\n\n    for (let current = 1; current <= amount; current++) {\n        for (const coin of coins) {\n            if (coin <= current) {\n                dp[current] = Math.min(dp[current], dp[current - coin] + 1);\n            }\n        }\n    }\n\n    return dp[amount] > amount ? -1 : dp[amount];\n};","filename":"JavaScript"},"revision":1},{"id":"c7addce2-5e7a-7ba8-8908-dc292fbf8673","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(amount × n) · Space: O(amount)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"f0ebc03c-1c54-753f-87b8-b8a99f1a0867","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Takeaway"}]},"revision":1},{"id":"6bff2564-5c65-7acb-96cf-85f10e82c218","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unbounded choice + minimum → 1-D DP.","marks":[{"type":"bold"}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
