  ('c91809a6-30f8-76ef-b57c-e53558e345d4', 'aB', 'code', '{"language":"python","code":"class Solution:\n    def coinChange(self, coins, amount):\n\n        def dfs(remaining):\n            if remaining == 0:\n                return 0\n\n            if remaining < 0:\n                return float(\"inf\")\n\n            answer = float(\"inf\")\n\n            for coin in coins:\n                answer = min(\n                    answer,\n                    1 + dfs(remaining - coin)\n                )\n\n            return answer\n\n        result = dfs(amount)\n\n        return -1 if result == float(\"inf\") else result","filename":"Python"}'),
  ('59b78285-72c0-740e-a461-94fc4dfb21c7', 'aC', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int coinChange(vector<int>& coins, int amount) {\n        int result = dfs(coins, amount);\n        return result == INT_MAX ? -1 : result;\n    }\n\nprivate:\n    int dfs(vector<int>& coins, int remaining) {\n        if (remaining == 0) return 0;\n        if (remaining < 0) return INT_MAX;\n\n        int answer = INT_MAX;\n\n        for (int coin : coins) {\n            int sub = dfs(coins, remaining - coin);\n            if (sub != INT_MAX) {\n                answer = min(answer, 1 + sub);\n            }\n        }\n\n        return answer;\n    }\n};","filename":"C++"}'),
  ('2f1338c1-b5c3-7bb2-845a-2d9931650560', 'aD', 'code', '{"language":"java","code":"class Solution {\n    public int coinChange(int[] coins, int amount) {\n        int result = dfs(coins, amount);\n        return result == Integer.MAX_VALUE ? -1 : result;\n    }\n\n    private int dfs(int[] coins, int remaining) {\n        if (remaining == 0) return 0;\n        if (remaining < 0) return Integer.MAX_VALUE;\n\n        int answer = Integer.MAX_VALUE;\n\n        for (int coin : coins) {\n            int sub = dfs(coins, remaining - coin);\n            if (sub != Integer.MAX_VALUE) {\n                answer = Math.min(answer, 1 + sub);\n            }\n        }\n\n        return answer;\n    }\n}","filename":"Java"}'),
  ('2561eed8-d573-72f1-95d2-72071c28608d', 'aE', 'code', '{"language":"javascript","code":"var coinChange = function(coins, amount) {\n    const dfs = (remaining) => {\n        if (remaining === 0) return 0;\n        if (remaining < 0) return Infinity;\n\n        let answer = Infinity;\n\n        for (const coin of coins) {\n            answer = Math.min(answer, 1 + dfs(remaining - coin));\n        }\n\n        return answer;\n    };\n\n    const result = dfs(amount);\n\n    return result === Infinity ? -1 : result;\n};","filename":"JavaScript"}'),
  ('35df81c2-8a25-7379-b5d7-f665b95879a8', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(n^amount) · Aux Space: O(amount)","marks":[{"type":"bold"}]}]}]}}'),
  ('6c5bce40-ccd7-78b9-aea6-48b7b7c36fcb', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]}'),
  ('8de463b9-af75-78b9-9d18-d19570efca10', 'aH', 'code', '{"language":"python","code":"class Solution:\n    def coinChange(self, coins, amount):\n\n        dp = [amount + 1] * (amount + 1)\n        dp[0] = 0\n\n        for current in range(1, amount + 1):\n            for coin in coins:\n\n                if coin <= current:\n                    dp[current] = min(\n                        dp[current],\n                        dp[current - coin] + 1\n                    )\n\n        return -1 if dp[amount] > amount else dp[amount]","filename":"Python"}'),
  ('ec6930d2-a183-7570-b679-618da2471518', 'aI', 'code', '{"language":"cpp","code":"class Solution {\npublic:\n    int coinChange(vector<int>& coins, int amount) {\n        vector<int> dp(amount + 1, amount + 1);\n        dp[0] = 0;\n\n        for (int current = 1; current <= amount; current++) {\n            for (int coin : coins) {\n                if (coin <= current) {\n                    dp[current] = min(dp[current], dp[current - coin] + 1);\n                }\n            }\n        }\n\n        return dp[amount] > amount ? -1 : dp[amount];\n    }\n};","filename":"C++"}'),
  ('23d219e2-7f5c-7cc1-b9f8-bd1ea58dcfcd', 'aJ', 'code', '{"language":"java","code":"class Solution {\n    public int coinChange(int[] coins, int amount) {\n        int[] dp = new int[amount + 1];\n        Arrays.fill(dp, amount + 1);\n        dp[0] = 0;\n\n        for (int current = 1; current <= amount; current++) {\n            for (int coin : coins) {\n                if (coin <= current) {\n                    dp[current] = Math.min(dp[current], dp[current - coin] + 1);\n                }\n            }\n        }\n\n        return dp[amount] > amount ? -1 : dp[amount];\n    }\n}","filename":"Java"}'),
  ('9576e2dc-a230-796c-bcbc-57d4303a4002', 'aK', 'code', '{"language":"javascript","code":"var coinChange = function(coins, amount) {\n    const dp = new Array(amount + 1).fill(amount + 1);\n    dp[0] = 0;\n\n    for (let current = 1; current <= amount; current++) {\n        for (const coin of coins) {\n            if (coin <= current) {\n                dp[current] = Math.min(dp[current], dp[current - coin] + 1);\n            }\n        }\n    }\n\n    return dp[amount] > amount ? -1 : dp[amount];\n};","filename":"JavaScript"}'),
  ('c7addce2-5e7a-7ba8-8908-dc292fbf8673', 'aL', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(amount × n) · Space: O(amount)","marks":[{"type":"bold"}]}]}]}}'),
