SELECT '096163df-fd60-76b3-90d7-632948c0566e', 'e6f1eafd-bdbe-7cae-a8a5-530b55858034', 1, 'PUBLISHED', 'Number of Connected Components', '[{"id":"b95ffc12-8920-76c8-addf-d66ae4052ee4","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty: "},{"type":"text","text":"Medium","marks":[{"type":"bold"}]},{"type":"text","text":" · "},{"type":"text","text":"LeetCode 323","marks":[{"type":"link","attrs":{"href":"https://leetcode.com/problems/number-of-connected-components-in-an-undirected-graph/"}}]}]}]}},"revision":1},{"id":"6bfc2067-cb94-7cb5-b368-5cb0cd544b20","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Problem"}]},"revision":1},{"id":"35897bfc-87c2-75a1-86be-e5288d0cec65","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given n nodes and edges list, return number of connected components."}]}]}},"revision":1},{"id":"61c6b0b5-27ce-747c-bb44-0d3917623716","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Understanding the problem"}]},"revision":1},{"id":"485723e0-5290-7d59-8b45-61bdbbef7364","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Start with n components and decrement by 1 on every successful union of disjoint sets."}]}]}},"revision":1},{"id":"d5df7309-02ed-7bcb-9ea5-1ca1dad275e3","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Intuition"}]},"revision":1},{"id":"5d5f4acb-6530-795d-8703-09afb8f35fdc","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Union-Find tracking component count ("},{"type":"text","text":"components -= 1","marks":[{"type":"code"}]},{"type":"text","text":" on successful union)."}]}]}},"revision":1},{"id":"e54ba1c3-2b48-7dee-8891-60bb2e78a8fc","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Approach"}]},"revision":1},{"id":"3ef06729-ad19-7c29-9e04-a748e5b8bbe1","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialize parent = list(range(n)) and components = n."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For each edge (a, b), call union. If merged, decrement components."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return components count."}]}]}]}]}},"revision":1},{"id":"541d9b2a-ec55-78ef-8b10-f9349a22c99f","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Naive Solution"}]},"revision":1},{"id":"03f662c9-87ff-70ca-ab79-78b4125c034f","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DFS component counting."}]}]}},"revision":1},{"id":"f2c664a8-06b6-7f3f-8183-7418e0643228","type":"code","position":"aB","content":{"language":"python","code":"class Solution:\n    def countComponents(self, n, edges):\n        graph = [[] for _ in range(n)]\n\n        for a, b in edges:\n            graph[a].append(b)\n            graph[b].append(a)\n\n        visited = [False] * n\n\n        def dfs(node):\n            visited[node] = True\n\n            for neighbor in graph[node]:\n                if not visited[neighbor]:\n                    dfs(neighbor)\n\n        components = 0\n\n        for node in range(n):\n            if not visited[node]:\n                components += 1\n                dfs(node)\n\n        return components","filename":"Python"},"revision":1},{"id":"a9f72088-ebab-72b3-bbf3-2fba3cd0a3b7","type":"code","position":"aC","content":{"language":"cpp","code":"class Solution {\npublic:\n    int countComponents(int n, vector<vector<int>>& edges) {\n        vector<vector<int>> graph(n);\n\n        for (auto& e : edges) {\n            graph[e[0]].push_back(e[1]);\n            graph[e[1]].push_back(e[0]);\n        }\n\n        vector<bool> visited(n, false);\n\n        function<void(int)> dfs = [&](int node) {\n            visited[node] = true;\n\n            for (int neighbor : graph[node])\n                if (!visited[neighbor]) dfs(neighbor);\n        };\n\n        int components = 0;\n\n        for (int node = 0; node < n; node++) {\n            if (!visited[node]) {\n                components++;\n                dfs(node);\n            }\n        }\n\n        return components;\n    }\n};","filename":"C++"},"revision":1},{"id":"3f5e9acc-9b38-771e-8056-a396c978b477","type":"code","position":"aD","content":{"language":"java","code":"class Solution {\n    private List<List<Integer>> graph = new ArrayList<>();\n    private boolean[] visited;\n\n    public int countComponents(int n, int[][] edges) {\n        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());\n\n        for (int[] e : edges) {\n            graph.get(e[0]).add(e[1]);\n            graph.get(e[1]).add(e[0]);\n        }\n\n        visited = new boolean[n];\n        int components = 0;\n\n        for (int node = 0; node < n; node++) {\n            if (!visited[node]) {\n                components++;\n                dfs(node);\n            }\n        }\n\n        return components;\n    }\n\n    private void dfs(int node) {\n        visited[node] = true;\n\n        for (int neighbor : graph.get(node))\n            if (!visited[neighbor]) dfs(neighbor);\n    }\n}","filename":"Java"},"revision":1},{"id":"6004d7ab-762a-7200-9af8-6a47827c5b2d","type":"code","position":"aE","content":{"language":"javascript","code":"var countComponents = function(n, edges) {\n    const graph = Array.from({ length: n }, () => []);\n\n    for (const [a, b] of edges) {\n        graph[a].push(b);\n        graph[b].push(a);\n    }\n\n    const visited = new Array(n).fill(false);\n\n    const dfs = (node) => {\n        visited[node] = true;\n\n        for (const neighbor of graph[node])\n            if (!visited[neighbor]) dfs(neighbor);\n    };\n\n    let components = 0;\n\n    for (let node = 0; node < n; node++) {\n        if (!visited[node]) {\n            components++;\n            dfs(node);\n        }\n    }\n\n    return components;\n};","filename":"JavaScript"},"revision":1},{"id":"4d17659f-35ca-7cb6-a97e-f2f35a94e9a9","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(V + E) · Aux Space: O(V + E)","marks":[{"type":"bold"}]}]}]}},"revision":1},{"id":"bc8c9f70-e7df-73a2-93d2-98cad7d50c7e","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Optimized Code (Python 3)"}]},"revision":1},{"id":"4d7d0619-bde7-7de6-9421-564045481049","type":"code","position":"aH","content":{"language":"python","code":"class Solution:\n    def countComponents(self, n, edges):\n        parent = list(range(n))\n        rank = [1] * n\n        components = n\n\n        def find(x):\n            while x != parent[x]:\n                parent[x] = parent[parent[x]]\n                x = parent[x]\n\n            return x\n\n        def union(a, b):\n            nonlocal components\n\n            root_a = find(a)\n            root_b = find(b)\n\n            if root_a == root_b:\n                return\n\n            if rank[root_a] < rank[root_b]:\n                root_a, root_b = root_b, root_a\n\n            parent[root_b] = root_a\n            rank[root_a] += rank[root_b]\n\n            components -= 1\n\n        for a, b in edges:\n            union(a, b)\n\n        return components","filename":"Python"},"revision":1},{"id":"cf3524b5-a41b-745f-ab19-405e27601b89","type":"code","position":"aI","content":{"language":"cpp","code":"class Solution {\npublic:\n    int countComponents(int n, vector<vector<int>>& edges) {\n        vector<int> parent(n), rank(n, 1);\n        iota(parent.begin(), parent.end(), 0);\n        int components = n;\n\n        auto find = [&](int x) {\n            while (x != parent[x]) {\n                parent[x] = parent[parent[x]];\n                x = parent[x];\n            }\n            return x;\n        };\n\n        auto unite = [&](int a, int b) {\n            int rootA = find(a), rootB = find(b);\n\n            if (rootA == rootB) return;\n\n            if (rank[rootA] < rank[rootB]) swap(rootA, rootB);\n\n            parent[rootB] = rootA;\n            rank[rootA] += rank[rootB];\n\n            components--;\n        };\n\n        for (auto& e : edges) unite(e[0], e[1]);\n\n        return components;\n    }\n};","filename":"C++"},"revision":1},{"id":"da41b2ec-51c2-7674-abe6-669636757d50","type":"code","position":"aJ","content":{"language":"java","code":"class Solution {\n    private int[] parent, rank;\n    private int components;\n\n    public int countComponents(int n, int[][] edges) {\n        parent = new int[n];\n        rank = new int[n];\n        for (int i = 0; i < n; i++) {\n            parent[i] = i;\n            rank[i] = 1;\n        }\n        components = n;\n\n        for (int[] e : edges) union(e[0], e[1]);\n\n        return components;\n    }\n\n    private int find(int x) {\n        while (x != parent[x]) {\n            parent[x] = parent[parent[x]];\n            x = parent[x];\n        }\n        return x;\n    }\n\n    private void union(int a, int b) {\n        int rootA = find(a), rootB = find(b);\n\n        if (rootA == rootB) return;\n\n        if (rank[rootA] < rank[rootB]) {\n            int tmp = rootA; rootA = rootB; rootB = tmp;\n        }\n\n        parent[rootB] = rootA;\n        rank[rootA] += rank[rootB];\n\n        components--;\n    }\n}","filename":"Java"},"revision":1},{"id":"df9eea78-bc5a-7597-9039-d876863eca01","type":"code","position":"aK","content":{"language":"javascript","code":"var countComponents = function(n, edges) {\n    const parent = Array.from({ length: n }, (_, i) => i);\n    const rank = new Array(n).fill(1);\n    let components = n;\n\n    const find = (x) => {\n        while (x !== parent[x]) {\n            parent[x] = parent[parent[x]];\n            x = parent[x];\n        }\n        return x;\n    };\n\n    const union = (a, b) => {\n        let rootA = find(a), rootB = find(b);\n\n        if (rootA === rootB) return;\n\n        if (rank[rootA] < rank[rootB]) [rootA, rootB] = [rootB, rootA];\n\n        parent[rootB] = rootA;\n        rank[rootA] += rank[rootB];\n\n        components--;\n    };\n\n    for (const [a, b] of edges) union(a, b);\n\n    return components;\n};","filename":"JavaScript"},"revision":1},{"id":"89a9868d-4f98-7562-98c0-2df55655da2a","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time: O(E α(V)) · Aux Space: O(V)","marks":[{"type":"bold"}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
